/* SINH TỰ ĐỘNG bởi cong-cu/on-tap/tao.js – đừng sửa tay. */
window.NGAN_HANG = {"tin6-an-toan-thong-tin-tren-internet":{"id":"tin6-bai9","ten":"Bài 9. An toàn thông tin trên Internet","cau":[{"id":"hd1a","type":"open","q":"Bạn Minh đã gặp rắc rối gì?","k":"Minh tải trò chơi trên mạng, bỏ qua cảnh báo khi cài đặt → máy tính bị nhiễm <b>virus hoặc mã độc</b>, bị treo, mất các tệp ảnh.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Thảo luận nhóm: Tác hại và nguy cơ khi dùng Internet.","k":"Lộ, mất thông tin cá nhân; máy nhiễm virus; bị lừa đảo, dụ dỗ, đe doạ, bắt nạt; tiếp nhận thông tin không chính xác; nghiện Internet, trò chơi trên mạng.","label":"HĐ1 – Câu 2"},{"id":"nc","type":"match","q":"Mỗi tình huống dưới đây thể hiện tác hại, nguy cơ nào khi dùng Internet?","k":"Năm tác hại, nguy cơ: lộ thông tin cá nhân; nhiễm virus, mã độc; lừa đảo, đe doạ, bắt nạt; thông tin không chính xác; nghiện Internet, trò chơi.","items":[["Kẻ xấu lấy được mật khẩu, dùng tài khoản của em để nhắn tin vay tiền",1],["Cài phần mềm lạ, máy tính chạy chậm, mất dữ liệu",2],["Một người lạ nhắn tin doạ đăng ảnh của em lên mạng",3],["Đọc tin “uống nước chanh chữa khỏi mọi bệnh” trên mạng và tin ngay",4],["Chơi trò chơi trên mạng đến khuya, bỏ bê việc học",5]],"opts":["Thông tin cá nhân bị lộ hoặc bị đánh cắp","Máy tính bị nhiễm virus hay mã độc","Bị lừa đảo, dụ dỗ, đe doạ, bắt nạt trên mạng","Tiếp nhận thông tin không chính xác","Nghiện Internet, nghiện trò chơi trên mạng"]},{"id":"p38a","type":"mcq","q":"Em hãy tìm phương án sai. Khi dùng Internet có thể:","k":"<b>C</b> sai. Thông tin trên mạng có nhiều nguồn, có thông tin không được kiểm duyệt nên không thể tin tưởng mọi nguồn.","o":["Bị lôi kéo vào các hoạt động không lành mạnh.","Máy tính bị nhiễm virus hoặc mã độc.","Tin tưởng mọi nguồn thông tin trên mạng.","Bị lừa đảo hoặc lợi dụng."],"a":2},{"id":"p38b","type":"mcq","q":"Việc làm nào được khuyến khích khi sử dụng các dịch vụ trên Internet?","k":"<b>D</b>. Dùng Internet để học tập là việc làm được khuyến khích.","o":["Mở thư điện tử do người lạ gửi.","Tải các phần mềm miễn phí trên Internet không có kiểm duyệt.","Liên tục vào các trang xã hội để cập nhật thông tin.","Vào trang web tìm kiếm để tìm tư liệu làm bài tập về nhà."],"a":3},{"id":"hd2a","type":"open","q":"Em đã từng sử dụng Internet chưa? Em đã bao giờ gặp phải một trong những nguy cơ như trên chưa? Nếu gặp phải, em sẽ làm gì?","k":"Học sinh chia sẻ; khi gặp nguy cơ: không làm theo, không trả lời, báo ngay cho bố mẹ, thầy cô.","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Thảo luận nhóm: Em cần làm gì để phòng tránh những nguy cơ và tác hại có thể gặp phải khi sử dụng Internet?","k":"Thực hiện 5 quy tắc: <b>giữ an toàn</b> thông tin, <b>không gặp gỡ</b> người quen qua mạng, <b>đừng chấp nhận</b> thư, tin nhắn lạ, <b>kiểm tra độ tin cậy</b> của thông tin, <b>hãy nói ra</b> với người tin cậy.","label":"HĐ2 – Câu 2"},{"id":"qt","type":"match","q":"Ghép mỗi việc làm với quy tắc an toàn phù hợp.","k":"Thông tin phải giữ <b>an toàn</b>; chớ nên <b>gặp gỡ</b> bạn vừa mới quen; không <b>chấp nhận</b> chớ có quên; tăng độ <b>tin cậy</b> điều nên giữ gìn; <b>nói ra</b> với người bạn tin; nắm <b>quy tắc</b> đó nên in vào lòng.","items":[["Không đăng số điện thoại, địa chỉ nhà lên mạng xã hội",1],["Từ chối lời mời đi chơi của một bạn chỉ quen trên mạng",2],["Không mở thư điện tử từ người lạ, từ chối lời mời vào nhóm lạ",3],["Chỉ tìm thông tin ở trang của cơ quan, tổ chức uy tín",4],["Bị đe doạ trên mạng thì kể ngay với bố mẹ, thầy cô",5]],"opts":["Giữ an toàn","Không gặp gỡ","Đừng chấp nhận","Kiểm tra độ tin cậy","Hãy nói ra"]},{"id":"p39a","type":"open","q":"Em có thể đưa ra một số giải pháp để giữ bí mật thông tin cá nhân không?","k":"Đặt mật khẩu mạnh, giữ bí mật mật khẩu; đăng xuất sau khi dùng; không chia sẻ thông tin cá nhân lên mạng; không kết bạn với người lạ; dùng phần mềm diệt virus.","label":"Câu hỏi tr.39 – Câu 1"},{"id":"p39b","type":"open","q":"Trong 5 quy tắc trên, em thấy quy tắc nào quan trọng nhất? Tại sao?","k":"Học sinh chọn và giải thích hợp lí; ví dụ: “Hãy nói ra” vì người lớn sẽ giúp em xử lí khi gặp nguy hiểm.","label":"Câu hỏi tr.39 – Câu 2"},{"id":"hd3a","type":"open","q":"Sau giờ thực hành, bạn Minh quên đăng xuất tài khoản thư điện tử và một người đã dùng tài khoản đó để gửi nội dung không hay cho những người khác. Theo em, điều gì có thể xảy ra với Minh?","k":"Minh bị hiểu lầm, mất uy tín, có thể bị bạn bè xa lánh, bị kỉ luật; thông tin cá nhân trong hộp thư bị lộ.","label":"HĐ3 – Câu 1"},{"id":"hd3b","type":"open","q":"Nếu thấy đường liên kết hoặc thư điện tử có chủ đề gây tò mò được gửi từ một người không quen biết thì em sẽ làm gì?","k":"Không mở liên kết, không mở thư và tệp đính kèm; xoá thư hoặc báo cho bố mẹ, thầy cô.","label":"HĐ3 – Câu 2"},{"id":"hd3c","type":"open","q":"Em hãy nêu một vài cách để bảo vệ tài khoản thư điện tử.","k":"Đặt mật khẩu mạnh (dài, có chữ hoa, chữ thường, chữ số, kí tự đặc biệt); không cho người khác biết mật khẩu; đăng xuất khi dùng xong; không dùng máy tính công cộng để đăng nhập.","label":"HĐ3 – Câu 3"},{"id":"hd4a","type":"open","q":"Một bạn quen trên mạng xin số điện thoại và địa chỉ của em để gặp nhau nói chuyện. Em có nên cho không? Tại sao?","k":"<b>Không</b>. Không biết người đó thực chất là ai; có thể là kẻ xấu lợi dụng để lừa đảo, đe doạ. Cần báo bố mẹ, thầy cô.","label":"HĐ4 – Câu 1"},{"id":"hd4b","type":"open","q":"Em được một bạn gửi qua mạng cho một số thông tin không tốt về một bạn khác cùng lớp. Em có nên đăng lên mạng để mọi người cùng biết không?","k":"<b>Không</b>. Thông tin chưa kiểm chứng, có thể là tin giả; lan truyền sẽ làm tổn thương bạn. Nên báo thầy cô.","label":"HĐ4 – Câu 2"},{"id":"p41","type":"mcq","q":"Lời khuyên nào sai khi em muốn bảo vệ máy tính của mình?","k":"<b>C</b> sai. Cần chủ động bảo vệ: cài và cập nhật phần mềm diệt virus, đăng xuất, không mở thư lạ.","o":["Đừng bao giờ mở thư điện tử và mở tệp đính kèm thư từ những người không quen biết.","Luôn nhớ đăng xuất khi sử dụng xong máy tính, thư điện tử.","Chẳng cần làm gì vì máy tính đã được cài đặt sẵn các thiết bị bảo vệ từ nhà sản xuất.","Nên cài đặt phần mềm bảo vệ máy tính khỏi virus và thường xuyên cập nhật phần mềm bảo vệ."],"a":2},{"id":"lt1","type":"sort","q":"Khi sử dụng Internet, những việc làm nào sau đây có thể khiến em gặp nguy cơ bị hại?","k":"<b>A, B, D, E</b> có nguy cơ. C là việc làm giúp bảo vệ tài khoản.","cats":["Có nguy cơ","An toàn"],"items":[["A. Tải phần mềm, tệp miễn phí trên Internet.",0],["B. Mở liên kết được cung cấp trong thư điện tử không biết rõ nguồn gốc.",0],["C. Định kì thay đổi mật khẩu của tài khoản cá nhân trên mạng xã hội và thư điện tử.",1],["D. Khi có kẻ đe doạ mình trên mạng không cho bố mẹ hoặc thầy cô giáo biết.",0],["E. Làm theo các lời khuyên và bài hướng dẫn sử dụng thuốc trên mạng.",0]]},{"id":"lt2","type":"sort","q":"Theo em, những tình huống nào sau đây là rủi ro khi sử dụng Internet?","k":"<b>A, B, C, D, E</b> là rủi ro. F là lợi ích của Internet.","cats":["Là rủi ro","Không phải"],"items":[["A. Máy tính bị hỏng do nhiễm virus hoặc mã độc.",0],["B. Thông tin cá nhân hoặc tập thể bị đánh cắp.",0],["C. Tài khoản ngân hàng bị mất tiền.",0],["D. Bị bạn quen trên mạng lừa đảo.",0],["E. Nghiện mạng xã hội, nghiện trò chơi trên mạng.",0],["F. Hoàn thành chương trình học ngoại ngữ trực tuyến.",1]]},{"id":"vd1","type":"open","q":"Em hãy đưa ra một số cách nhận diện những trò lừa đảo trên Internet.","k":"Tin nhắn, thư hứa trúng thưởng, quà miễn phí, kiếm tiền dễ; yêu cầu cung cấp mật khẩu, mã OTP, thông tin cá nhân; giục “nháy chuột nhanh”; người lạ xin kết bạn, mời vào nhóm; địa chỉ trang web lạ, sai chính tả.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Em sẽ làm gì khi phát hiện bạn bè hoặc người thân có nguy cơ bị hại khi truy cập mạng?","k":"Nhắc nhở, khuyên bạn dừng lại; giải thích nguy cơ; báo ngay cho bố mẹ, thầy cô hoặc người lớn tin cậy để được giúp đỡ.","label":"Vận dụng – Câu 2"},{"id":"vd3","type":"open","q":"Em nên làm gì để bảo vệ thông tin và tài khoản cá nhân?","k":"Cài và cập nhật phần mềm chống virus; đặt mật khẩu mạnh, giữ bí mật; đăng xuất khi dùng xong; tránh dùng mạng công cộng; không truy cập liên kết lạ; không chia sẻ thông tin cá nhân; không lan truyền tin giả.","label":"Vận dụng – Câu 3"}],"the":[{"t":"Tác hại, nguy cơ khi dùng Internet","b":"<ul><li>Thông tin cá nhân bị lộ hoặc bị đánh cắp.</li><li>Máy tính bị nhiễm virus hay mã độc.</li><li>Bị lừa đảo, dụ dỗ, đe doạ, bắt nạt trên mạng.</li><li>Tiếp nhận thông tin không chính xác.</li><li>Nghiện Internet, nghiện trò chơi trên mạng.</li></ul>"},{"t":"Ghi nhớ","b":"<p>Thông tin phải giữ AN TOÀN<br>Chớ nên GẶP GỠ bạn vừa mới quen.<br>Không CHẤP NHẬN chớ có quên.<br>Tăng độ TIN CẬY điều nên giữ gìn.<br>NÓI RA với người bạn tin.<br>Nắm quy tắc đó nên in vào lòng.</p>"},{"t":"Một số biện pháp bảo vệ thông tin, tài khoản cá nhân và chia sẻ thông tin an toàn","b":"<ul><li>Cài đặt và cập nhật phần mềm chống virus.</li><li>Đặt mật khẩu mạnh. Bảo vệ mật khẩu.</li><li>Đăng xuất các tài khoản khi đã dùng xong.</li><li>Tránh dùng mạng công cộng.</li><li>Không truy cập vào các liên kết lạ; không mở thư điện tử và tệp đính kèm gửi từ những người không quen biết; không kết bạn và nhắn tin cho người lạ.</li><li>Không chia sẻ thông tin cá nhân và những thông tin chưa được kiểm chứng trên Internet; không lan truyền tin giả làm tổn thương người khác.</li></ul>"}]},"tin6-cac-cau-truc-dieu-khien":{"id":"tin6-bai16","ten":"Bài 16. Các cấu trúc điều khiển","cau":[{"id":"hd1a","type":"open","q":"Trong trò chơi ở phần khởi động, điều kiện để cặp chơi được cộng một điểm là gì?","k":"Bạn thứ hai <b>trả lời đúng</b>: gật đầu khi câu khẳng định đúng, lắc đầu khi câu khẳng định sai.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Việc đánh giá điểm gồm những bước nào? Em hãy viết các bước đó ra giấy.","k":"1. Bạn thứ nhất đọc câu ghi trong phiếu. 2. Bạn thứ hai gật hoặc lắc đầu. 3. Kiểm tra câu trả lời: <b>nếu đúng thì cộng 1 điểm</b>, sai thì không cộng.","label":"HĐ1 – Câu 2"},{"id":"q1","type":"open","q":"Em hãy kể hai công việc trong cuộc sống được thực hiện tuần tự theo các bước. Em mô tả một công việc đó bằng sơ đồ khối.","k":"Ví dụ: pha trà (đun nước → cho trà vào ấm → rót nước sôi → chờ 3 phút → rót ra cốc); đánh răng (lấy bàn chải → cho kem → chải răng → súc miệng). Sơ đồ khối: Bắt đầu → các hình chữ nhật nối nhau bằng mũi tên → Kết thúc.","label":"Câu hỏi 1 – Cấu trúc tuần tự"},{"id":"q2","type":"mcq","q":"Câu “Nếu trời mưa thì em không đi đá bóng” có chứa cấu trúc nào?","k":"<b>B</b>. Rẽ nhánh dạng thiếu: hình thoi “Trời mưa?” → Đúng: “Không đi đá bóng”; Sai: không làm gì, đi tiếp.","o":["Cấu trúc tuần tự","Cấu trúc rẽ nhánh dạng thiếu","Cấu trúc rẽ nhánh dạng đủ","Cấu trúc lặp"],"a":1},{"id":"hd2a","type":"open","q":"Trong trò chơi ở phần khởi động, hoạt động nào được lặp lại?","k":"Hoạt động <b>đọc phiếu và trả lời</b> (cùng việc chấm điểm) được lặp lại nhiều lần.","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Điều kiện để dừng trò chơi là gì?","k":"<b>Hết thời gian</b> quy định (một phút) thì dừng.","label":"HĐ2 – Câu 2"},{"id":"q3","type":"open","q":"Em hãy kể hai công việc trong cuộc sống mà việc thực hiện gồm các bước được lặp lại nhiều lần.","k":"Ví dụ: chạy 5 vòng sân trường; nhảy dây đến khi đủ 100 lần; tưới từng cây trong vườn đến khi hết cây; chép phạt một từ 10 lần.","label":"Câu hỏi 3 – Công việc lặp lại"},{"id":"q4a","type":"mcq","q":"Bạn Khoa muốn chú mèo trong Scratch di chuyển 10 bước một liên tục cho đến khi chạm biên thì dừng lại. Điều kiện để chú mèo dừng lại là gì?","k":"<b>B</b>. Chú mèo dừng lại khi <b>chạm biên</b>; còn “chưa chạm biên” thì tiếp tục di chuyển.","o":["Đã di chuyển 10 bước.","Chú mèo chạm biên.","Hết thời gian.","Chú mèo chưa chạm biên."],"a":1},{"id":"q4b","type":"match","q":"Điền các bước vào các vị trí của sơ đồ khối Hình 6.10 để mô tả thuật toán của bạn Khoa.","k":"① Chưa chạm biên? · ② Đúng · ③ Di chuyển 10 bước (rồi quay lại hình thoi) · ④ Sai · ⑤ Dừng lại.","items":[["① Hình thoi",2],["② Nhãn mũi tên đi xuống",3],["③ Hình chữ nhật dưới hình thoi",1],["④ Nhãn mũi tên bên phải",4],["⑤ Hình chữ nhật cuối cùng",5]],"opts":["1) Di chuyển 10 bước","2) Chưa chạm biên?","3) Đúng","4) Sai","5) Dừng lại"]},{"id":"lt1","type":"open","q":"Em hãy trình bày các câu sau đây dưới dạng sơ đồ khối cấu trúc rẽ nhánh: a) Nếu có kẻ trên mạng đe doạ thì em cần nói cho cha mẹ biết. b) Nếu nhận được thư điện tử có đính kèm tệp từ địa chỉ không quen biết thì em không nên mở tệp đính kèm. c) Nếu có tin nhắn từ người không quen biết yêu cầu gửi thông tin cá nhân thì em không nên gửi.","k":"Cả ba câu đều là <b>rẽ nhánh dạng thiếu</b>. a) “Có kẻ đe doạ?” → Đúng: “Nói cho cha mẹ biết”. b) “Thư từ địa chỉ lạ có tệp đính kèm?” → Đúng: “Không mở tệp”. c) “Người lạ xin thông tin cá nhân?” → Đúng: “Không gửi”. Nhánh Sai: đi tiếp.","label":"Luyện tập – Câu 1"},{"id":"lt2","type":"sort","q":"Trong các câu sau đây, câu nào có thể biểu diễn bằng sơ đồ khối có cấu trúc lặp?","k":"Chỉ <b>b</b> là cấu trúc lặp: “Chưa hết bài tập?” → Đúng: “Làm một bài tập” rồi quay lại kiểm tra; Sai: dừng. (a: rẽ nhánh dạng thiếu; c: rẽ nhánh dạng đủ.)","cats":["Cấu trúc lặp","Không phải lặp"],"items":[["a) Nếu sáng mai trời mưa, em sẽ mang theo áo mưa.",1],["b) Nếu vẫn chưa làm hết bài tập, em phải làm bài tập đến khi nào hết.",0],["c) Nếu được nghỉ ba ngày vào dịp Tết Dương lịch thì gia đình em sẽ đi du lịch, còn không sẽ có kế hoạch khác.",1]]},{"id":"lt3","type":"match","q":"Quan sát hai sơ đồ khối trong Hình 6.11a, Hình 6.11b và cho biết mỗi sơ đồ khối mô tả cấu trúc nào?","k":"Hình 6.11a: <b>lặp</b> (ném bóng xong quay lại kiểm tra, ném đến khi trúng). Hình 6.11b: <b>rẽ nhánh dạng thiếu</b> (chỉ ném một lần nếu chưa trúng).","items":[["Hình 6.11a",4],["Hình 6.11b",2]],"opts":["1) Cấu trúc tuần tự","2) Cấu trúc rẽ nhánh dạng thiếu","3) Cấu trúc rẽ nhánh dạng đủ","4) Cấu trúc lặp"]},{"id":"vd1","type":"open","q":"Bạn An cho rằng: “Sơ đồ khối ở Hình 6.12a thể hiện rằng nếu chưa hiểu bài thì việc đọc lại sách chỉ thực hiện một lần rồi làm bài tập. Còn sơ đồ khối ở Hình 6.12b thể hiện rằng nếu chưa hiểu bài thì việc đọc lại sách và làm bài tập sẽ thực hiện nhiều lần”. Em có đồng ý với ý kiến bạn An không? Nếu phải sửa nhận xét đó, em sẽ sửa như thế nào?","k":"Ý thứ nhất <b>đúng</b> (6.12a là rẽ nhánh dạng thiếu). Ý thứ hai cần sửa: ở 6.12b chỉ <b>đọc lại sách</b> được lặp lại đến khi hiểu bài; <b>làm bài tập chỉ thực hiện một lần</b> sau khi đã hiểu bài.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Trong trò chơi ở phần khởi động, việc tính điểm cho mỗi cặp chơi là một hoạt động lặp. Hãy chỉ rõ công việc được lặp lại và vẽ sơ đồ khối cấu trúc lặp của hoạt động này.","k":"Công việc lặp lại: đọc phiếu, trả lời và cộng điểm nếu đúng. Sơ đồ: “Còn thời gian?” → Đúng: “Đọc phiếu và trả lời” → “Trả lời đúng?” (Đúng: cộng 1 điểm) → quay lại; Sai: dừng, thông báo điểm.","label":"Vận dụng – Câu 2"},{"id":"vd3","type":"open","q":"Cô giáo điểm danh bằng cách gọi tên từng bạn trong danh sách lớp. Nếu bạn nào trả lời có thì cô giáo gọi tên bạn tiếp theo, còn không thì cô giáo đánh dấu vắng mặt và gọi tên bạn tiếp theo. Việc điểm danh của cô giáo có thể mô tả bằng những cấu trúc nào? Em hãy vẽ sơ đồ khối mô tả các cấu trúc đó.","k":"<b>Lặp</b> (“Còn bạn chưa gọi?” → gọi tên bạn tiếp theo) kết hợp <b>rẽ nhánh dạng thiếu</b> bên trong (“Bạn trả lời có?” → Sai: đánh dấu vắng mặt). Hết danh sách thì dừng.","label":"Vận dụng – Câu 3"}],"the":[{"t":"Cấu trúc tuần tự, rẽ nhánh","b":"<ul><li><b>Cấu trúc tuần tự</b>: thực hiện lần lượt các lệnh theo trình tự từ bắt đầu đến kết thúc.</li><li><b>Rẽ nhánh dạng thiếu</b>: nếu điều kiện đúng thì thực hiện lệnh.</li><li><b>Rẽ nhánh dạng đủ</b>: nếu điều kiện đúng thì thực hiện lệnh 1, nếu sai thì thực hiện lệnh 2.</li></ul>"},{"t":"Cấu trúc lặp","b":"<ul><li>Cấu trúc lặp dùng để mô tả các bước của thuật toán được thực hiện lặp lại nhiều lần.</li><li>Trong cấu trúc lặp, bao giờ cũng có khâu kiểm tra điều kiện kết thúc quá trình lặp.</li><li><b>Ba cấu trúc tuần tự, rẽ nhánh và lặp là đủ để mô tả mọi thuật toán.</b></li></ul>"}]},"tin6-chuong-trinh-may-tinh":{"id":"tin6-bai17","ten":"Bài 17. Chương trình máy tính","cau":[{"id":"kd","type":"open","q":"Chơi trò “Làm theo chỉ dẫn” theo cặp: một bạn nhìn bức tranh đơn giản và đưa ra từng chỉ dẫn, bạn kia vẽ lại mà không được nhìn tranh. So sánh hai bức tranh: các chỉ dẫn có rõ ràng không, bạn vẽ có làm đúng chỉ dẫn không?","k":"Bức tranh giống nhau khi chỉ dẫn <b>rõ ràng, đúng thứ tự</b> và người vẽ <b>hiểu, làm đúng</b> từng chỉ dẫn. Chỉ dẫn mơ hồ (“vẽ một bông hoa”) dễ cho kết quả khác.","label":"Khởi động – Làm theo chỉ dẫn"},{"id":"hd1","type":"open","q":"Nếu thuật toán được chuyển giao cho máy tính thực hiện thì theo em, làm thế nào để máy tính có thể hiểu và thực hiện được?","k":"Phải viết thuật toán bằng một <b>ngôn ngữ lập trình</b> mà máy tính hiểu được (ví dụ Scratch), tức là tạo ra một <b>chương trình</b>.","label":"HĐ1 – Thực hiện thuật toán"},{"id":"q1","type":"match","q":"Dựa vào chương trình tính tổng hai số bằng ngôn ngữ tự nhiên và chương trình Scratch ở Hình 6.13, ghép mỗi công việc với bước mô tả và các câu lệnh Scratch tương ứng.","k":"Nhập đầu vào: bước 1 ↔ lệnh ③④⑤⑥ (hỏi và đặt a, b). Xử lí: bước 2 ↔ lệnh ⑦ (đặt tong là a + b). Đầu ra: bước 3 ↔ lệnh ⑧ (nói tong). Lệnh ①② là bắt đầu chương trình và lời chào.","items":[["Nhập dữ liệu đầu vào",1],["Xử lí",2],["Thông báo đầu ra",3]],"opts":["a) Bước 1. Nhập hai số a và b – lệnh ③ ④ ⑤ ⑥","b) Bước 2. tong = a + b – lệnh ⑦","c) Bước 3. Thông báo giá trị của tong – lệnh ⑧"]},{"id":"th1","type":"open","q":"Ba bạn An, Minh, Khoa làm thiệp chúc mừng để bán lấy tiền mua sách tặng các bạn vùng khó khăn. Gọi số tiền bán được là a, số tiền mua vật liệu là b. Em hãy xác định đầu vào, đầu ra của bài toán tính số tiền lãi thu được hoặc số tiền bị lỗ.","k":"Đầu vào: hai số <b>a, b</b>. Đầu ra: <b>số tiền lãi hoặc số tiền bị lỗ</b>. Nếu a ≥ b thì tiền lãi = a − b, còn không thì tiền bị lỗ = b − a.","label":"Thực hành – Đầu vào, đầu ra"},{"id":"th2","type":"mcq","q":"Chạy chương trình tính tiền bán thiệp với số tiền bán được a = 150 000 đồng, số tiền mua vật liệu b = 200 000 đồng. Chương trình sẽ thông báo gì?","k":"<b>B</b>. a ≥ b sai (150 000 &lt; 200 000) nên đi theo nhánh Sai: tiền bị lỗ = b − a = 50 000.","o":["Số tiền lãi là 50 000","Số tiền bị lỗ là 50 000","Số tiền lãi là 350 000","Số tiền bị lỗ là 0"],"a":1},{"id":"th3","type":"open","q":"Tạo chương trình Scratch tính tiền bán thiệp theo sơ đồ khối Hình 6.14 rồi chạy thử với hai bộ dữ liệu (một bộ có lãi, một bộ bị lỗ). Ghi lại dữ liệu em đã nhập và kết quả chương trình thông báo.","k":"Ví dụ: a = 300 000, b = 180 000 → “Số tiền lãi là 120 000”; a = 100 000, b = 120 000 → “Số tiền bị lỗ là 20 000”.","label":"Thực hành – Tạo chương trình"},{"id":"lt1","type":"mcq","q":"Tìm câu sai.","k":"<b>C</b> sai: máy tính thực hiện các lệnh <b>theo đúng trình tự</b> trong chương trình.","o":["Chương trình máy tính là một dãy các lệnh mà máy tính có thể hiểu và thực hiện được.","Chương trình máy tính được viết bằng ngôn ngữ lập trình.","Máy tính có thể thực hiện các lệnh trong chương trình theo trình tự tuỳ ý."],"a":2},{"id":"lt2","type":"open","q":"Cho chương trình Scratch như ở Hình 6.15. a) Chương trình đó thực hiện thuật toán nào? b) Xác định đầu vào, đầu ra của thuật toán đó. d) Trình bày thuật toán bằng sơ đồ khối.","k":"a) Tính <b>điểm trung bình</b> ba môn Toán, Văn, Tiếng Anh và thông báo khen nếu điểm trung bình lớn hơn 8.0. b) Đầu vào: ba điểm a, b, c; đầu ra: lời thông báo. d) Bắt đầu → [nhập a, b, c] → DTB ← (a + b + c) : 3 → ◇ DTB &gt; 8.0? Đúng: [“Bạn được thưởng ngôi sao”], Sai: [“Bạn cố gắng lên nhé”] → Kết thúc.","label":"Luyện tập – Câu 2a, b, d"},{"id":"lt2c","type":"mcq","q":"Với chương trình ở Hình 6.15, nếu nhập điểm Toán 8, điểm Văn 8, điểm Tiếng Anh 8 thì chương trình nói gì?","k":"<b>B</b>. DTB = (8 + 8 + 8) : 3 = 8; điều kiện DTB &gt; 8.0 <b>sai</b> nên nói “Bạn cố gắng lên nhé”. Ví dụ khác: 9, 8, 10 → DTB = 9 → “Bạn được thưởng ngôi sao”.","o":["Bạn được thưởng ngôi sao","Bạn cố gắng lên nhé","Không nói gì","8.0"],"a":1},{"id":"lt3","type":"open","q":"Cho chương trình Scratch như ở Hình 6.16. a) Chương trình đó thực hiện công việc gì? b) Các cấu trúc điều khiển tuần tự, rẽ nhánh và lặp có được sử dụng trong chương trình không? Hãy nêu các câu lệnh trong chương trình thể hiện cấu trúc đó.","k":"a) Nhân vật nói “Xin chào!” trong 2 giây, rồi 10 lần: đi 10 bước, chơi trống, nếu chạm biên thì bật lại. b) <b>Tuần tự</b>: các khối xếp nối tiếp; <b>lặp</b>: “lặp lại 10 lần”; <b>rẽ nhánh</b> nằm trong khối “nếu chạm biên, bật lại” (chạm biên mới bật lại).","label":"Luyện tập – Câu 3"},{"id":"vd1","type":"open","q":"Em hãy vẽ sơ đồ khối mô tả thuật toán tìm số lớn hơn trong hai số a và b. Từ sơ đồ khối, hãy viết chương trình Scratch thực hiện thuật toán.","k":"Bắt đầu → [nhập a, b] → ◇ a &gt; b? Đúng: [thông báo a], Sai: [thông báo b] → Kết thúc. Scratch: hỏi, đặt a, b; <i>nếu a &gt; b thì nói a, còn không thì nói b</i>.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Em hãy viết chương trình Scratch thực hiện thuật toán tính trung bình cộng của ba số.","k":"Hỏi và đặt a, b, c → đặt TBC là (a + b + c) / 3 → nói TBC. Ví dụ nhập 4, 5, 9 → nói 6.","label":"Vận dụng – Câu 2"}],"the":[{"t":"Chương trình","b":"<ul><li>Máy tính thực hiện công việc theo chương trình.</li><li>Chương trình là mô tả thuật toán để máy tính “hiểu” và thực hiện được.</li><li>Chương trình dựa trên các dữ liệu đầu vào, tiến hành các bước xử lí để trả lại kết quả đầu ra.</li></ul>"}]},"tin6-dinh-dang-van-ban":{"id":"tin6-bai11","ten":"Bài 11. Định dạng văn bản","cau":[{"id":"kd1","type":"open","q":"Theo bạn Khoa, làm cuốn sổ lưu niệm trên máy tính có những thuận lợi gì so với viết tay?","k":"Gửi cho thầy cô, các bạn xem trước để góp ý; dễ sửa lại; in ra cho mỗi bạn; lưu tệp trong máy để phòng khi cuốn sổ in bị hỏng hoặc thất lạc.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Dựa vào sơ đồ tư duy trình bày nội dung cuốn sổ lưu niệm ở Bài 10, em hãy lựa chọn các phần mềm cần sử dụng để tạo nội dung cho cuốn sổ trên máy tính.","k":"Phần mềm <b>soạn thảo văn bản</b> (Word, Google Docs,…) cho bài viết cảm nghĩ, danh sách thành viên; phần mềm xử lí ảnh; phần mềm sơ đồ tư duy;…","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Các phần mềm đó cần có chức năng gì để giúp em hoàn thành công việc?","k":"Tạo và định dạng văn bản, chèn hình ảnh, chỉnh sửa nội dung, lưu và in văn bản.","label":"HĐ1 – Câu 2"},{"id":"cn","type":"sort","q":"Mỗi chức năng dưới đây là chức năng cơ bản hay chức năng nâng cao của phần mềm soạn thảo văn bản?","k":"<b>Cơ bản</b>: tạo và định dạng, biên tập, lưu trữ, in. <b>Nâng cao</b>: theo dõi thay đổi, lưu trữ đám mây, làm việc cộng tác.","cats":["Cơ bản","Nâng cao"],"items":[["Tạo và định dạng văn bản",0],["Biên tập, chỉnh sửa nội dung",0],["Lưu trữ văn bản",0],["In văn bản",0],["Xem lại và theo dõi sự thay đổi của tài liệu",1],["Lưu trữ tài liệu nhờ công nghệ đám mây",1],["Làm việc cộng tác với người khác trên cùng một tài liệu",1]]},{"id":"p48","type":"open","q":"Em sẽ sử dụng những chức năng nào của phần mềm soạn thảo văn bản để tạo nội dung cho cuốn sổ lưu niệm?","k":"Gõ và định dạng văn bản (phông chữ, căn lề), chèn hình ảnh, định dạng trang, lưu và in; có thể làm việc cộng tác với các bạn qua đám mây.","label":"Câu hỏi tr.48"},{"id":"dt","type":"sort","q":"Mỗi thao tác dưới đây thuộc định dạng đoạn văn bản hay định dạng trang văn bản?","k":"<b>Đoạn</b>: thẻ Home, nhóm Paragraph (căn lề, thụt lề, khoảng cách dòng, khoảng cách đoạn). <b>Trang</b>: thẻ Page Layout, nhóm Page Setup (hướng trang, lề trang, khổ giấy).","cats":["Định dạng đoạn","Định dạng trang"],"items":[["Căn thẳng hai lề",0],["Tăng mức thụt lề trái",0],["Khoảng cách giữa các dòng trong đoạn",0],["Khoảng cách giữa các đoạn",0],["Chọn hướng trang đứng (Portrait)",1],["Đặt lề trên, lề dưới, lề trái, lề phải (Margins)",1],["Chọn khổ giấy A4 (Size)",1]]},{"id":"vt","type":"match","q":"Mỗi nhóm lệnh dưới đây nằm ở đâu trong Microsoft Word?","k":"Đoạn: Home/Paragraph. Trang: Page Layout/Page Setup. In: File/Print (chọn máy in, nhập trang cần in, xem trước khi in).","items":[["Các lệnh định dạng đoạn văn bản",1],["Các lệnh định dạng trang văn bản",2],["Lệnh in văn bản",3]],"opts":["Thẻ Home, nhóm lệnh Paragraph","Thẻ Page Layout, nhóm lệnh Page Setup","Thẻ File, lệnh Print"]},{"id":"th1","type":"order","q":"Sắp xếp các bước căn giữa tiêu đề, hình ảnh và dòng “Tớ là An” (dùng nút ↑ ↓).","k":"<b>Chọn</b> phần văn bản → thẻ <b>Home</b> → nút <b>căn giữa</b>. Thực hiện tương tự để căn thẳng hai lề cho các đoạn văn.","items":{"a":"Chọn dòng tiêu đề, hình ảnh và dòng Tớ là An","b":"Nháy chuột vào thẻ Home","c":"Chọn nút căn giữa trong nhóm Paragraph"},"ans":["a","b","c"],"start":["c","b","a"]},{"id":"th2","type":"order","q":"Sắp xếp các bước chọn hướng trang đứng (dùng nút ↑ ↓).","k":"Page Layout → Page Setup → Orientation → <b>Portrait</b>. Chọn lề trang: Page Layout → Page Setup → Margins → <b>Normal</b>.","items":{"a":"Nháy chuột chọn thẻ Page Layout","b":"Tìm nhóm lệnh Page Setup","c":"Nháy chuột chọn Orientation và chọn Portrait"},"ans":["a","b","c"],"start":["c","a","b"]},{"id":"th3","type":"open","q":"Tham khảo bài viết của bạn An (Hình 5.8), soạn một bài viết cảm nghĩ của em trên phần mềm soạn thảo văn bản: nhập nội dung, chèn hình ảnh, căn lề, chọn hướng trang, lề trang, xem trang in và lưu tệp với tên CamNghiVeBan.docx. Ghi lại các định dạng em đã dùng.","k":"Tiêu đề, ảnh căn giữa; các đoạn căn thẳng hai lề; hướng trang đứng; lề Normal; lưu bằng File/Save với tên CamNghiVeBan.docx.","label":"Thực hành – Bài viết cảm nghĩ"},{"id":"lt1","type":"sort","q":"Em hãy chọn hướng trang phù hợp cho các văn bản sau.","k":"Đơn, báo cáo: <b>trang đứng</b>. Sách ảnh phong cảnh (ảnh rộng): <b>trang ngang</b>. c) Sổ lưu niệm của lớp: có thể chọn trang đứng hoặc ngang tuỳ cách trình bày.","cats":["Trang đứng","Trang ngang"],"items":[["a) Đơn xin nghỉ học.",0],["b) Báo cáo tổng kết năm học của lớp.",0],["d) Sách ảnh chứa ảnh phong cảnh.",1]]},{"id":"lt2","type":"mcq","q":"Em chọn loại căn lề nào khi trình bày nội dung bài thơ lục bát trên phần mềm soạn thảo văn bản? Tại sao?","k":"<b>Căn giữa</b>: câu 6 chữ và câu 8 chữ cân đối hai bên, bài thơ đẹp, dễ đọc (cũng có thể căn trái và thụt lề câu 6 chữ).","o":["Căn thẳng lề trái.","Căn giữa.","Căn thẳng lề phải.","Căn thẳng hai lề."],"a":1},{"id":"lt3","type":"open","q":"Em hãy soạn thảo Đơn xin nghỉ học và thực hiện các thao tác định dạng hợp lí. Ghi lại các định dạng em đã dùng.","k":"Quốc hiệu, tiêu ngữ, tên đơn căn giữa; nội dung căn thẳng hai lề hoặc lề trái; chữ kí căn phải; trang đứng, khổ A4, lề Normal.","label":"Luyện tập – Câu 3"},{"id":"vd","type":"open","q":"Với nội dung cuốn sổ lưu niệm của lớp, em hãy: a) soạn thảo thêm nội dung (bài viết cảm nghĩ, bài viết giới thiệu hoạt động, sự kiện,…); b) chèn thêm hình ảnh minh hoạ; c) căn lề và định dạng trang để có được bố cục hợp lí và đẹp; d) lưu lại tệp để dùng cho việc tạo cuốn sổ lưu niệm của lớp. Ghi lại tên tệp và nội dung em đã soạn.","k":"Học sinh nêu tên tệp, nội dung, hình ảnh đã chèn và các định dạng đã dùng.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<p>Phần mềm soạn thảo văn bản có các chức năng cơ bản: tạo và định dạng văn bản; biên tập, chỉnh sửa nội dung; lưu trữ văn bản; in văn bản. Chức năng nâng cao: xem lại và theo dõi sự thay đổi của tài liệu; lưu trữ nhờ công nghệ đám mây; làm việc cộng tác với người khác.</p>"},{"t":"Ghi nhớ","b":"<ul><li>Định dạng đoạn văn bản: căn lề, thụt lề, khoảng cách giữa các dòng, giữa các đoạn (thẻ Home, nhóm Paragraph).</li><li>Định dạng trang văn bản: hướng trang, lề trang, khổ giấy (thẻ Page Layout, nhóm Page Setup).</li><li>In văn bản: thẻ File, lệnh Print.</li></ul>"}]},"tin6-hoan-thien-so-luu-niem":{"id":"tin6-bai14","ten":"Bài 14. Thực hành tổng hợp: Hoàn thiện sổ lưu niệm","cau":[{"id":"kd1","type":"open","q":"Qua các bài học trước, nhóm em đã có những tệp nội dung nào cho cuốn sổ lưu niệm? Hãy liệt kê và phân công các bạn trong nhóm (3–5 em).","k":"Ví dụ: CamNghiVeBan.docx (bài viết cảm nghĩ), danh sách thành viên (bảng), sơ đồ tư duy SoLuuNiem.emm, ảnh hoạt động,… Phân công: người tập hợp, người thu thập ảnh, người soạn thêm nội dung, người làm trang bìa.","label":"Khởi động"},{"id":"b1","type":"order","q":"Sắp xếp các thao tác tập hợp nội dung từ các tệp đã có vào tệp Soluuniem.docx (dùng nút ↑ ↓).","k":"Insert → Object (nhóm Text) → <b>Text from File…</b> → chọn tệp. Lặp lại cho từng tệp nội dung.","items":{"a":"Nháy chuột vào thẻ Insert","b":"Trong nhóm lệnh Text, chọn Object","c":"Chọn Text from File… rồi chọn tệp cần đưa vào"},"ans":["a","b","c"],"start":["c","b","a"]},{"id":"b2","type":"sort","q":"Khi soạn thảo, định dạng nội dung bổ sung, mỗi việc dưới đây dùng công cụ nào?","k":"<b>Home</b>: phông chữ, đoạn, Find/Replace. <b>Page Layout</b>: hướng trang, lề trang. <b>Insert</b>: hình ảnh, bảng, trang bìa.","cats":["Home","Page Layout","Insert"],"items":[["Định dạng chữ (màu sắc, cỡ chữ,…)",0],["Căn chỉnh lề đoạn văn bản",0],["Tìm kiếm và Thay thế để sửa lỗi",0],["Định dạng hướng trang, lề trang",1],["Bổ sung hình ảnh",2],["Chèn bảng",2]]},{"id":"b2o","type":"open","q":"Xem lại sơ đồ tư duy nội dung sổ lưu niệm đã tạo ở Bài 10 để rà soát. Nhóm em đã bổ sung thêm những thông tin, hình ảnh gì (thầy cô, hoạt động thể thao, văn hoá, văn nghệ, tham quan,…)?","k":"Ví dụ: bài viết về thầy cô giáo, ảnh hội thao, tiết mục văn nghệ 20/11, chuyến tham quan bảo tàng,…","label":"Bước 2 – Nội dung bổ sung"},{"id":"b3","type":"order","q":"Sắp xếp các bước tạo trang bìa cho cuốn sổ lưu niệm (dùng nút ↑ ↓).","k":"Insert → Pages → <b>Cover Page</b> → chọn mẫu → sửa nội dung (Sổ lưu niệm lớp 6A, năm học) và thay hình.","items":{"a":"Nháy chuột vào thẻ Insert","b":"Trong nhóm lệnh Pages, chọn Cover Page","c":"Chọn một mẫu trang bìa","d":"Sửa lại nội dung và thay hình trang bìa"},"ans":["a","b","c","d"],"start":["d","b","c","a"]},{"id":"b4","type":"open","q":"Hãy tưởng tượng các em đã là người lớn. Cả lớp gặp lại nhau trong một lần họp lớp ở tương lai khi đã 50 tuổi. Hãy cùng xem lại cuốn sổ lưu niệm và nghĩ về câu hỏi “Tại sao chúng ta lại đưa nội dung này vào sổ?”. Nhóm em giữ lại, bổ sung hay bỏ bớt nội dung nào?","k":"Học sinh nêu lí do giữ lại các nội dung có ý nghĩa (kỉ niệm, thông tin liên lạc, cảm nghĩ), bỏ bớt nội dung trùng lặp, bổ sung nội dung còn thiếu.","label":"Bước 4 – Xem lại nội dung"},{"id":"dg","type":"open","q":"Nhóm em chia sẻ sản phẩm với cả lớp. Em thích nhất sản phẩm của nhóm nào? Vì sao? Cuốn sổ chung của lớp nên lấy thêm nội dung gì từ các nhóm?","k":"Đánh giá theo bảng kiểm: đủ nội dung, có trang bìa, định dạng đẹp, bố cục hợp lí, không lỗi chính tả, có hình ảnh, bảng.","label":"Chia sẻ và đánh giá"}],"the":[{"t":"Ghi nhớ","b":"<p>Để hoàn thiện một sản phẩm từ nhiều nội dung, em cần: tập hợp các nội dung đã có (Insert/Object/Text from File); bổ sung, định dạng nội dung (định dạng chữ, căn lề, hướng trang, lề trang, hình ảnh, bảng, tìm kiếm và thay thế); tạo trang bìa (Insert/Cover Page); xem lại nội dung, chia sẻ và trao đổi để hoàn thiện.</p>"}]},"tin6-internet":{"id":"tin6-bai5","ten":"Bài 5. Internet","cau":[{"id":"kd1","type":"open","q":"Nhờ đâu mẹ An có thể đặt vé máy bay mà không cần đến phòng vé? Em hãy kể một việc mà gia đình em đã làm nhờ Internet.","k":"Nhờ <b>Internet</b>: các hãng hàng không đăng thông tin chuyến bay, giờ bay, giá vé trên Internet; người dùng tìm thông tin, đặt vé và thanh toán trực tuyến.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Em hiểu Internet là gì?","k":"Internet là <b>mạng liên kết các mạng máy tính</b> trên khắp thế giới.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Người sử dụng có thể làm được những gì khi truy cập Internet?","k":"Tìm kiếm, chia sẻ, lưu trữ và trao đổi thông tin; xem tin tức, học trực tuyến, gửi thư điện tử, mua bán, giải trí,…","label":"HĐ1 – Câu 2"},{"id":"p21","type":"match","q":"Thay các số (1)…(5) bằng một từ hoặc cụm từ thích hợp: a) Internet là mạng …(1)… các …(2)… máy tính trên khắp thế giới. b) Người sử dụng truy cập Internet để tìm kiếm, …(3)…, lưu trữ và trao đổi …(4)…. c) Có nhiều …(5)… thông tin khác nhau trên Internet.","k":"(1) liên kết; (2) mạng; (3) chia sẻ; (4) thông tin; (5) dịch vụ.","items":[["(1)",2],["(2)",5],["(3)",1],["(4)",3],["(5)",4]],"opts":["chia sẻ","liên kết","thông tin","dịch vụ","mạng"]},{"id":"hd2","type":"open","q":"Theo em Internet có những đặc điểm gì?","k":"Toàn cầu, tương tác, dễ tiếp cận, không chủ sở hữu; ngoài ra còn cập nhật, lưu trữ, đa dạng, ẩn danh.","label":"HĐ2 – Đặc điểm của Internet"},{"id":"dd","type":"match","q":"Ghép mỗi mô tả với đặc điểm chính phù hợp của Internet.","k":"Lần lượt: <b>toàn cầu</b>, <b>tương tác</b>, <b>dễ tiếp cận</b>, <b>không chủ sở hữu</b>.","items":[["Năm 2020 khoảng hơn một phần ba dân số thế giới ở hầu hết các quốc gia đang sử dụng Internet.",1],["Người dùng có thể tức thời nhận và gửi thông tin, khác với truyền thông một chiều của sách báo, truyền hình.",2],["Người dùng tìm kiếm, lưu trữ, trao đổi thông tin thuận lợi, nhanh chóng ở mọi lúc, mọi nơi.",3],["Internet không thuộc sở hữu hay do bất kì tổ chức hoặc cá nhân nào điều hành.",4]],"opts":["Tính toàn cầu","Tính tương tác","Tính dễ tiếp cận","Tính không chủ sở hữu"]},{"id":"p21a","type":"sort","q":"Internet có những đặc điểm chính nào dưới đây? Chọn Đúng (là đặc điểm chính) hoặc Sai.","k":"<b>A, B, D, F</b>. Tính lưu trữ và tính đa dạng là đặc điểm <b>khác</b>, không phải đặc điểm chính.","cats":["Đúng","Sai"],"items":[["A. Tính toàn cầu.",0],["B. Tính tương tác.",0],["C. Tính lưu trữ.",1],["D. Tính dễ tiếp cận.",0],["E. Tính đa dạng.",1],["F. Tính không chủ sở hữu.",0]]},{"id":"p21b","type":"open","q":"Trong các đặc điểm của Internet, em thích đặc điểm nào nhất? Vì sao?","k":"Học sinh nêu đặc điểm và lí do, ví dụ: thích tính dễ tiếp cận vì em có thể học, tìm tài liệu ở mọi lúc, mọi nơi.","label":"Câu hỏi tr.21 – Câu 2"},{"id":"hd3a","type":"open","q":"Em thường truy cập Internet để làm những việc gì?","k":"Ví dụ: học trực tuyến, tìm tư liệu làm bài tập, xem phim, nghe nhạc, chơi trò chơi, gửi thư cho bạn bè, giúp bố mẹ bán hàng trực tuyến,…","label":"HĐ3 – Câu 1"},{"id":"hd3b","type":"open","q":"Internet có những lợi ích gì?","k":"Trao đổi thông tin nhanh chóng, hiệu quả; học tập và làm việc trực tuyến; nguồn tài liệu phong phú; tiện ích phục vụ đời sống; vui chơi, giải trí.","label":"HĐ3 – Câu 2"},{"id":"p22","type":"sort","q":"Em hãy chọn những việc mà em có thể làm với Internet.","k":"<b>a, b, d, e</b>. Chơi đá bóng là hoạt động ngoài đời thực.","cats":["Làm được với Internet","Không"],"items":[["a) Học ngoại ngữ trực tuyến với người nước ngoài.",0],["b) Nghe nhạc, xem phim trực tuyến.",0],["c) Chơi đá bóng để nâng cao sức khoẻ.",1],["d) Tìm kiếm tài liệu học tập.",0],["e) Gửi thư điện tử.",0]]},{"id":"lt1","type":"mcq","q":"Internet là mạng:","k":"<b>C</b>. Internet kết nối nhiều mạng máy tính trên phạm vi toàn cầu.","o":["Kết nối hai máy tính với nhau.","Kết nối các máy tính trong một nước.","Kết nối nhiều mạng máy tính trên phạm vi toàn cầu.","Kết nối các máy tính trong một thành phố."],"a":2},{"id":"lt2","type":"open","q":"Để máy tính kết nối được Internet ta cần làm gì?","k":"Đăng kí với một <b>nhà cung cấp dịch vụ Internet (ISP)</b> để được hỗ trợ cài đặt và cấp quyền truy cập; máy tính được kết nối qua ISP.","label":"Luyện tập – Câu 2"},{"id":"vd1","type":"open","q":"Em hãy lấy ví dụ cho thấy Internet mang lại lợi ích cho việc học tập và giải trí.","k":"Học tập: học trực tuyến, xem bài giảng, tra từ điển, tìm tư liệu. Giải trí: nghe nhạc, xem phim, đọc truyện, chơi trò chơi trí tuệ.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Em hãy giải thích tại sao Internet lại được sử dụng rộng rãi và ngày càng phát triển.","k":"Vì Internet có nhiều lợi ích (trao đổi nhanh, nguồn tài liệu phong phú, học tập, làm việc, giải trí,…) và các đặc điểm toàn cầu, tương tác, dễ tiếp cận, không chủ sở hữu → ai cũng có thể dùng ở mọi lúc, mọi nơi.","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Internet là mạng liên kết các mạng máy tính trên khắp thế giới.</li><li>Máy tính có thể được kết nối với Internet thông qua một nhà cung cấp dịch vụ Internet.</li><li>Người sử dụng truy cập Internet để tìm kiếm, chia sẻ, lưu trữ và trao đổi thông tin.</li><li>Có nhiều dịch vụ thông tin khác nhau trên Internet: WWW, tìm kiếm, thư điện tử,…</li></ul>"},{"t":"Ghi nhớ","b":"<p>Đặc điểm chính của Internet: tính toàn cầu, tính tương tác, tính dễ tiếp cận, tính không chủ sở hữu.</p>"},{"t":"Lợi ích của Internet","b":"<ul><li>Trao đổi thông tin nhanh chóng, hiệu quả.</li><li>Học tập và làm việc trực tuyến.</li><li>Cung cấp nguồn tài liệu phong phú.</li><li>Cung cấp các tiện ích phục vụ đời sống.</li><li>Là phương tiện vui chơi, giải trí.</li></ul>"}]},"tin6-mang-may-tinh":{"id":"tin6-bai4","ten":"Bài 4. Mạng máy tính","cau":[{"id":"kd1","type":"open","q":"Theo em, vì sao những nơi có đường đi qua thường trù phú hơn những nơi khác? Đường giao thông có vai trò gì?","k":"Đường <b>kết nối</b> mọi người, mọi nơi với nhau, giúp đi lại, trao đổi hàng hoá → nơi có đường thường phát triển hơn. Nhiều con đường nối với nhau tạo thành <b>mạng lưới</b>.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Em hãy kể ra một số mạng lưới, giống như mạng giao thông đường bộ.","k":"Mạng đường sắt, mạng đường thuỷ, mạng ống nước, mạng tải điện, mạng điện thoại, mạng máy tính,…","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Những gì được vận chuyển trên mạng lưới đó?","k":"Đường bộ, đường sắt, đường thuỷ: người, hàng hoá. Ống nước: nước. Tải điện: điện. Điện thoại: tiếng nói. Mạng máy tính: dữ liệu, thông tin.","label":"HĐ1 – Câu 2"},{"id":"hd1c","type":"sort","q":"Điểm chung của những mạng lưới đó là gì? Chọn Đúng hoặc Sai cho từng phương án.","k":"<b>A, B, C</b>. Mạng lưới có nhiều thành viên, <b>kết nối</b> các thành viên và <b>chia sẻ</b> tài nguyên cho nhiều người. “Nhiều đường cắt nhau” không phải đặc điểm chung.","cats":["Đúng","Sai"],"items":[["A. Có nhiều thành viên.",0],["B. Chia sẻ tài nguyên.",0],["C. Kết nối các thành viên.",0],["D. Có nhiều đường cắt nhau.",1]]},{"id":"hd2a","type":"open","q":"Mạng máy tính chia sẻ những gì?","k":"Chia sẻ <b>dữ liệu</b> (tệp ảnh, văn bản, video,…) và <b>thiết bị</b> (máy in, máy quét,…).","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Em hãy nêu một số ví dụ về lợi ích của mạng máy tính.","k":"Ví dụ: gửi tệp ảnh từ máy Minh sang máy An; cả phòng máy dùng chung một máy in; học trực tuyến, nhắn tin, gọi video với người ở xa.","label":"HĐ2 – Câu 2"},{"id":"ln","type":"sort","q":"Mỗi ví dụ dưới đây thể hiện lợi ích nào của mạng máy tính?","k":"Mạng máy tính giúp người dùng <b>trao đổi dữ liệu</b> và <b>dùng chung thiết bị</b> trên mạng.","cats":["Trao đổi dữ liệu","Dùng chung thiết bị"],"items":[["Minh gửi tệp ảnh từ máy của mình sang máy của An",0],["Cô giáo gửi bài tập cho cả lớp qua mạng",0],["Cả phòng máy in tài liệu bằng một máy in",1],["Nhiều máy tính dùng chung một máy quét",1]]},{"id":"p17","type":"open","q":"Em hãy thảo luận với bạn về lợi ích của mạng máy tính.","k":"Liên lạc với nhau để trao đổi thông tin; chia sẻ dữ liệu; dùng chung các thiết bị (máy in, máy quét,…) → tiết kiệm, nhanh chóng.","label":"Câu hỏi tr.17"},{"id":"hd3a","type":"open","q":"Quan sát Hình 2.1 và cho biết những thiết bị nào đang được nối vào mạng?","k":"Hai máy tính để bàn, máy quét, máy tính xách tay, máy chủ, máy in, điện thoại di động, bộ chuyển mạch, bộ định tuyến không dây.","label":"HĐ3 – Câu 1"},{"id":"hd3b","type":"open","q":"Các thiết bị đó được nối với nhau như thế nào? Qua các thiết bị trung gian nào?","k":"Máy tính để bàn, máy chủ, máy in, máy quét nối bằng <b>dây</b> vào <b>bộ chuyển mạch</b>; máy tính xách tay, điện thoại nối <b>không dây</b> qua <b>bộ định tuyến không dây</b>.","label":"HĐ3 – Câu 2"},{"id":"tp","type":"sort","q":"Xếp mỗi mục dưới đây vào thành phần phù hợp của mạng máy tính.","k":"<b>Thiết bị đầu cuối</b>: điểm xuất phát, đích đến (máy tính, điện thoại, máy in,…). <b>Thiết bị kết nối</b>: đường truyền, bộ chia, bộ chuyển mạch, bộ định tuyến,… <b>Phần mềm mạng</b>: như luật giao thông, giúp dữ liệu đi đến đúng nơi.","cats":["Thiết bị đầu cuối","Thiết bị kết nối","Phần mềm mạng"],"items":[["Máy tính để bàn",0],["Điện thoại thông minh",0],["Máy in",0],["Máy ảnh",0],["Bộ chuyển mạch (Switch)",1],["Bộ định tuyến (Router)",1],["Dây cáp mạng",1],["Điểm truy cập không dây (Access Point)",1],["Ứng dụng truyền thông trên thiết bị đầu cuối",2],["Phần mềm điều khiển quá trình truyền dữ liệu",2]]},{"id":"p19a","type":"sort","q":"Quan sát Hình 2.1, xếp mỗi thiết bị vào nhóm thiết bị đầu cuối hoặc thiết bị kết nối.","k":"a) Đầu cuối: máy tính để bàn, máy quét, máy tính xách tay, máy chủ, máy in, điện thoại di động. b) Kết nối: bộ chuyển mạch, bộ định tuyến không dây.","cats":["Thiết bị đầu cuối","Thiết bị kết nối"],"items":[["Máy tính để bàn",0],["Máy quét",0],["Máy tính xách tay",0],["Máy chủ",0],["Máy in",0],["Điện thoại di động",0],["Bộ chuyển mạch",1],["Bộ định tuyến không dây",1]]},{"id":"p19b","type":"open","q":"Em hãy kể tên một số cách kết nối không dây mà em biết.","k":"Wi-Fi, Bluetooth, mạng di động 3G/4G/5G, hồng ngoại, NFC,…","label":"Câu hỏi tr.19 – Câu 2"},{"id":"p19c","type":"open","q":"Em hãy nêu ví dụ cho thấy kết nối không dây thuận tiện hơn kết nối có dây.","k":"Ví dụ: hành khách trên xe khách dùng điện thoại truy cập Internet; mang máy tính xách tay đi khắp nhà vẫn vào mạng; ở sân bay, nhà ga, trường học dùng Wi-Fi miễn phí; không phải khoan đục tường, đi dây.","label":"Câu hỏi tr.19 – Câu 3"},{"id":"lt1","type":"sort","q":"Máy tính kết nối với nhau để làm gì? Chọn Đúng hoặc Sai cho từng phương án.","k":"<b>A, C</b>. Kết nối mạng để chia sẻ thiết bị và trao đổi dữ liệu.","cats":["Đúng","Sai"],"items":[["A. Chia sẻ các thiết bị.",0],["B. Tiết kiệm điện.",1],["C. Trao đổi dữ liệu.",0],["D. Thuận lợi cho việc sửa chữa.",1]]},{"id":"lt2","type":"sort","q":"Thiết bị có kết nối không dây ở Hình 2.2 là gì? Chọn Đúng hoặc Sai.","k":"<b>B, C</b>. Máy tính xách tay và điện thoại di động kết nối không dây với bộ định tuyến không dây; máy tính để bàn và bộ định tuyến nối bằng dây.","cats":["Đúng","Sai"],"items":[["A. Máy tính để bàn.",1],["B. Máy tính xách tay.",0],["C. Điện thoại di động.",0],["D. Bộ định tuyến.",1]]},{"id":"vd1","type":"open","q":"Phòng thư viện của trường có 5 máy tính cần kết nối thành một mạng. Em hãy vẽ (hoặc mô tả) hai cách khác để kết nối chúng thành một mạng.","k":"Ví dụ: cách 1 – cả 5 máy nối vào <b>một bộ chuyển mạch</b> (hình sao); cách 2 – nối các máy thành <b>một vòng</b>; cách 3 – dùng <b>bộ định tuyến không dây</b>. Miễn là từ mỗi máy đều đi được tới mọi máy khác.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Nhà bạn An có điện thoại di động của bố, của mẹ và một máy tính xách tay đang cùng truy cập mạng Internet. Các thiết bị đó có đang được kết nối thành một mạng máy tính không? Nếu có, hãy chỉ ra các thiết bị đầu cuối và thiết bị kết nối.","k":"<b>Có</b>. Thiết bị đầu cuối: hai điện thoại, máy tính xách tay. Thiết bị kết nối: bộ định tuyến không dây (modem Wi-Fi), đường truyền.","label":"Vận dụng – Câu 2"}],"the":[{"t":"Mạng máy tính","b":"<ul><li>Hai hay nhiều máy tính và các thiết bị được kết nối để truyền thông tin cho nhau tạo thành một mạng máy tính.</li><li>Lợi ích của mạng máy tính: người sử dụng có thể liên lạc với nhau để trao đổi thông tin, chia sẻ dữ liệu và dùng chung các thiết bị trên mạng.</li></ul>"},{"t":"Các thành phần chính của mạng máy tính","b":"<p>Mạng máy tính gồm:</p><ul><li>Các thiết bị đầu cuối (máy tính, điện thoại, máy in, máy ảnh,…).</li><li>Các thiết bị kết nối (đường truyền dữ liệu, bộ chia, bộ chuyển mạch, bộ định tuyến,…).</li><li>Phần mềm mạng (ứng dụng truyền thông và phần mềm điều khiển quá trình truyền dữ liệu).</li></ul>"}]},"tin6-mang-thong-tin-toan-cau":{"id":"tin6-bai6","ten":"Bài 6. Mạng thông tin toàn cầu","cau":[{"id":"kd1","type":"open","q":"Khi truy cập Internet, em thường xem những thông tin gì? Các trang thông tin đó được nối với nhau như thế nào?","k":"Ví dụ: tin tức, truyện, bài hát, hình ảnh, video,… Các trang thông tin được <b>nối với nhau bằng liên kết</b> tạo thành một mạng giống mạng nhện bao trùm thế giới → World Wide Web.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Thông tin trong một cuốn sách được tổ chức như thế nào?","k":"Theo <b>trình tự</b>: chương, bài, mục, trang; có mục lục để tìm. Người đọc thường đọc lần lượt từng trang.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Em đã xem thông tin trên Internet chưa? Trên Internet có những dạng thông tin gì?","k":"Văn bản, hình ảnh, âm thanh, video,… thường được kết hợp trên cùng một trang và có <b>liên kết</b> tới trang khác.","label":"HĐ1 – Câu 2"},{"id":"kn","type":"match","q":"Ghép mỗi khái niệm với mô tả phù hợp.","k":"Trang siêu văn bản → trang web (có địa chỉ) → website (tập hợp trang web, địa chỉ trang chủ) → WWW (hệ thống các website).","items":[["Trang siêu văn bản",1],["Trang web",2],["Website",3],["Trang chủ",4],["World Wide Web",5]],"opts":["Trang văn bản đặc biệt, tích hợp nhiều dạng dữ liệu và chứa các liên kết","Trang siêu văn bản được gán một địa chỉ truy cập trên Internet","Tập hợp các trang web liên quan, truy cập qua một địa chỉ","Trang được mở ra đầu tiên khi truy cập một website","Hệ thống các website trên Internet (mạng thông tin toàn cầu)"]},{"id":"p24a","type":"mcq","q":"Trang siêu văn bản là:","k":"<b>B</b>. Trang siêu văn bản tích hợp nhiều dạng dữ liệu và chứa các liên kết.","o":["Trang văn bản thông thường không chứa liên kết.","Trang văn bản đặc biệt tích hợp nhiều dạng dữ liệu khác nhau và chứa các liên kết.","Trang văn bản đặc biệt tích hợp nhiều dạng dữ liệu khác nhau không chứa liên kết."],"a":1},{"id":"p24b","type":"open","q":"Hãy nêu địa chỉ một số website có nội dung phục vụ việc học tập.","k":"Ví dụ: https://vi.wikipedia.org, https://hoc10.vn, https://vtv7.vtv.vn, https://olm.vn, https://hoctot.nam.name.vn, website của trường em,…","label":"Câu hỏi tr.24 – Câu 2"},{"id":"p25a","type":"open","q":"Em hãy kể tên một số trình duyệt mà em biết.","k":"Google Chrome, Mozilla Firefox, Microsoft Edge, Safari, Cốc Cốc, Opera,…","label":"Câu hỏi tr.25 – Câu 1"},{"id":"p25b","type":"order","q":"Để truy cập một trang web ta cần làm thế nào? Sắp xếp các bước (dùng nút ↑ ↓).","k":"Mở trình duyệt → nhập địa chỉ trang web vào <b>thanh địa chỉ</b> → nhấn <b>Enter</b>.","items":{"a":"Nháy đúp chuột vào biểu tượng trình duyệt","b":"Nhập địa chỉ trang web vào ô địa chỉ","c":"Nhấn phím Enter"},"ans":["a","b","c"],"start":["c","a","b"]},{"id":"th1","type":"open","q":"Truy cập https://vi.wikipedia.org, gõ một từ hoặc cụm từ (ví dụ: Internet) vào ô tìm kiếm. Ghi lại tên bài viết và hai thông tin em thấy hay.","k":"Học sinh ghi tên bài viết và 2 thông tin chính. Nêu được các phần chính của trang: tên và biểu tượng trang, ô tìm kiếm, các mục chính, bài viết chọn lọc, bạn có biết…","label":"Thực hành – Tra cứu Wikipedia"},{"id":"th2","type":"open","q":"Truy cập https://nchmf.gov.vn (thời tiết) hoặc https://vtvgo.vn (thời sự). Ghi lại thông tin thời tiết hôm nay ở nơi em sống (hoặc một bản tin thời sự) và lưu địa chỉ trang vào thanh đánh dấu.","k":"Ghi được nhiệt độ thấp nhất, cao nhất, tình hình mưa nắng; nháy nút ☆ (Bookmark) để lưu địa chỉ trang lên thanh đánh dấu.","label":"Thực hành – Thời tiết, thời sự"},{"id":"lt1","type":"mcq","q":"Thông tin trên Internet được tổ chức như thế nào?","k":"<b>C</b>. Các trang siêu văn bản kết nối với nhau bởi các liên kết.","o":["Tương tự như thông tin trong cuốn sách.","Thành từng văn bản rời rạc.","Thành các trang siêu văn bản kết nối với nhau bởi các liên kết.","Một cách tuỳ ý."],"a":2},{"id":"lt2","type":"match","q":"Ghép mỗi nội dung ở cột A với một nội dung phù hợp ở cột B.","k":"1 – c; 2 – d; 3 – a; 4 – b.","items":[["1) Website là tập hợp",3],["2) Khi duyệt web, muốn chuyển đến một nội dung khác hoặc một trang web khác thì ta nháy chuột vào",4],["3) Để truy cập các trang web ta cần",1],["4) WWW là hệ thống các",2]],"opts":["a) sử dụng trình duyệt web.","b) website trên Internet.","c) các trang web liên quan được truy cập thông qua một địa chỉ.","d) liên kết trỏ đến đó."]},{"id":"vd1","type":"open","q":"Có điểm gì khác nhau giữa cách tổ chức thông tin trong cuốn sách với cách tổ chức thông tin trên Internet?","k":"Sách: thông tin sắp xếp <b>theo trình tự</b> trang, chương; chủ yếu chữ và hình. Internet: các trang siêu văn bản <b>nối với nhau bằng liên kết</b>, có nhiều dạng (âm thanh, video), nhảy tới trang khác chỉ bằng một cú nháy chuột, thường xuyên được cập nhật.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Truy cập https://hoahoctro.tienphong.vn và https://vtv7.vtv.vn, xem thông tin trên trang (tên, biểu tượng, các mục chính,…), theo các liên kết đến các trang khác và lưu địa chỉ trang em thích vào thanh đánh dấu. Ghi lại kết quả.","k":"Học sinh nêu tên website, biểu tượng, các mục chính, một trang đã mở qua liên kết và trang đã lưu đánh dấu.","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Thông tin trên Internet được tạo nên từ nhiều trang web kết nối với nhau bởi các liên kết. Mỗi trang web có địa chỉ truy cập riêng.</li><li>Website là một tập hợp các trang web liên quan được truy cập thông qua một địa chỉ. Địa chỉ của trang chủ là địa chỉ của website.</li><li>World Wide Web là mạng thông tin toàn cầu, liên kết các website trên Internet.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Trình duyệt là phần mềm giúp người sử dụng truy cập các trang web trên Internet.</li><li>Người sử dụng có thể theo các liên kết để khai thác thông tin từ các trang web.</li></ul>"}]},"tin6-so-do-tu-duy":{"id":"tin6-bai10","ten":"Bài 10. Sơ đồ tư duy","cau":[{"id":"hd1a","type":"open","q":"Hãy tưởng tượng khi 50 tuổi, em tìm thấy cuốn sổ lưu niệm đã cũ của lớp mình. Hãy viết ra ba điều mà cuốn sổ lưu niệm làm em thích thú, một điều làm em hạnh phúc và một điều gợi lại cho em kỉ niệm buồn.","k":"Học sinh tự viết, ví dụ: thích ảnh cả lớp đi dã ngoại, bài thơ bạn tặng, danh sách sở thích; hạnh phúc vì được cô khen; buồn vì một bạn chuyển trường.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Theo em sổ lưu niệm sẽ gồm những thông tin gì?","k":"Giới thiệu thành viên (họ tên, ngày sinh, ảnh, sở thích, địa chỉ liên lạc); giáo viên; các bài viết cảm nghĩ; hoạt động, sự kiện của lớp;…","label":"HĐ1 – Câu 2"},{"id":"hd2a","type":"mcq","q":"Quan sát sơ đồ tư duy ở Hình 5.2. Cách biểu diễn nào dễ hiểu, dễ nhớ và thú vị hơn?","k":"<b>Sơ đồ tư duy</b>: trực quan, thấy được bức tranh tổng thể, dễ nhớ.","o":["Văn bản (Hình 5.1)","Sơ đồ tư duy (Hình 5.2)"],"a":1},{"id":"hd2b","type":"open","q":"Sử dụng sơ đồ tư duy có lợi ích gì?","k":"Nhìn thấy bức tranh tổng thể, dễ dàng ghi nhớ, thúc đẩy tư duy, tăng khả năng sáng tạo, đơn giản dễ hiểu, tiết kiệm thời gian.","label":"HĐ2 – Câu 2"},{"id":"hd2c","type":"sort","q":"Trong Hình 5.2, mỗi mục dưới đây là chủ đề chính hay chủ đề nhánh?","k":"Chủ đề chính: <b>Sơ đồ tư duy</b>. Chủ đề nhánh: <b>Người sáng tạo, Lợi ích, Làm gì?, Thành phần</b>.","cats":["Chủ đề chính","Chủ đề nhánh"],"items":[["Sơ đồ tư duy",0],["Người sáng tạo",1],["Lợi ích",1],["Làm gì?",1],["Thành phần",1]]},{"id":"hd2d","type":"mcq","q":"Các ý chi tiết của chủ đề nhánh “Thành phần” là gì?","k":"<b>A</b>. Từ khoá, hình ảnh, đường nối.","o":["Từ khoá, hình ảnh, đường nối.","Tony Buzan, quốc tịch Anh, sinh năm 1942.","Ghi nhớ thông tin, tổ chức thông tin.","Dễ ghi nhớ, tiết kiệm thời gian."],"a":0},{"id":"p43a","type":"sort","q":"Sơ đồ tư duy giúp chúng ta (chọn các phương án đúng):","k":"<b>A, C, D</b>.","cats":["Đúng","Sai"],"items":[["A. Ghi nhớ tốt hơn.",0],["B. Giải các bài toán.",1],["C. Sáng tạo hơn.",0],["D. Nhìn thấy bức tranh tổng thể.",0]]},{"id":"p43b","type":"sort","q":"Sơ đồ tư duy là (chọn các phương án đúng):","k":"<b>A, B, C</b>.","cats":["Đúng","Sai"],"items":[["A. Một công cụ tổ chức thông tin phù hợp với quá trình tư duy.",0],["B. Một phương pháp chuyển tải thông tin.",0],["C. Một cách ghi chép sáng tạo.",0],["D. Một công cụ soạn thảo văn bản.",1]]},{"id":"cb","type":"order","q":"Sắp xếp các bước tạo sơ đồ tư duy (dùng nút ↑ ↓).","k":"Chủ đề chính ở giữa → các chủ đề nhánh → chi tiết từng nhánh → nhánh con. Nên dùng màu sắc vì màu sắc có tác dụng kích thích não bộ.","items":{"a":"Viết chủ đề chính ở giữa tờ giấy, dùng một hình bao quanh","b":"Từ chủ đề chính, vẽ các chủ đề nhánh","c":"Phát triển thông tin chi tiết cho mỗi chủ đề nhánh (từ khoá, hình ảnh)","d":"Tạo thêm nhánh con khi bổ sung thông tin để mở rộng sơ đồ"},"ans":["a","b","c","d"],"start":["c","a","d","b"]},{"id":"hd3a","type":"open","q":"Em và các bạn thảo luận nhóm để bàn về nội dung cuốn sổ lưu niệm của lớp, sau đó tạo sơ đồ tư duy trên giấy (hoặc bằng công cụ ở trên) để ghi lại kết quả thảo luận theo gợi ý trong Hình 5.3. Ghi lại các nhánh chính của nhóm em.","k":"Ví dụ: Giới thiệu thành viên (họ tên, ngày sinh, địa chỉ liên lạc, ảnh, sở thích); Giáo viên (giáo viên chủ nhiệm,…); Các bài viết cảm nghĩ (về bạn, về trường lớp); Hoạt động, sự kiện.","label":"HĐ3 – Câu 1"},{"id":"hd3b","type":"open","q":"Theo em sơ đồ tư duy thủ công trên giấy có hạn chế gì?","k":"Khó sửa chữa, thay đổi bố cục; khó thêm, bớt nội dung khi hết chỗ; khó chia sẻ cho nhiều người ở xa; mất thời gian vẽ lại.","label":"HĐ3 – Câu 2"},{"id":"p44","type":"mcq","q":"Ưu điểm của việc tạo sơ đồ tư duy thủ công trên giấy là gì?","k":"<b>D</b>. A, B, C là ưu điểm của phần mềm sơ đồ tư duy.","o":["Dễ sắp xếp, bố trí, thay đổi, thêm bớt nội dung.","Sản phẩm tạo ra dễ dàng sử dụng cho các mục đích khác nhau như đưa vào bài trình chiếu, gửi cho bạn qua thư điện tử,…","Sản phẩm tạo ra nhanh chóng, dễ dàng chia sẻ cho nhiều người ở các địa điểm khác nhau.","Có thể thực hiện ở bất cứ đâu, chỉ cần giấy và bút. Thể hiện được phong cách riêng của người tạo."],"a":3},{"id":"pm","type":"order","q":"Sắp xếp các thao tác tạo sơ đồ tư duy bằng phần mềm MindMaple Lite (dùng nút ↑ ↓).","k":"File/New → chọn mẫu, Create → nhập chủ đề chính → Insert/Subtopic → File/Save. <i>Chú ý: tạo chủ đề nhánh cho chủ đề nào thì nháy chuột chọn chủ đề đó trước khi tạo.</i>","items":{"a":"Nháy chuột vào File, chọn New","b":"Chọn một mẫu, nháy Create","c":"Nháy vào khung Central Topic, nhập tên chủ đề chính","d":"Chọn chủ đề chính, chọn Insert/Subtopic để tạo chủ đề nhánh","e":"Chọn File/Save, lưu tệp với tên SoLuuNiem.emm"},"ans":["a","b","c","d","e"],"start":["d","e","b","a","c"]},{"id":"th","type":"open","q":"Sử dụng phần mềm sơ đồ tư duy (hoặc công cụ trên trang này) để tạo sơ đồ tư duy ghi lại các nội dung có trong cuốn sổ lưu niệm của lớp em. Ghi lại tên tệp và các nhánh em đã tạo.","k":"Tệp SoLuuNiem.emm gồm chủ đề chính SỔ LƯU NIỆM LỚP 6A và các nhánh: Giới thiệu thành viên, Giáo viên, Các bài viết cảm nghĩ, Hoạt động sự kiện,…","label":"Thực hành – Sổ lưu niệm"},{"id":"lt","type":"open","q":"Thực hiện cho sơ đồ tư duy sổ lưu niệm: a) bổ sung các nhánh nội dung (nếu cần); b) chỉnh sửa màu sắc và kiểu đường nối, bổ sung hình ảnh, biểu tượng,… để tăng hiệu quả trình bày; c) chia sẻ sơ đồ cho thầy cô và các bạn để cả lớp trao đổi, thống nhất nội dung. Em đã thay đổi những gì?","k":"Học sinh nêu các nhánh bổ sung, màu sắc, biểu tượng đã thêm và ý kiến góp ý của các bạn.","label":"Luyện tập"},{"id":"vd","type":"open","q":"Em hãy dùng sơ đồ tư duy (vẽ trên giấy hoặc tạo bằng phần mềm) trình bày tóm tắt nội dung Bài 9. An toàn thông tin trên Internet. Ghi lại các nhánh chính em đã vẽ.","k":"Chủ đề chính: An toàn thông tin trên Internet. Nhánh: Tác hại, nguy cơ (5 ý); Quy tắc an toàn (Giữ an toàn, Không gặp gỡ, Đừng chấp nhận, Kiểm tra độ tin cậy, Hãy nói ra); Biện pháp bảo vệ (mật khẩu mạnh, đăng xuất, phần mềm chống virus,…).","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Sơ đồ tư duy là phương pháp trình bày thông tin một cách trực quan bằng cách sử dụng văn bản, hình ảnh và các đường nối.</li><li>Sơ đồ tư duy tận dụng tối đa khả năng ghi nhận hình ảnh của bộ não, giúp chúng ta dễ dàng ghi nhớ chi tiết, tổng hợp hay phân tích vấn đề.</li></ul>"},{"t":"Ghi nhớ","b":"<p>Phần mềm máy tính giúp em tạo sơ đồ tư duy dễ dàng, nhanh chóng; dễ sửa chữa và điều chỉnh; nhanh chóng chia sẻ và trao đổi. Em có thể dùng sơ đồ tư duy để ghi lại nội dung kiến thức các môn học, kế hoạch hoạt động ngoại khoá, kế hoạch đi du lịch,…</p>"}]},"tin6-thong-tin-trong-may-tinh":{"id":"tin6-bai3","ten":"Bài 3. Thông tin trong máy tính","cau":[{"id":"kd1","type":"open","q":"Máy tính thông dụng hiện nay chỉ làm việc với hai kí hiệu 0 và 1. Theo em, làm thế nào để máy tính “hiểu” được những con số, chữ cái, hình ảnh mà con người đưa vào?","k":"Mọi thông tin phải được <b>mã hoá</b> (chuyển đổi) thành những dãy chỉ gồm hai kí hiệu <b>0 và 1</b> thì máy tính mới xử lí được.","label":"Khởi động"},{"id":"hd1a","type":"mcq","q":"Theo cách mã hoá ở Hình 1.3, số 4 được mã hoá thành dãy nào?","k":"Phải → trái → trái → <b>100</b>.","o":["100","001","011","110"],"a":0},{"id":"hd1b","type":"mcq","q":"Mã hoá số 3 và số 6 theo cách trên. Kết quả là gì? Hai dãy có giống nhau không?","k":"Số 3: trái, phải, phải → <b>011</b>. Số 6: phải, phải, trái → <b>110</b>. Hai dãy <b>khác nhau</b> → mỗi số có một mã riêng.","o":["3 → 011; 6 → 110. Hai dãy khác nhau.","3 → 110; 6 → 011. Hai dãy khác nhau.","3 → 011; 6 → 011. Hai dãy giống nhau.","3 → 100; 6 → 110. Hai dãy khác nhau."],"a":0},{"id":"vb","type":"mcq","q":"Theo Bảng 1.2, dãy bit 01000010 01000001 01000100 biểu diễn từ nào?","k":"01000010 = B, 01000001 = A, 01000100 = D → <b>BAD</b>.","o":["CAFE","BAD","DAB","FED"],"a":1},{"id":"ha","type":"mcq","q":"Trong cách biểu diễn hình ảnh đen trắng ở Hình 1.4, mỗi ô vuông (pixel) màu đen được kí hiệu là gì?","k":"Màu đen kí hiệu là <b>1</b>, màu trắng là <b>0</b>. Mỗi dòng 8 ô → một dãy 8 bit.","o":["0","1","2","A"],"a":1},{"id":"hd2a","type":"open","q":"Vẽ hình trái tim vào lưới 8 × 8 ở trên. Viết dãy bit của từng dòng (từ trên xuống).","k":"Mỗi dòng 8 ô: ô tô màu → 1, ô trắng → 0. Ví dụ một dòng: 01100110.","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Chuyển cả hình vẽ thành dãy bit bằng cách nối các dãy bit của các dòng lại với nhau (từ trên xuống dưới).","k":"Nối 8 dãy 8 bit → một dãy <b>64 bit</b>. Hình vẽ đã được biểu diễn hoàn toàn bằng 0 và 1.","label":"HĐ2 – Câu 2"},{"id":"p14a","type":"mcq","q":"Dãy bit là gì?","k":"<b>A</b>. Dãy bit là dãy những kí hiệu 0 và 1.","o":["Là dãy những kí hiệu 0 và 1.","Là âm thanh phát ra từ máy tính.","Là một dãy chỉ gồm chữ số 2.","Là dãy những chữ số từ 0 đến 9."],"a":0},{"id":"p14b","type":"mcq","q":"Máy tính sử dụng dãy bit để làm gì?","k":"<b>D</b>. Mọi dạng thông tin trong máy tính đều được biểu diễn bằng dãy bit.","o":["Biểu diễn các số.","Biểu diễn văn bản.","Biểu diễn hình ảnh, âm thanh.","Biểu diễn số, văn bản, hình ảnh, âm thanh."],"a":3},{"id":"dv","type":"order","q":"Sắp xếp các đơn vị đo dung lượng thông tin từ nhỏ đến lớn (dùng nút ↑ ↓).","k":"Byte → KB → MB → GB → TB. Mỗi đơn vị bằng <b>1024</b> lần đơn vị liền trước; 1 byte = 8 bit.","items":{"a":"Byte (B)","b":"Kilobyte (KB)","c":"Megabyte (MB)","d":"Gigabyte (GB)","e":"Terabyte (TB)"},"ans":["a","b","c","d","e"],"start":["d","a","e","c","b"]},{"id":"p15a","type":"open","q":"Quan sát hình các ổ đĩa ở trên và cho biết thông tin về dung lượng của từng ổ đĩa.","k":"C: dung lượng 109 GB, còn trống 37,9 GB. E: 111 GB, trống 48,2 GB. F: 169 GB, trống 153 GB. G (DATA2): 186 GB, trống 27,2 GB.","label":"Câu hỏi tr.15 – Câu 1"},{"id":"p15b","type":"mcq","q":"Quan sát danh sách tệp ảnh ở trên. Tệp nào có dung lượng lớn nhất?","k":"IMG_0039.jpg (1 108 KB ≈ 1,08 MB). Các tệp còn lại: 372 KB, 408 KB, 482 KB, 512 KB, 1 095 KB, 846 KB, 488 KB.","o":["IMG_0013.jpg","IMG_0024.jpg","IMG_0039.jpg","IMG_0046.jpg"],"a":2},{"id":"lt1","type":"mcq","q":"Một GB xấp xỉ bao nhiêu byte?","k":"<b>C</b>. 1 GB ≈ 1 tỉ byte.","o":["Một nghìn byte.","Một triệu byte.","Một tỉ byte.","Một nghìn tỉ byte."],"a":2},{"id":"lt2","type":"mcq","q":"Một bức ảnh chụp bằng máy ảnh chuyên nghiệp có dung lượng khoảng 12 MB. Một thẻ nhớ 16 GB có thể chứa khoảng bao nhiêu bức ảnh như vậy?","k":"16 GB = 16 × 1024 MB = 16 384 MB. 16 384 : 12 ≈ <b>1 365</b> bức ảnh (ước lượng nhanh: 16 000 : 12 ≈ 1 333).","o":["Khoảng 1 365 bức ảnh","Khoảng 136 bức ảnh","Khoảng 13 bức ảnh","Khoảng 13 650 bức ảnh"],"a":0},{"id":"vd1","type":"open","q":"Em hãy kiểm tra và ghi lại dung lượng các ổ đĩa của máy tính mà em đang sử dụng.","k":"Mở File Explorer → This PC: ghi tên ổ, dung lượng, dung lượng còn trống (ví dụ: C: 237 GB, trống 120 GB).","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Thực hiện tương tự Hoạt động 1 với dãy các số từ 0 đến 15, mã hoá các số từ 8 đến 15 và đưa ra nhận xét.","k":"8 → 1000, 9 → 1001, 10 → 1010, 11 → 1011, 12 → 1100, 13 → 1101, 14 → 1110, 15 → 1111. Nhận xét: cần <b>4 bit</b> (thu gọn 4 lần); các số 8–15 đều bắt đầu bằng 1 (nằm ở nửa phải).","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Thông tin được biểu diễn trong máy tính bằng dãy các bit. Mỗi bit là một kí hiệu 0 hoặc 1, hay còn được gọi là chữ số nhị phân.</li><li>Bit là đơn vị đo nhỏ nhất trong lưu trữ thông tin.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Byte (B) là dãy 8 bit liên tục. 1 KB = 1024 B; 1 MB = 1024 KB; 1 GB = 1024 MB; 1 TB = 1024 GB.</li><li>Ổ đĩa cứng hiện nay có dung lượng từ vài trăm GB đến vài TB; thẻ nhớ có thể lưu trữ được hàng trăm GB hoặc cao hơn; đĩa CD khoảng 700 MB; đĩa DVD từ 4,7 GB đến 17 GB.</li></ul>"}]},"tin6-thong-tin-va-du-lieu":{"id":"tin6-bai1","ten":"Bài 1. Thông tin và dữ liệu","cau":[{"id":"kd1","type":"open","q":"Sáng nay trên đường đến trường, em đã nhìn thấy, nghe thấy những gì? Những điều đó giúp em biết được điều gì?","k":"Ví dụ: nghe tiếng chim hót → biết trời đã sáng; thấy mây đen → biết trời sắp mưa; thấy đèn đỏ → biết phải dừng lại. Các giác quan thu nhận, não xử lí → em có <b>hiểu biết</b> về thế giới xung quanh.","label":"Khởi động"},{"id":"hd1","type":"open","q":"Bạn Minh đã thấy những gì và biết được điều gì để quyết định nhanh chóng qua đường?","k":"Minh <b>thấy</b> đèn giao thông phía mình chuyển sang màu xanh, các xe bên chiều đèn đỏ dừng lại. Minh <b>biết</b> mình có thể qua đường an toàn.","label":"HĐ1 – Thấy gì? Biết gì?"},{"id":"pl","type":"sort","q":"Xếp mỗi mục dưới đây (lấy từ các ví dụ trong SGK) vào nhóm phù hợp.","k":"<b>Dữ liệu</b>: số, chữ, hình ảnh, âm thanh ghi trên vật mang tin. <b>Thông tin</b>: hiểu biết mà con người có được. <b>Vật mang tin</b>: thứ dùng để lưu trữ, truyền dữ liệu.","cats":["Dữ liệu","Thông tin","Vật mang tin"],"items":[["Đèn xanh bật sáng, các xe bên kia dừng lại",0],["Các con số, văn bản, hình ảnh, âm thanh trong mục dự báo thời tiết",0],["Dòng chữ “Đảo Cò, xuồng máy, 40 000đ, 35 phút”",0],["Minh biết có thể qua đường an toàn",1],["An biết hôm nay trời nắng",1],["Khách biết giá vé đi Đảo Cò là 40 000 đồng",1],["Đèn giao thông",2],["Tấm bảng gỗ ở bến xuồng",2],["Giấy viết, đĩa CD, thẻ nhớ",2]]},{"id":"qh","type":"mcq","q":"Cùng xem bản tin dự báo thời tiết, An biết “hôm nay trời nắng” nhưng em bé 5 tuổi thì không hiểu gì. Vì sao?","k":"<b>B</b>. Dữ liệu chỉ đem lại thông tin khi người nhận hiểu được nó. Sự hiểu biết mà thông tin đem lại <b>phụ thuộc vào người tiếp nhận</b>.","o":["Bản tin dự báo thời tiết không có dữ liệu.","Sự hiểu biết mà thông tin đem lại phụ thuộc vào người tiếp nhận; với em bé, dữ liệu đó không đem lại thông tin.","Ti vi là vật mang tin bị hỏng.","Thông tin và dữ liệu là hai thứ hoàn toàn giống nhau."],"a":1},{"id":"c1m","type":"match","q":"Em hãy ghép mỗi mục ở cột A với một mục phù hợp ở cột B.","k":"1 – b; 2 – a; 3 – c.","items":[["1) Thông tin",2],["2) Dữ liệu",1],["3) Vật mang tin",3]],"opts":["a) Các số, văn bản, hình ảnh, âm thanh,…","b) Những gì đem lại hiểu biết cho con người về thế giới xung quanh và chính bản thân mình.","c) Vật chứa dữ liệu."]},{"id":"c2","type":"sort","q":"Mỗi dòng sau đây là thông tin hay dữ liệu?","k":"“16:00” và “0123456789” đứng riêng chỉ là <b>dữ liệu</b> (chưa biết dùng để làm gì). Câu “Hãy gọi cho tôi lúc 16 giờ…” cho ta biết phải làm gì → là <b>thông tin</b>.","cats":["Dữ liệu","Thông tin"],"items":[["16:00",0],["0123456789",0],["Hãy gọi cho tôi lúc 16 giờ theo số điện thoại 0123456789!",1]]},{"id":"hd2","type":"open","q":"Lớp em sắp tổ chức một buổi dã ngoại. Nhóm em hãy đưa ra các câu hỏi giúp tìm thông tin để chuẩn bị cho buổi dã ngoại đó (ít nhất 3 câu).","k":"Ví dụ: Hôm đó thời tiết thế nào? (chọn trang phục) · Ở đó có những trò chơi gì? · Có di tích lịch sử nào để tham quan? · Nên mang theo món ăn nhẹ gì? · Phong cảnh chỗ nào đẹp để chụp ảnh? Mỗi câu trả lời là một thông tin giúp lớp chuẩn bị tốt hơn.","label":"HĐ2 – Hỏi để có thông tin"},{"id":"tq1","type":"mcq","q":"Nhờ học bài lịch sử về Chiến dịch Điện Biên Phủ, em biết được điều gì?","k":"<b>B</b>. Thông tin về địa điểm, thời gian, diễn biến trận đánh,… giúp em hiểu biết thêm → <b>thông tin đem lại hiểu biết</b> cho con người.","o":["Không biết thêm điều gì.","Tinh thần dũng cảm của quân và dân ta, truyền thống chống giặc ngoại xâm của dân tộc.","Thời tiết ngày mai.","Giá vé đi Đảo Cò."],"a":1},{"id":"tq2","type":"mcq","q":"Chuẩn bị đi sang nhà bạn Minh, An nghe mẹ nói: “Trời sắp mưa đấy nhé”. An quay vào nhà cầm theo chiếc ô. Ví dụ này cho thấy điều gì?","k":"<b>B</b>. Thông tin “trời sắp mưa” làm An thay đổi hành động (mang ô) → thông tin đúng giúp con người <b>lựa chọn tốt</b>, hoạt động <b>hiệu quả</b>.","o":["Thông tin không ảnh hưởng gì đến con người.","Thông tin có khả năng làm thay đổi hành động của con người.","Chỉ có dữ liệu mới làm thay đổi hành động.","Chiếc ô là thông tin."],"a":1},{"id":"lta","type":"mcq","q":"Các con số trong Bảng 1.1 là thông tin hay dữ liệu?","k":"<b>Dữ liệu</b> – các con số ghi lượng mưa, được lưu trên bảng (vật mang tin).","o":["Thông tin","Dữ liệu"],"a":1},{"id":"ltb","type":"mcq","q":"Phát biểu “Tháng 6, Đà Nẵng ít mưa nhất so với các thành phố Hà Nội, Huế” là thông tin hay dữ liệu?","k":"<b>Thông tin</b> – có được nhờ so sánh các số ở cột tháng 6 (Hà Nội 200,7; Huế 134,2; Đà Nẵng 92,2).","o":["Thông tin","Dữ liệu"],"a":0},{"id":"ltc","type":"mcq","q":"Huế ít mưa nhất vào tháng nào trong năm? (Câu trả lời này là thông tin hay dữ liệu?)","k":"<b>Tháng 3</b> (34,1 mm). Câu trả lời là <b>thông tin</b>.","o":["Tháng 3","Tháng 8","Tháng 2","Tháng 11"],"a":0},{"id":"ltd","type":"open","q":"Câu trả lời cho câu hỏi c) có ảnh hưởng đến việc lựa chọn thời gian và địa điểm du lịch không? Vì sao?","k":"<b>Có</b>. Ví dụ: muốn đi Huế nên chọn tháng 3 (ít mưa); tránh tháng 10–12 vì mưa rất nhiều. Thông tin giúp ta chọn thời gian, địa điểm phù hợp.","label":"Luyện tập – Câu d"},{"id":"vd1a","type":"open","q":"Nêu ví dụ cho thấy thông tin giúp em có những lựa chọn trang phục phù hợp hơn.","k":"Ví dụ: nghe dự báo ngày mai trời rét → mặc áo ấm; biết thứ Hai chào cờ → mặc đồng phục; biết trời mưa → mang áo mưa.","label":"Vận dụng – Câu 1a"},{"id":"vd1b","type":"open","q":"Nêu ví dụ cho thấy thông tin giúp em đảm bảo an toàn khi tham gia giao thông.","k":"Ví dụ: thấy đèn đỏ → dừng lại; thấy biển báo trường học → đi chậm; biết đoạn đường đang sửa → chọn đường khác.","label":"Vận dụng – Câu 1b"},{"id":"vd2","type":"open","q":"Nêu ví dụ về vật mang tin giúp ích cho việc học tập của em.","k":"Ví dụ: sách giáo khoa, vở ghi, bảng lớp, bản đồ, thẻ nhớ/USB lưu bài, máy tính, điện thoại xem bài giảng…","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Thông tin</b> là những gì đem lại hiểu biết cho con người về thế giới xung quanh và về chính bản thân mình.</li><li>Thông tin được ghi lên vật mang tin trở thành <b>dữ liệu</b>. Dữ liệu được thể hiện dưới dạng những con số, văn bản, hình ảnh và âm thanh.</li><li><b>Vật mang tin</b> là phương tiện được dùng để lưu trữ và truyền tải thông tin, ví dụ như giấy viết, đĩa CD, thẻ nhớ,…</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Thông tin đem lại hiểu biết cho con người. Hầu hết hoạt động của con người đều cần đến thông tin.</li><li>Thông tin đúng giúp con người đưa ra những lựa chọn tốt, giúp cho hoạt động của con người đạt hiệu quả.</li></ul>"}]},"tin6-thu-dien-tu":{"id":"tin6-bai8","ten":"Bài 8. Thư điện tử","cau":[{"id":"kd1","type":"open","q":"Ba hình ảnh (chim bồ câu đưa thư, gửi thư qua hòm thư bưu điện, gửi thư bằng máy tính) cho em biết điều gì?","k":"Cách gửi thư của con người thay đổi theo thời gian: dùng chim bồ câu → qua bưu điện → bằng máy tính qua Internet (<b>thư điện tử</b>), ngày càng nhanh và tiện lợi.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Để soạn và gửi một bức thư qua đường bưu điện đến tay người nhận thì cần những gì và thực hiện như thế nào?","k":"Cần giấy, bút, phong bì, tem, địa chỉ người nhận. Viết thư → cho vào phong bì, ghi địa chỉ, dán tem → bỏ vào hòm thư → bưu điện chuyển đến người nhận (mất nhiều ngày).","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Em biết gì về thư điện tử? Tài khoản thư điện tử?","k":"Thư điện tử là thư gửi và nhận bằng phương tiện điện tử qua Internet. Muốn dùng cần có tài khoản thư điện tử (tên đăng nhập, mật khẩu).","label":"HĐ1 – Câu 2"},{"id":"p33a","type":"open","q":"Dịch vụ thư điện tử là gì?","k":"Là dịch vụ cung cấp các chức năng <b>soạn thảo, gửi, nhận, chuyển tiếp, lưu trữ và quản lí</b> thư điện tử cho người sử dụng.","label":"Câu hỏi tr.33 – Câu 1"},{"id":"p33b","type":"sort","q":"Địa chỉ thư điện tử nào sau đây không đúng? Tại sao?","k":"<b>B</b> sai vì thiếu kí tự bắt buộc <b>@</b>. Địa chỉ đúng có dạng &lt;tên đăng nhập&gt;@&lt;địa chỉ máy chủ thư điện tử&gt;.","cats":["Đúng dạng","Không đúng"],"items":[["A. khoa123@gmail.com",0],["B. minhtuan.gmail.com",1],["C. nmha@hnmu.edu.vn",0],["D. thuyk39@yahoo.com",0]]},{"id":"hd2","type":"open","q":"Theo em dịch vụ thư điện tử có những ưu điểm và nhược điểm gì so với các phương thức liên lạc khác?","k":"Ưu: nhanh, gửi cho nhiều người, đính kèm tệp, lưu trữ dễ, chi phí thấp. Nhược: cần kết nối mạng, có thể nhiễm virus, thư rác, thư lừa đảo.","label":"HĐ2 – Ưu, nhược điểm"},{"id":"un","type":"sort","q":"Mỗi ý dưới đây là ưu điểm hay nhược điểm của dịch vụ thư điện tử?","k":"<b>Ưu điểm</b>: chi phí thấp, tiết kiệm thời gian, thuận tiện. <b>Nhược điểm</b>: cần phương tiện điện tử kết nối mạng, có thể gặp nguy cơ, phiền toái.","cats":["Ưu điểm","Nhược điểm"],"items":[["Thời gian gửi và nhận nhanh, kịp thời",0],["Có thể gửi thư cùng lúc cho nhiều người",0],["Có thể gửi kèm tệp văn bản, âm thanh, hình ảnh",0],["Lưu trữ và tìm kiếm thư dễ dàng",0],["Chi phí thấp, nhiều dịch vụ miễn phí",0],["Phải kết nối mạng mới sử dụng được",1],["Có thể bị nhiễm virus",1],["Có thể bị làm phiền với các thư rác",1],["Có thể bị lừa đảo bởi các thư giả mạo",1]]},{"id":"p34","type":"open","q":"Em hãy nêu các ưu điểm và hạn chế của dịch vụ thư truyền thống. Các điểm đó đã thay đổi thế nào khi ta sử dụng dịch vụ thư điện tử?","k":"Thư truyền thống: không cần mạng, gửi được đồ vật; nhưng chậm, tốn tem, dễ thất lạc, mỗi lần gửi một người. Thư điện tử: nhanh, gửi nhiều người, rẻ, lưu trữ dễ; nhưng cần mạng, có thư rác, virus.","label":"Câu hỏi tr.34"},{"id":"tk","type":"order","q":"Sắp xếp các bước tạo tài khoản thư điện tử trên mail.google.com (dùng nút ↑ ↓).","k":"a → b → c → d → e → f. Trẻ vị thành niên cần sự đồng ý, trợ giúp và quản lí của phụ huynh. Em cần ghi nhớ <b>tên đăng nhập</b> và <b>mật khẩu</b>.","items":{"a":"Truy cập trang mail.google.com","b":"Nháy chuột vào nút Tạo tài khoản","c":"Nhập đầy đủ thông tin theo hướng dẫn","d":"Nháy chuột vào nút Tiếp theo","e":"Xác nhận số điện thoại (nếu có), làm theo hướng dẫn","f":"Xuất hiện thông báo Chào mừng bạn!"},"ans":["a","b","c","d","e","f"],"start":["c","f","a","d","b","e"]},{"id":"dn","type":"mcq","q":"Vì sao cần nháy nút Đăng xuất khi không dùng hộp thư điện tử nữa?","k":"<b>B</b>. Đăng xuất để tránh bị người khác sử dụng hộp thư của mình.","o":["Để thư được gửi nhanh hơn.","Để tránh bị người khác sử dụng hộp thư của em.","Để xoá hết thư trong hộp thư.","Để đổi mật khẩu."],"a":1},{"id":"gt","type":"open","q":"Đăng nhập hộp thư, soạn một thư mới gửi cho bạn (Người nhận, Chủ đề, Nội dung) rồi nháy Gửi. Ghi lại địa chỉ người nhận, chủ đề thư em đã gửi.","k":"Nháy <b>Soạn thư</b> → nhập địa chỉ người nhận → nhập tiêu đề (chủ đề) → nhập nội dung → (đính kèm tệp nếu có) → nháy <b>Gửi</b>.","label":"Thực hành – Soạn và gửi thư"},{"id":"lt1","type":"mcq","q":"Thư điện tử có hạn chế nào dưới đây so với các hình thức gửi thư khác?","k":"<b>C</b>. Phải phòng tránh virus, thư rác.","o":["Không đồng thời gửi được cho nhiều người.","Thời gian gửi thư lâu.","Phải phòng tránh virus, thư rác.","Chi phí thấp."],"a":2},{"id":"lt2","type":"mcq","q":"Một người có thể mở được nhiều tài khoản thư điện tử không?","k":"<b>Có</b>. Mỗi tài khoản có một địa chỉ thư riêng, duy nhất trên toàn cầu.","o":["Có","Không"],"a":0},{"id":"lt3","type":"mcq","q":"Khi tạo tài khoản thư điện tử em không cần khai báo gì?","k":"<b>C</b>. Không cần khai báo địa chỉ nhà.","o":["Họ và tên.","Ngày sinh.","Địa chỉ nhà.","Hộp thư của phụ huynh."],"a":2},{"id":"vd1","type":"sort","q":"Em hãy xác định xem thư nào có thể là thư rác trong các thư điện tử có tiêu đề sau.","k":"<b>A, C, D, F</b> có thể là thư rác (quảng cáo, dụ dỗ, lừa đảo). Không mở thư, tệp đính kèm, liên kết từ người lạ.","cats":["Có thể là thư rác","Thư bình thường"],"items":[["A. Cơ hội đầu tư kiếm được nhiều tiền hơn.",0],["B. Danh sách học sinh tham gia thi học sinh giỏi môn Tin học.",1],["C. Quà tặng miễn phí, hãy nháy chuột nhanh.",0],["D. Bạn đã trúng một chuyến đi miễn phí đến Mĩ.",0],["E. Ảnh tập thể lớp 6A ngày khai trường.",1],["F. Khuyến mãi, ưu đãi giá rẻ cho bạn.",0]]},{"id":"vd2","type":"open","q":"Em hãy soạn một thư điện tử có gửi kèm ảnh (hoặc tệp văn bản, thiệp chúc mừng,…) cho bạn hoặc người thân của em. Ghi lại chủ đề thư và tên tệp đính kèm.","k":"Khi soạn thư, nháy nút 📎 (Đính kèm) → chọn tệp → nháy Gửi.","label":"Vận dụng – Câu 2"},{"id":"oc","type":"mcq","q":"Giải ô chữ ở trên. Từ khoá ở cột màu xanh là gì?","k":"1 TAIKHOAN, 2 MATKHAU, 3 NGUOINHAN, 4 DANGNHAP, 5 DIACHI, 6 TEP, 7 DANGXUAT, 8 HOPTHU, 9 GUI → từ khoá <b>THUDIENTU</b> (thư điện tử).","o":["TAI KHOAN","THU DIEN TU","MAT KHAU","DANG NHAP"],"a":1}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Thư điện tử là thư được gửi và nhận bằng phương tiện điện tử.</li><li>Khi đăng kí tài khoản thư điện tử, người sử dụng có một hộp thư điện tử cùng địa chỉ thư và mật khẩu.</li><li>Địa chỉ thư điện tử có dạng: &lt;tên đăng nhập&gt;@&lt;địa chỉ máy chủ thư điện tử&gt;.</li><li>Dịch vụ thư điện tử cung cấp các chức năng để soạn, gửi, nhận, chuyển tiếp, lưu trữ và quản lí thư điện tử cho người sử dụng.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Ưu điểm của dịch vụ thư điện tử: chi phí thấp, tiết kiệm thời gian, thuận tiện,…</li><li>Nhược điểm của dịch vụ thư điện tử: phải sử dụng phương tiện điện tử kết nối mạng, có thể gặp một số nguy cơ, phiền toái.</li></ul>"}]},"tin6-thuat-toan":{"id":"tin6-bai15","ten":"Bài 15. Thuật toán","cau":[{"id":"kd","type":"order","q":"Sắp xếp các bước gấp hình trò chơi Đông-Tây-Nam-Bắc theo đúng thứ tự (dùng nút ↑ ↓).","k":"a → b → c → d → e → f: đúng sáu bước theo hướng dẫn (Hình 6.1).","items":{"a":"Gấp hai đường chéo của tờ giấy hình vuông để tạo nếp gấp, mở tờ giấy ra.","b":"Gấp bốn góc của tờ giấy vào tâm.","c":"Lật mặt bên kia.","d":"Tiếp tục gấp bốn góc vào tâm.","e":"Đặt tờ giấy đã gấp nằm ngang, luồn ngón cái và ngón trỏ của hai tay vào bốn góc ở mặt dưới.","f":"Chỉnh sửa các nếp gấp."},"ans":["a","b","c","d","e","f"],"start":["c","a","e","b","f","d"]},{"id":"hd1a","type":"open","q":"Nếu đảo thứ tự của bước 3 và bước 4 trong hướng dẫn trên thì em có gấp được hình trò chơi Đông-Tây-Nam-Bắc không? Tại sao?","k":"<b>Không</b>. Nếu chưa lật mặt mà gấp tiếp bốn góc vào tâm thì các góc chồng lên cùng một mặt, không tạo được bốn túi để luồn ngón tay. Thay đổi thứ tự các bước thì <b>kết quả sẽ khác</b>.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Trước khi thực hiện theo hướng dẫn trên, em cần có gì? Sau khi thực hiện lần lượt sáu bước theo hướng dẫn, em nhận được kết quả là gì?","k":"Cần có <b>một tờ giấy hình vuông</b> (đầu vào). Kết quả là <b>hình trò chơi Đông-Tây-Nam-Bắc</b> (đầu ra).","label":"HĐ1 – Câu 2"},{"id":"q1","type":"mcq","q":"Thuật toán là gì?","k":"<b>C</b>. Thuật toán là một dãy các <b>chỉ dẫn rõ ràng, có trình tự</b> để giải quyết vấn đề hoặc nhiệm vụ đã cho.","o":["Một dãy các cách giải quyết một nhiệm vụ.","Một dãy các kết quả nhận được khi giải quyết một nhiệm vụ.","Một dãy các chỉ dẫn rõ ràng, có trình tự sao cho khi thực hiện những chỉ dẫn này người ta giải quyết được vấn đề hoặc nhiệm vụ đã cho.","Một dãy các dữ liệu đầu vào để giải quyết một nhiệm vụ."],"a":2},{"id":"q2","type":"mcq","q":"Em hãy chọn câu đúng.","k":"<b>A</b>. Đầu ra (Output) là <b>kết quả</b> nhận được sau khi thực hiện các bước. (B cũng đúng: đầu vào (Input) là dữ liệu ban đầu; C và D sai.)","o":["Thuật toán có đầu ra là kết quả nhận được sau khi thực hiện các bước của thuật toán.","Thuật toán có đầu vào là các dữ liệu ban đầu.","Thuật toán có đầu vào là kết quả nhận được sau khi thực hiện các bước của thuật toán.","Thuật toán có đầu ra là các dữ liệu ban đầu."],"a":0},{"id":"hd2","type":"open","q":"Ngoài cách trình bày thuật toán bằng ngôn ngữ tự nhiên, em còn biết cách nào khác không? Cách đó có hiệu quả không? Vì sao?","k":"Có thể dùng <b>sơ đồ khối</b> (hình vẽ và mũi tên). Cách này trực quan, dễ theo dõi thứ tự các bước, nhất là khi thuật toán có nhiều bước.","label":"HĐ2 – Mô tả thuật toán"},{"id":"q3","type":"mcq","q":"Câu nào sau đây SAI khi nói về vai trò của mũi tên trong sơ đồ khối của thuật toán?","k":"<b>C</b> sai. Mũi tên không chỉ để nối các hình mà còn <b>chỉ hướng thực hiện tiếp theo</b>.","o":["Hướng mũi tên cho thấy hướng đi trong sơ đồ khối.","Mũi tên được sử dụng để chỉ hướng thực hiện tiếp theo.","Mũi tên được sử dụng chỉ để kết nối các hình khối trong sơ đồ khối."],"a":2},{"id":"q4","type":"match","q":"Ghép mỗi hình ở cột trái với một ý nghĩa phù hợp ở cột phải khi nói về sơ đồ khối của thuật toán.","k":"1–a, 2–c, 3–d, 4–b.","items":[["1) Hình elip (màu hồng)",1],["2) Hình bình hành (màu xanh)",3],["3) Hình chữ nhật (màu vàng)",4],["4) Mũi tên ↓",2]],"opts":["a) Bắt đầu hoặc Kết thúc","b) Chỉ hướng thực hiện tiếp theo","c) Đầu vào hoặc Đầu ra","d) Bước xử lí"]},{"id":"lt1","type":"open","q":"Em hãy tìm đầu vào, đầu ra của các thuật toán sau đây: a) Thuật toán tính trung bình cộng của hai số a, b. b) Thuật toán tìm ước chung lớn nhất của hai số tự nhiên a và b.","k":"a) Đầu vào: hai số a, b; đầu ra: trung bình cộng của a và b. b) Đầu vào: hai số tự nhiên a, b; đầu ra: ước chung lớn nhất của a và b.","label":"Luyện tập – Câu 1"},{"id":"lt2","type":"open","q":"Quan sát sơ đồ khối ở Hình 6.3 và cho biết sơ đồ khối mô tả thuật toán gì? Xác định đầu vào và đầu ra của thuật toán. Mô tả lại thuật toán dưới dạng liệt kê.","k":"Thuật toán <b>tính tổng hai số a, b</b>. Đầu vào: a, b; đầu ra: tổng. Liệt kê: 1. Nhập a, b. 2. Tổng ← a + b. 3. Đưa ra giá trị tổng.","label":"Luyện tập – Câu 2"},{"id":"lt3","type":"order","q":"Sắp xếp các phần được đánh số trong Hình 6.4 để được thuật toán tính trung bình cộng của hai số a và b (dùng nút ↑ ↓).","k":"<b>1 → 3 → 2 → 4 → 6 → 5</b>: Bắt đầu → nhập a, b → Tổng ← a + b → Trung bình cộng ← Tổng : 2 → đưa ra trung bình cộng → Kết thúc.","items":{"1":"Bắt đầu","2":"Tổng ← a + b","3":"Giá trị a, giá trị b","4":"Trung bình cộng ← Tổng : 2","5":"Kết thúc","6":"Giá trị trung bình cộng của a và b"},"ans":["1","3","2","4","6","5"],"start":["1","2","3","4","5","6"]},{"id":"vd1","type":"open","q":"Phần hướng dẫn làm kem sữa chua xoài gồm 7 bước là một thuật toán. a) Xác định đầu vào và đầu ra của thuật toán làm kem sữa chua xoài. b) Dùng sơ đồ khối để thể hiện thuật toán đó.","k":"a) Đầu vào: xoài 250 g, sữa chua 100 g, mật ong 1 thìa cà phê (cùng 1 tô to, 4 khuôn làm kem); đầu ra: kem sữa chua xoài. b) Bắt đầu → [nguyên liệu, dụng cụ] → 7 hình chữ nhật cho 7 bước → [kem sữa chua xoài] → Kết thúc.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Em hãy mô tả thuật toán tính điểm trung bình ba môn Toán, Ngữ văn, Ngoại ngữ theo hai cách: liệt kê các bước và sơ đồ khối.","k":"Liệt kê: 1. Nhập điểm Toán, Ngữ văn, Ngoại ngữ. 2. Tổng ← Toán + Văn + Ngoại ngữ. 3. Điểm TB ← Tổng : 3. 4. Đưa ra điểm TB. Sơ đồ khối: Bắt đầu → [nhập 3 điểm] → Tổng ← … → Điểm TB ← Tổng : 3 → [điểm TB] → Kết thúc.","label":"Vận dụng – Câu 2"},{"id":"vd3","type":"open","q":"Em hãy nêu ví dụ về thuật toán giải quyết một nhiệm vụ trong thực tế. Hãy xác định đầu vào, đầu ra và các bước thực hiện thuật toán để giải quyết nhiệm vụ đó.","k":"Ví dụ pha nước chanh. Đầu vào: chanh, đường, nước, đá. Đầu ra: cốc nước chanh. Các bước: vắt chanh vào cốc → cho đường → đổ nước, khuấy tan → cho đá.","label":"Vận dụng – Câu 3"}],"the":[{"t":"Thuật toán","b":"<p><b>Thuật toán</b> là một dãy các chỉ dẫn rõ ràng, có trình tự sao cho khi thực hiện những chỉ dẫn này người ta giải quyết được vấn đề hoặc nhiệm vụ đã cho.</p><p>Thuật toán có <b>đầu vào</b> (Input) là dữ liệu ban đầu và <b>đầu ra</b> (Output) là kết quả.</p>"},{"t":"Mô tả thuật toán","b":"<ul><li>Liệt kê các bước bằng ngôn ngữ tự nhiên và sử dụng sơ đồ khối là những cách mô tả thuật toán.</li><li>Sơ đồ khối của thuật toán là một sơ đồ gồm các hình mô tả các bước và đường có mũi tên để chỉ hướng thực hiện.</li></ul>"}]},"tin6-tim-kiem-thong-tin-tren-internet":{"id":"tin6-bai7","ten":"Bài 7. Tìm kiếm thông tin trên Internet","cau":[{"id":"kd1","type":"open","q":"Em chỉ nhớ vài câu trong một bài hát. Làm thế nào để tìm được cả bài hát đó trên Internet?","k":"Dùng <b>máy tìm kiếm</b> (Google, Cốc Cốc, Bing,…), gõ vài câu đã nhớ làm <b>từ khoá</b> → nhận được danh sách liên kết tới lời bài hát, video trình diễn.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Em đã bao giờ tìm kiếm thông tin trên Internet chưa? Em đã tìm gì? Kết quả có như em mong muốn không?","k":"Học sinh kể trải nghiệm; nhận xét: kết quả có khi rất nhiều, có khi chưa đúng ý → cần chọn từ khoá phù hợp.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Em biết gì về máy tìm kiếm? Sử dụng máy tìm kiếm để tìm kiếm thông tin em thấy có thuận lợi và khó khăn gì?","k":"Thuận lợi: nhanh, nhiều kết quả, nhiều dạng (văn bản, hình ảnh, video). Khó khăn: quá nhiều kết quả, có thông tin không chính xác, cần chọn lọc.","label":"HĐ1 – Câu 2"},{"id":"mt","type":"sort","q":"Mỗi địa chỉ dưới đây có phải là máy tìm kiếm không?","k":"Máy tìm kiếm: Google, Bing, Cốc Cốc, Yahoo. Wikipedia là website bách khoa; mail.google.com là dịch vụ thư điện tử.","cats":["Máy tìm kiếm","Không phải"],"items":[["www.google.com",0],["www.bing.com",0],["www.coccoc.com",0],["www.yahoo.com",0],["vi.wikipedia.org",1],["mail.google.com",1]]},{"id":"tk","type":"mcq","q":"Tìm thông tin về vai trò của tầng ozon. Từ khoá nào cho danh sách kết quả ít hơn, sát nội dung hơn?","k":"<b>B</b>. Đặt từ khoá trong dấu ngoặc kép → chỉ tìm trang có đúng cụm từ đó → <b>thu hẹp phạm vi</b> (khoảng 1 510 kết quả thay vì 52 900).","o":["vai trò của tầng ozon","“vai trò của tầng ozon”","tầng","ozon vai trò tầng của"],"a":1},{"id":"p29a","type":"match","q":"Thay các số trong mỗi câu bằng một cụm từ thích hợp (từ khoá, liên kết, tìm kiếm thông tin): a) Máy tìm kiếm là công cụ hỗ trợ …(1)… trên Internet theo yêu cầu của người sử dụng. b) Kết quả tìm kiếm là danh sách các …(2)…. c) Cần chọn …(3)… phù hợp.","k":"(1) tìm kiếm thông tin; (2) liên kết; (3) từ khoá.","items":[["(1)",3],["(2)",2],["(3)",1]],"opts":["từ khoá","liên kết","tìm kiếm thông tin"]},{"id":"p29b","type":"mcq","q":"Sử dụng máy tìm kiếm em sẽ nhận được kết quả là gì?","k":"<b>A</b>. Kết quả tìm kiếm là danh sách liên kết trỏ đến các trang web có chứa từ khoá.","o":["Danh sách liên kết trỏ đến các trang web có chứa từ khoá.","Nội dung thông tin cần tìm trên một trang web.","Danh sách địa chỉ các trang web có chứa thông tin cần tìm.","Danh sách liên kết dạng văn bản."],"a":0},{"id":"th1","type":"open","q":"Tìm lần lượt với từ khoá vai trò của tầng ozon và “vai trò của tầng ozon”. Ghi lại số kết quả của mỗi lần và so sánh.","k":"Có dấu ngoặc kép cho <b>ít kết quả hơn</b>, sát nội dung hơn. Các trang liên quan nhất thường xuất hiện ở đầu danh sách.","label":"Thực hành – So sánh kết quả"},{"id":"th2","type":"order","q":"Sắp xếp các bước sao chép một đoạn thông tin dạng văn bản từ trang web về tệp văn bản trên máy tính (dùng nút ↑ ↓).","k":"Mở liên kết → chọn nội dung → <b>Ctrl + C</b> → mở tệp văn bản → <b>Ctrl + V</b>.","items":{"a":"Nháy chuột vào một liên kết để xem nội dung","b":"Chọn (bôi đen) nội dung cần sao chép","c":"Nhấn tổ hợp phím Ctrl + C","d":"Mở tệp văn bản, nhấn tổ hợp phím Ctrl + V"},"ans":["a","b","c","d"],"start":["c","d","a","b"]},{"id":"th3","type":"mcq","q":"Để lưu một hình ảnh trên trang web thành tệp trên máy tính, em làm thế nào?","k":"<b>B</b>. Nháy nút phải chuột vào hình ảnh → <b>Lưu hình ảnh thành…</b> → chọn thư mục, đặt tên → Lưu. Muốn chỉ xem ảnh: nháy mục <b>Hình ảnh</b> để lọc kết quả.","o":["Nháy chuột trái vào hình ảnh.","Nháy nút phải chuột vào hình ảnh, chọn lệnh Lưu hình ảnh thành… (Save image as…).","Nhấn phím Enter.","Chụp màn hình bằng điện thoại."],"a":1},{"id":"lt1","type":"mcq","q":"Khi tìm kiếm thông tin bằng máy tìm kiếm, kết quả là danh sách liên kết dưới dạng nào?","k":"<b>D</b>. Các liên kết có thể là văn bản, hình ảnh hoặc video.","o":["Văn bản.","Hình ảnh.","Video.","Văn bản, hình ảnh, video."],"a":3},{"id":"lt2","type":"mcq","q":"Để tìm kiếm thông tin về lớp vỏ Trái Đất, em sử dụng từ khoá nào để thu hẹp phạm vi tìm kiếm?","k":"<b>C</b>. Đặt cả cụm từ trong dấu ngoặc kép.","o":["Trái Đất.","Lớp vỏ Trái Đất.","“lớp vỏ Trái Đất”.","“lớp vỏ” + “Trái Đất”."],"a":2},{"id":"vd1","type":"open","q":"Em hãy tìm thông tin về Văn Miếu – Quốc Tử Giám trên mạng Internet. Ghi lại từ khoá em dùng và 2–3 thông tin em tìm được.","k":"Ví dụ từ khoá: “Văn Miếu Quốc Tử Giám”. Thông tin: xây dựng năm 1070 thời Lý Thánh Tông; Quốc Tử Giám là trường đại học đầu tiên của Việt Nam; có 82 tấm bia tiến sĩ,…","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Gia đình em có kế hoạch đi du lịch Hạ Long. Hãy dùng máy tìm kiếm để: a) tìm thông tin thời tiết ở Hạ Long trong tuần này; b) tìm những điểm tham quan đẹp ở Hạ Long; c) sao chép và lưu các thông tin, hình ảnh vào một tệp văn bản để giới thiệu với gia đình.","k":"a) Từ khoá: “thời tiết Hạ Long”. b) “điểm tham quan Hạ Long” (hang Sửng Sốt, đảo Ti Tốp, động Thiên Cung,…). c) Ctrl + C, Ctrl + V văn bản; nháy phải → Lưu hình ảnh thành…","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Máy tìm kiếm là một website đặc biệt, giúp người sử dụng tìm kiếm thông tin trên Internet một cách nhanh chóng, hiệu quả thông qua các từ khoá.</li><li>Kết quả tìm kiếm là danh sách các liên kết. Các liên kết có thể là văn bản, hình ảnh hoặc video.</li><li>Từ khoá tìm kiếm rất quan trọng. Lựa chọn từ khoá phù hợp sẽ giúp tìm kiếm thông tin nhanh và chính xác.</li></ul>"}]},"tin6-tim-kiem-va-thay-the":{"id":"tin6-bai13","ten":"Bài 13. Thực hành: Tìm kiếm và thay thế","cau":[{"id":"hd1a","type":"open","q":"Từ công thức làm kem sữa chua dưa hấu, muốn thành công thức làm kem sữa chua xoài em làm thế nào?","k":"Thay tất cả các từ “dưa hấu” trong công thức bằng từ “xoài”.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Trong phần mềm soạn thảo văn bản, em thực hiện những thao tác nào để giúp An chỉnh sửa tệp văn bản công thức làm kem?","k":"Tìm từng chỗ có từ “dưa hấu”, xoá đi rồi gõ “xoài” (làm thủ công) – hoặc dùng công cụ <b>Tìm kiếm và Thay thế</b>.","label":"HĐ1 – Câu 2"},{"id":"hd1c","type":"open","q":"Em có biết cách nào chỉnh sửa tệp văn bản nhanh hơn không?","k":"Dùng công cụ <b>Replace</b> (Thay thế) với nút <b>Replace All</b>: thay tất cả chỉ bằng một lần nháy chuột.","label":"HĐ1 – Câu 3"},{"id":"tl","type":"mcq","q":"Với văn bản dài hàng trăm trang, dùng công cụ Tìm kiếm và Thay thế có lợi gì?","k":"<b>B</b>. Công cụ Tìm kiếm và Thay thế giúp tìm, thay từ hoặc cụm từ <b>nhanh chóng và chính xác</b>, tiết kiệm thời gian và không bỏ sót.","o":["Văn bản đẹp hơn.","Tìm kiếm, thay thế nhanh chóng, chính xác, không bỏ sót.","Văn bản ngắn hơn.","Tự động sửa mọi lỗi chính tả."],"a":1},{"id":"th1","type":"order","q":"Sắp xếp các bước tìm kiếm cụm từ “dưa hấu” trong văn bản (dùng nút ↑ ↓).","k":"Home → Editing → <b>Find</b> → gõ cụm từ, Enter. Các từ tìm thấy được đánh dấu; nháy vào các kết quả trong ô Navigation để chuyển đến từng vị trí.","items":{"a":"Nháy chuột vào thẻ Home","b":"Trong nhóm lệnh Editing, chọn Find","c":"Gõ từ, cụm từ cần tìm vào ô Navigation rồi nhấn phím Enter"},"ans":["a","b","c"],"start":["c","a","b"]},{"id":"th2","type":"mcq","q":"Trong hộp thoại Find and Replace, nút nào thay thế tất cả các cụm từ tìm được trong toàn bộ văn bản?","k":"<b>Replace All</b> thay tất cả. <b>Replace</b> thay lần lượt từng cụm từ tìm kiếm được; <b>Find Next</b> tìm vị trí tiếp theo.","o":["Find Next","Replace","Replace All","Cancel"],"a":2},{"id":"th3","type":"open","q":"Nhập công thức làm kem sữa chua dưa hấu, lưu với tên kemsuachua-duahau.docx. Thay thế “dưa hấu” bằng “xoài” rồi lưu với tên kemsuachua-xoai.docx. Có bao nhiêu chỗ đã được thay thế?","k":"Ví dụ: thay được 4 chỗ (tên món, nguyên liệu, bước 1, bước 2). Lưu ý dùng File/Save As để lưu thành tệp mới.","label":"Thực hành – Kem sữa chua xoài"},{"id":"lt1","type":"open","q":"Tệp văn bản chứa các bài viết cảm nghĩ gồm nhiều trang. An muốn xem lại nội dung bài viết về nhóm bạn thân lớp 6A, nhưng không nhớ ở trang nào. Vì vậy, An thực hiện thao tác tìm kiếm cụm từ “nhóm bạn thân” trong tệp văn bản. An phải thực hiện thao tác gì để xem lần lượt các kết quả tìm thấy?","k":"Nháy chuột lần lượt vào các kết quả hiện trong ô <b>Navigation</b> (hoặc dùng mũi tên ▲▼ / Find Next) để chuyển tới từng vị trí tìm thấy.","label":"Luyện tập – Câu 1"},{"id":"lt2","type":"order","q":"Em hãy sắp xếp lại các bước sau đây theo thứ tự đúng để thực hiện thao tác thay thế một từ hoặc cụm từ trong phần mềm soạn thảo văn bản (dùng nút ↑ ↓).","k":"b) Home → c) Replace → d) gõ cụm từ cần tìm → a) gõ cụm từ thay thế → e) Replace.","items":{"a":"Gõ từ, cụm từ cần thay thế.","b":"Nháy chuột vào thẻ Home.","c":"Trong nhóm lệnh Editing, chọn Replace.","d":"Gõ từ, cụm từ cần tìm.","e":"Nháy chuột vào nút Replace để thay lần lượt từng từ hoặc cụm từ."},"ans":["b","c","d","a","e"],"start":["a","b","c","d","e"]},{"id":"vd","type":"open","q":"Trong bài học trước, em đã tạo ra một số tệp văn bản cho cuốn sổ lưu niệm. Em hãy xem lại các tệp văn bản này để rà soát lỗi chính tả. Em có thể sử dụng chức năng Tìm kiếm và Thay thế để chỉnh sửa các lỗi chính tả, thay thế các từ viết tắt,… để các tệp văn bản hoàn chỉnh hơn. Em đã sửa những gì?","k":"Ví dụ: thay “ko” → “không”, “hs” → “học sinh”, sửa “xinh nhật” → “sinh nhật”,…","label":"Vận dụng"}],"the":[{"t":"Tìm kiếm và thay thế","b":"<p>Công cụ Tìm kiếm và Thay thế giúp tìm kiếm, thay thế từ hoặc cụm từ theo yêu cầu một cách nhanh chóng và chính xác.</p>"}]},"tin6-trinh-bay-bang":{"id":"tin6-bai12","ten":"Bài 12. Trình bày thông tin ở dạng bảng","cau":[{"id":"hd1a","type":"open","q":"Hình 5.11 cho thấy hai cách trình bày danh sách học sinh trong cuốn sổ lưu niệm: trang bên trái sử dụng bảng, trang bên phải liệt kê lần lượt danh sách các thành viên. Em hãy nhận xét về hai cách trình bày.","k":"Trình bày bằng <b>bảng</b>: gọn, ngay ngắn, dễ nhìn, dễ tìm, chứa được cả ảnh và chữ. Liệt kê: dài, tốn chỗ, khó tìm.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Em sẽ lựa chọn cách nào để trình bày danh sách học sinh trong cuốn sổ lưu niệm của lớp em? Tại sao?","k":"Chọn trình bày dạng bảng vì cô đọng, đầy đủ, dễ so sánh, tìm kiếm.","label":"HĐ1 – Câu 2"},{"id":"hd2a","type":"mcq","q":"Bảng thống kê kết quả khảo sát gồm mấy cột, mấy hàng?","k":"<b>4 cột</b> (STT, Tên trò chơi, Số bạn nam thích, Số bạn nữ thích), <b>5 hàng</b> (1 hàng tiêu đề + 4 trò chơi).","o":["4 cột, 5 hàng","5 cột, 4 hàng","4 cột, 4 hàng","3 cột, 5 hàng"],"a":0},{"id":"hd2b","type":"mcq","q":"Trò chơi nào được nhiều bạn nam yêu thích nhất? Trò chơi nào được nhiều bạn nữ yêu thích nhất? Trò chơi nào được học sinh cả lớp yêu thích nhất?","k":"Nam: <b>Kéo co</b> (19). Nữ: <b>Lò cò tiếp sức</b> (18). Cả lớp: Kéo co 35, Ném bóng 27, Lò cò 34, Trốn tìm 18 → <b>Kéo co</b>.","o":["Nam: Kéo co; nữ: Lò cò tiếp sức; cả lớp: Kéo co","Nam: Lò cò tiếp sức; nữ: Kéo co; cả lớp: Lò cò tiếp sức","Nam: Kéo co; nữ: Kéo co; cả lớp: Kéo co","Nam: Ném bóng trúng đích; nữ: Trốn tìm; cả lớp: Trốn tìm"],"a":0},{"id":"hd2c","type":"open","q":"Nếu không dùng bảng biểu diễn thì việc so sánh và tìm kiếm có dễ không?","k":"<b>Không</b>. Phải đọc từng phiếu, đếm lại, rất mất thời gian và dễ nhầm. Bảng giúp dễ dàng tìm kiếm, so sánh, tổng hợp thông tin.","label":"HĐ2 – Câu 3"},{"id":"p55a","type":"order","q":"Em hãy sắp xếp lại thứ tự các bước để được thao tác tạo bảng đúng (dùng nút ↑ ↓).","k":"c) Chọn <b>Insert</b> → a) chọn mũi tên dưới <b>Table</b> → b) kéo chuột chọn số hàng, số cột.","items":{"a":"Chọn mũi tên nhỏ bên dưới Table.","b":"Di chuyển chuột để chọn số hàng, số cột.","c":"Chọn Insert."},"ans":["c","a","b"],"start":["a","b","c"]},{"id":"p55b","type":"mcq","q":"Bạn An đã nhập số hàng, số cột như Hình 5.15 (Number of columns: 4; Number of rows: 35) để tạo bảng. Bảng được tạo sẽ có:","k":"<b>A</b>. 4 cột, 35 hàng (columns = cột, rows = hàng).","o":["4 cột, 35 hàng.","35 cột, 35 hàng.","35 cột, 4 hàng.","4 cột, 4 hàng."],"a":0},{"id":"cs","type":"match","q":"Ghép mỗi nhóm lệnh trong thẻ Layout (Table Tools) với chức năng của nó.","k":"Delete – xoá; Insert – chèn hàng, cột; Merge/Split – gộp, tách; Cell Size – kích thước ô; Alignment – căn lề trong ô.","items":[["Delete",1],["Insert Above / Below / Left / Right",2],["Merge Cells / Split Cells / Split Table",3],["Height / Width (Cell Size)",4],["Alignment",5]],"opts":["Xoá bảng, xoá hàng, cột","Chèn thêm hàng, cột","Gộp, tách ô, tách bảng","Điều chỉnh kích thước ô","Căn chỉnh lề, hướng của văn bản trong ô"]},{"id":"p55c","type":"mcq","q":"Muốn xoá một số hàng trong bảng, sau khi chọn các hàng cần xoá, em thực hiện lệnh nào sau đây?","k":"<b>C</b>. Delete Rows (Rows = hàng).","o":["Delete Cells.","Delete Columns.","Delete Rows.","Delete Table."],"a":2},{"id":"th1","type":"order","q":"Sắp xếp các bước gộp bốn ô nhỏ thành một ô to cho phần giáo viên chủ nhiệm (dùng nút ↑ ↓).","k":"Chọn các ô → <b>Layout</b> → <b>Merge Cells</b>. Thay đổi độ rộng cột/độ cao hàng: kéo thả đường biên khi con trỏ thành mũi tên hai chiều.","items":{"a":"Kéo thả chuột để chọn bốn ô của bảng","b":"Trong nhóm thẻ Table Tools, chọn thẻ Layout","c":"Trong nhóm lệnh Merge, chọn Merge Cells"},"ans":["a","b","c"],"start":["c","a","b"]},{"id":"th2","type":"open","q":"Tạo bảng danh sách thành viên của lớp như Hình 5.11: ảnh, họ tên, ngày sinh của giáo viên chủ nhiệm và từng thành viên trong lớp; chỉnh sửa, định dạng bảng. Bảng của em có mấy hàng, mấy cột? Em đã gộp những ô nào?","k":"Ví dụ: bảng 4 cột × 4 hàng, gộp 4 ô góc trên bên trái cho giáo viên chủ nhiệm; có thể chèn thêm hàng, cột cho đủ thành viên; bổ sung địa chỉ, sở thích,…","label":"Thực hành – Danh sách lớp"},{"id":"lt1","type":"open","q":"Soạn bảng kết quả khảo sát trò chơi tập thể ở Mục 1. Nếu cần bổ sung cột Tổng số (số học sinh cả lớp thích trò chơi tương ứng) thì em sẽ chèn cột này vào vị trí nào của bảng? Hãy chèn và điền số liệu cho cột Tổng số.","k":"Chèn cột <b>bên phải</b> cột “Số bạn nữ thích” (Insert Right). Tổng số: Kéo co 35, Ném bóng trúng đích 27, Lò cò tiếp sức 34, Trốn tìm 18.","label":"Luyện tập – Câu 1"},{"id":"lt2","type":"open","q":"Bản tin “Phong trào đọc sách”: năm 2017 có 230 em (52% tổng số học sinh khối 6) yêu thích đọc sách; năm 2018 và 2019 lần lượt là 256 em (64%) và 345 em (78%). a) Tạo một bảng để trình bày cô đọng nội dung bản tin. b) Bổ sung thông tin: năm 2016 có 175 em yêu thích đọc sách, chiếm 45%. Bảng của em gồm những cột, hàng nào?","k":"Bảng 3 cột: Năm | Số học sinh thích đọc sách | Tỉ lệ (%). Các hàng: 2016 – 175 – 45%; 2017 – 230 – 52%; 2018 – 256 – 64%; 2019 – 345 – 78% (chèn hàng 2016 phía trên hàng 2017).","label":"Luyện tập – Câu 2"},{"id":"vd1","type":"open","q":"Em hãy trình bày dưới dạng bảng: a) Thời khoá biểu của lớp. b) Thời gian biểu hoạt động các ngày trong tuần của em. Bảng của em có mấy cột, mấy hàng?","k":"Thời khoá biểu: cột Tiết + các cột Thứ Hai → Thứ Bảy; hàng là các tiết. Thời gian biểu: cột Giờ + các ngày trong tuần.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Em hãy xem lại nội dung cuốn sổ lưu niệm và cân nhắc xem phần nội dung nào nên được trình bày ở dạng bảng thì hợp lí hơn. Hãy trình bày lại nội dung đó.","k":"Ví dụ: danh sách thành viên, lịch các hoạt động của lớp, bảng thành tích, sinh nhật các bạn theo tháng,…","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<p>Chúng ta có thể sử dụng bảng để trình bày thông tin một cách cô đọng. Bảng cũng thường được sử dụng để ghi lại dữ liệu của công việc thống kê, điều tra, khảo sát,… Từ bảng dữ liệu, em có thể dễ dàng tìm kiếm, so sánh, tổng hợp được thông tin.</p>"}]},"tin6-xu-li-thong-tin":{"id":"tin6-bai2","ten":"Bài 2. Xử lí thông tin","cau":[{"id":"kd1","type":"open","q":"Theo em, để sút thắng thủ môn, cầu thủ đã phải quan sát, suy nghĩ và hành động như thế nào?","k":"Cầu thủ <b>quan sát</b> thủ môn, <b>đoán</b> góc sơ hở, rồi <b>điều khiển chân</b> sút bóng vào góc đó. Tất cả do bộ não thực hiện rất nhanh → bộ não đang <b>xử lí thông tin</b>.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Bộ não của cầu thủ nhận được thông tin từ những giác quan nào?","k":"Chủ yếu từ <b>mắt</b> (nhìn vị trí thủ môn, khung thành, quả bóng); ngoài ra còn tai (nghe tiếng còi).","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Thông tin nào được bộ não ghi nhớ và sử dụng khi đá phạt?","k":"Vị trí của thủ môn, khung thành; kết quả của hoạt động trước (ví dụ: góc nào sơ hở) để làm hoạt động sau.","label":"HĐ1 – Câu 2"},{"id":"hd1c","type":"open","q":"Bộ não xử lí thông tin nhận được thành thông tin gì?","k":"Thành <b>ý định</b> của cầu thủ: sút bóng vào góc cao của khung thành.","label":"HĐ1 – Câu 3"},{"id":"hd1d","type":"open","q":"Bộ não chuyển thông tin điều khiển thành thao tác nào của cầu thủ?","k":"Thao tác <b>chân sút bóng</b> (sải bước, tạo đà, sút mạnh vào góc cao).","label":"HĐ1 – Câu 4"},{"id":"hd1e","type":"order","q":"Quá trình xử lí thông tin của bộ não gồm những hoạt động nào? Sắp xếp theo thứ tự như Hình 1.1 (dùng nút ↑ ↓).","k":"Thu nhận → Lưu trữ → Xử lí → Truyền thông tin.","items":{"a":"Thu nhận thông tin","b":"Lưu trữ thông tin","c":"Xử lí thông tin","d":"Truyền thông tin"},"ans":["a","b","c","d"],"start":["c","a","d","b"]},{"id":"ct","type":"sort","q":"Mỗi việc dưới đây thuộc hoạt động nào của quá trình xử lí thông tin?","k":"<b>Thu nhận</b>: nhờ giác quan. <b>Lưu trữ</b>: ghi nhớ, ghi chép. <b>Xử lí</b>: so sánh, phân tích, suy luận, quyết định → thông tin mới. <b>Truyền</b>: chuyển thành hành vi hoặc chia sẻ cho người khác.","cats":["Thu nhận","Lưu trữ","Xử lí","Truyền"],"items":[["Mắt nhìn vị trí thủ môn và khung thành",0],["Tai nghe tiếng còi của trọng tài",0],["Não ghi nhớ kết quả lần sút trước",1],["Ghi kết quả trận đấu vào sổ",1],["Não suy luận xem góc nào sơ hở nhất",2],["Não quyết định sút vào góc cao",2],["Não điều khiển chân sút bóng",3],["Kể cho bạn nghe về bàn thắng",3]]},{"id":"p9","type":"sort","q":"Mỗi việc dưới đây thuộc hoạt động nào trong quá trình xử lí thông tin?","k":"a, b – <b>thu nhận</b> (nghe, nhìn); c – <b>lưu trữ</b> (ghi chép vào vở); d – <b>xử lí</b> (tính toán ra kết quả mới).","cats":["Thu nhận","Lưu trữ","Xử lí","Truyền"],"items":[["a) Em đang nghe chương trình ca nhạc trên Đài tiếng nói Việt Nam.",0],["b) Bố em xem chương trình thời sự trên ti vi.",0],["c) Em chép bài trên bảng vào vở.",1],["d) Em thực hiện một phép tính nhẩm.",2]]},{"id":"tb","type":"sort","q":"Mỗi thiết bị dưới đây thuộc thành phần nào của máy tính?","k":"<b>Thiết bị vào</b> – thu nhận; <b>bộ nhớ</b> – lưu trữ; <b>bộ xử lí</b> – xử lí; <b>thiết bị ra</b> – truyền, chia sẻ thông tin.","cats":["Thiết bị vào","Bộ xử lí","Bộ nhớ","Thiết bị ra"],"items":[["Bàn phím",0],["Chuột",0],["Máy quét",0],["CPU",1],["Thẻ nhớ",2],["Đĩa quang",2],["Màn hình",3],["Máy in",3]]},{"id":"p10a","type":"mcq","q":"Máy tính gồm mấy thành phần để có thể thực hiện được các hoạt động xử lí thông tin?","k":"<b>4</b> thành phần: thiết bị vào, bộ nhớ, bộ xử lí, thiết bị ra.","o":["3","4","5","6"],"a":1},{"id":"p10b","type":"mcq","q":"Chức năng của bộ nhớ máy tính là gì?","k":"Bộ nhớ dùng để <b>lưu trữ</b> thông tin.","o":["Thu nhận thông tin.","Hiển thị thông tin.","Lưu trữ thông tin.","Xử lí thông tin."],"a":2},{"id":"hd2a","type":"open","q":"Nêu ví dụ máy tính giúp con người thu nhận thông tin. So sánh hiệu quả khi có và khi không dùng máy tính.","k":"Ví dụ: chụp ảnh, quét bài thơ bằng điện thoại trong vài giây – nhanh hơn chép tay rất nhiều; tìm thông tin trên mạng có đủ chữ, hình, âm thanh, phim.","label":"HĐ2 – a) Thu nhận"},{"id":"hd2b","type":"open","q":"Nêu ví dụ máy tính giúp con người lưu trữ thông tin. So sánh hiệu quả.","k":"Ví dụ: một thẻ nhớ nhỏ chứa nội dung hàng nghìn cuốn sách; ảnh lưu trên máy không bị phai, dễ tìm lại.","label":"HĐ2 – b) Lưu trữ"},{"id":"hd2c","type":"open","q":"Nêu ví dụ máy tính giúp con người xử lí thông tin. So sánh hiệu quả.","k":"Ví dụ: máy tính thực hiện hàng trăm tỉ phép tính mỗi giây, chính xác; tính số Pi đến hàng nghìn tỉ chữ số – con người không thể làm được.","label":"HĐ2 – c) Xử lí"},{"id":"hd2d","type":"open","q":"Nêu ví dụ máy tính giúp con người truyền thông tin. So sánh hiệu quả.","k":"Ví dụ: gửi thư điện tử, gọi video cho người ở xa trong vài giây thay vì gửi thư qua bưu điện mất nhiều ngày.","label":"HĐ2 – d) Truyền"},{"id":"p11","type":"mcq","q":"Máy tính giúp con người nâng cao hiệu quả trong những hoạt động nào của quá trình xử lí thông tin?","k":"<b>D</b>. Máy tính hỗ trợ <b>cả bốn</b> hoạt động: thu nhận dễ dàng, đa dạng; lưu trữ lượng rất lớn; xử lí nhanh, chính xác; truyền đi khắp nơi.","o":["Chỉ thu nhận thông tin.","Chỉ xử lí thông tin (tính toán).","Chỉ lưu trữ và truyền thông tin.","Cả bốn hoạt động: thu nhận, lưu trữ, xử lí và truyền thông tin."],"a":3},{"id":"lt1","type":"mcq","q":"Vật mang tin xuất hiện trong hoạt động nào của quá trình xử lí thông tin? Bộ nhớ có là vật mang tin không?","k":"<b>A</b>. Vật mang tin dùng khi <b>lưu trữ</b> thông tin; bộ nhớ máy tính chứa dữ liệu nên <b>là vật mang tin</b>.","o":["Hoạt động lưu trữ thông tin; bộ nhớ là vật mang tin.","Hoạt động xử lí thông tin; bộ nhớ không phải vật mang tin.","Hoạt động thu nhận thông tin; bộ nhớ không phải vật mang tin.","Không xuất hiện trong hoạt động nào."],"a":0},{"id":"lt2","type":"sort","q":"Em hãy phân loại những công việc sau đây theo các hoạt động của quá trình xử lí thông tin.","k":"a – thu nhận; b – lưu trữ; c – xử lí; d – truyền thông tin.","cats":["Thu nhận","Lưu trữ","Xử lí","Truyền"],"items":[["a) Quan sát đường đi của một chiếc tàu biển.",0],["b) Ghi chép các sự kiện của một chuyến tham quan.",1],["c) Chuyển thể một bài văn xuôi thành văn vần.",2],["d) Thuyết trình chủ đề tình bạn trước lớp.",3]]},{"id":"vd1","type":"open","q":"Giả sử em được đi chơi xa nhà, hãy phân tích các hoạt động xử lí thông tin liên quan đến việc lên kế hoạch cho chuyến đi.","k":"<b>Thu nhận</b>: tìm thông tin về địa điểm, thời tiết, đường đi. <b>Lưu trữ</b>: ghi lại vào sổ, điện thoại. <b>Xử lí</b>: so sánh, chọn ngày đi, đồ cần mang, lịch trình. <b>Truyền</b>: báo kế hoạch cho bố mẹ, bạn bè.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Liệt kê những lợi ích của máy tính ở một trong các lĩnh vực: y tế, giáo dục, âm nhạc, hội hoạ, xây dựng, nông nghiệp, thương mại, du lịch.","k":"Ví dụ – y tế: lưu hồ sơ bệnh án, chụp chiếu, hỗ trợ chẩn đoán; giáo dục: bài giảng điện tử, học trực tuyến; nông nghiệp: theo dõi thời tiết, tưới tiêu tự động; thương mại: bán hàng trực tuyến…","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<p>Các hoạt động xử lí thông tin bao gồm:</p><ul><li>Thu nhận thông tin.</li><li>Lưu trữ thông tin.</li><li>Xử lí thông tin.</li><li>Truyền thông tin.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Máy tính có đủ bốn thành phần thực hiện các hoạt động xử lí thông tin: thiết bị vào (thu nhận thông tin), bộ nhớ (lưu trữ thông tin), bộ xử lí (xử lí thông tin) và thiết bị ra (truyền, chia sẻ thông tin).</li><li>Máy tính là thiết bị hỗ trợ con người xử lí thông tin một cách hiệu quả do nó có thể thực hiện nhanh các lệnh, tính toán chính xác, xử lí nhiều dạng thông tin, lưu trữ thông tin với dung lượng lớn và hoạt động bền bỉ.</li></ul>"}]},"tin7-cong-cu-ho-tro-tinh-toan":{"id":"tin7-bai8","ten":"Bài 8. Công cụ hỗ trợ tính toán","cau":[{"id":"kd1","type":"open","q":"Phần mềm bảng tính có rất nhiều hàm có sẵn hỗ trợ tính toán, ví dụ hàm tính tổng, hàm đếm, hàm tính giá trị trung bình,… Trong dự án Trường học xanh có cần dùng các hàm này để tính toán không? Em dự đoán sẽ cần tính những gì?","k":"<b>Có.</b> Ví dụ: tính <b>tổng</b> số cây mỗi lớp trồng, số cây <b>trung bình</b>, lớp trồng <b>nhiều nhất, ít nhất</b>, <b>đếm</b> số lớp trồng một loại cây,…","label":"Mở đầu"},{"id":"hd1","type":"open","q":"Quan sát công thức là hàm trong Hình 8.1 và Hình 8.2 (chú ý vùng nhập dữ liệu) và trả lời: 1. Tên của hàm là gì? 2. Ý nghĩa của hàm là gì? 3. Hàm có bao nhiêu tham số, các tham số của hàm là gì?","k":"Hình 8.1: hàm <b>SUM</b>, tính <b>tổng</b>; 1 tham số là vùng <b>B5:D7</b> → 24. Hình 8.2: hàm <b>AVERAGE</b>, tính <b>trung bình cộng</b>; 1 tham số là vùng <b>B5:C7</b> → 5.","label":"HĐ1 – Hàm trong bảng tính"},{"id":"cuphap","type":"mcq","q":"Cách viết nào dưới đây đúng cú pháp nhập hàm tính tổng vùng B5:D7?","k":"<b>=SUM(B5:D7)</b>. Cú pháp: <b>= &lt;tên hàm&gt;(&lt;các tham số&gt;)</b>. Các tham số cách nhau bởi dấu “,” hoặc “;”.","o":["SUM(B5:D7)","=SUM B5:D7","=SUM(B5:D7)","=(B5:D7)SUM"],"a":2},{"id":"hd2","type":"open","q":"Theo em, nhập hàm vào bảng tính có giống như nhập dữ liệu thông thường không? Hãy nêu các bước nhập hàm tính tổng số cây hoa của lớp 7A vào ô C9.","k":"Nhập hàm <b>giống nhập công thức</b>: Bước 1. Nháy chuột vào ô C9 (hoặc vùng nhập dữ liệu). Bước 2. Gõ <b>=SUM(</b>, dùng chuột đánh dấu vùng <b>C4:C8</b>, gõ “)”, nhấn <b>Enter</b>.","label":"HĐ2 – Nhập hàm"},{"id":"saochep","type":"mcq","q":"Sao chép công thức =SUM(C4:C8) từ ô C9 sang các ô từ D9 đến I9. Công thức tại ô I9 là:","k":"<b>=SUM(I4:I8)</b>: sao chép sang phải 6 cột nên địa chỉ cột trong tham số cũng dịch 6 cột.","o":["=SUM(C4:C8)","=SUM(I4:I8)","=SUM(C9:I9)","=SUM(I9:I13)"],"a":1},{"id":"p41a","type":"open","q":"Hàm được nhập như thế nào?","k":"Giống nhập công thức: <b>= &lt;tên hàm&gt;(&lt;các tham số&gt;)</b>, nhấn Enter. Cần nhập chính xác tên hàm và tham số; tên hàm viết hoa hoặc thường đều được; có thể dùng chuột chọn ô, vùng làm tham số.","label":"Câu hỏi tr.41 – câu 1"},{"id":"p41b","type":"mcq","q":"Các tham số của hàm có thể là địa chỉ ô hoặc vùng dữ liệu không?","k":"<b>Có.</b> Ví dụ =SUM(D4:H4,15,K10): tham số là vùng D4:H4, số 15 và ô K10.","o":["Có. Tham số có thể là số, địa chỉ ô, địa chỉ vùng dữ liệu.","Không. Tham số chỉ có thể là số."],"a":0},{"id":"hd3","type":"open","q":"Em hãy xem lại dữ liệu của dự án Trường học xanh và cho biết em cần tính toán những gì? Các yêu cầu tính toán đó có thể diễn tả bằng các hàm như thế nào?","k":"Ví dụ: tổng số cây mỗi lớp → <b>SUM</b>; trung bình mỗi lớp trồng bao nhiêu cây → <b>AVERAGE</b>; lớp trồng nhiều nhất, ít nhất → <b>MAX, MIN</b>; bao nhiêu lớp trồng một loại cây → <b>COUNT</b>.","label":"HĐ3 – Một số hàm đơn giản"},{"id":"yn","type":"sort","q":"Đọc Bảng 8.2. Mỗi ý nghĩa dưới đây là của hàm nào?","k":"<b>SUM</b> tổng, <b>AVERAGE</b> trung bình cộng, <b>MIN</b> nhỏ nhất, <b>MAX</b> lớn nhất, <b>COUNT</b> đếm số các giá trị là số. Các hàm chỉ xử lí dữ liệu số, <b>bỏ qua</b> ô chứa văn bản hoặc ô trống.","cats":["SUM","AVERAGE","MIN","MAX","COUNT"],"items":[["Tính tổng các giá trị số",0],["Tính trung bình cộng các giá trị số",1],["Tìm giá trị nhỏ nhất",2],["Tìm giá trị lớn nhất",3],["Đếm số các giá trị là số",4]]},{"id":"b81","type":"sort","q":"Nhập các công thức của Bảng 8.1 vào K4:K8 trên bảng mô phỏng. Mỗi yêu cầu tính toán dưới đây có kết quả bao nhiêu?","k":"=AVERAGE(C4:I8) = <b>13.6667</b> (287 cây : 21 ô có số); =MAX(C6:I6) = <b>16</b>; =MIN(C4:I4) = <b>10</b>; =COUNT(C8:I8) = <b>4</b>; =COUNT(D4:D8) = <b>3</b>.","cats":["13.6667","16","10","4","3"],"items":[["Trung bình mỗi lớp sẽ trồng bao nhiêu cây? =AVERAGE(C4:I8)",0],["Số cây hoa Dừa cạn lớn nhất một lớp sẽ trồng? =MAX(C6:I6)",1],["Số cây hoa Mười giờ ít nhất một lớp sẽ trồng? =MIN(C4:I4)",2],["Bao nhiêu lớp sẽ trồng hoa Hồng? =COUNT(C8:I8)",3],["Lớp 7B sẽ trồng bao nhiêu loại hoa? =COUNT(D4:D8)",4]]},{"id":"p42","type":"open","q":"Mỗi hàm sau cho kết quả như thế nào? a) SUM(1,3,“Hà Nội”,“Zero”,5); b) MIN(3,5,“One”,1); c) COUNT(1,3,5,7). (Có thể nhập thử vào bảng mô phỏng.)","k":"Theo lưu ý của SGK (hàm chỉ xử lí giá trị số, bỏ qua văn bản): a) <b>9</b>; b) <b>1</b>; c) <b>4</b>. Lưu ý: trong Excel, Google Sheets, nếu gõ <b>trực tiếp văn bản</b> làm tham số của SUM, MIN thì máy báo lỗi <b>#VALUE!</b> (bảng mô phỏng cũng vậy); còn văn bản nằm <b>trong ô</b> của vùng tham số thì được bỏ qua. COUNT luôn bỏ qua văn bản.","label":"Câu hỏi tr.42"},{"id":"nv1","type":"order","q":"Sắp xếp các bước thực hành (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → a → e → d → c</b>.","items":{"a":"Chèn hai hàng trống trên hàng 9 và trên hàng có STT 12.","b":"Tạo trang tính 4. Dự kiến kết quả, nhập và sao chép dữ liệu.","c":"Định dạng và lưu kết quả.","d":"Tính tổng số cây các loại mỗi lớp (hàng 25), cột Tổng số cây, Trung bình.","e":"Tính tổng số cây mỗi loại mỗi lớp (D9, D17, D24 và sao chép sang phải)."},"ans":["b","a","e","d","c"],"start":["a","b","c","d","e"]},{"id":"nv2","type":"mcq","q":"Tại ô D25, công thức tính tổng số cây đã trồng của lớp 7A là:","k":"<b>=D9+D17+D24</b>: cộng ba tổng cây hoa, cây ăn quả, cây bóng mát. (=SUM(D4:D24) sẽ cộng cả các hàng tổng nên bị gấp đôi.)","o":["=SUM(D4:D24)","=D9+D17+D24","=D9+D17","=SUM(D9:J9)"],"a":1},{"id":"nvkq","type":"open","q":"Báo cáo kết quả: tổng số cây dự kiến của cả khối là bao nhiêu? Lớp nào trồng nhiều cây nhất? Trung bình mỗi lớp trồng bao nhiêu cây?","k":"Tổng cả khối <b>623</b> cây (K25). Lớp <b>7C</b> nhiều nhất: <b>104</b> cây. Trung bình mỗi lớp <b>89</b> cây (L25).","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Tại các ô K9, K17, K24 trong trang tính 4. Dự kiến kết quả có thể dùng công thức khác được không? Nếu có thì dùng công thức gì? Từ đó em rút ra điều gì?","k":"<b>Có.</b> K9 có thể dùng <b>=SUM(D9:J9)</b> (cộng hàng tổng) hoặc <b>=SUM(K4:K8)</b> (cộng cột tổng) — đều bằng 287. Tương tự K17, K24. Rút ra: tổng theo hàng của các tổng cột bằng tổng theo cột của các tổng hàng; có nhiều cách viết công thức cho cùng một kết quả.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"mcq","q":"Các công thức sau có cho kết quả giống nhau không? a) =SUM(C3:K3); b) =C3 + SUM(D3:J3) + K3; c) =SUM(C3:G3) + SUM(H3:K3)","k":"<b>Giống nhau</b>: cả ba đều cộng các ô C3, D3,…, K3, chỉ chia vùng theo cách khác nhau.","o":["Giống nhau: đều là tổng các ô từ C3 đến K3.","Khác nhau hoàn toàn.","Chỉ a và b giống nhau.","Chỉ a và c giống nhau."],"a":0},{"id":"lt3","type":"open","q":"Dựa trên dữ liệu của Bảng 4. Dự kiến phân bổ cây cho các lớp, em hãy: a) Tìm số cây lớn nhất sẽ được trồng của các lớp. b) Tính số cây trung bình sẽ được trồng của các lớp. Ghi công thức và kết quả.","k":"a) <b>=MAX(D25:J25)</b> → 104 (lớp 7C). b) <b>=AVERAGE(D25:J25)</b> → 89.","label":"Luyện tập – câu 3"},{"id":"vd1","type":"open","q":"Tạo bảng tính ghi lại các khoản chi tiêu của gia đình em trong một tháng. Sử dụng các hàm để trả lời: a) Tổng số tiền chi tiêu một tháng? b) Khoản chi nhiều nhất, ít nhất? c) Có bao nhiêu khoản đã chi? d) Trung bình mỗi ngày chi bao nhiêu tiền? Ghi các công thức em đã dùng.","k":"Nếu số tiền ở B2:B11: a) <b>=SUM(B2:B11)</b>; b) <b>=MAX(B2:B11)</b>, <b>=MIN(B2:B11)</b>; c) <b>=COUNT(B2:B11)</b>; d) <b>=SUM(B2:B11)/30</b> (tháng 30 ngày). Chia sẻ với bố mẹ để cân đối chi tiêu hợp lí.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Cách nhập hàm tương tự như cách nhập công thức. Cú pháp nhập hàm: <b>= &lt;tên hàm&gt;(&lt;các tham số&gt;)</b>.</li><li>Cần nhập chính xác tên của hàm và các tham số của hàm. Khi nhập thông tin vùng dữ liệu trong tham số của hàm có thể dùng chuột chọn các ô hoặc vùng này. Tên hàm có thể dùng chữ in hoa hoặc in thường.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>SUM</b>: tổng; <b>AVERAGE</b>: trung bình cộng; <b>MIN</b>: nhỏ nhất; <b>MAX</b>: lớn nhất; <b>COUNT</b>: đếm số các giá trị là số.</li><li>Các hàm chỉ xử lí các ô có dữ liệu số, <b>bỏ qua</b> các ô chứa văn bản hoặc ô trống.</li><li>Bảng tính thường dùng dấu chấm “.” ngăn cách phần nguyên và phần thập phân, dấu phẩy “,” ngăn cách hàng nghìn, hàng triệu.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Chèn hàng: chọn hàng, nháy nút phải chuột, chọn <b>Insert</b>.</li><li>Tổng mỗi loại: <b>=SUM(D4:D8)</b> rồi sao chép sang phải; tổng cả hàng: <b>=SUM(D4:J4)</b>; trung bình: <b>=AVERAGE(D4:J4)</b>.</li></ul>"}]},"tin7-dinh-dang-trang-chieu":{"id":"tin7-bai12","ten":"Bài 12. Định dạng đối tượng trên trang chiếu","cau":[{"id":"kd1","type":"open","q":"Đọc đoạn hội thoại của An, Minh và Khoa. Để bài báo cáo dự án Trường học xanh thật ấn tượng, các bạn định làm những gì?","k":"<b>Sao chép</b> dữ liệu có sẵn từ tệp văn bản Truonghocxanh.docx và kết quả tính toán từ bảng tính THXanh.xlsx; minh hoạ bằng <b>hình ảnh</b> (trực quan, thuyết phục); sử dụng <b>định dạng văn bản và ảnh minh hoạ</b> một cách hợp lí.","label":"Mở đầu"},{"id":"hd1a","type":"open","q":"Theo em có nên sử dụng hình ảnh để minh hoạ cho bài trình chiếu không? Vì sao?","k":"<b>Nên</b>, vì hình ảnh là dạng thông tin trực quan, dễ gây ấn tượng; giúp bài trình chiếu <b>hấp dẫn, sinh động</b>, thu hút sự chú ý của người nghe.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Em sẽ chọn hình ảnh gì để thêm vào bài trình chiếu báo cáo dự án?","k":"Hình ảnh <b>phù hợp với nội dung</b>, có <b>tính thẩm mĩ</b>: cây xanh, vườn hoa, sân trường, các bạn học sinh trồng cây,… Ưu tiên ảnh tự chụp hoặc ảnh được phép sử dụng.","label":"HĐ1 – Câu 2"},{"id":"p62","type":"sort","q":"Phát biểu nào đúng, phát biểu nào sai?","k":"a, b, d <b>đúng</b>; c <b>sai</b>: hình ảnh (cả màu sắc, hoạ tiết) cần phù hợp với nội dung, chủ đề của bài trình chiếu.","cats":["Đúng","Sai"],"items":[["a) Hình ảnh minh hoạ làm cho bài trình chiếu ấn tượng hơn.",0],["b) Nên chọn hình ảnh phù hợp với chủ đề của bài trình chiếu.",0],["c) Màu sắc, hoạ tiết trên hình ảnh không cần trùng khớp với chủ đề.",1],["d) Hình ảnh minh hoạ cần có tính thẩm mĩ.",0]]},{"id":"hd2a","type":"open","q":"Sau khi tạo văn bản cho một bài trình chiếu, em thường định dạng văn bản như thế nào? Cần làm gì để nhấn mạnh nội dung trên một trang?","k":"Chọn phông, cỡ, kiểu, màu chữ, căn lề,… giống trong phần mềm soạn thảo. Để nhấn mạnh: dùng <b>chữ đậm, màu</b> nổi bật cho thông điệp chính, cỡ chữ tiêu đề lớn hơn nội dung.","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"mcq","q":"Có nên viết nhiều chữ, dùng nhiều màu trên một trang không?","k":"<b>Không nên.</b> Màu nền và định dạng văn bản cần thống nhất. Không nên dùng nhiều màu, nhiều phông chữ trên một trang; nội dung cô đọng, khoảng 5–7 dòng mỗi trang.","o":["Nên, để trang chiếu đầy đủ thông tin và nhiều màu sắc.","Không nên: mỗi trang chỉ nên có khoảng 5 đến 7 dòng, tập trung vào một ý chính; màu chữ tương phản với màu nền, không dùng quá nhiều màu.","Nên viết thật nhiều chữ nhưng chỉ một màu.","Chỉ nên dùng hình, không dùng chữ."],"a":1},{"id":"quytac","type":"sort","q":"Đọc mục 2 (SGK trang 62). Mỗi lời khuyên dưới đây nói về yếu tố nào?","k":"<b>Phông</b> đơn giản, dễ đọc; <b>cỡ</b> tiêu đề 40–50, nội dung ≥ 18; <b>kiểu</b> tiêu đề đậm; <b>màu</b> tương phản nền; <b>số lượng chữ</b> 5–7 dòng mỗi trang.","cats":["Phông chữ","Cỡ chữ","Kiểu chữ","Màu chữ","Số lượng chữ"],"items":[["Chọn phông đơn giản, dễ đọc (Arial, Calibri, Tahoma,…)",0],["Tiêu đề từ 40 đến 50, văn bản từ 18 trở lên",1],["Tiêu đề chọn chữ đậm, nội dung chữ thường",2],["Tương phản với màu nền, không dùng quá nhiều màu",3],["Mỗi trang chỉ khoảng 5 đến 7 dòng",4]]},{"id":"p63","type":"sort","q":"Ghép mỗi nội dung ở cột A với một nội dung phù hợp ở cột B.","k":"1 – d; 2 – a; 3 – b; 4 – c.","cats":["a) nội dung chính của trang chiếu","b) cô đọng","c) cho văn bản trên một trang chiếu","d) tương tự như định dạng trong soạn thảo văn bản"],"items":[["1) Định dạng văn bản trong trang chiếu",3],["2) Định dạng làm nổi bật",0],["3) Nội dung trên mỗi trang chiếu",1],["4) Không nên dùng quá nhiều phông chữ",2]]},{"id":"nv1","type":"order","q":"Sắp xếp các bước sao chép dữ liệu từ tệp văn bản sang tệp trình chiếu (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → c</b>. Thông tin về dự án sẽ thống nhất, chính xác và tiết kiệm thời gian soạn thảo.","items":{"a":"Mở tệp trình chiếu Truonghocxanh.pptx.","b":"Mở tệp văn bản Truonghocxanh.docx.","c":"Đặt con trỏ tại vị trí cần sao chép đến, chọn Home/Paste (Ctrl+V).","d":"Chọn phần dữ liệu cần sao chép, chọn Home/Copy (Ctrl+C)."},"ans":["b","d","a","c"],"start":["a","b","c","d"]},{"id":"nv2","type":"mcq","q":"Muốn áp dụng một mẫu định dạng (theme) chỉ cho trang 3 và trang 4, em làm thế nào?","k":"<b>B</b>. Nếu không chọn trang thì mẫu được áp dụng cho tất cả các trang. Nút <b>More</b> để xem thêm mẫu; <b>Variants</b> để đổi màu sắc, phông, hiệu ứng, nền; <b>Undo (Ctrl+Z)</b> để khôi phục mẫu trước đó.","o":["Nháy vào mẫu trong nhóm Themes mà không chọn trang nào.","Nhấn giữ Ctrl để chọn đồng thời trang 3 và 4, chọn thẻ Design rồi nháy vào mẫu muốn áp dụng.","Chọn thẻ Insert/Pictures.","Nhấn Ctrl+Z."],"a":1},{"id":"nv3","type":"mcq","q":"Hình ảnh vừa chèn che mất dòng chữ “TRƯỜNG HỌC XANH” (Hình 12.7). Để hình ảnh nằm bên dưới văn bản, em chọn hình rồi chọn:","k":"<b>Send Backward</b> đưa hình xuống dưới (không che văn bản); <b>Bring Forward</b> đưa hình lên lại lớp trên.","o":["Format/Arrange/Bring Forward","Format/Arrange/Send Backward","Format/Picture Border","Design/Themes"],"a":1},{"id":"nv4","type":"mcq","q":"Muốn thay đổi kích thước hình ảnh mà vẫn giữ nguyên tỉ lệ, em kéo thả:","k":"Kéo <b>nút ở góc theo đường chéo</b> để giữ nguyên tỉ lệ. Nút cạnh trên/dưới đổi chiều dọc; nút cạnh trái/phải đổi chiều ngang; kéo thả hình để đổi vị trí.","o":["Nút ở giữa cạnh trên hoặc cạnh dưới.","Nút ở giữa cạnh trái hoặc cạnh phải.","Nút ở góc hình theo đường chéo.","Kéo thả ở giữa hình."],"a":2},{"id":"nvkq","type":"open","q":"Báo cáo kết quả: em đã sao chép nội dung gì sang trang chiếu, biên tập lại ra sao? Em đã chọn mẫu định dạng, hình ảnh, màu nền như thế nào?","k":"Ví dụ: sao chép phần “1. Ý TƯỞNG” từ tệp văn bản, biên tập thành 3–4 ý ngắn có kí hiệu đầu dòng; chọn mẫu Lá xanh; trang tiêu đề chèn ảnh đồng cỏ, đưa xuống dưới văn bản, thêm viền trắng, nền trang màu xanh lá (Hình 12.10).","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Em hãy bổ sung thêm một hình ảnh vào trang trình bày ý tưởng (Hình 12.5) rồi định dạng hình ảnh đó sao cho hợp lí. Em đã chọn hình gì, đặt ở đâu?","k":"Ví dụ: chèn hình cây xanh, thu nhỏ, đặt ở góc phải dưới, không che chữ; thêm viền mảnh cùng màu với mẫu định dạng.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"open","q":"Em hãy bổ sung kết quả tính toán của dự án Trường học xanh đã làm trong phần mềm bảng tính vào bài trình chiếu (có thể ở trang Dự kiến kết quả). Em đưa vào những số liệu nào?","k":"Ví dụ: tổng số cây dự kiến 623 cây; trung bình mỗi lớp 89 cây; tổng chi phí 30.692.200 đồng. Sao chép từ bảng tính (Ctrl+C) rồi dán vào trang chiếu (Ctrl+V).","label":"Luyện tập – câu 2"},{"id":"lt3","type":"open","q":"Em hãy định dạng văn bản, biên tập nội dung cho các trang chiếu của tệp Truonghocxanh.pptx và chọn mẫu định dạng phù hợp. Em đã chọn mẫu nào? Vì sao?","k":"Ví dụ: mẫu màu xanh lá phù hợp chủ đề cây xanh; phông chữ đơn giản, tiêu đề cỡ 40–44 đậm, nội dung cỡ 24; mỗi trang tối đa 5–7 dòng.","label":"Luyện tập – câu 3"},{"id":"vd1","type":"open","q":"Mở tệp Baitaptinhoc7.pptx đã tạo ở Bài 11, bổ sung thông tin vào các trang chiếu (sao chép từ tệp văn bản hoặc nhập mới từ bàn phím). Tạo cấu trúc phân cấp, chèn hình ảnh, chọn mẫu định dạng và định dạng văn bản, hình ảnh. Mô tả ngắn bài của em.","k":"Học sinh tự làm. Bài tốt có: nội dung ngắn gọn, phân cấp; mẫu định dạng thống nhất; hình ảnh phù hợp, không che chữ, kích thước và vị trí hợp lí; màu chữ tương phản với nền.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Hình ảnh thường được dùng để minh hoạ cho nội dung bài trình chiếu, nhờ đó bài trình chiếu trở nên <b>trực quan, ấn tượng và hấp dẫn</b> hơn.</li><li>Nên lựa chọn hình ảnh <b>phù hợp với nội dung</b> bài trình chiếu và có <b>tính thẩm mĩ</b>.</li><li>Kích thước hình ảnh và vị trí đặt trên trang chiếu cần hợp lí.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Định dạng văn bản trong phần mềm trình chiếu <b>tương tự</b> trong phần mềm soạn thảo.</li><li>Nên chọn phông chữ, cỡ chữ, kiểu chữ, màu chữ, nền,… <b>thống nhất và phù hợp</b>, để làm nổi bật thông điệp chính của trang.</li><li>Nội dung trình bày nên <b>cô đọng</b>. Mỗi trang chiếu chỉ nên tập trung vào <b>một ý chính</b>.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Sao chép: <b>Copy (Ctrl+C)</b> ở tệp văn bản → <b>Paste (Ctrl+V)</b> ở trang chiếu.</li><li>Mẫu định dạng: <b>Design → Themes</b> (giữ Ctrl để chọn nhiều trang).</li><li>Hình ảnh: <b>Insert/Pictures</b>; lớp: <b>Send Backward / Bring Forward</b>; viền: <b>Picture Border</b>; kéo nút góc để giữ tỉ lệ.</li></ul>"}]},"tin7-hoan-thien-bai-trinh-chieu":{"id":"tin7-bai13","ten":"Bài 13. Thực hành tổng hợp: Hoàn thiện bài trình chiếu","cau":[{"id":"kd1","type":"open","q":"Bài trình chiếu báo cáo dự án Trường học xanh đã có đầy đủ thông tin, các đối tượng đã được định dạng. Theo em, cần làm gì thêm để có một bài thuyết trình hoàn chỉnh, hấp dẫn?","k":"Bổ sung các <b>hiệu ứng động</b> (cho đối tượng và chuyển trang) một cách hợp lí; xem lại bố cục, nội dung, sắp xếp các trang thành một bài trình chiếu hoàn chỉnh.","label":"Mở đầu"},{"id":"hd1a","type":"open","q":"Quan sát hai trang chiếu có cùng nội dung trên bảng mô phỏng (một trang không có hiệu ứng động, một trang có thêm hiệu ứng động). Em thích xem trang nào hơn? Vì sao? Em có muốn sử dụng các hiệu ứng động trong bài trình chiếu của mình không?","k":"Thường thích trang <b>có hiệu ứng động</b>: các đối tượng xuất hiện lần lượt giúp người xem <b>tập trung</b> vào từng ý, bài trình chiếu <b>sinh động, hấp dẫn</b> hơn.","label":"HĐ1 – Câu 1, 2"},{"id":"hd1c","type":"open","q":"Sử dụng hiệu ứng động cần lưu ý những điều gì? Tại sao?","k":"Chỉ dùng hiệu ứng <b>có chọn lọc, phù hợp</b>; không dùng quá nhiều, quá phức tạp, vì sẽ làm người xem <b>mất tập trung</b> vào nội dung chính (gây hiệu ứng ngược).","label":"HĐ1 – Câu 3"},{"id":"loai","type":"sort","q":"Đọc mục 1 (SGK trang 68). Mỗi hiệu ứng dưới đây thuộc loại nào?","k":"<b>Hiệu ứng cho đối tượng</b>: cách thức, thời điểm xuất hiện của văn bản, hình ảnh,… trên trang. <b>Hiệu ứng chuyển trang chiếu</b>: cách thức xuất hiện của cả trang chiếu khi chuyển trang.","cats":["Hiệu ứng cho đối tượng","Hiệu ứng chuyển trang chiếu"],"items":[["Dòng chữ “TRƯỜNG HỌC XANH” bay vào từ phía dưới",0],["Hình ảnh cây xanh hiện dần lên",0],["Trang mới đẩy trang cũ sang bên trái",1],["Khi chuyển sang trang 2, trang mở ra từ giữa sang hai bên",1],["Các dòng nội dung lần lượt xuất hiện sau mỗi lần nháy chuột",0]]},{"id":"p69","type":"sort","q":"Ghép mỗi nội dung ở cột A với một nội dung phù hợp ở cột B.","k":"1 – b; 2 – d; 3 – a; 4 – c.","cats":["a) gọi là hiệu ứng chuyển trang chiếu","b) giúp cho việc trình chiếu trở nên sinh động và hấp dẫn hơn","c) khi được thêm các hiệu ứng động","d) là cách thức và thời điểm xuất hiện của các trang chiếu và các đối tượng trên trang chiếu"],"items":[["1) Sử dụng hiệu ứng động trong bài trình chiếu",1],["2) Hiệu ứng động trong bài trình chiếu",3],["3) Hiệu ứng cho các trang chiếu",0],["4) Nội dung trên trang chiếu sẽ thu hút sự chú ý của người xem và tạo hiệu quả tốt hơn trong việc truyền đạt thông tin",2]]},{"id":"nv1","type":"order","q":"Sắp xếp các bước tạo hiệu ứng cho đối tượng theo Hình 13.1 (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → e → c</b>: chọn đối tượng → Animations → chọn hiệu ứng → Start, Duration, Reorder → Preview.","items":{"a":"Chọn hiệu ứng.","b":"Chọn đối tượng.","c":"Xem trước (Preview).","d":"Chọn thẻ Animations.","e":"Chọn cách đối tượng xuất hiện, thời lượng; thay đổi thứ tự xuất hiện nếu cần."},"ans":["b","d","a","e","c"],"start":["a","b","c","d","e"]},{"id":"nv2","type":"order","q":"Sắp xếp các bước tạo hiệu ứng chuyển trang chiếu theo Hình 13.2 (dùng nút ↑ ↓).","k":"Thứ tự: <b>c → a → d → e → b</b>. Nên dùng <b>Apply To All</b> để hiệu ứng chuyển trang thống nhất cho tất cả các trang.","items":{"a":"Chọn thẻ Transitions.","b":"Xem trước (Preview).","c":"Chọn trang chiếu.","d":"Chọn hiệu ứng.","e":"Chọn âm thanh, thời lượng thực hiện hiệu ứng."},"ans":["c","a","d","e","b"],"start":["a","b","c","d","e"]},{"id":"hopli","type":"sort","q":"Đọc mục c) Sử dụng hiệu ứng hợp lí. Mỗi việc dưới đây nên hay không nên làm?","k":"Trình bày càng <b>đơn giản, rõ ràng</b> càng thuyết phục; chuyển trang <b>thống nhất</b>; <b>chọn lọc</b> hiệu ứng (tự hỏi: hiệu ứng này có khiến bài thuyết trình hiệu quả hơn không?); chỉ dùng âm thanh khi thật cần thiết.","cats":["Nên","Không nên"],"items":[["Dùng một kiểu chuyển trang thống nhất cho tất cả các trang",0],["Mỗi dòng chữ dùng một hiệu ứng khác nhau cho “vui mắt”",1],["Thêm âm thanh cho mọi hiệu ứng",1],["Chọn hiệu ứng giúp làm nổi bật ý chính của trang",0],["Trình bày đơn giản, rõ ràng",0],["Cho tiêu đề bay, xoay, phóng to liên tục",1]]},{"id":"nvkq","type":"open","q":"Báo cáo kết quả: em đã tạo những hiệu ứng nào cho các đối tượng, hiệu ứng chuyển trang nào? Em đã bổ sung, sắp xếp lại những gì để hoàn thiện bài trình chiếu?","k":"Ví dụ: trang tiêu đề: tiêu đề Fly In (On Click), phụ đề Fade (After Previous); trang nội dung: khung nội dung Wipe; chuyển trang Fade cho tất cả các trang; bổ sung trang Dự kiến kết quả, Kết luận; sắp xếp các trang theo thứ tự Ý tưởng → Kế hoạch → Kết quả → Kết luận.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Em hãy tạo hiệu ứng cho các trang và đối tượng để hoàn thiện bài trình chiếu báo cáo dự án của nhóm em. Nhóm đã chọn hiệu ứng nào? Vì sao?","k":"Học sinh tự làm. Lí do tốt: hiệu ứng giúp các ý xuất hiện lần lượt theo lời thuyết trình, làm nổi bật số liệu quan trọng; chuyển trang nhẹ nhàng, thống nhất.","label":"Luyện tập"},{"id":"vd1","type":"open","q":"Em hãy bổ sung hiệu ứng động cho bài trình chiếu ghi trong tệp Baitaptinhoc7.pptx. Xem lại nội dung, định dạng, hiệu ứng của từng trang để hoàn thiện bài trình chiếu. Mô tả ngắn bài của em.","k":"Học sinh tự làm. Bài hoàn chỉnh: trang tiêu đề, các trang nội dung có tiêu đề, phân cấp, hình ảnh hợp lí, mẫu định dạng thống nhất, hiệu ứng chọn lọc, chuyển trang thống nhất.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Hiệu ứng động</b> là cách thức và thời điểm xuất hiện của các trang chiếu và các đối tượng trên trang khi trình chiếu.</li><li>Sử dụng hiệu ứng động giúp cho bài trình chiếu trở nên <b>sinh động và hấp dẫn</b> hơn, thu hút sự chú ý của người xem và tạo hiệu quả tốt trong việc truyền đạt thông tin.</li><li>Hiệu ứng động nên được sử dụng một cách <b>có chọn lọc</b> để giúp tăng tính hiệu quả cho nội dung và tạo ấn tượng với người xem.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Hiệu ứng cho đối tượng: chọn đối tượng → <b>Animations</b> → chọn hiệu ứng → Start, Duration, thứ tự → <b>Preview</b>.</li><li>Hiệu ứng chuyển trang: chọn trang → <b>Transitions</b> → chọn hiệu ứng → âm thanh, thời lượng → Preview.</li><li>Đơn giản, rõ ràng; chuyển trang thống nhất; chọn lọc hiệu ứng; chỉ dùng âm thanh khi cần.</li></ul>"}]},"tin7-hoan-thien-bang-tinh":{"id":"tin7-bai10","ten":"Bài 10. Hoàn thiện bảng tính","cau":[{"id":"kd1","type":"open","q":"Công việc thu thập dữ liệu, tính toán dữ liệu cho dự án Trường học xanh đã hoàn thành. Theo em, để trình bày bảng tính trước lớp (trình chiếu hoặc in ra giấy) cần làm thêm những gì?","k":"Định dạng dữ liệu cho dễ đọc, gộp ô, tô màu, <b>kẻ đường viền, khung</b> cho bảng, sắp xếp, đặt tên các <b>trang tính</b>, xem trước rồi <b>in</b> hoặc sao chép sang phần mềm trình chiếu.","label":"Mở đầu"},{"id":"hd1","type":"open","q":"Bạn An in dữ liệu trong Bảng 2 (Hình 10.1a) ra giấy nhưng kết quả nhận được là bảng dữ liệu không có các đường kẻ (Hình 10.1b) giống như bạn nhìn thấy trên màn hình máy tính. Em có biết lí do tại sao không? (Thử bấm Xem trước khi in trên bảng mô phỏng.)","k":"Các đường lưới trên màn hình chỉ giúp nhìn rõ các ô; <b>mặc định khi in thì đường lưới không được in ra</b>. Muốn có đường kẻ trên giấy, phải <b>kẻ đường viền ô và khung</b> cho vùng dữ liệu (Format Cells → Border).","label":"HĐ1 – Vì sao không thấy đường kẻ?"},{"id":"trang","type":"sort","q":"Đọc mục 1a (SGK trang 51–52). Mỗi việc dưới đây làm bằng thao tác nào?","k":"Tạo mới: <b>⊕</b>; xoá: <b>Delete</b>; chèn trước: <b>Insert/Worksheet</b>; đổi tên: <b>nháy đúp</b>; đổi thứ tự: <b>kéo thả</b>; sao chép: <b>Move or Copy</b>, đánh dấu <b>Create a copy</b>, chọn vị trí, OK.","cats":["Nháy nút ⊕","Nháy phải → Delete","Nháy phải → Insert/Worksheet","Nháy đúp tên trang tính","Kéo thả tên trang tính","Nháy phải → Move or Copy"],"items":[["Tạo trang tính mới ở cuối",0],["Xoá trang tính Sheet2",1],["Chèn trang tính mới trước trang tính A",2],["Đổi tên Sheet1 thành Dữ liệu 1",3],["Đưa trang tính 5. Tổng kết lên trước trang tính 4",4],["Tạo một bản sao của trang tính 5. Tổng kết",5]]},{"id":"bd","type":"sort","q":"Trong trang Border của cửa sổ Format Cells, mỗi nút dưới đây có tác dụng gì?","k":"<b>None</b>: không kẻ khung; <b>Outline</b>: kẻ khung bên ngoài; <b>Inside</b>: kẻ đường viền ô bên trong. Có thể chọn kiểu, màu đường kẻ.","cats":["None","Outline","Inside"],"items":[["Không kẻ khung",0],["Kẻ khung bên ngoài vùng dữ liệu",1],["Kẻ đường viền các ô bên trong",2]]},{"id":"vien","type":"mcq","q":"Muốn bảng dữ liệu A3:D6 khi in ra có đủ khung và đường kẻ giữa các ô, em làm thế nào?","k":"<b>B</b>. Nên kẻ khung các vùng dữ liệu trước khi tiến hành in hoặc trình bày dữ liệu.","o":["Không cần làm gì, máy tự in đường lưới.","Chọn vùng A3:D6, mở Format Cells, trang Border, chọn Outline và Inside, nháy OK.","Chọn vùng, tô màu nền.","Chọn vùng, gộp ô."],"a":1},{"id":"hd2","type":"order","q":"Quan sát Hình 10.5. Sắp xếp các bước in dữ liệu trong bảng tính (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → c</b>. Có thể in trang tính hiện thời, toàn bộ bảng tính hoặc chỉ vùng dữ liệu đang chọn.","items":{"a":"Nhập các thông số in (số bản, máy in, vùng in, hướng giấy, khổ giấy).","b":"Đánh dấu vùng dữ liệu muốn in.","c":"Nháy chuột lên nút lệnh Print.","d":"Thực hiện lệnh File/Print."},"ans":["b","d","a","c"],"start":["a","b","c","d"]},{"id":"vungin","type":"mcq","q":"Em chỉ muốn in vùng dữ liệu đang chọn. Trong hộp thoại Print, mục Settings em chọn:","k":"<b>Print Selection</b>: chỉ in vùng đang chọn. Print Active Sheets: in trang tính hiện thời; Print Entire Workbook: in toàn bộ bảng tính.","o":["Print Active Sheets","Print Entire Workbook","Print Selection","Portrait Orientation"],"a":2},{"id":"nv1","type":"order","q":"Sắp xếp các bước thực hành (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → c → a → d</b>.","items":{"a":"Kẻ đường viền, khung vùng A3:N25; căn chỉnh hàng, cột.","b":"Tạo trang tính 6. Hoàn thiện, sao chép nội dung trang tính 5, sửa tên bảng.","c":"Định dạng cột Trung bình, Chi phí; gộp ô cột Loại cây; tô màu nền.","d":"Lưu tệp."},"ans":["b","c","a","d"],"start":["a","b","c","d"]},{"id":"nv2","type":"mcq","q":"Cột Chi phí cần hiển thị như 1,400,000. Trong Format Cells em chọn:","k":"<b>A</b>. Số chữ số thập phân bằng 0 và hiển thị phân tách hàng nghìn, hàng triệu. Cột Trung bình: Number, 2 chữ số thập phân.","o":["Number, Decimal places = 0, chọn Use 1000 Separator.","Number, Decimal places = 2, không chọn Use 1000 Separator.","Percentage, Decimal places = 0.","Date."],"a":0},{"id":"nvkq","type":"open","q":"Báo cáo kết quả: trang tính 6. Hoàn thiện của em đã được trình bày như thế nào (định dạng số, gộp ô, màu nền, đường viền)? Khi xem trước khi in, bảng có những đường kẻ nào?","k":"Trung bình 2 chữ số thập phân (14.00, 11.67,…); Chi phí dạng 1,400,000; cột Loại cây gộp ô, căn giữa theo cả hai chiều; mỗi nhóm cây một màu nền; vùng A3:N25 có khung và đường viền mọi ô nên khi in có đủ đường kẻ.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Quan sát lệnh in một trang tính và so sánh với lệnh in văn bản mà em đã học ở lớp 6, có điểm gì khác nhau giữa hai lệnh in này?","k":"Giống: cùng dùng <b>File/Print</b>, chọn máy in, số bản, trang in, hướng giấy, khổ giấy. Khác: bảng tính có thể chọn <b>vùng in</b> (vùng đang chọn, trang tính hiện thời, toàn bộ bảng tính); <b>đường lưới không được in</b> nên cần kẻ viền; có thể chỉnh để bảng vừa một trang (Scaling).","label":"Luyện tập – câu 1"},{"id":"lt2","type":"open","q":"Hãy thực hiện lệnh in bảng dữ liệu rút gọn bằng cách ẩn đi tất cả các cột ứng với các lớp cụ thể từ 7A đến 7H (làm trên bảng mô phỏng ở phần Thực hành). Bảng in ra còn những cột nào?","k":"Chọn các cột E đến K (7A–7H), nháy phải chuột → <b>Hide</b>, rồi File/Print. Bảng in còn: STT, Loại cây, Tên cây, Đơn giá, Tổng số cây, Trung bình, Chi phí. Cột ẩn không được in.","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Em hãy giúp cô giáo tạo trang tính Điểm thi khảo sát có các cột Họ và tên, Toán, Ngữ văn, Tiếng Anh và Điểm trung bình. Dùng các hàm hay công thức để tính toán rồi trình bày trang tính. Em đã dùng công thức gì và trình bày thế nào?","k":"Ví dụ: F3 <b>=AVERAGE(C3:E3)</b> rồi sao chép xuống; định dạng Điểm TB 1 chữ số thập phân; hàng tiêu đề chữ đậm, tô nền; kẻ khung, đường viền cho bảng; có thể thêm điểm cao nhất =MAX(F3:F7), thấp nhất =MIN(F3:F7).","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Người sử dụng có thể thực hiện các thao tác đa dạng trên trang tính của bảng tính: <b>đổi tên, tạo mới, chèn, sao chép, di chuyển hoặc xoá</b> một trang tính.</li><li>Nên <b>kẻ khung</b> các vùng dữ liệu trước khi tiến hành in hoặc trình bày dữ liệu.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>In: đánh dấu vùng → <b>File/Print</b> → nhập thông số (số bản, máy in, vùng in, trang, hướng giấy, khổ giấy) → <b>Print</b>.</li><li>Có thể in trang tính hiện thời, toàn bộ bảng tính hoặc chỉ vùng đang chọn (<b>Print Selection</b>).</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Trung bình: Number, 2 chữ số thập phân. Chi phí: Number, 0 chữ số thập phân, <b>Use 1000 Separator</b>.</li><li>Gộp ô Loại cây, căn giữa hai chiều; tô màu theo loại cây; kẻ viền vùng <b>A3:N25</b>.</li></ul>"}]},"tin7-mang-xa-hoi":{"id":"tin7-bai4","ten":"Bài 4. Mạng xã hội và một số kênh trao đổi thông tin thông dụng trên Internet","cau":[{"id":"kd1","type":"sort","q":"Con người đã nghĩ ra nhiều cách trao đổi thông tin với nhau. Mỗi cách dưới đây là cách truyền thống hay là kênh trao đổi trên Internet?","k":"Cách truyền thống: chim bồ câu đưa thư, thư bưu điện, điện báo, điện thoại,… Internet tạo ra nhiều kênh <b>hữu ích, nhanh chóng</b>: thư điện tử, diễn đàn, <b>mạng xã hội</b>,…","cats":["Cách truyền thống","Kênh trên Internet"],"items":[["Dùng chim bồ câu đưa thư",0],["Gửi thư qua bưu điện",0],["Điện báo",0],["Thư điện tử (email)",1],["Mạng xã hội",1],["Diễn đàn (Forum)",1]]},{"id":"hd1a","type":"open","q":"Ở lớp 6 em đã biết sử dụng Internet để nhận và gửi thông tin. Đó là cách nào?","k":"Ví dụ: gửi, nhận <b>thư điện tử</b>; tìm kiếm, xem thông tin trên các <b>trang web</b>.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Em có biết cách trao đổi thông tin nào trên Internet đang được sử dụng nhiều nhất không? Tại sao?","k":"Thường là <b>mạng xã hội</b> (Facebook, Zalo, YouTube,…) vì dễ dùng, miễn phí, trao đổi ngay lập tức, gửi được nhiều dạng thông tin (văn bản, hình ảnh, âm thanh, video) và kết nối được rất nhiều người.","label":"HĐ1 – Câu 2"},{"id":"kenh","type":"sort","q":"Đọc mục a) (SGK trang 18). Mỗi thứ dưới đây có phải là kênh trao đổi thông tin trên Internet không?","k":"Một số kênh trao đổi thông tin phổ biến trên Internet: <b>thư điện tử, diễn đàn, mạng xã hội</b>,… Thông tin trên đó tồn tại ở nhiều dạng: văn bản, hình ảnh, âm thanh, video, phần mềm,…","cats":["Là kênh trao đổi trên Internet","Không phải"],"items":[["Thư điện tử",0],["Diễn đàn (Forum)",0],["Mạng xã hội",0],["Phần mềm soạn thảo văn bản",1],["Máy in",1]]},{"id":"mucdich","type":"sort","q":"Đọc mục b) và Bảng 4.1 (SGK trang 19). Mỗi mạng xã hội dưới đây chủ yếu dùng cho mục đích nào?","k":"Facebook, Zalo: <b>giao lưu với bạn bè</b>. YouTube: <b>chia sẻ video</b>. Instagram: <b>chia sẻ ảnh</b>. Scratch: <b>diễn đàn học tập</b>, thảo luận. Mỗi mạng xã hội thường có một mục đích nhất định.","cats":["Giao lưu với bạn bè","Chia sẻ video","Chia sẻ ảnh","Diễn đàn học tập, thảo luận"],"items":[["Facebook",0],["Zalo",0],["YouTube",1],["Instagram",2],["Cộng đồng Scratch",3]]},{"id":"haimat","type":"sort","q":"Đọc đoạn cuối trang 19. Mỗi việc dưới đây là sử dụng mạng xã hội hữu ích hay sai trái?","k":"Mạng xã hội có <b>hai mặt</b>: giúp kết nối, học hỏi; nhưng dùng sai mục đích (tin giả, đe doạ, bắt nạt, gian lận thi cử) gây hậu quả cho người khác và chính mình, có thể bị kỉ luật, xử lí theo pháp luật.","cats":["Hữu ích","Sai trái"],"items":[["Kết nối, hỏi thăm bạn bè",0],["Học thêm kĩ năng hay từ video",0],["Đăng thông tin chưa được kiểm chứng gây hoang mang",1],["Chụp ảnh đề thi đăng lên nhờ làm hộ",1],["Bình luận đe doạ, bắt nạt bạn",1],["Thảo luận bài tập với nhóm học tập",0]]},{"id":"p20a","type":"mcq","q":"Không nên dùng mạng xã hội cho mục đích nào sau đây?","k":"<b>C</b>. Bình luận xấu về người khác là sử dụng mạng xã hội sai trái, có thể làm tổn thương người khác.","o":["Giao lưu với bạn bè.","Học hỏi kiến thức.","Bình luận xấu về người khác.","Chia sẻ các hình ảnh phù hợp của mình."],"a":2},{"id":"p20b","type":"mcq","q":"“Đưa thông tin sai sự thật lên mạng, sử dụng thông tin vào mục đích sai trái là hành vi bị nghiêm cấm và có thể bị phạt theo quy định của pháp luật”. Theo em điều đó là:","k":"<b>A. Đúng.</b> Cần tuân thủ đúng các quy định khi sử dụng mạng xã hội và các kênh trao đổi thông tin trên Internet.","o":["Đúng.","Sai."],"a":0},{"id":"nv1","type":"order","q":"Sắp xếp các bước tạo tài khoản mạng xã hội (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → e → a → d → c</b>. Lưu ý: Facebook yêu cầu phải đủ <b>13 tuổi</b> mới được tạo tài khoản.","items":{"a":"Nháy chuột vào ô Tạo tài khoản mới.","b":"Truy cập trang web của mạng xã hội.","c":"Nháy chuột vào nút Đăng ký.","d":"Nhập đầy đủ thông tin vào các ô theo hướng dẫn.","e":"Chọn ngôn ngữ Tiếng Việt."},"ans":["b","e","a","d","c"],"start":["a","b","c","d","e"]},{"id":"nv2","type":"mcq","q":"Để chia sẻ một nội dung lên trang cá nhân, em làm thế nào?","k":"<b>B</b>. Nháy vào <b>hộp trạng thái</b> để nhập nội dung; nháy <b>Ảnh/Video</b> để thêm ảnh, video; nháy <b>Đăng</b> để hoàn thành.","o":["Nhập vào ô Tìm kiếm rồi nhấn Enter.","Nháy chuột vào hộp trạng thái, nhập nội dung (có thể thêm Ảnh/Video), rồi nháy nút Đăng.","Nháy chuột vào nút Thêm bạn bè.","Nháy vào ảnh đại diện của bạn."],"a":1},{"id":"nv3","type":"order","q":"Sắp xếp các bước kết nối với một bạn cùng lớp (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → c → a</b>. Khi lời mời được chấp nhận, hai tài khoản trở thành “bạn bè”, tự động theo dõi nhau.","items":{"a":"Nháy chuột vào nút Thêm bạn bè.","b":"Nhập tên của bạn vào ô tìm kiếm.","c":"Nháy chuột vào ảnh đại diện để mở trang của bạn."},"ans":["b","c","a"],"start":["a","b","c"]},{"id":"nvkq","type":"open","q":"Báo cáo kết quả thực hành (trên mạng xã hội thật nếu đủ tuổi, hoặc trên bảng mô phỏng): em đã chia sẻ nội dung gì? Em đã kết bạn với ai? Khi đăng bài em đã lưu ý những gì?","k":"Học sinh tự báo cáo. Lưu ý: chỉ chia sẻ nội dung <b>phù hợp, đúng sự thật</b>; không đăng thông tin cá nhân (số điện thoại, địa chỉ); chỉ kết bạn với người <b>mình quen biết</b>.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Em hãy nêu tên ba kênh trao đổi thông tin trên Internet.","k":"<b>Thư điện tử</b>, <b>diễn đàn</b>, <b>mạng xã hội</b>.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"sort","q":"Các phát biểu về mạng xã hội sau đây đúng hay sai?","k":"<b>a, c đúng</b>. <b>b sai</b>: chỉ một số website là mạng xã hội. <b>d sai</b>: nhiều mạng xã hội quy định độ tuổi tối thiểu, phổ biến là <b>13 tuổi</b>.","cats":["Đúng","Sai"],"items":[["a) Mạng xã hội giúp mọi người tương tác với nhau mà không cần gặp mặt.",0],["b) Tất cả các website đều là mạng xã hội.",1],["c) Người xấu có thể đưa tin giả lên mạng xã hội. Vì vậy, chỉ nên trò chuyện với người mình quen biết.",0],["d) Bất cứ tuổi nào cũng có thể tham gia mạng xã hội.",1]]},{"id":"vd1","type":"open","q":"Em hãy tìm hiểu kĩ một mạng xã hội (ví dụ: Zalo, Lotus) mà em quan tâm và giới thiệu với các bạn hay người thân. Phần giới thiệu nên có: chức năng chính, đối tượng phù hợp để tham gia, cách thức tham gia, những lưu ý cần thiết khi tham gia,…","k":"Học sinh tự làm. Ví dụ Zalo: nhắn tin, gọi điện, chia sẻ ảnh, lập nhóm lớp; dành cho người đủ tuổi theo quy định; tham gia bằng số điện thoại; lưu ý giữ bí mật mật khẩu, không chia sẻ thông tin cá nhân, không kết bạn với người lạ.","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Em hãy tìm hiểu thêm những ví dụ cụ thể về hậu quả của việc sử dụng thông tin vào mục đích sai trái. Hãy chia sẻ với người thân và bạn bè để cùng phòng tránh.","k":"Ví dụ: đăng tin giả về dịch bệnh bị xử phạt hành chính; bình luận bắt nạt khiến bạn bị tổn thương; chụp đề thi đăng lên mạng bị đình chỉ thi. Bài học: <b>kiểm chứng</b> trước khi chia sẻ, <b>tôn trọng</b> người khác, tuân thủ pháp luật.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Thư điện tử, diễn đàn, mạng xã hội,… là những <b>kênh trao đổi thông tin</b> thông dụng trên Internet.</li><li>Tham gia mạng xã hội là tham gia một <b>cộng đồng trực tuyến</b>, nơi mọi người tương tác với nhau theo nhiều cách.</li><li>Mạng xã hội thường được tổ chức dưới dạng các <b>website</b>. Mỗi mạng xã hội thường có mục đích nhất định như: thảo luận, chia sẻ ảnh, video,…</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Mạng xã hội giúp người sử dụng <b>kết nối, giao lưu, chia sẻ</b> và thảo luận các vấn đề mà họ quan tâm.</li><li>Cần <b>tuân thủ đúng các quy định</b> khi sử dụng mạng xã hội và các kênh trao đổi thông tin trên Internet.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Tạo tài khoản: truy cập trang → <b>Tạo tài khoản mới</b> → nhập thông tin → <b>Đăng ký</b> (đủ 13 tuổi).</li><li>Chia sẻ: hộp trạng thái → nhập nội dung, <b>Ảnh/Video</b> → <b>Đăng</b>.</li><li>Kết bạn: tìm tên → mở trang của bạn → <b>Thêm bạn bè</b>.</li></ul>"}]},"tin7-phan-mem-bang-tinh":{"id":"tin7-bai6","ten":"Bài 6. Làm quen với phần mềm bảng tính","cau":[{"id":"kd1","type":"open","q":"Để thực hiện dự án Trường học xanh, cần thu thập và tính toán rất nhiều dữ liệu (vị trí trồng cây, loại cây, công việc,…). Nên sử dụng phần mềm nào trên máy tính để thực hiện những công việc đó? Vì sao?","k":"Nên dùng <b>phần mềm bảng tính</b> (Microsoft Excel, Google Sheets, LibreOffice Calc,…): trình bày dữ liệu dạng <b>bảng</b> gọn, dễ so sánh; <b>tính toán</b> tự động; vẽ <b>biểu đồ</b> minh hoạ.","label":"Mở đầu – Dự án Trường học xanh"},{"id":"hd1","type":"open","q":"Quan sát giao diện làm việc của một phần mềm bảng tính mà em biết. Nêu tên các vùng chính và chức năng của chúng.","k":"Thẻ và nhóm lệnh; <b>hộp địa chỉ</b> (hiện địa chỉ ô hiện thời); <b>vùng nhập dữ liệu</b>; <b>khu vực chính</b> gồm các trang tính (hàng, cột, ô) để lưu trữ và hiển thị dữ liệu; tên các trang tính (Sheet1, Sheet2) ở phía dưới.","label":"HĐ1 – Giao diện bảng tính"},{"id":"vung","type":"sort","q":"Đọc mục 1 (SGK trang 28–29) và quan sát Hình 6.1. Mỗi mô tả dưới đây là thành phần nào?","k":"<b>Vùng nhập dữ liệu</b>: nhập dữ liệu. <b>Hộp địa chỉ</b>: hiện địa chỉ ô hiện thời. <b>Ô hiện thời</b>: ô đang làm việc, được đóng khung. <b>Trang tính</b>: lưới ô gồm hàng (1, 2, 3,…) và cột (A, B, C,…).","cats":["Hộp địa chỉ","Vùng nhập dữ liệu","Ô hiện thời","Trang tính"],"items":[["Nơi thực hiện trực tiếp việc nhập dữ liệu vào bảng tính.",1],["Hiển thị địa chỉ của ô hiện thời, nằm bên trái vùng nhập dữ liệu.",0],["Ô đang được quan sát, nhập dữ liệu, luôn được đóng khung.",2],["Lưới ô gồm các hàng và cột; tên nằm ở phía dưới cửa sổ (Sheet1, Sheet2).",3]]},{"id":"p29a","type":"mcq","q":"Vị trí giao của một hàng và một cột được gọi là gì?","k":"<b>A. Ô</b> (gọi tắt của ô tính).","o":["Ô.","Trang tính.","Hộp địa chỉ.","Bảng tính."],"a":0},{"id":"p29b","type":"mcq","q":"Phát biểu nào dưới đây đúng?","k":"<b>B</b>. Hàng đặt tên bằng <b>số</b> 1, 2, 3,… (từ trên xuống); cột đặt tên bằng <b>chữ cái</b> A, B, C,… (từ trái sang phải).","o":["Các hàng của trang tính được đặt tên theo các chữ cái: A, B, C,…","Các hàng của trang tính được đặt tên theo các số: 1, 2, 3,…","Các cột của trang tính được đặt tên theo các số: 1, 2, 3,…","Các hàng và cột trong trang tính không có tên."],"a":1},{"id":"hd2","type":"mcq","q":"Trong Hình 6.2, ô ghi tên học sinh “Bùi Lê Đình Anh” có địa chỉ là gì?","k":"<b>B6</b>: tên cột (B) ghép với tên hàng (6). &lt;địa chỉ ô&gt; = &lt;tên cột&gt;&lt;tên hàng&gt;.","o":["6B","B6","B:6","Hàng 6"],"a":1},{"id":"diachi","type":"mcq","q":"Vùng dữ liệu có ô góc trên bên trái là C5 và ô góc dưới bên phải là E10 có địa chỉ là:","k":"<b>C5:E10</b>. &lt;địa chỉ vùng&gt; = &lt;ô góc trên bên trái&gt; <b>:</b> &lt;ô góc dưới bên phải&gt;.","o":["C5-E10","C5:E10","E10:C5","C5;E10"],"a":1},{"id":"p30a","type":"mcq","q":"Một ô có thể coi là một vùng được không?","k":"<b>Có</b>. Một ô là vùng đặc biệt chỉ gồm 1 ô.","o":["Có, vì ô là vùng có góc trên bên trái và góc dưới bên phải trùng nhau (ví dụ B6:B6).","Không, vùng phải có ít nhất hai ô."],"a":0},{"id":"p30b","type":"mcq","q":"Vùng A5:B10 có bao nhiêu ô?","k":"<b>12 ô</b>: 2 cột (A, B) × 6 hàng (5, 6, 7, 8, 9, 10). Thử chọn vùng A5:B10 trên bảng mô phỏng để đếm.","o":["2 ô","6 ô","10 ô","12 ô"],"a":3},{"id":"p30c","type":"mcq","q":"Có thể chọn một vùng hình tam giác được không?","k":"<b>Không</b>. Vùng là nhiều ô liền kề tạo thành <b>hình chữ nhật</b>.","o":["Có.","Không, vùng luôn là hình chữ nhật."],"a":1},{"id":"hd3a","type":"open","q":"Có thể nhập dữ liệu vào trang tính theo bao nhiêu cách? Hãy nêu cách đó.","k":"<b>Hai cách</b>: nháy chuột vào ô rồi gõ trực tiếp từ bàn phím; hoặc nháy chuột vào ô, nháy vào <b>vùng nhập dữ liệu</b> rồi gõ. Nhập xong nhấn <b>Enter</b>.","label":"HĐ3 – Câu 1"},{"id":"canle","type":"sort","q":"Quan sát Hình 6.5 (hoặc thử trên bảng mô phỏng). Khi nhập vào ô, dữ liệu nào tự động căn trái, dữ liệu nào tự động căn phải?","k":"Dữ liệu <b>văn bản</b> tự động <b>căn trái</b>. Dữ liệu <b>số, ngày tháng</b> tự động <b>căn phải</b>. Phần mềm tự nhận biết, phân loại kiểu dữ liệu.","cats":["Căn trái","Căn phải"],"items":[["Nguyễn Việt Hương",0],["9/23/2010",1],["8.5",1],["Hoàn Kiếm",0],["7",1],["Ngày sinh",0]]},{"id":"font","type":"sort","q":"Quan sát Hình 6.6. Mỗi lệnh định dạng dưới đây nằm trong nhóm lệnh nào của thẻ Home?","k":"Nhóm <b>Font</b>: phông, cỡ, kiểu chữ, màu nền ô, màu chữ. Nhóm <b>Alignment</b>: căn dữ liệu theo chiều ngang và chiều dọc.","cats":["Nhóm Font","Nhóm Alignment"],"items":[["Phông chữ, cỡ chữ",0],["Chữ đậm, nghiêng, gạch chân",0],["Màu nền ô, màu chữ",0],["Căn trái, giữa, phải",1],["Căn trên, giữa, dưới",1]]},{"id":"p32","type":"mcq","q":"Nếu em chọn một vùng rồi nhập dữ liệu thì dữ liệu sẽ được nhập vào ô nào?","k":"<b>Ô hiện thời</b>: khi chọn vùng, ô chọn đầu tiên là ô hiện thời, dữ liệu được nhập vào ô đó.","o":["Tất cả các ô trong vùng.","Ô hiện thời (ô chọn đầu tiên, thường là ô góc trên bên trái).","Ô góc dưới bên phải.","Không nhập được."],"a":1},{"id":"nv1","type":"order","q":"Sắp xếp các bước thực hành nhập thông tin khảo sát dự án Trường học xanh (dùng nút ↑ ↓).","k":"Thứ tự: <b>c → a → e → d → b</b>.","items":{"a":"Nhập dữ liệu: A1, A2, các cột STT, Địa điểm, Loại cây.","b":"Lưu bảng tính với tên THXanh.xlsx (File/Save hoặc Ctrl+S).","c":"Mở Excel, chọn Blank workbook.","d":"Nháy đúp tên trang tính Sheet1, đổi thành 1. Khảo sát.","e":"Chỉnh độ rộng cột, định dạng tiêu đề, căn giữa cột STT, tô nền hàng 3."},"ans":["c","a","e","d","b"],"start":["a","b","c","d","e"]},{"id":"nv2","type":"mcq","q":"Muốn thay đổi độ rộng cột B để nhìn thấy toàn bộ dữ liệu, em làm thế nào?","k":"Kéo thả <b>vạch giữa các tên cột</b> (tại hàng ghi tên cột). Đổi chiều cao hàng: kéo vạch giữa các tên hàng.","o":["Nháy đúp vào ô B1.","Đưa con trỏ chuột vào vạch giữa tên cột B và C, khi xuất hiện biểu tượng ↔ thì kéo thả chuột.","Chọn lệnh File/Save.","Nhấn phím Delete."],"a":1},{"id":"nvkq","type":"open","q":"Báo cáo kết quả thực hành: em đã nhập và định dạng bảng khảo sát như thế nào (tiêu đề, cột STT, hàng 3, tên trang tính)? Em gặp khó khăn gì?","k":"Tiêu đề A1: chữ <b>đậm</b>, màu <b>xanh lá</b>, cỡ chữ lớn. Hàng 3: nền <b>vàng</b>, căn giữa. Cột STT: <b>căn giữa</b>. Trang tính đổi tên <b>1. Khảo sát</b>. Lưu tệp <b>THXanh.xlsx</b>.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Muốn xoá nhanh dữ liệu trong một vùng thì em làm thế nào?","k":"<b>Chọn vùng</b> đó rồi nhấn phím <b>Delete</b>.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"open","q":"Có bao nhiêu cách nhập dữ liệu vào trang tính? Em hãy mô tả các cách đó.","k":"<b>Hai cách</b>: (1) nháy vào ô, gõ trực tiếp; (2) nháy vào ô, nháy vào vùng nhập dữ liệu rồi gõ. Nhập xong nhấn Enter.","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Vì sao khi nhập 12/15/2020 thì phần mềm tự động căn phải, nhưng nếu nhập 15/12/2020 thì phần mềm tự động căn trái? (Thử trên bảng mô phỏng.)","k":"Phần mềm đang dùng định dạng ngày kiểu Mĩ <b>tháng/ngày/năm</b>. 12/15/2020 là ngày hợp lệ (tháng 12, ngày 15) → kiểu <b>ngày tháng</b> → căn phải. 15/12/2020 có “tháng 15” không hợp lệ → phần mềm coi là <b>văn bản</b> → căn trái.","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Tìm một số loại cây có thể mua và trồng cho dự án Trường học xanh. Tạo bảng tính và đặt tên là Danh sách các loại cây, gồm ba cột STT, Loại cây (Cây hoa, Cây ăn quả, Cây bóng mát) và Tên cây. Nhập dữ liệu, chỉnh sửa và định dạng. Mô tả bảng của em.","k":"Ví dụ: 1 – Cây hoa – Hoa giấy; 2 – Cây bóng mát – Bàng; 3 – Cây ăn quả – Ổi;… Tiêu đề đậm, hàng tiêu đề cột tô nền, cột STT căn giữa, độ rộng cột vừa dữ liệu.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Phần mềm bảng tính giúp <b>lưu lại và trình bày</b> thông tin dưới dạng bảng, thực hiện các <b>tính toán</b> (từ đơn giản đến phức tạp) cũng như xây dựng các <b>biểu đồ</b> biểu diễn một cách trực quan các số liệu trong bảng.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>&lt;địa chỉ ô&gt; = &lt;tên cột&gt;&lt;tên hàng&gt;. Ví dụ: <b>B6</b>.</li><li>Nhiều ô liền kề tạo thành hình chữ nhật trên trang tính gọi là <b>vùng</b>.</li><li>&lt;địa chỉ vùng&gt; = &lt;địa chỉ ô góc trên bên trái&gt; <b>:</b> &lt;địa chỉ ô góc dưới bên phải&gt;. Ví dụ: <b>B4:E11</b>.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Nhập dữ liệu: nháy vào ô (hoặc vùng nhập dữ liệu), gõ, nhấn <b>Enter</b>. Sửa: nháy đúp vào ô, hoặc sửa ở vùng nhập dữ liệu.</li><li>Văn bản tự động <b>căn trái</b>; số, ngày tháng tự động <b>căn phải</b>.</li><li>Định dạng: chọn vùng → nhóm lệnh <b>Font</b>, <b>Alignment</b> của thẻ Home.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Đổi độ rộng cột: kéo <b>vạch giữa các tên cột</b>. Đổi tên trang tính: <b>nháy đúp</b> vào tên trang tính.</li><li>Lưu: <b>File/Save</b> hoặc <b>Ctrl+S</b>.</li></ul>"}]},"tin7-phan-mem-may-tinh":{"id":"tin7-bai2","ten":"Bài 2. Phần mềm máy tính","cau":[{"id":"kd1","type":"open","q":"Sau khi kết nối bàn phím, màn hình, chuột,… vào thân máy chứa bộ xử lí, máy tính đã hoạt động được chưa? Máy tính còn cần thêm gì để hoạt động và giúp em soạn văn bản, xem video, chơi trò chơi?","k":"Máy tính <b>vẫn chưa hoạt động được</b>. Máy tính còn cần có <b>phần mềm</b>:<ul><li>phần mềm quản lí và điều khiển máy tính là <b>hệ điều hành</b> (Operating System);</li><li>các phần mềm giúp em xử lí những loại dữ liệu cụ thể như văn bản, âm thanh, hình ảnh,… gọi chung là <b>phần mềm ứng dụng</b> (Application Software).</li></ul>","label":"Mở đầu"},{"id":"hd1","type":"sort","q":"Trong dự án Sổ lưu niệm, bạn An đóng vai trò trưởng nhóm. Với mỗi công việc dưới đây, em chọn “Điều hành” nếu đó là việc thể hiện chức năng điều hành nhóm của bạn An (có đúng ba việc như vậy).","k":"Ba việc điều hành là <b>b, d, f</b>. Bạn An không trực tiếp làm một phần việc cụ thể (a, c, e) mà <b>điều phối</b> công việc, <b>kết nối</b> các thành viên với nhau và kết nối nhóm với bên ngoài.","cats":["Điều hành","Không phải"],"items":[["a) Mô tả nội dung sổ lưu niệm bằng phần mềm sơ đồ tư duy",1],["b) Quản lí công việc của cả nhóm, theo dõi thời gian thực hiện",0],["c) Định dạng và sắp xếp các đoạn văn bản trong sổ lưu niệm",1],["d) Phân công nhiệm vụ và kết nối các hoạt động của các thành viên",0],["e) Thiết kế bài giới thiệu sản phẩm bằng phần mềm trình chiếu",1],["f) Thay mặt cả nhóm, trao đổi thông tin với cô giáo và các nhóm khác",0]]},{"id":"hd1b","type":"open","q":"Hệ điều hành trong máy tính giống với vai trò của bạn An trong nhóm ở điểm nào? Nếu máy tính không có hệ điều hành thì sẽ ra sao?","k":"Giống bạn An, hệ điều hành là phần mềm <b>đóng vai trò kết nối</b> giữa người sử dụng với khả năng xử lí của máy tính. Không có hệ điều hành, máy tính <b>chỉ là một khối kim loại và dây dẫn</b>, chẳng hoạt động gì.","label":"HĐ1 – So sánh"},{"id":"hd1c","type":"open","q":"Đọc SGK trang 10–11, em hãy nêu những chức năng cơ bản của hệ điều hành.","k":"<ul><li><b>Quản lí các thiết bị và dữ liệu</b> của máy tính, điều khiển chúng phối hợp hoạt động nhịp nhàng với nhau.</li><li>Cung cấp và quản lí <b>môi trường trao đổi thông tin (giao diện)</b> giữa người sử dụng và máy tính.</li><li>Cung cấp, quản lí <b>môi trường cho phép người sử dụng chạy các phần mềm ứng dụng</b> trên máy tính.</li></ul>","label":"Đọc hiểu – Chức năng"},{"id":"p11a","type":"mcq","q":"Phần mềm nào sau đây KHÔNG phải là một hệ điều hành?","k":"<b>Windows Explorer</b> là phần mềm quản lí tệp và thư mục chạy trên Windows, không phải hệ điều hành. Windows 7, Windows 10 (máy tính) và Windows Phone (điện thoại) đều là hệ điều hành.","o":["Windows 7.","Windows 10.","Windows Explorer.","Windows Phone."],"a":2},{"id":"p11b","type":"mcq","q":"Chức năng nào sau đây KHÔNG phải của hệ điều hành?","k":"<b>Tạo và chỉnh sửa tệp hình ảnh</b> là công việc cụ thể, do phần mềm ứng dụng (như Paint, Photoshop) thực hiện. Ba chức năng còn lại là của hệ điều hành.","o":["Quản lí các tệp dữ liệu trên đĩa.","Tạo và chỉnh sửa nội dung một tệp hình ảnh.","Điều khiển các thiết bị vào – ra.","Quản lí giao diện giữa người sử dụng và máy tính."],"a":1},{"id":"hd2","type":"match","q":"Em hãy ghép mỗi loại tệp với một phần mở rộng tệp phù hợp.","k":"1 – f, 2 – c, 3 – a, 4 – b, 5 – e, 6 – d.","items":[["1) Tài liệu Word",6],["2) Chương trình viết bằng Scratch",3],["3) Hình ảnh",1],["4) Ứng dụng",2],["5) Trang web",5],["6) Bài trình bày PowerPoint",4]],"opts":["a) .jpg, .png, .bmp","b) .exe, .com, .bat, .msi","c) .sb, .sb2, .sb3","d) .ppt, .pptx","e) .htm, .html","f) .doc, .docx"]},{"id":"hd2b","type":"open","q":"Một tệp có tên đầy đủ là TapLamVan.doc. Phần mở rộng của tệp là gì? Phần mở rộng đó giúp hệ điều hành biết điều gì?","k":"Phần mở rộng là <b>.doc</b> (các kí tự sau dấu chấm cuối cùng trong tên tệp). Nhờ đó hệ điều hành biết đây là <b>tệp văn bản</b>, mở và chỉnh sửa được bằng <b>phần mềm soạn thảo văn bản Microsoft Word</b>.","label":"Đọc hiểu – Phần mở rộng"},{"id":"p12a","type":"sort","q":"Em hãy chỉ ra những phần mềm ứng dụng trong các phương án sau: chọn “Ứng dụng” hoặc “Hệ điều hành” cho từng phần mềm.","k":"Phần mềm ứng dụng: <b>B. Gmail, C. UnikeyNT, E. Zalo, F. Windows Media Player</b>. Linux và Windows 8 là hệ điều hành.","cats":["Ứng dụng","Hệ điều hành"],"items":[["A. Linux",1],["B. Gmail",0],["C. UnikeyNT",0],["D. Windows 8",1],["E. Zalo",0],["F. Windows Media Player",0]]},{"id":"p12b","type":"sort","q":"Loại tệp nào dưới đây có thể sử dụng được với Windows Media Player?","k":"Windows Media Player là phần mềm chơi nhạc, xem video nên dùng được với tệp âm thanh <b>.mp3</b> và tệp video <b>.avi, .mp4</b> (A, C, D). Tệp .jpg là hình ảnh, tệp .txt là văn bản.","cats":["Dùng được","Không dùng được"],"items":[["A. .mp3",0],["B. .jpg",1],["C. .avi",0],["D. .mp4",0],["E. .txt",1]]},{"id":"sortCmp","type":"sort","q":"Mỗi đặc điểm dưới đây là của hệ điều hành hay của phần mềm ứng dụng?","k":"Hệ điều hành <b>quản lí các thành phần của máy tính và điều khiển máy tính hoạt động</b>; phần mềm ứng dụng <b>thực hiện yêu cầu xử lí thông tin cụ thể</b> của người sử dụng và phải chạy trên hệ điều hành. Đối chiếu Bảng 2.1 (SGK trang 12).","cats":["Hệ điều hành","Phần mềm ứng dụng"],"items":[["Trực tiếp quản lí và vận hành phần cứng như bàn phím, chuột, màn hình, máy in,…",0],["Tương tác với phần cứng thông qua hệ điều hành",1],["Phải cài đặt đầu tiên để máy tính có thể hoạt động được",0],["Có thể cài đặt hoặc không, tuỳ theo yêu cầu của người sử dụng",1],["Tạo môi trường để cài đặt và chạy phần mềm khác",0],["Chạy trong môi trường hệ điều hành, phải chọn phiên bản phù hợp",1],["Windows, Linux, macOS, Android, iOS",0],["MS Word, Writer, MindMaple, MS Paint, Photoshop",1]]},{"id":"lt1","type":"open","q":"Em hãy nêu các chức năng của hệ điều hành.","k":"<ul><li>Quản lí các thiết bị và dữ liệu của máy tính, điều khiển chúng phối hợp hoạt động nhịp nhàng.</li><li>Cung cấp và quản lí môi trường trao đổi thông tin (giao diện) giữa người sử dụng và máy tính.</li><li>Cung cấp, quản lí môi trường cho phép người sử dụng chạy các phần mềm ứng dụng.</li></ul>","label":"Luyện tập – câu 1"},{"id":"lt2","type":"mcq","q":"Phát biểu nào sau đây là SAI?","k":"Phát biểu <b>C</b> sai. Máy tính chỉ cần có <b>hệ điều hành</b> là hoạt động được; phần mềm ứng dụng có thể cài hoặc không tuỳ theo yêu cầu của người sử dụng.","o":["Người sử dụng xử lí những yêu cầu cụ thể bằng phần mềm ứng dụng.","Để phần mềm ứng dụng chạy được trên máy tính phải có hệ điều hành.","Để máy tính hoạt động được phải có phần mềm ứng dụng.","Để máy tính hoạt động được phải có hệ điều hành."],"a":2},{"id":"vd1","type":"open","q":"Khi tải Scratch để cài đặt lên máy tính, tại sao cần phải chọn phiên bản phù hợp với hệ điều hành trên máy tính của em?","k":"Scratch là <b>phần mềm ứng dụng</b>, chỉ chạy được trong môi trường của hệ điều hành và tương tác với phần cứng <b>thông qua hệ điều hành</b>. Mỗi hệ điều hành (Windows, macOS, Linux,…) quản lí phần cứng và chạy phần mềm theo cách khác nhau, nên phải chọn bản Scratch viết cho đúng hệ điều hành (và đúng phiên bản, ví dụ Windows 10 hay Windows 7) thì mới cài đặt và chạy được.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Hệ điều hành</b> là phần mềm hệ thống quản lí và điều khiển hoạt động chung của máy tính, quản lí dữ liệu, cung cấp cho con người môi trường tương tác với máy tính và chạy các phần mềm ứng dụng.</li><li>Có những hệ điều hành dành cho máy tính như Windows, Mac OS, Linux,… và những hệ điều hành dành cho điện thoại thông minh và máy tính bảng như iOS, Android,…</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Phần mềm ứng dụng</b> là các chương trình máy tính cho phép người sử dụng thực hiện những công việc cụ thể và thường xử lí những loại dữ liệu cụ thể.</li><li>Loại tệp được nhận biết nhờ <b>phần mở rộng</b>, gồm những kí tự sau dấu chấm cuối cùng trong tên tệp. Loại tệp cũng cho biết phần mềm ứng dụng nào có thể được dùng với nó.</li><li>Phần mở rộng thường có tối đa ba kí tự, nhưng một số phần mềm ứng dụng cho phép phần mở rộng nhiều hơn, ví dụ .docx, .html.</li></ul>"},{"t":"Bảng 2.1","b":"<p><b>Phân biệt hệ điều hành và phần mềm ứng dụng</b></p><div class=\"tbl-wrap\"><table class=\"tbl\"><thead><tr><th>Tiêu chí</th><th>Hệ điều hành</th><th>Phần mềm ứng dụng</th></tr></thead><tbody><tr><th>Tương tác với phần cứng</th><td>Trực tiếp quản lí và vận hành phần cứng như bàn phím, chuột, màn hình, máy in,…</td><td>Tương tác với phần cứng thông qua hệ điều hành.</td></tr><tr><th>Sự cần thiết</th><td>Phải cài đặt đầu tiên để máy tính có thể hoạt động được.</td><td>Có thể cài đặt hoặc không tuỳ theo yêu cầu của người sử dụng.</td></tr><tr><th>Phụ thuộc</th><td>Tạo môi trường để cài đặt và chạy phần mềm ứng dụng.</td><td>Chạy trong môi trường hệ điều hành. Được lựa chọn phù hợp với hệ điều hành.</td></tr><tr><th>Ví dụ</th><td>Windows, Linux, macOS,… (cho máy tính). Android, iOS,… (cho điện thoại thông minh hoặc máy tính bảng).</td><td>MindMaple, MindManager,… (sơ đồ tư duy); MS Word, Writer,… (soạn thảo văn bản); MS Paint, Draw, Photoshop (xử lí ảnh),…</td></tr></tbody></table></div>"}]},"tin7-quan-li-du-lieu":{"id":"tin7-bai3","ten":"Bài 3. Quản lí dữ liệu trong máy tính","cau":[{"id":"kd1","type":"open","q":"Chuyến du lịch cùng gia đình có nhiều ảnh và thông tin cần lưu trên máy tính. Em hãy vẽ sơ đồ cây thư mục để chứa các tệp dữ liệu đó và đặt tên cho các thư mục sao cho dễ tìm kiếm, truy cập. (Ghi sơ đồ dạng: DuLich → GiaDinh, DiemDen → …)","k":"Ví dụ: <b>DuLich</b> → <b>GiaDinh</b> (ảnh cả nhà), <b>DiemDen</b> → <b>BinhMinh</b>, <b>BanNgay</b>, <b>HoangHon</b>. Tên thư mục <b>ngắn, dễ nhớ, cho biết bên trong chứa gì</b>; tệp ảnh đặt tên có số thứ tự như PhaoHoa01.jpg, PhaoHoa02.jpg.","label":"Mở đầu – Đặt tên thư mục"},{"id":"ten","type":"sort","q":"Đọc mục 1 (SGK trang 13–14). Tên nào dưới đây đặt hợp lí (dễ nhớ, cho biết bên trong chứa gì), tên nào chưa hợp lí?","k":"Tên hợp lí cho biết <b>nội dung bên trong</b> và <b>dễ nhớ</b>: DuLich, PhaoHoa01.jpg, ToanLop7. Những tên như New Folder (3), abc123, Linh tinh khiến em mất thời gian mở từng thư mục, từng tệp để tìm.","cats":["Hợp lí","Chưa hợp lí"],"items":[["Thư mục DuLich",0],["Thư mục New Folder (3)",1],["Tệp PhaoHoa01.jpg",0],["Tệp abc123.jpg",1],["Thư mục ToanLop7",0],["Thư mục Linh tinh",1]]},{"id":"p14a","type":"mcq","q":"Để việc tìm kiếm dữ liệu trong máy tính được dễ dàng và nhanh chóng, khi đặt tên thư mục và tệp em nên:","k":"<b>B</b>. Tên dễ nhớ và cho biết bên trong chứa gì giúp tìm kiếm nhanh, thuận lợi cho công việc.","o":["Đặt tên theo ý thích như tên người thân hay tên thú cưng.","Đặt tên sao cho dễ nhớ và để biết trong đó chứa gì.","Đặt tên giống như trong ví dụ của sách giáo khoa.","Đặt tên tuỳ ý, không cần theo quy tắc gì."],"a":1},{"id":"p14b","type":"mcq","q":"Tệp có phần mở rộng .exe thuộc loại tệp gì?","k":"<b>B</b>. Chương trình máy tính cũng được lưu dưới dạng tệp. Trong Windows, tệp chương trình thường có phần mở rộng <b>.exe</b>, .com, .bat, .msi. Không nên xoá hay di chuyển các tệp này nếu không biết rõ chúng dùng để làm gì.","o":["Không có loại tệp này.","Tệp chương trình máy tính.","Tệp dữ liệu của phần mềm Microsoft Word.","Tệp dữ liệu video."],"a":1},{"id":"hd2","type":"open","q":"Máy tính của em có nhiều dữ liệu quan trọng. Em muốn bảo vệ dữ liệu trong máy tính của mình thì: a) Em sẽ chọn cách bảo vệ dữ liệu nào? b) Tại sao em chọn cách đó?","k":"Có thể chọn: <b>sao lưu</b> dữ liệu (sang USB, ổ cứng ngoài, lưu trữ đám mây) để không mất khi máy hỏng; đặt <b>mật khẩu</b> để người khác không truy cập trái phép; cài <b>phần mềm diệt virus</b> để chống phần mềm độc hại. Mỗi cách chống lại một loại rủi ro khác nhau.","label":"HĐ2 – Bảo vệ dữ liệu"},{"id":"bang","type":"sort","q":"Đọc Bảng 3.1 (SGK trang 15). Mỗi đặc điểm dưới đây là của thiết bị lưu trữ nào?","k":"<b>USB, thẻ nhớ</b>: nhỏ gọn, dễ thất lạc. <b>Đĩa quang</b>: rẻ, ít nhiễm virus nhưng dung lượng nhỏ, dễ hỏng. <b>Ổ cứng ngoài</b>: dung lượng lớn nhưng to, nặng. <b>Đám mây</b>: truy cập từ xa nhưng cần Internet, có thể bị tấn công.","cats":["Thẻ nhớ, USB","Đĩa quang","Ổ cứng ngoài","Lưu trữ đám mây"],"items":[["Nhỏ gọn, tiện sử dụng nhưng dễ thất lạc",0],["Chi phí thấp nhưng dung lượng nhỏ, cần có đầu ghi",1],["Dung lượng lớn nhưng to và nặng, khó mang theo",2],["Truy cập ở bất kì máy nào có Internet, cần kết nối mạng",3],["Khó bị nhiễm virus nhưng dễ hỏng, khó cất giữ",1],["Dịch vụ có thể không đáng tin cậy, có thể bị tin tặc tấn công",3]]},{"id":"saoluu","type":"sort","q":"Đọc mục a) Sao lưu dữ liệu. Mỗi cách làm dưới đây là sao lưu cục bộ hay sao lưu từ xa?","k":"<b>Cục bộ</b>: bản sao đặt cùng nơi với máy tính (USB, ổ cứng ngoài, đĩa) → phục hồi nhanh nhưng có thể mất cùng máy khi cháy, trộm. <b>Từ xa</b>: bản sao ở nơi khác (Internet, đám mây) → máy hỏng vẫn còn.","cats":["Sao lưu cục bộ","Sao lưu từ xa"],"items":[["Sao chép thư mục DuLich sang USB",0],["Tải thư mục DuLich lên Google Drive",1],["Sao chép ảnh sang ổ cứng ngoài",0],["Lưu bản sao trên OneDrive",1],["Ghi dữ liệu ra đĩa DVD cất trong tủ",0]]},{"id":"mk","type":"sort","q":"Đọc mục b) Tài khoản người sử dụng và mật khẩu. Thử các mật khẩu trong bảng kiểm tra ở trên, rồi xếp mỗi mật khẩu vào nhóm phù hợp.","k":"Mật khẩu <b>mạnh</b>: dài ít nhất 8 kí tự, gồm <b>chữ số, chữ hoa, chữ thường, kí hiệu</b> (@, #,…), không phải thông tin cá nhân: Lan@Ha#2010, Meo3Mau!xanh. Các mật khẩu còn lại là dãy số, từ thông dụng, tên địa danh, ngày sinh → dễ đoán.","cats":["Mạnh","Yếu"],"items":[["12345678",1],["Lan@Ha#2010",0],["matkhau",1],["Ha Noi",1],["Meo3Mau!xanh",0],["15062012 (ngày sinh)",1]]},{"id":"virus","type":"mcq","q":"Đọc mục c) Phần mềm diệt virus. Để phần mềm diệt virus bảo vệ máy tính hiệu quả, em cần:","k":"<b>B</b>. Virus mới xuất hiện liên tục nên phần mềm diệt virus phải được <b>cập nhật thường xuyên</b> và <b>luôn bật</b>. Không dùng phần mềm không rõ nguồn gốc. Windows có sẵn <b>Windows Defender</b>.","o":["Cài một lần rồi không cần quan tâm nữa.","Cài phần mềm diệt virus và thường xuyên cập nhật, luôn bật chế độ bảo vệ.","Tắt phần mềm diệt virus khi chạy phần mềm tải trên mạng.","Chỉ cần đặt mật khẩu mạnh là đủ."],"a":1},{"id":"p16a","type":"mcq","q":"Mật khẩu nào sau đây là mạnh nhất?","k":"<b>D</b>. 2n#M1nhKh0a. có chữ số, chữ hoa, chữ thường và kí hiệu đặc biệt, dài hơn 8 kí tự.","o":["12345678.","AnMinhKhoa.","matkhau.","2n#M1nhKh0a."],"a":3},{"id":"p16b","type":"sort","q":"Mỗi phát biểu dưới đây đúng hay sai?","k":"Phát biểu <b>sai</b>: <b>B</b> (đĩa CD dung lượng <b>nhỏ</b>) và <b>C</b> (ổ cứng ngoài <b>to, nặng</b>, khó mang theo).","cats":["Đúng","Sai"],"items":[["A. Lưu trữ bằng công nghệ đám mây có thể tránh được rơi, mất, hỏng dữ liệu.",0],["B. Lưu trữ bằng đĩa CD cần phải có đầu ghi đĩa nhưng dung lượng rất lớn.",1],["C. Lưu trữ bằng ổ cứng ngoài vừa nhỏ gọn vừa có dung lượng lớn.",1],["D. Lưu trữ bằng thẻ nhớ, USB dễ bị rơi, mất dữ liệu nhưng thuận tiện.",0]]},{"id":"nv1","type":"order","q":"Sắp xếp các bước tạo thư mục DuLich trong File Explorer (dùng nút ↑ ↓).","k":"Thứ tự: <b>d → b → a → c</b>. Thư mục mới có tên New Folder, em gõ tên mới rồi nhấn Enter.","items":{"a":"Gõ tên mới DuLich.","b":"Nháy nút phải chuột trên vùng trống, chọn New/Folder.","c":"Nhấn phím Enter.","d":"Mở File Explorer, vào nơi muốn tạo thư mục."},"ans":["d","b","a","c"],"start":["a","b","c","d"]},{"id":"lenh","type":"sort","q":"Quan sát Hình 3.6. Để thực hiện mỗi thao tác dưới đây em dùng lệnh nào?","k":"Đổi tên: <b>Rename</b>. Di chuyển: <b>Cut</b> rồi <b>Paste</b>. Sao chép: <b>Copy</b> rồi <b>Paste</b>. Xoá: <b>Delete</b>. Cut và Copy đều đưa đối tượng vào bộ nhớ; Paste dán ra chỗ mới.","cats":["Rename","Cut rồi Paste","Copy rồi Paste","Delete"],"items":[["Đổi tên thư mục HoangHon thành ChieuToi",0],["Di chuyển các tệp của BinhMinh sang BanNgay",1],["Tạo thêm một bản của ảnh PhaoHoa01.jpg ở thư mục GiaDinh",2],["Xoá thư mục BinhMinh",3]]},{"id":"nvkq","type":"open","q":"Báo cáo kết quả nhiệm vụ thực hành (làm trên máy tính hoặc trên bảng mô phỏng): sau khi thực hiện, thư mục DiemDen gồm những gì? Thư mục BanNgay gồm những gì?","k":"DiemDen gồm: <b>BanNgay</b>, <b>ChieuToi</b>, PhaoHoa01.jpg, PhaoHoa02.jpg (không còn BinhMinh và HoangHon). BanNgay chứa thêm các tệp và thư mục con chuyển từ BinhMinh sang.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"mcq","q":"Đâu là chương trình máy tính giúp em quản lí tệp và thư mục?","k":"<b>D</b>. <b>File Explorer</b> là ứng dụng quản lí tệp trong Windows 10 (Windows 7 trở về trước gọi là Windows Explorer).","o":["Internet Explorer.","Help.","Microsoft Word.","File Explorer."],"a":3},{"id":"lt2","type":"mcq","q":"Đâu là phần mềm có thể bảo vệ máy tính tránh được virus?","k":"<b>A</b>. <b>Windows Defender</b> là phần mềm diệt virus có sẵn trong Windows. Firefox là trình duyệt web, Windows là hệ điều hành, Word là phần mềm soạn thảo.","o":["Windows Defender.","Mozilla Firefox.","Microsoft Windows.","Microsoft Word."],"a":0},{"id":"vd1","type":"open","q":"Em hãy lựa chọn một thiết bị lưu trữ để sao lưu thư mục “DuLich”. Giải thích tại sao em lựa chọn cách sao lưu đó.","k":"Ví dụ: ảnh du lịch nhiều, dung lượng lớn → chọn <b>ổ cứng ngoài</b> (dung lượng lớn, dùng lâu) hoặc <b>lưu trữ đám mây</b> (máy hỏng vẫn còn, xem được ở mọi nơi có Internet). Có thể kết hợp cả hai để an toàn hơn.","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Sau khi học xong bài này và có thêm các kiến thức về sao lưu, bảo vệ dữ liệu, em có thay đổi cách bảo vệ dữ liệu mà em đã chọn trong Hoạt động 2 không? Tại sao?","k":"Học sinh tự trả lời. Câu trả lời tốt nêu được: kết hợp nhiều biện pháp (<b>sao lưu thường xuyên</b> + <b>mật khẩu mạnh</b> + <b>phần mềm diệt virus</b> luôn cập nhật), vì mỗi biện pháp chống một loại rủi ro.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Tên tệp và thư mục cần đặt sao cho <b>dễ nhớ</b>, cho biết trong đó <b>chứa gì</b>. Điều đó giúp công việc thuận lợi hơn.</li><li>Chương trình máy tính được lưu trữ trên thiết bị nhớ giống như một <b>tệp dữ liệu</b>. Tệp chương trình trong Windows thường có phần mở rộng <b>.exe, .com, .bat, .msi</b>.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Dữ liệu cần được <b>sao lưu thường xuyên</b> lên thiết bị lưu trữ ngoài máy tính chứa dữ liệu gốc để tránh bị mất hoặc hỏng dữ liệu.</li><li>Đặt <b>mật khẩu</b> cho tài khoản trên máy tính và trên Internet giúp dữ liệu khỏi bị truy cập trái phép.</li><li>Không dùng phần mềm không rõ nguồn gốc; luôn bật chế độ bảo vệ của <b>phần mềm diệt virus</b>.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Tạo thư mục: nháy phải chuột → <b>New/Folder</b> → gõ tên → Enter.</li><li>Đổi tên: <b>Rename</b>. Di chuyển: <b>Cut</b> + <b>Paste</b>. Sao chép: <b>Copy</b> + <b>Paste</b>. Xoá: <b>Delete</b>.</li><li>Làm tương tự với tệp.</li></ul>"}]},"tin7-tao-bai-trinh-chieu":{"id":"tin7-bai11","ten":"Bài 11. Tạo bài trình chiếu","cau":[{"id":"kd1","type":"open","q":"Đọc đoạn hội thoại của An, Minh và Khoa. Để báo cáo kết quả dự án Trường học xanh, nhóm sẽ dùng phần mềm nào? Theo các bạn, bài trình chiếu báo cáo cần có những gì?","k":"Dùng <b>phần mềm trình chiếu</b>. Bài trình chiếu cần có <b>trang tiêu đề</b>, mỗi trang nội dung có <b>tiêu đề trang</b>, nội dung trình bày theo <b>cấu trúc phân cấp</b> để mạch lạc, rõ ràng.","label":"Mở đầu"},{"id":"hd1a","type":"open","q":"Em đã biết gì về phần mềm trình chiếu?","k":"Ví dụ: Microsoft PowerPoint, Google Slides; dùng để tạo các trang chiếu có chữ, hình ảnh, âm thanh, video; trình chiếu lên màn hình hoặc máy chiếu; có hiệu ứng động.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"mcq","q":"Khi tạo một bài trình bày với nội dung gồm văn bản, hình ảnh và nhiều đối tượng khác, em chọn phần mềm nào?","k":"<b>Phần mềm trình chiếu</b>: thông tin được trình bày ngắn gọn trên từng trang chiếu, kết hợp văn bản, hình ảnh, âm thanh, video, hiệu ứng động và chiếu lên màn hình rộng cho nhiều người xem.","o":["Phần mềm soạn thảo văn bản, vì có nhiều công cụ xử lí văn bản.","Phần mềm trình chiếu, vì trình bày thông tin dưới dạng các trang chiếu cô đọng, hấp dẫn, có hiệu ứng và trình chiếu được lên màn hình.","Phần mềm bảng tính.","Không cần phần mềm."],"a":1},{"id":"p56","type":"sort","q":"Trong các phát biểu sau, phát biểu nào đúng, phát biểu nào sai?","k":"a, b, c <b>đúng</b>. d <b>sai</b>: tính toán tự động là chức năng của phần mềm bảng tính. Hai chức năng cơ bản của phần mềm trình chiếu là <b>tạo bài trình chiếu</b> và <b>trình chiếu</b>.","cats":["Đúng","Sai"],"items":[["a) Phần mềm trình chiếu thường được sử dụng để tạo bài trình chiếu phục vụ hội nghị, dạy học, quảng cáo,…",0],["b) Phần mềm trình chiếu có chức năng tạo bài trình chiếu và lưu dưới dạng tệp.",0],["c) Có thể nhập và xử lí văn bản, hình ảnh trên các trang chiếu.",0],["d) Chức năng chính của phần mềm trình chiếu là tính toán tự động.",1]]},{"id":"hd2a","type":"open","q":"Khi tạo bài trình chiếu, em thường trình bày các trang như thế nào?","k":"Trang đầu là <b>trang tiêu đề</b> (tên bài, tên tác giả, ngày, địa điểm); các trang sau là <b>trang nội dung</b>, mỗi trang có tiêu đề trang và nội dung; các trang thống nhất theo cùng một mẫu.","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Theo em, tiêu đề của bài trình chiếu nên đặt ở trang nào? Muốn làm nổi bật nội dung của mỗi trang thì cần làm như thế nào?","k":"Tiêu đề bài trình chiếu đặt ở <b>trang đầu tiên</b> (trang tiêu đề). Mỗi trang nội dung có <b>tiêu đề trang</b> đặt ở trên đầu, viết dưới dạng văn bản, giúp làm nổi bật nội dung cần trình bày.","label":"HĐ2 – Câu 2"},{"id":"layout","type":"sort","q":"Đọc mục 2 (SGK trang 56). Mỗi mô tả dưới đây nói về thành phần nào?","k":"<b>Trang tiêu đề</b> (Title Slide): trang đầu, cho biết chủ đề, thu hút người nghe. <b>Tiêu đề trang</b>: ở trên đầu mỗi trang, làm nổi bật nội dung. <b>Mẫu bố trí</b> (layout): ví dụ Title and Content.","cats":["Trang tiêu đề","Tiêu đề trang","Mẫu bố trí (layout)"],"items":[["Trang đầu tiên, cho biết chủ đề của bài trình chiếu",0],["Có thể thêm tên tác giả, ngày, địa điểm trình bày",0],["Viết dưới dạng văn bản ở trên đầu mỗi trang nội dung",1],["Các cách bố trí nội dung có sẵn trong phần mềm, có thể thay đổi hoặc tự tạo",2]]},{"id":"p57a","type":"mcq","q":"Phát biểu nào sau đây không đúng?","k":"<b>D</b> không đúng: các phần mềm trình chiếu <b>có sẵn</b> các mẫu bố trí nội dung trang chiếu để thuận tiện cho người sử dụng.","o":["Trang tiêu đề là trang đầu tiên và cho biết chủ đề của bài trình chiếu.","Các trang nội dung của bài trình chiếu thường có tiêu đề trang.","Tiêu đề trang giúp làm nổi bật nội dung cần trình bày của trang.","Các phần mềm trình chiếu không có sẵn các mẫu bố trí."],"a":3},{"id":"hd3","type":"mcq","q":"Quan sát hai cách trình bày dự án Trường học xanh. Cách trình bày nào dễ hiểu hơn?","k":"<b>Cách 2</b> là hình thức trình bày theo <b>cấu trúc phân cấp</b>: truyền tải thông tin mạch lạc, dễ hiểu, dễ quản lí; người xem dễ hiểu được bố cục nội dung.","o":["Cách 1, vì các dòng đều ngang cấp nhau.","Cách 2, vì nội dung được chia thành các mục lớn, mục nhỏ lùi vào trong, thấy rõ cái nào thuộc cái nào.","Hai cách như nhau.","Không cách nào dễ hiểu."],"a":1},{"id":"p57b","type":"mcq","q":"Câu nào sau đây sai khi nói về cấu trúc phân cấp?","k":"<b>C</b> sai: các đầu dòng ngang cấp nhau là Cách 1, không phải cấu trúc phân cấp.","o":["Là cấu trúc gồm danh sách nhiều cấp.","Giúp làm cho nội dung cần trình bày có bố cục mạch lạc, dễ hiểu.","Cấu trúc này gồm một chuỗi các đầu dòng ngang cấp nhau.","Cấu trúc này được sử dụng nhiều trong soạn thảo văn bản, tạo bài trình chiếu."],"a":2},{"id":"nv1","type":"order","q":"Sắp xếp các bước tạo bài trình chiếu Trường học xanh (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → a → d → c</b>.","items":{"a":"Nháy New Slide, chọn Layout, nhập tiêu đề trang và nội dung.","b":"Khởi động phần mềm trình chiếu, nhập tiêu đề và phụ đề ở trang tiêu đề.","c":"Lưu bài với tên Truonghocxanh.pptx.","d":"Tạo cấu trúc phân cấp (Tab / Shift+Tab), đổi kí hiệu đầu dòng."},"ans":["b","a","d","c"],"start":["a","b","c","d"]},{"id":"nv2","type":"mcq","q":"Để đưa dòng “Vai trò của cây xanh” thành mục con của “Ý tưởng”, em đặt con trỏ vào đầu dòng đó rồi:","k":"<b>Increase List Level</b> (phím <b>Tab</b>) tăng bậc phân cấp: dòng dịch sang phải, cỡ chữ giảm. <b>Decrease List Level</b> (<b>Shift+Tab</b>) giảm bậc phân cấp.","o":["Nhấn Enter.","Chọn Increase List Level hoặc nhấn phím Tab.","Nhấn Shift+Tab.","Nhấn Delete."],"a":1},{"id":"nv3","type":"mcq","q":"Muốn đổi kí hiệu đầu dòng chấm tròn thành mũi tên ➢ màu đỏ, em:","k":"Mở hộp thoại <b>Bullets and Numbering</b>: <b>Bulleted</b> để đổi kí hiệu, <b>Numbered</b> để đánh số thứ tự, <b>Color</b> để đổi màu.","o":["Home → mũi tên bên phải lệnh Bullets → Bullets and Numbering… → chọn kí hiệu ở Bulleted, chọn Color → OK.","Insert → Picture.","Design → Themes.","Nhấn phím Tab."],"a":0},{"id":"nvkq","type":"open","q":"Báo cáo kết quả: bài trình chiếu của nhóm có mấy trang? Trang nội dung có mấy cấp? Em đã dùng những kí hiệu đầu dòng nào cho mỗi cấp?","k":"Ví dụ: 2 trang (trang tiêu đề “DỰ ÁN TRƯỜNG HỌC XANH”, trang “Nội dung trình bày”); 3 cấp: Ý tưởng, Kế hoạch, Kết luận (cấp 1); Vai trò của cây xanh, Đề xuất dự án, Khảo sát, Thực hiện, Kết quả dự kiến (cấp 2); Phân công, Thời gian (cấp 3); cấp 1 ■ đỏ, cấp 2 ➢, cấp 3 ✓.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Ưu điểm của việc sử dụng cấu trúc phân cấp trong bài trình chiếu là gì?","k":"Nội dung có <b>bố cục mạch lạc, dễ hiểu</b>; người xem thấy rõ mục lớn, mục nhỏ; giúp <b>truyền tải thông tin</b> và <b>quản lí nội dung</b> tốt hơn.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"open","q":"Em hãy tạo trang chiếu ghi các công việc cần làm trong ngày và sử dụng cấu trúc phân cấp để trình bày nội dung (làm trên bảng mô phỏng ở phần Vận dụng hoặc trên máy). Ghi lại các mục cấp 1 em đã dùng.","k":"Ví dụ: Buổi sáng (cấp 1) → Đi học, Học Tin học (cấp 2); Buổi chiều → Làm bài tập, Chơi thể thao; Buổi tối → Giúp mẹ việc nhà, Đọc sách.","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Đề xuất một dự án thiết thực (ví dụ: Làm sạch đẹp cảnh quan ngôi nhà của em; Trang trí thư viện của trường; Tái chế rác thải;…). Tạo bài trình chiếu trình bày dự án đó (mục tiêu, cách làm, tác dụng, hiệu ứng,…) có trang tiêu đề, các trang nội dung có tiêu đề trang và dùng cấu trúc phân cấp. Lưu với tên Baitaptinhoc7.pptx. Mô tả ngắn bài của em.","k":"Học sinh tự làm. Bài tốt có: trang tiêu đề (tên dự án, người thực hiện); 2–4 trang nội dung có tiêu đề trang (Mục tiêu, Cách làm, Tác dụng,…); nội dung phân cấp rõ ràng, kí hiệu đầu dòng phù hợp.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Phần mềm trình chiếu có hai chức năng cơ bản là <b>tạo bài trình chiếu</b> và <b>trình chiếu</b> nó.</li><li>Phần mềm trình chiếu có các <b>hiệu ứng</b> làm cho nội dung trình bày thêm sinh động và hấp dẫn.</li><li>Phần mềm trình chiếu thường được sử dụng để tạo bài trình chiếu phục vụ hội thảo, hội nghị, dạy học, quảng cáo,…</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Bài trình chiếu thường có trang đầu tiên là <b>trang tiêu đề</b> cho biết chủ đề của bài trình bày, tiếp theo là các <b>trang nội dung</b>.</li><li><b>Tiêu đề trang</b> làm nổi bật nội dung cần trình bày trong trang và được đặt trên đầu các trang nội dung.</li><li>Các phần mềm trình chiếu có sẵn các <b>mẫu bố trí</b> nội dung trang chiếu để thuận tiện cho người sử dụng.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Cấu trúc phân cấp</b> (hay danh sách kí hiệu đầu dòng nhiều cấp) thường được dùng trong soạn thảo văn bản, tạo bài trình chiếu,… Đây là một công cụ giúp làm cho nội dung trình bày có bố cục mạch lạc, dễ hiểu, giúp truyền tải thông tin và quản lí nội dung tốt hơn.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Trang mới: <b>New Slide</b>; mẫu bố trí: <b>Layout</b>.</li><li>Tăng cấp: <b>Increase List Level</b> (Tab); giảm cấp: <b>Decrease List Level</b> (Shift+Tab).</li><li>Đổi kí hiệu, màu: <b>Bullets and Numbering</b>.</li></ul>"}]},"tin7-thiet-bi-vao-ra":{"id":"tin7-bai1","ten":"Bài 1. Thiết bị vào – ra","cau":[{"id":"kd1","type":"open","q":"Ở lớp 6, em đã biết máy tính cần bốn thành phần cơ bản để hỗ trợ con người xử lí thông tin. Đó là những thành phần nào? Thành phần nào giúp máy tính trao đổi dữ liệu với thế giới bên ngoài?","k":"Bốn thành phần: <b>thiết bị vào, thiết bị ra, bộ xử lí và bộ nhớ</b>. Trong đó, <b>thiết bị vào – ra</b> đóng vai trò quan trọng, giúp máy tính trao đổi dữ liệu với thế giới bên ngoài.","label":"Mở đầu"},{"id":"h1a","type":"open","q":"Các thiết bị trong Hình 1.1 làm việc với dạng thông tin nào?","k":"Micro và loa làm việc với thông tin dạng <b>âm thanh</b>.","label":"HĐ1 – câu 1"},{"id":"h1b","type":"open","q":"Thiết bị nào tiếp nhận thông tin và chuyển vào máy tính?","k":"<b>Micro</b> nhận âm thanh và chuyển vào máy tính để mã hoá thành dữ liệu số. Micro là <b>thiết bị vào</b>.","label":"HĐ1 – câu 2"},{"id":"h1c","type":"open","q":"Thiết bị nào nhận thông tin từ máy tính đưa ra bên ngoài?","k":"<b>Loa</b> nhận dữ liệu từ máy tính, thể hiện ra bên ngoài dưới dạng âm thanh mà chúng ta nghe được. Loa là <b>thiết bị ra</b>.","label":"HĐ1 – câu 3"},{"id":"h2a","type":"open","q":"Mỗi thiết bị vào – ra trong Hình 1.2 làm việc với dạng thông tin nào? Thiết bị nào có cả hai chức năng vào và ra?","k":"<ul><li>Thiết bị vào: chuột, bàn phím (lệnh, văn bản); micro (âm thanh); camera, máy quét (hình ảnh).</li><li>Thiết bị ra: màn hình, máy in (văn bản, hình ảnh); tai nghe, loa (âm thanh).</li><li><b>Bảng vẽ điện tử có bút cảm ứng</b> xuất hiện ở cả hai nhóm: vừa nhận nét vẽ, thao tác chạm (vào) vừa hiển thị hình ảnh (ra), nên có cả hai chức năng.</li></ul>","label":"HĐ2 – câu 1"},{"id":"h2b","type":"open","q":"Máy chiếu là thiết bị vào hay thiết bị ra? Máy chiếu làm việc với dạng thông tin nào?","k":"Máy chiếu là <b>thiết bị ra</b>, dùng để hiển thị nội dung màn hình máy tính lên màn chiếu. Máy chiếu làm việc với thông tin dạng <b>hình ảnh, văn bản</b>.","label":"HĐ2 – câu 2"},{"id":"h2c","type":"open","q":"Bộ điều khiển game (Hình 1.3a) là thiết bị vào hay thiết bị ra?","k":"Bộ điều khiển game là <b>thiết bị vào</b>: đưa mệnh lệnh vào máy tính để điều khiển đối tượng trong trò chơi.","label":"HĐ2 – câu 3"},{"id":"h2d","type":"open","q":"Màn hình cảm ứng (Hình 1.3b) là thiết bị vào, thiết bị ra hay có cả hai chức năng vào và ra?","k":"Màn hình cảm ứng có <b>cả hai chức năng</b>: hiển thị thông tin (ra), đồng thời phát hiện vị trí và sự di chuyển của ngón tay trên bề mặt để chọn đối tượng, thực hiện lệnh (vào).","label":"HĐ2 – câu 4"},{"id":"sortDev","type":"sort","q":"Chọn nhóm cho từng thiết bị.","k":"Tiêu chí phân loại là <b>chiều đi của thông tin so với máy tính</b>, không phải hình dạng thiết bị. Thông tin đi vào máy tính: thiết bị vào. Thông tin đi ra khỏi máy tính: thiết bị ra. Có cả hai chiều: vừa vào vừa ra.","cats":["Vào","Ra","Vừa vào vừa ra"],"items":[["Chuột",0],["Bàn phím",0],["Micro",0],["Webcam",0],["Camera an ninh",0],["Máy quét",0],["Bút cảm ứng",0],["Bộ điều khiển game",0],["Tấm cảm ứng (touchpad)",0],["Màn hình",1],["Máy in",1],["Loa",1],["Tai nghe",1],["Máy chiếu",1],["Màn hình cảm ứng",2],["Tai nghe có gắn micro",2]]},{"id":"h2e","type":"open","q":"Loa thông minh và máy ghi hình kĩ thuật số là thiết bị vào hay ra? Ngoài nhập hoặc xuất thông tin, chúng còn thực hiện được những chức năng nào?","k":"<ul><li><b>Loa thông minh</b> là <b>thiết bị ra</b>. Ngoài ra, nó còn kết nối không dây với máy tính, điện thoại thông minh, Internet,… để trao đổi dữ liệu; có thể nhận lệnh bằng giọng nói và trả lời bằng giọng nói.</li><li><b>Máy ghi hình kĩ thuật số</b> là <b>thiết bị vào</b>, còn có thể <b>lưu trữ</b> và thực hiện một số chức năng <b>xử lí</b> ảnh, xử lí video đơn giản.</li></ul>","label":"Đọc hiểu – câu 5"},{"id":"p7a","type":"mcq","q":"Em hãy cho biết máy ảnh nhập thông tin dạng nào vào máy tính?","k":"Máy ảnh là thiết bị vào, nhập thông tin dạng <b>hình ảnh</b>.","o":["Con số.","Văn bản.","Hình ảnh.","Âm thanh."],"a":2},{"id":"p7b","type":"mcq","q":"Thiết bị nào xuất dữ liệu âm thanh từ máy tính ra ngoài?","k":"<b>Loa</b> là thiết bị ra, xuất dữ liệu âm thanh. Micro cũng làm việc với âm thanh nhưng là thiết bị vào.","o":["Máy ảnh.","Micro.","Màn hình.","Loa."],"a":3},{"id":"h3a","type":"match","q":"Em hãy lắp các thiết bị vào đúng cổng bằng cách chọn số cổng cho mỗi đầu nối.","k":"a – 7, b – 6, c – 7, d – 3, e – 4, f – 8.","items":[["a) Bàn phím",7],["b) Dây mạng",6],["c) Chuột",7],["d) Dây màn hình",3],["e) Tai nghe",4],["f) Dây nguồn",8]]},{"id":"h3b","type":"open","q":"Việc cấp nguồn điện cho máy tính cần được thực hiện trước hay sau các kết nối trên? Tại sao?","k":"Cấp nguồn điện <b>sau</b> khi các thiết bị đã được kết nối xong, để đảm bảo an toàn điện cho người dùng và cho thiết bị.","label":"HĐ3 – câu 2"},{"id":"sortSafe","type":"sort","q":"Với mỗi việc dưới đây khi sử dụng máy tính, em chọn Nên hoặc Không nên.","k":"Đối chiếu Bảng 1.1 (SGK trang 9). Những việc không nên làm có thể gây hỏng thiết bị, mất dữ liệu hoặc mất an toàn điện.","cats":["Nên","Không nên"],"items":[["Đọc kĩ hướng dẫn trước khi sử dụng thiết bị",0],["Thao tác tuỳ tiện, không theo hướng dẫn",1],["Giữ bàn tay khô, sạch khi sử dụng máy tính",0],["Để đồ uống gần chuột, bàn phím, thẻ nhớ",1],["Gõ phím dứt khoát nhưng nhẹ nhàng",0],["Dùng vật sắc, nhọn tác động lên màn hình",1],["Sử dụng nút lệnh Shut down để tắt máy tính",0],["Tắt máy tính bằng cách ngắt điện đột ngột",1],["Rút điện trước khi lau, dọn máy tính",0],["Chạm vào phần kim loại của máy tính",1],["Đóng mọi tài liệu và ứng dụng trước khi tắt máy",0],["Nối máy tính với máy in khi một trong hai máy đang bật nguồn",1]]},{"id":"p9a","type":"mcq","q":"Thao tác nào sau đây tắt máy tính một cách an toàn?","k":"Dùng nút lệnh <b>Shut down</b>. Restart là khởi động lại máy; nhấn giữ công tắc nguồn hoặc rút dây nguồn là ngắt điện đột ngột, dễ mất dữ liệu và hỏng máy.","o":["Sử dụng nút lệnh Restart của Windows.","Sử dụng nút lệnh Shut down của Windows.","Nhấn giữ công tắc nguồn vài giây.","Rút dây nguồn khỏi ổ cắm."],"a":1},{"id":"p9b","type":"open","q":"Tại sao không nên vừa ăn vừa sử dụng máy tính?","k":"Vụn thức ăn, nước uống có thể rơi vào bàn phím, chuột gây kẹt phím, chập điện, hỏng thiết bị; tay dính thức ăn làm bẩn thiết bị. Vừa ăn vừa dùng máy cũng không tốt cho sức khoẻ.","label":"Câu hỏi tr.9 – câu 2"},{"id":"lt1","type":"mcq","q":"Một bộ tai nghe có gắn micro sử dụng cho máy tính là loại thiết bị gì?","k":"Tai nghe xuất âm thanh (ra), micro gắn kèm nhập âm thanh (vào), nên bộ tai nghe có micro là <b>thiết bị vừa vào vừa ra</b>.","o":["Thiết bị vào.","Thiết bị ra.","Thiết bị vừa vào vừa ra.","Không phải thiết bị vào – ra."],"a":2},{"id":"lt2","type":"order","q":"Máy tính của em đang làm việc với một tệp trên thẻ nhớ. Em hãy sắp xếp lại thứ tự các thao tác để tắt máy tính an toàn, không làm mất dữ liệu (dùng nút ↑ ↓).","k":"Thứ tự đúng: <b>d → b → c → a</b>. Lưu tệp, đóng tệp, ngắt kết nối thẻ nhớ an toàn, rồi mới tắt máy bằng Shut down.","items":{"a":"Chọn nút lệnh Shut down để tắt máy tính.","b":"Đóng tệp đang mở trên thẻ nhớ.","c":"Chọn \"Safe To Remove Hardware\" để ngắt kết nối với thẻ nhớ.","d":"Lưu lại nội dung của tệp."},"ans":["d","b","c","a"],"start":["a","b","c","d"]},{"id":"vd1","type":"open","q":"Trên màn hình theo dõi, em thấy một người đứng trước camera an ninh. Người đó có biết em đang theo dõi không? Tại sao?","k":"<b>Không biết.</b> Camera là thiết bị vào: chỉ thu hình ảnh rồi chuyển vào máy tính, không đưa thông tin nào ra để người đứng trước camera biết có người đang xem.","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Máy in của em in ra những kí hiệu không mong muốn và em biết lỗi này là do virus gây ra. Em cần phải diệt virus ở máy in hay không? Tại sao?","k":"<b>Không cần</b> diệt virus ở máy in. Máy in là thiết bị ra, chỉ in theo dữ liệu máy tính gửi tới. Virus nằm trên máy tính làm sai dữ liệu gửi đi, vì vậy cần quét và diệt virus <b>trên máy tính</b>.","label":"Vận dụng – câu 2"},{"id":"vd3","type":"open","q":"Em hãy đề xuất một số quy tắc để giúp các bạn sử dụng phòng máy tính an toàn.","k":"Gợi ý: không mang đồ ăn, nước uống vào phòng máy; giữ tay khô, sạch; không tự ý cắm, rút thiết bị khi máy đang bật; tắt máy bằng lệnh Shut down; không chạm vào phần kim loại, ổ điện; báo thầy cô khi thiết bị gặp sự cố; giữ chỗ ngồi gọn gàng, sạch sẽ.","label":"Vận dụng – câu 3"}],"the":[{"t":"Khái niệm","b":"<ul><li><b>Thiết bị vào</b> được dùng để nhập thông tin vào máy tính như bàn phím, chuột, micro,…</li><li><b>Thiết bị ra</b> được dùng để xuất thông tin từ máy tính ra bên ngoài như màn hình, máy in, loa,…</li><li>Cách nhận biết: xét <b>chiều đi của thông tin</b> so với máy tính.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Thiết bị vào được dùng để nhập thông tin vào máy tính.</li><li>Thiết bị ra xuất thông tin từ máy tính ra để con người nhận biết được.</li><li>Các thiết bị vào – ra có nhiều loại, có những công dụng và hình dạng khác nhau. Một số thiết bị vào – ra còn thực hiện cả chức năng lưu trữ, xử lí dữ liệu.</li></ul>"},{"t":"Chốt kiến thức","b":"<ul><li>Đầu nối tai nghe (e) cắm vào cổng <b>4</b>. Cắm nhầm sang cổng 5 sẽ không nghe thấy âm thanh, em có thể tưởng thiết bị bị hỏng.</li><li>Dây màn hình (d) cắm vào cổng <b>3</b>. Cố cắm vào cổng khác có thể làm hỏng đầu nối.</li><li>Cổng <b>7</b> là cổng USB dùng cho nhiều thiết bị như bàn phím, chuột. Cắm nhầm đầu nối khác có thể gây chập điện, hỏng thiết bị.</li><li>Dây nguồn (f) cắm vào cổng <b>8</b>; chỉ cấp nguồn <b>sau khi</b> các thiết bị đã được kết nối.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Đọc kĩ hướng dẫn của nhà sản xuất trước khi sử dụng thiết bị.</li><li>Kết nối các thiết bị đúng cách.</li><li>Giữ gìn nơi làm việc với máy tính gọn gàng, ngăn nắp, vệ sinh, khô ráo.</li></ul>"}]},"tin7-thuat-toan-sap-xep":{"id":"tin7-bai16","ten":"Bài 16. Thuật toán sắp xếp","cau":[{"id":"kd1","type":"open","q":"Có hai cốc A (đựng chất lỏng màu xanh) và B (đựng chất lỏng màu đỏ). Cần đổi chỗ hai chất lỏng để cốc A đựng màu đỏ, cốc B đựng màu xanh. Em hãy mô tả cách thực hiện. Vì sao cần dùng thêm cốc C?","k":"Ba bước: <b>rót A sang C</b> → <b>rót B sang A</b> → <b>rót C sang B</b>. Cốc C dùng để <b>giữ tạm</b> một chất lỏng; nếu rót thẳng thì hai chất lỏng bị trộn lẫn. Đây chính là cách <b>hoán đổi</b> giá trị hai phần tử.","label":"Khởi động"},{"id":"nb1","type":"order","q":"Sắp xếp các bước của thuật toán sắp xếp nổi bọt (dãy tăng dần) theo đúng thứ tự (dùng nút ↑ ↓).","k":"(b) So sánh hai phần tử cạnh nhau từ cuối dãy lên → (a) phần tử sau nhỏ hơn thì đổi chỗ → (d) phần tử nhỏ nhất nổi lên vị trí đầu tiên → (e) lặp lại với các vị trí tiếp theo → (c) kết thúc.","items":{"a":"Nếu phần tử đứng sau nhỏ hơn phần tử đứng trước thì đổi chỗ chúng cho nhau.","b":"Với vị trí đầu tiên: so sánh hai phần tử đứng cạnh nhau theo thứ tự từ cuối dãy lên vị trí đầu tiên.","c":"Kết thúc, em sẽ nhận được dãy số đã được sắp xếp theo thứ tự từ nhỏ đến lớn.","d":"Cuối vòng lặp, phần tử nhỏ nhất nổi lên vị trí đầu tiên.","e":"Tương tự với vị trí thứ hai, thứ ba, … đến vị trí trước vị trí cuối cùng."},"ans":["b","a","d","e","c"],"start":["a","b","c","d","e"]},{"id":"hd1a","type":"mcq","q":"Sắp xếp nổi bọt dãy 3, 5, 4, 1, 2 theo thứ tự tăng dần. Kết quả sau vòng lặp thứ nhất là:","k":"Từ cuối dãy lên: 2 &lt; 1? Không. 1 &lt; 4 → hoán đổi (3 5 1 4 2); 1 &lt; 5 → hoán đổi (3 1 5 4 2); 1 &lt; 3 → hoán đổi. Kết quả: <b>1, 3, 5, 4, 2</b> — số 1 nhỏ nhất đã “nổi” lên vị trí đầu.","o":["1, 3, 5, 4, 2","1, 2, 3, 4, 5","3, 5, 4, 1, 2","3, 1, 5, 4, 2"],"a":0},{"id":"hd1b","type":"mcq","q":"Tiếp tục sắp xếp dãy trên. Kết quả sau vòng lặp thứ hai, thứ ba lần lượt là:","k":"Vòng 2: <b>1, 2, 3, 5, 4</b> (3 lần hoán đổi). Vòng 3: <b>1, 2, 3, 4, 5</b> (hoán đổi 4 và 5). Vòng 4 không còn hoán đổi nào. Tổng cộng 7 lần hoán đổi.","o":["1, 2, 3, 5, 4 và 1, 2, 3, 4, 5","1, 3, 2, 5, 4 và 1, 2, 3, 5, 4","1, 2, 3, 4, 5 và 1, 2, 3, 4, 5","1, 3, 5, 2, 4 và 1, 2, 3, 4, 5"],"a":0},{"id":"nb2","type":"mcq","q":"Thuật toán sắp xếp nổi bọt sắp xếp danh sách bằng cách:","k":"<b>C</b>. Nổi bọt so sánh và <b>hoán đổi các phần tử liền kề</b> nếu chúng không đúng thứ tự.","o":["Chọn phần tử có giá trị bé nhất đặt vào đầu danh sách.","Chọn phần tử có giá trị lớn nhất đặt vào đầu danh sách.","Hoán đổi nhiều lần các phần tử liền kề nếu giá trị của chúng không đúng thứ tự.","Chèn phần tử vào vị trí thích hợp để đảm bảo danh sách sắp xếp theo đúng thứ tự."],"a":2},{"id":"ch1","type":"sort","q":"Sắp xếp chọn dãy 3, 4, 1, 5, 2 (Hình 16.5). Sau vòng lặp thứ nhất được 1, 4, 3, 5, 2. Ở các vòng lặp thứ 2, 3, 4, mỗi lần so sánh dưới đây có hoán đổi hay không?","k":"Vòng 2: 3 &lt; 4 hoán đổi → 1 3 4 5 2; 5 không; 2 &lt; 3 hoán đổi → <b>1 2 4 5 3</b>. Vòng 3: 5 không; 3 &lt; 4 hoán đổi → <b>1 2 3 5 4</b>. Vòng 4: 4 &lt; 5 hoán đổi → <b>1 2 3 4 5</b>.","cats":["Hoán đổi","Không hoán đổi"],"items":[["Vòng 2: so sánh 3 (vị trí 3) với 4 (vị trí 2)",0],["Vòng 2: so sánh 5 (vị trí 4) với 3 (vị trí 2)",1],["Vòng 2: so sánh 2 (vị trí 5) với 3 (vị trí 2)",0],["Vòng 3: so sánh 5 (vị trí 4) với 4 (vị trí 3)",1],["Vòng 3: so sánh 3 (vị trí 5) với 4 (vị trí 3)",0],["Vòng 4: so sánh 4 (vị trí 5) với 5 (vị trí 4)",0]]},{"id":"hd2a","type":"mcq","q":"Năm bạn cầm các số 41, 15, 17, 32, 18. Bạn thứ sáu sắp xếp chọn theo thứ tự tăng dần. Kết quả sau vòng lặp thứ nhất là:","k":"Xét vị trí đầu (41): 15 &lt; 41 → hoán đổi (15 41 17 32 18); 17, 32, 18 đều không nhỏ hơn 15. Kết quả: <b>15, 41, 17, 32, 18</b>.","o":["15, 41, 17, 32, 18","15, 17, 18, 32, 41","41, 15, 17, 32, 18","15, 17, 41, 32, 18"],"a":0},{"id":"hd2","type":"open","q":"Ghi kết quả sau mỗi vòng lặp khi sắp xếp chọn dãy 41, 15, 17, 32, 18 theo thứ tự tăng dần. Có tất cả bao nhiêu lần hoán đổi?","k":"Vòng 1: 15 41 17 32 18. Vòng 2: 15 17 41 32 18. Vòng 3: 15 17 18 41 32. Vòng 4: <b>15 17 18 32 41</b>. Có <b>5</b> lần hoán đổi.","label":"HĐ2 – Sắp xếp chọn"},{"id":"ss","type":"sort","q":"Mỗi ý dưới đây đúng với thuật toán nào?","k":"Nổi bọt: so sánh <b>cặp liền kề</b>, từ cuối dãy lên. Chọn: so sánh <b>vị trí đang xét</b> với từng phần tử phía sau. Cả hai đều lặp lại việc <b>hoán đổi</b> và sau vòng k thì phần tử nhỏ thứ k về đúng chỗ.","cats":["Nổi bọt","Chọn","Cả hai"],"items":[["So sánh hai phần tử đứng cạnh nhau (liền kề)",0],["So sánh phần tử ở vị trí đang xét với từng phần tử phía sau nó",1],["Thực hiện nhiều lần một việc đơn giản: hoán đổi giá trị hai phần tử",2],["Sau vòng lặp thứ k, phần tử nhỏ thứ k ở đúng vị trí k",2],["Các cặp được so sánh theo thứ tự từ cuối dãy lên",0]]},{"id":"chia","type":"mcq","q":"Tại sao chúng ta chia bài toán thành những bài toán nhỏ hơn?","k":"<b>C</b>. Chia bài toán thành những bài toán nhỏ hơn giúp thuật toán <b>dễ hiểu</b> và <b>dễ thực hiện</b> hơn.","o":["Để thay đổi đầu vào của bài toán.","Để thay đổi yêu cầu đầu ra của bài toán.","Để bài toán dễ giải quyết hơn.","Để bài toán khó giải quyết hơn."],"a":2},{"id":"lt1","type":"mcq","q":"Sắp xếp nổi bọt dãy 3, 2, 4, 1, 5 theo thứ tự tăng dần. Kết quả sau vòng lặp thứ nhất và thứ hai lần lượt là:","k":"Vòng 1: 5 &lt; 1? Không; 1 &lt; 4 đổi; 1 &lt; 2 đổi; 1 &lt; 3 đổi → <b>1 3 2 4 5</b>. Vòng 2: 2 &lt; 3 đổi → <b>1 2 3 4 5</b>. Vòng 3, 4 không hoán đổi. Tổng 4 lần hoán đổi.","o":["1, 3, 2, 4, 5 và 1, 2, 3, 4, 5","2, 3, 1, 4, 5 và 2, 1, 3, 4, 5","1, 2, 3, 4, 5 và 1, 2, 3, 4, 5","3, 2, 1, 4, 5 và 1, 2, 3, 4, 5"],"a":0},{"id":"lt2","type":"mcq","q":"Sắp xếp chọn dãy 3, 2, 4, 1, 5 theo thứ tự tăng dần. Kết quả sau vòng lặp thứ nhất và thứ hai lần lượt là:","k":"Vòng 1 (vị trí 1 = 3): 2 &lt; 3 đổi → 2 3 4 1 5; 1 &lt; 2 đổi → <b>1 3 4 2 5</b>. Vòng 2 (vị trí 2 = 3): 2 &lt; 3 đổi → <b>1 2 4 3 5</b>. Vòng 3: 3 &lt; 4 đổi → 1 2 3 4 5. Vòng 4 không đổi.","o":["1, 3, 4, 2, 5 và 1, 2, 4, 3, 5","1, 2, 4, 3, 5 và 1, 2, 3, 4, 5","2, 3, 4, 1, 5 và 1, 3, 4, 2, 5","1, 3, 2, 4, 5 và 1, 2, 3, 4, 5"],"a":0},{"id":"vd1","type":"open","q":"Ghi lại điểm học tập môn Tin học của các bạn trong tổ. Thực hiện sắp xếp chọn hoặc sắp xếp nổi bọt để sắp xếp điểm theo thứ tự giảm dần, rồi cho biết danh sách tên các bạn tương ứng.","k":"Sắp xếp <b>giảm dần</b> thì đổi điều kiện: hoán đổi khi phần tử được xét <b>lớn hơn</b>. Khi hoán đổi điểm phải đổi chỗ <b>cả tên</b> đi kèm, để mỗi điểm vẫn đúng với bạn của mình.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Sắp xếp nổi bọt</b> là thuật toán sắp xếp được thực hiện bằng cách <b>hoán đổi nhiều lần các phần tử liền kề</b> nếu giá trị của chúng không đúng thứ tự.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Sắp xếp chọn</b> xét từng vị trí từ đầu đến cuối dãy, so sánh trực tiếp phần tử ở vị trí được xét với những phần tử ở phía sau nó và <b>hoán đổi</b> nếu chúng chưa đúng thứ tự.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Chia một bài toán thành những bài toán nhỏ hơn</b> giúp thuật toán dễ hiểu và dễ thực hiện hơn.</li><li>Ví dụ: sắp xếp = nhiều lần hoán đổi hai phần tử; tìm kiếm nhị phân = tìm trong nửa dãy.</li></ul>"}]},"tin7-thuat-toan-tim-kiem-nhi-phan":{"id":"tin7-bai15","ten":"Bài 15. Thuật toán tìm kiếm nhị phân","cau":[{"id":"kd1","type":"open","q":"Việc kinh doanh mở rộng, số lượng khách hàng của cửa hàng bán giống cây trồng nhà An lên đến hàng trăm người. Việc tìm kiếm tên khách hàng trong danh sách trở thật khó khăn. Em có gợi ý gì cho bạn An để việc tìm kiếm được dễ dàng hơn không?","k":"<b>Sắp xếp</b> danh sách khách hàng theo thứ tự chữ cái của tên (như danh bạ, từ điển). Khi đó không cần xem từ đầu: mở ở giữa, so sánh rồi chỉ tìm tiếp ở nửa trước hoặc nửa sau → tìm nhanh hơn nhiều.","label":"Mở đầu"},{"id":"hd1a","type":"mcq","q":"Thuật toán tìm kiếm tuần tự phải thực hiện bao nhiêu bước lặp để tìm được khách hàng tên “Trúc” trong danh sách ở Hình 15.1? So sánh với số bước lặp của thuật toán tìm kiếm nhị phân.","k":"“Trúc” ở vị trí 8 nên tìm kiếm tuần tự cần <b>8 bước lặp</b>; tìm kiếm nhị phân chỉ cần <b>3 bước lặp</b> (vị trí giữa lần lượt là 5 – Mai, 7 – Trang, 8 – Trúc).","o":["Tuần tự 3 bước, nhị phân 8 bước.","Tuần tự 8 bước, nhị phân 3 bước.","Cả hai đều 8 bước.","Cả hai đều 3 bước."],"a":1},{"id":"hd1b","type":"mcq","q":"Trước khi thực hiện thuật toán tìm kiếm nhị phân, danh sách khách hàng cần thoả mãn điều kiện gì? Nếu không thoả mãn điều kiện đó thì sao?","k":"Danh sách phải <b>được sắp xếp</b>. Nếu chưa sắp xếp thì không thể biết giá trị cần tìm nằm ở nửa trước hay nửa sau, nên <b>không thực hiện được</b> tìm kiếm nhị phân.","o":["Không cần điều kiện gì.","Danh sách phải được sắp xếp (theo thứ tự chữ cái của tên); nếu chưa sắp xếp thì không thực hiện được thuật toán tìm kiếm nhị phân.","Danh sách phải có đúng 9 khách hàng.","Danh sách phải có số điện thoại."],"a":1},{"id":"vung","type":"sort","q":"Đọc mô tả thuật toán bằng ngôn ngữ tự nhiên (SGK trang 76). Tìm “Trúc” trong danh sách Hình 15.1: sau mỗi lần so sánh, vùng tìm kiếm mới là nửa trước hay nửa sau?","k":"“T” đứng sau “M” → <b>nửa sau</b> (vị trí 6–9); “Tru” đứng sau “Tra” → <b>nửa sau</b> (vị trí 8–9); hai giá trị bằng nhau → <b>tìm thấy</b>, kết thúc.","cats":["Nửa trước","Nửa sau","Tìm thấy, kết thúc"],"items":[["So sánh “Trúc” với “Mai” (vị trí 5)",1],["So sánh “Trúc” với “Trang” (vị trí 7)",1],["So sánh “Trúc” với “Trúc” (vị trí 8)",2]]},{"id":"nn","type":"order","q":"Sắp xếp các bước của thuật toán tìm kiếm nhị phân (dùng nút ↑ ↓).","k":"Bước 1 (b) → Bước 2 (e) → Bước 3 (a) → Bước 4 (c) → Bước 5 (d). Vị trí giữa = phần nguyên của (vị trí đầu + vị trí cuối)/2.","items":{"a":"Nếu giá trị cần tìm bằng giá trị ở vị trí giữa thì kết luận tìm thấy tại vị trí giữa và kết thúc.","b":"Nếu vùng tìm kiếm không có phần tử nào thì kết luận không tìm thấy và kết thúc.","c":"Nếu giá trị cần tìm nhỏ hơn giá trị ở vị trí giữa thì vùng tìm kiếm mới chỉ còn nửa trước, ngược lại chỉ còn nửa sau.","d":"Lặp lại các bước trên cho đến khi tìm thấy hoặc vùng tìm kiếm không còn phần tử nào.","e":"Xác định vị trí ở giữa của vùng tìm kiếm."},"ans":["b","e","a","c","d"],"start":["a","b","c","d","e"]},{"id":"p76","type":"mcq","q":"Viết các bước lặp thực hiện thuật toán tìm kiếm nhị phân để tìm khách hàng tên “Hoà” trong danh sách ở Hình 15.1. Các vị trí giữa lần lượt được xét là:","k":"Lặp 1: vùng 1–9, giữa 5 (Mai): Hoà đứng trước Mai → nửa trước 1–4. Lặp 2: giữa 2 (Bình): Hoà đứng sau Bình → nửa sau 3–4. Lặp 3: giữa 3 (Hoà): bằng nhau → <b>tìm thấy ở vị trí 3</b>.","o":["5 (Mai) → 2 (Bình) → 3 (Hoà): tìm thấy sau 3 bước lặp.","5 (Mai) → 7 (Trang) → 8 (Trúc): không tìm thấy.","1 → 2 → 3: tìm thấy sau 3 bước lặp.","5 (Mai) → 3 (Hoà): tìm thấy sau 2 bước lặp."],"a":0},{"id":"khong","type":"mcq","q":"Với danh sách 9 khách hàng ở Hình 15.1, nếu tìm một khách hàng không có tên trong danh sách thì:","k":"Tuần tự phải xét <b>hết 9</b> khách hàng; nhị phân mỗi bước loại đi một nửa nên chỉ mất <b>4 bước lặp</b>. Nhờ danh sách đã được sắp xếp, tìm kiếm nhị phân thu hẹp được phạm vi tìm kiếm chỉ còn một nửa sau mỗi bước.","o":["Tìm kiếm tuần tự cần 9 bước lặp, tìm kiếm nhị phân chỉ mất 4 bước lặp.","Cả hai cần 9 bước lặp.","Tìm kiếm nhị phân cần nhiều bước hơn.","Không thuật toán nào kết luận được."],"a":0},{"id":"hd2","type":"open","q":"Chơi trò chơi tìm số (trên bảng mô phỏng hoặc với bạn cùng bàn). Sau một số ván, em thấy cần nhiều nhất bao nhiêu lượt lật thẻ để tìm được một số trong 10 tấm thẻ? Vì sao?","k":"Nhiều nhất <b>4 lượt</b> (10 → 5 → 2 → 1 thẻ), vì mỗi lượt loại bỏ được khoảng một nửa số thẻ còn lại. Nếu tìm lần lượt từng thẻ thì có thể phải lật cả 10 thẻ.","label":"HĐ2 – Trò chơi tìm số"},{"id":"p77","type":"open","q":"Em hãy nêu ví dụ trong thực tế cho thấy mối liên quan giữa sắp xếp và tìm kiếm.","k":"Ví dụ: <b>từ điển</b> sắp xếp theo thứ tự chữ cái nên tra từ nhanh; <b>danh bạ điện thoại</b>; danh sách học sinh theo tên; sách trong thư viện xếp theo mã; số nhà trên một con phố (chẵn, lẻ tăng dần).","label":"Câu hỏi tr.77"},{"id":"lt1a","type":"order","q":"Sắp xếp danh sách tên các nước theo thứ tự trong bảng chữ cái (dùng nút ↑ ↓).","k":"Albania, Bolivia, Canada, Germany, Greenland, Iceland, Portugal, Scotland, Vietnam.","items":{"a":"Bolivia","b":"Albania","c":"Scotland","d":"Canada","e":"Vietnam","f":"Iceland","g":"Portugal","h":"Greenland","i":"Germany"},"ans":["b","a","d","i","h","f","g","c","e"],"start":["a","b","c","d","e","f","g","h","i"]},{"id":"lt1b","type":"mcq","q":"Liệt kê các bước lặp tìm kiếm tên nước “Iceland” trong danh sách đã sắp xếp theo thuật toán tìm kiếm nhị phân. Các vị trí giữa lần lượt là:","k":"Lặp 1: vùng 1–9, giữa 5 (Greenland): Iceland đứng sau → 6–9. Lặp 2: giữa 7 (Portugal): Iceland đứng trước → 6–6. Lặp 3: giữa 6 (Iceland): <b>tìm thấy</b>, sau <b>3 bước lặp</b>.","o":["5 (Greenland) → 7 (Portugal) → 6 (Iceland): tìm thấy sau 3 bước lặp.","5 (Greenland) → 6 (Iceland): tìm thấy sau 2 bước lặp.","1 → 2 → … → 6: tìm thấy sau 6 bước lặp.","5 (Greenland) → 2 (Bolivia): không tìm thấy."],"a":0},{"id":"lt1c","type":"mcq","q":"So sánh số bước lặp thực hiện tìm kiếm ở phần b với số bước lặp thực hiện tìm kiếm ở phần Luyện tập của Bài 14.","k":"Tìm kiếm nhị phân <b>3</b> bước lặp, tìm kiếm tuần tự (Bài 14) <b>6</b> bước lặp. Danh sách càng dài thì chênh lệch càng lớn.","o":["Nhị phân 3 bước, tuần tự 6 bước: nhị phân nhanh hơn.","Bằng nhau.","Tuần tự nhanh hơn.","Không so sánh được."],"a":0},{"id":"lt2","type":"open","q":"Em hãy chỉ ra một bài toán tìm kiếm trong thực tế mà có thể thực hiện bằng thuật toán tìm kiếm nhị phân. Hãy thực hiện thuật toán tìm kiếm nhị phân để giải quyết bài toán đó.","k":"Ví dụ: tìm số báo danh trong danh sách thi đã sắp xếp tăng dần; tìm trang sách có số trang cho trước; đoán số từ 1 đến 100 (mỗi lần hỏi lớn hơn hay bé hơn số ở giữa).","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Em tìm một từ tiếng Anh trong quyển từ điển theo cách nào? Tại sao em lại dùng cách đó?","k":"Mở khoảng giữa từ điển, so sánh chữ cái đầu với từ cần tìm rồi lật về phía trước hoặc phía sau, cứ thế thu hẹp phạm vi — giống <b>tìm kiếm nhị phân</b>. Dùng được vì từ điển đã <b>sắp xếp theo thứ tự chữ cái</b>, giúp tìm nhanh hơn nhiều so với lật từng trang.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Thuật toán tìm kiếm nhị phân</b> thực hiện trên danh sách <b>đã được sắp xếp</b> theo thứ tự từ nhỏ đến lớn. Bắt đầu từ vị trí ở giữa danh sách.</li><li>Tại mỗi bước lặp, so sánh giá trị cần tìm với giá trị ở vị trí giữa: nếu bằng thì dừng lại; nếu nhỏ hơn thì tìm trong <b>nửa trước</b>, nếu lớn hơn thì tìm trong <b>nửa sau</b> của danh sách.</li><li>Chừng nào chưa tìm thấy và vùng tìm kiếm còn phần tử thì còn tìm tiếp.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Vị trí giữa của vùng tìm kiếm = <b>phần nguyên của (vị trí đầu + vị trí cuối)/2</b>.</li><li>Trong trường hợp so sánh kí tự thì đứng trước tương ứng là “nhỏ hơn”, kí tự đứng sau trong bảng chữ cái là “lớn hơn”.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Sắp xếp</b> giúp cho việc tìm kiếm được thực hiện <b>nhanh hơn</b>.</li></ul>"}]},"tin7-thuat-toan-tim-kiem-tuan-tu":{"id":"tin7-bai14","ten":"Bài 14. Thuật toán tìm kiếm tuần tự","cau":[{"id":"kd1","type":"open","q":"Mẹ An ghi thông tin khách hàng (họ tên, địa chỉ, số điện thoại) trong cuốn sổ. Một khách hàng gọi điện đặt mua cây giống. Em sẽ giúp An tìm địa chỉ của khách hàng đó trong sổ như thế nào?","k":"Xem <b>lần lượt</b> từng khách hàng <b>từ đầu đến cuối</b> danh sách: nếu đúng họ tên cần tìm thì ghi ra địa chỉ và dừng; nếu đã hết danh sách mà không thấy thì báo không tìm thấy.","label":"Mở đầu"},{"id":"bt","type":"sort","q":"Đọc phần đầu mục Thuật toán tìm kiếm tuần tự. Với bài toán của An, mỗi thông tin dưới đây là đầu vào hay đầu ra?","k":"<b>Đầu vào</b>: danh sách khách hàng; họ tên khách hàng cần tìm. <b>Đầu ra</b>: địa chỉ của khách hàng cần tìm.","cats":["Đầu vào","Đầu ra"],"items":[["Danh sách khách hàng",0],["Họ tên khách hàng cần tìm",0],["Địa chỉ của khách hàng cần tìm",1]]},{"id":"dk","type":"sort","q":"Thuật toán tìm kiếm tuần tự dùng cấu trúc lặp. Mỗi câu hỏi dưới đây là điều kiện thứ nhất hay điều kiện thứ hai cần kiểm tra?","k":"Điều kiện thứ nhất: kiểm tra họ tên khách hàng có <b>đúng là họ tên cần tìm</b> không. Điều kiện thứ hai: kiểm tra <b>đã hết danh sách</b> chưa. Chừng nào chưa tìm thấy và chưa hết danh sách thì còn tìm tiếp.","cats":["Điều kiện thứ nhất","Điều kiện thứ hai"],"items":[["Họ tên khách hàng có đúng là họ tên cần tìm không?",0],["Đã hết danh sách chưa?",1]]},{"id":"hd1","type":"sort","q":"Thực hiện thuật toán tìm kiếm tuần tự để tìm địa chỉ của khách hàng “Thanh Trúc” trong Bảng 14.1. Ở mỗi lần lặp, câu trả lời cho các câu hỏi dưới đây là Đúng hay Sai? (Kiểm tra lại bằng bảng mô phỏng.)","k":"Lần lặp 1, 2, 3: cả hai câu đều <b>Sai</b> nên xem khách hàng tiếp theo. Lần lặp 4: Thanh Trúc là khách hàng cần tìm (<b>Đúng</b>) → ghi ra địa chỉ <b>Xóm 2, Lục Xuân</b>; kết thúc (không cần kiểm tra điều kiện thứ hai).","cats":["Đúng","Sai"],"items":[["Lần lặp 1 – Nguyễn An: có đúng khách hàng cần tìm không?",1],["Lần lặp 1: có đúng là đã hết danh sách không?",1],["Lần lặp 2 – Trần Bình: có đúng khách hàng cần tìm không?",1],["Lần lặp 2: có đúng là đã hết danh sách không?",1],["Lần lặp 3 – Hoàng Mai: có đúng khách hàng cần tìm không?",1],["Lần lặp 3: có đúng là đã hết danh sách không?",1],["Lần lặp 4 – Thanh Trúc: có đúng khách hàng cần tìm không?",0]]},{"id":"hd1b","type":"mcq","q":"Thuật toán tìm được địa chỉ của khách hàng “Thanh Trúc” sau bao nhiêu lần lặp, địa chỉ là gì?","k":"<b>4 lần lặp</b>, địa chỉ <b>Xóm 2, Lục Xuân</b> (Thanh Trúc ở vị trí 4 của danh sách).","o":["Sau 1 lần lặp; Số 48 đường Trưng Vương.","Sau 4 lần lặp; Xóm 2, Lục Xuân.","Sau 5 lần lặp; Số 69 đường Ngô Quyền.","Không tìm thấy."],"a":1},{"id":"nn","type":"order","q":"Sắp xếp các bước của thuật toán tìm kiếm tuần tự mô tả bằng ngôn ngữ tự nhiên (dùng nút ↑ ↓).","k":"Bước 1 (b) → Bước 2 (a) → Bước 3 (d) → Bước 4 (e) → Bước 5 (c).","items":{"a":"Nếu giá trị ở vị trí đang xét bằng giá trị cần tìm thì chuyển sang bước trả lời “Tìm thấy”, nếu không thì chuyển đến vị trí tiếp theo.","b":"Xét vị trí đầu tiên của danh sách.","c":"Trả lời “Không tìm thấy”; Kết thúc.","d":"Kiểm tra đã hết danh sách chưa. Nếu đã hết thì chuyển sang bước trả lời “Không tìm thấy”, nếu chưa thì lặp lại bước so sánh.","e":"Trả lời “Tìm thấy” và chỉ ra vị trí phần tử tìm được; Kết thúc."},"ans":["b","a","d","e","c"],"start":["a","b","c","d","e"]},{"id":"p73a","type":"mcq","q":"Thuật toán tìm kiếm tuần tự thực hiện công việc gì?","k":"<b>D</b>. Tìm kiếm một dữ liệu cho trước trong một danh sách đã cho.","o":["Lưu trữ dữ liệu.","Sắp xếp dữ liệu theo chiều tăng dần.","Xử lí dữ liệu.","Tìm kiếm một dữ liệu cho trước trong một danh sách đã cho."],"a":3},{"id":"p73b","type":"mcq","q":"Thuật toán tìm kiếm tuần tự thực hiện công việc như thế nào?","k":"<b>B</b>. Thuật toán tìm kiếm tuần tự thực hiện tìm lần lượt từ đầu đến cuối danh sách, chừng nào chưa tìm thấy và chưa hết danh sách thì còn tìm tiếp.","o":["Sắp xếp lại dữ liệu theo thứ tự của bảng chữ cái.","Xem xét mục dữ liệu đầu tiên, sau đó xem xét lần lượt từng mục dữ liệu tiếp theo cho đến khi tìm thấy mục dữ liệu được yêu cầu hoặc đến khi hết danh sách.","Chia nhỏ dữ liệu thành từng phần để tìm kiếm.","Bắt đầu tìm từ vị trí bất kì của danh sách."],"a":1},{"id":"lt1","type":"mcq","q":"Danh sách: Bolivia, Albania, Scotland, Canada, Vietnam, Iceland, Portugal, Greenland, Germany. Thực hiện thuật toán tìm kiếm tuần tự để tìm “Iceland”. Đầu ra và số lần lặp là:","k":"Lần lặp 1–5 (Bolivia, Albania, Scotland, Canada, Vietnam): Sai, Sai. Lần lặp 6: <b>Iceland</b> – Đúng → đầu ra “<b>Tìm thấy</b>” ở <b>vị trí 6</b>.","o":["Tìm thấy ở vị trí 1, sau 1 lần lặp.","Tìm thấy ở vị trí 6, sau 6 lần lặp.","Tìm thấy ở vị trí 6, sau 9 lần lặp.","Không tìm thấy, sau 9 lần lặp."],"a":1},{"id":"lt2","type":"mcq","q":"Với cùng danh sách trên, nếu tìm “Japan” thì thuật toán dừng lại khi nào và đầu ra là gì?","k":"Phải xét <b>hết cả 9 nước</b>; ở lần lặp 9 (Germany) câu “đã hết danh sách?” là Đúng → đầu ra “<b>Không tìm thấy</b>”.","o":["Dừng ở lần lặp 1, Không tìm thấy.","Dừng sau khi xét hết 9 nước (9 lần lặp), Không tìm thấy.","Dừng ở lần lặp 5, Tìm thấy.","Không bao giờ dừng."],"a":1},{"id":"vd1","type":"open","q":"Em hãy lập danh sách những cuốn sách mà em có. Sau đó sử dụng thuật toán tìm kiếm tuần tự để tìm một cuốn sách trong danh sách đó (thử trên bảng mô phỏng ở phần Vận dụng). Em tìm cuốn sách nào, sau mấy lần lặp thì tìm thấy?","k":"Học sinh tự làm. Ví dụ danh sách 6 cuốn, tìm cuốn ở vị trí 4 thì sau 4 lần lặp tìm thấy; tìm cuốn không có trong danh sách thì phải xét hết 6 cuốn mới biết là không tìm thấy.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Thuật toán tìm kiếm tuần tự</b> thực hiện tìm <b>lần lượt từ đầu đến cuối</b> danh sách, chừng nào <b>chưa tìm thấy</b> và <b>chưa hết danh sách</b> thì còn tìm tiếp.</li><li>Hai điều kiện cần kiểm tra để dừng vòng lặp: đúng giá trị cần tìm chưa; đã hết danh sách chưa.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Bước 1. Xét vị trí đầu tiên. Bước 2. Nếu bằng giá trị cần tìm → Bước 4; nếu không → vị trí tiếp theo. Bước 3. Hết danh sách → Bước 5; chưa hết → lặp lại Bước 2. Bước 4. “Tìm thấy”, chỉ ra vị trí; kết thúc. Bước 5. “Không tìm thấy”; kết thúc.</li></ul>"}]},"tin7-tinh-toan-tu-dong":{"id":"tin7-bai7","ten":"Bài 7. Tính toán tự động trên bảng tính","cau":[{"id":"kd1","type":"open","q":"Bài trước em đã biết nhập dữ liệu dạng số, văn bản và thời gian vào bảng tính. Có thể nhập dữ liệu là công thức tính toán được không? Khi thực hiện dự án Trường học xanh, em cần tính toán những gì?","k":"<b>Có.</b> Phần mềm bảng tính cho phép nhập <b>công thức</b> (bắt đầu bằng dấu =) để tính toán. Dự án cần tính: số lượng cây mỗi loại, tổng số cây, chi phí mua cây,…","label":"Mở đầu"},{"id":"hd1a","type":"open","q":"Quan sát các ô dữ liệu, vùng nhập dữ liệu (có hình ngôi sao) trong Hình 7.1, Hình 7.2. Bảng tính điện tử nhận biết được các kiểu dữ liệu nào?","k":"<b>Văn bản</b> (Nguyễn Văn Hùng, Hải Phòng), <b>số</b> (8.5, 9), <b>ngày tháng</b> (3/5/2010) và <b>công thức</b> (= 2 + 1.5 + 2.5).","label":"HĐ1 – Câu 1"},{"id":"kieu","type":"sort","q":"Các kiểu dữ liệu được thể hiện thế nào trên bảng tính? Xếp mỗi dữ liệu nhập vào ô dưới đây theo kiểu của nó (có thể nhập thử vào bảng mô phỏng).","k":"Văn bản căn trái; số, ngày tháng căn phải. <b>Công thức luôn bắt đầu bằng dấu “=”</b>, sau đó là biểu thức; ô hiện <b>kết quả</b>, vùng nhập dữ liệu hiện <b>công thức</b>.","cats":["Văn bản","Số","Ngày tháng","Công thức"],"items":[["Nguyễn Văn Hùng",0],["8.5",1],["3/5/2010",2],["= 2 + 1.5 + 2.5",3],["Hải Phòng",0],["9",1],["=C4*D4",3]]},{"id":"kihieu","type":"mcq","q":"Biểu thức toán học 5³ × 2 : 4 được viết trong phần mềm bảng tính là:","k":"<b>=5^3*2/4</b>. Trong bảng tính: nhân <b>*</b>, chia <b>/</b>, luỹ thừa <b>^</b>; công thức bắt đầu bằng <b>=</b>.","o":["=5³×2:4","=5^3*2/4","5^3*2/4","=5*3*2:4"],"a":1},{"id":"p35","type":"sort","q":"Trong phần mềm bảng tính, những công thức tính nào dưới đây sai? Vì sao? (Thử nhập vào bảng mô phỏng.)","k":"<b>B sai</b>: thừa một dấu ngoặc đóng. <b>C sai</b>: thiếu dấu nhân, phải viết = 2*(3 + 4). A, D đúng.","cats":["Đúng","Sai"],"items":[["A. = 5^2 + 6*101",0],["B. = 6*(3 + 2))",1],["C. = 2(3 + 4)",1],["D. = 1^2 + 2^2",0]]},{"id":"hd2","type":"open","q":"Nếu nhập công thức vào một ô tính và tính toán với giá trị nằm ở các ô khác thì phải làm thế nào?","k":"Trong công thức, ghi <b>địa chỉ của các ô</b> chứa dữ liệu thay cho giá trị. Ví dụ ô E4 nhập <b>=C4*D4</b> thay vì =25*10.","label":"HĐ2 – Nhập công thức"},{"id":"cach","type":"mcq","q":"Ô E4 có công thức =25*10 (cách 1), ô E5 có công thức =C5*D5 (cách 2). Nếu sửa số lượng cây ở ô D4 và D5 thì:","k":"<b>Chỉ E5</b> (cách 2, dùng địa chỉ ô) được <b>tính toán tự động</b> khi dữ liệu thay đổi. Cách 1 dùng giá trị cố định nên không cập nhật.","o":["Cả E4 và E5 đều tự động cập nhật.","Chỉ E5 tự động cập nhật; E4 vẫn giữ kết quả cũ.","Chỉ E4 tự động cập nhật.","Không ô nào cập nhật."],"a":1},{"id":"p36a","type":"mcq","q":"Hình 7.5: độ dài AB, BC, CA ở các ô C3, C4, C5. Công thức cần nhập tại ô C6 để tính nửa chu vi tam giác ABC là:","k":"<b>=(C3+C4+C5)/2</b>. A sai vì chỉ chia C5 cho 2; C thiếu dấu =; D tính đúng nhưng không tự động cập nhật khi đổi số liệu.","o":["=C3+C4+C5/2","=(C3+C4+C5)/2","(C3+C4+C5)/2","=(15+10+12)/2"],"a":1},{"id":"p36b","type":"open","q":"Hình 7.6: bán kính R ở ô C3, số PI ở ô C4. Em nhập công thức gì vào ô C5 (chu vi) và ô C6 (diện tích) hình tròn?","k":"C5: <b>=2*C4*C3</b> (chu vi = 2πR). C6: <b>=C4*C3^2</b> (diện tích = πR²).","label":"Câu hỏi tr.36 – Hình 7.6"},{"id":"hd3a","type":"open","q":"Khi sao chép ô tính chứa công thức hoặc vùng có chứa công thức thì các công thức này sẽ được sao chép như thế nào?","k":"Các <b>địa chỉ</b> trong công thức <b>được điều chỉnh</b> để giữ nguyên vị trí tương đối giữa ô chứa công thức và ô có địa chỉ trong công thức. Ví dụ =C4*D4 ở E4 sao chép xuống E6 thành <b>=C6*D6</b>.","label":"HĐ3 – Câu 1"},{"id":"hd3b","type":"open","q":"Chức năng tính toán tự động của công thức có được bảo toàn hay không khi sao chép dữ liệu? Nếu có thì được thể hiện như thế nào?","k":"<b>Có.</b> Công thức sau khi sao chép vẫn tham chiếu tới các ô tương ứng, nên khi dữ liệu ở các ô đó thay đổi thì kết quả tự động cập nhật.","label":"HĐ3 – Câu 2"},{"id":"p37a","type":"mcq","q":"Nếu sao chép công thức =C4*D4 từ ô E4 sang ô E10 thì công thức tại ô E10 là gì?","k":"<b>=C10*D10</b>: dịch xuống 6 hàng nên các địa chỉ cũng tăng 6 hàng.","o":["=C4*D4","=C10*D10","=C6*D6","=E10*E10"],"a":1},{"id":"p37b","type":"mcq","q":"Giả sử tại ô G10 có công thức =H10 + 2*K10. Nếu sao chép công thức này đến ô G12 thì công thức sẽ thay đổi như thế nào?","k":"<b>=H12 + 2*K12</b>: cùng cột, xuống 2 hàng → địa chỉ tăng 2 hàng; số 2 trong công thức giữ nguyên.","o":["=H10 + 2*K10","=H12 + 2*K12","=J10 + 2*M10","=H12 + 4*K12"],"a":1},{"id":"nv1","type":"order","q":"Sắp xếp các bước thực hành (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → a → d → e → c</b>.","items":{"a":"Nhập =C4*D4 vào E4, sao chép xuống E5, E6.","b":"Mở tệp THXanh.xlsx, tạo trang tính mới tên 2. Dự kiến số lượng cây, nhập dữ liệu.","c":"Lưu lại kết quả.","d":"Nhập =E4+E5+E6 vào E7.","e":"Định dạng A2 và hàng 3 chữ đậm, nền vàng; căn giữa cột STT; chỉnh độ rộng cột."},"ans":["b","a","d","e","c"],"start":["a","b","c","d","e"]},{"id":"nvkq","type":"open","q":"Báo cáo kết quả: các ô E4, E5, E6, E7 có công thức gì và kết quả bao nhiêu? Nếu đổi số lượng cây hoa ở D4 thành 12 thì những ô nào tự động thay đổi?","k":"E4 =C4*D4 → 250; E5 =C5*D5 → 100; E6 =C6*D6 → 150; E7 =E4+E5+E6 → 500. Đổi D4 = 12 thì <b>E4</b> (300) và <b>E7</b> (550) tự động cập nhật.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Tạo trang tính mới tên 3. Tìm hiểu giống cây, nhập danh sách các loại cây cụ thể và đơn giá như Hình 7.10, định dạng và lưu kết quả. Em đã định dạng những gì?","k":"Ví dụ: tiêu đề A2 chữ đậm; hàng 3 chữ đậm, nền vàng; cột STT căn giữa; chỉnh độ rộng cột cho đủ dữ liệu.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"mcq","q":"Nhập công thức =D4*E4 vào F4, sao chép F4 xuống các ô từ F5 đến F19. Công thức tại ô F19 là:","k":"<b>=D19*E19</b>: Thành tiền = Đơn giá × Số lượng của cùng hàng.","o":["=D4*E4","=D19*E19","=D19*E4","=F19*F19"],"a":1},{"id":"vd1","type":"open","q":"Phần mềm bảng tính mặc định căn phải dữ liệu là số và ngày tháng, căn trái dữ liệu là văn bản. Em có thể thay đổi lại cách căn lề của dữ liệu số, ngày tháng và văn bản được không? Nếu có thì bằng lệnh nào?","k":"<b>Có.</b> Chọn ô hoặc vùng, dùng các lệnh căn lề trong nhóm <b>Alignment</b> của thẻ <b>Home</b> (căn trái, căn giữa, căn phải).","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Tạo bảng tính mới như Hình 7.11, nhập công thức tính tổng diện tích rừng của tỉnh Tuyên Quang và sao chép công thức để tính cho các tỉnh còn lại. Lưu tệp với tên Dientichrung.xlsx. Em đã nhập công thức gì, ở ô nào?","k":"Nếu Tuyên Quang ở hàng 4, rừng tự nhiên cột B, rừng trồng cột C: nhập <b>=B4+C4</b> vào D4 (Tổng diện tích = 424.689), rồi sao chép D4 xuống D5:D8.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Dữ liệu trong ô tính có thể thuộc kiểu <b>văn bản, số, ngày tháng</b> và <b>công thức</b>.</li><li>Công thức luôn bắt đầu bằng dấu <b>“=”</b>, sau đó là biểu thức toán học.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Khi nhập công thức vào ô tính, nếu tính toán với giá trị từ các ô dữ liệu khác thì trong công thức cần ghi <b>địa chỉ của ô dữ liệu</b> tương ứng. Phần mềm bảng tính sẽ <b>tự động tính toán</b> và cập nhật kết quả nếu có thay đổi.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Khi sao chép một ô có công thức chứa địa chỉ, các địa chỉ được <b>điều chỉnh</b> để giữ nguyên <b>vị trí tương đối</b> giữa ô chứa công thức và ô có địa chỉ trong công thức.</li><li>Chức năng tính toán tự động của phần mềm bảng tính còn được thể hiện khi sao chép công thức.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Tạo trang tính mới: nháy nút <b>⊕</b> cạnh tên trang tính.</li><li>Sao chép công thức: chọn ô → <b>Ctrl+C</b> → chọn vùng đích → <b>Ctrl+V</b>.</li></ul>"}]},"tin7-trinh-bay-bang-tinh":{"id":"tin7-bai9","ten":"Bài 9. Trình bày bảng tính","cau":[{"id":"kd1","type":"open","q":"Quan sát một phần bảng tính của dự án Trường học xanh trong Hình 9.1, em có nhận xét gì? Có cần chỉnh sửa, định dạng hay trình bày dữ liệu cho đẹp hơn không?","k":"Cột Trung bình có số chữ số thập phân không đều (11.66666667), khó đọc; cột Chi phí là số tiền nhưng không có dấu phân tách hàng nghìn; cột Loại cây chỉ ghi ở một ô. <b>Cần định dạng, trình bày</b> lại cho dễ đọc, dễ so sánh.","label":"Mở đầu"},{"id":"hd1a","type":"open","q":"Cột dữ liệu Trung bình cần điều chỉnh gì để hiển thị dễ đọc, dễ so sánh hơn?","k":"Cho hiển thị <b>cùng một số chữ số thập phân</b> (ví dụ 1 hoặc 2 chữ số), ví dụ 11.67 thay cho 11.66666667.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Dữ liệu tại cột Chi phí nên trình bày lại như thế nào để phù hợp với dữ liệu là số tiền?","k":"Dùng <b>dấu phân tách hàng nghìn, hàng triệu</b> (ví dụ 1,400,000), không cần phần thập phân hoặc để 2 chữ số thập phân thống nhất.","label":"HĐ1 – Câu 2"},{"id":"so","type":"mcq","q":"Để ô hiển thị số 1400000 thành 1,400,000.00, em thực hiện:","k":"<b>B</b>. Mở cửa sổ <b>Format Cells</b> (mũi tên cạnh nhóm lệnh Number của thẻ Home), chọn <b>Number</b>, đặt số chữ số thập phân, đánh dấu <b>Use 1000 Separator (,)</b>.","o":["Gõ lại số có dấu phẩy vào ô.","Chọn ô, Home → mũi tên cạnh nhóm Number → Format Cells: Number, Decimal places = 2, chọn Use 1000 Separator → OK.","Chọn ô, nhấn Delete.","Home → Merge & Center."],"a":1},{"id":"pct","type":"mcq","q":"Ô E4 có giá trị 0.982142857 (= 55/56). Sau khi định dạng kiểu Percentage với 2 chữ số thập phân, ô E4 hiển thị:","k":"<b>98.21%</b>. Kiểu Percentage nhân giá trị với 100 và thêm dấu %; dữ liệu trong ô vẫn là 0.982142857.","o":["0.98","98.21%","0.98%","9821%"],"a":1},{"id":"ngay","type":"mcq","q":"Phần mềm nhập ngày theo khuôn dạng mm/dd/yyyy. Nếu muốn nhập ngày 15 tháng 3 năm 2021 rồi hiển thị theo kiểu Việt Nam (dd/mm/yyyy), em:","k":"<b>B</b>. Việc nhập vẫn theo thứ tự mặc định của phần mềm (tháng/ngày/năm); Format Cells chỉ thay đổi <b>cách hiển thị</b>. Gõ 15/3/2021 sẽ bị coi là văn bản (căn trái).","o":["Gõ 15/3/2021 là xong.","Gõ 3/15/2021, rồi Format Cells → Date → Locale Vietnamese, chọn kiểu ngày/tháng/năm → OK.","Gõ 2021/15/3.","Gõ “ngày 15 tháng 3”."],"a":1},{"id":"phep","type":"mcq","q":"Ô A3 là ngày 15/3/2021, ô B3 là ngày 31/3/2021 (kiểu Việt Nam). Công thức =B3-A3 cho kết quả:","k":"<b>16</b> (ngày). Ngày tháng cộng được với số nguyên (mỗi số là một ngày): 3/1/2020 + 30 = 2/2/2020; hai ngày trừ nhau ra số ngày.","o":["16","31/3/2021","#VALUE!","46"],"a":0},{"id":"hd2a","type":"open","q":"Theo em việc định dạng dữ liệu và trình bày bảng tính có khác nhau không?","k":"Khác nhau: <b>định dạng dữ liệu</b> là thay đổi cách hiển thị giá trị trong ô (số thập phân, phần trăm, ngày tháng, phông, màu); <b>trình bày bảng tính</b> là sắp xếp bố cục bảng: chèn, xoá, ẩn, hiện hàng cột, gộp ô,…","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Các lệnh trình bày bảng tính hay định dạng dữ liệu có làm thay đổi dữ liệu trên bảng tính không?","k":"Định dạng <b>không</b> làm thay đổi dữ liệu, chỉ đổi cách hiển thị. Lệnh ẩn hàng, cột không xoá dữ liệu. Nhưng <b>xoá</b> hàng, cột làm mất dữ liệu; <b>gộp ô</b> chỉ giữ dữ liệu ô đầu tiên bên trái, dữ liệu các ô khác bị xoá.","label":"HĐ2 – Câu 2"},{"id":"lenh","type":"sort","q":"Đọc mục 2 (SGK trang 48). Mỗi việc dưới đây dùng lệnh nào?","k":"<b>Insert</b> chèn (hàng mới ở trên, cột mới bên trái); <b>Delete</b> xoá; <b>Hide</b> ẩn; <b>Unhide</b> hiện lại (chọn các hàng, cột xung quanh vị trí bị ẩn); <b>Merge &amp; Center</b> gộp ô và căn giữa (Home → Alignment).","cats":["Insert","Delete","Hide","Unhide","Merge & Center"],"items":[["Thêm một cột Đơn giá vào bên trái cột 7A",0],["Bỏ hẳn hàng chứa loại cây không trồng nữa",1],["Tạm che các cột 7A–7H cho bảng gọn khi trình chiếu",2],["Cho hiển thị lại các cột đã che",3],["Ghi chữ “Cây hoa” ở giữa vùng B4:B8",4]]},{"id":"gop","type":"mcq","q":"Ô A2 chứa 120, ô B2, A3, B3 chứa dữ liệu khác. Sau khi gộp vùng A2:B3 thì:","k":"<b>B</b>. Ô kết quả có địa chỉ là <b>ô đầu tiên bên trái</b> của vùng (A2) và lưu kết quả của ô này; dữ liệu trong các ô khác bị xoá.","o":["Ô gộp có địa chỉ B3, giữ dữ liệu của cả 4 ô.","Ô gộp có địa chỉ A2, chỉ giữ 120; dữ liệu các ô khác bị xoá.","Ô gộp không có địa chỉ.","Dữ liệu 4 ô được cộng lại."],"a":1},{"id":"hd3","type":"open","q":"Bảng Hình 9.12 có ô ghi số, “Không”, “Đang làm”, “???” hoặc để trống. Cột J tính Tổng số cây theo từng loại, hàng 9 đếm số loại cây đã trồng của mỗi lớp. Các kết quả của bảng dữ liệu này có luôn đúng hay không? Vì sao?","k":"<b>Luôn đúng</b>, vì các hàm SUM, AVERAGE, COUNT, MIN, MAX chỉ tính trên các ô chứa <b>dữ liệu số</b>, <b>bỏ qua</b> các ô chứa văn bản hoặc ô trống. Khi lớp nhập số liệu thật thay cho “???”, “Đang làm” thì kết quả tự cập nhật.","label":"HĐ3 – Tính chất của hàm"},{"id":"p49","type":"sort","q":"Trong bảng dữ liệu của Hình 9.12 các hàm sau sẽ cho kết quả bao nhiêu? (Nhập thử vào bảng mô phỏng.)","k":"a) <b>3</b> (16, 12, 10); b) <b>15</b> = (20 + 12 + 13) : 3; c) <b>20</b>; d) <b>190</b> = 49 + 35 + 38 + 45 + 23.","cats":["3","15","20","190"],"items":[["a) =COUNT(C6:I6)",0],["b) =AVERAGE(C7:I7)",1],["c) =MAX(C4:I8)",2],["d) =SUM(C4:I8)",3]]},{"id":"nv1","type":"order","q":"Sắp xếp các bước thực hành (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → a → d → c</b>.","items":{"a":"Chèn cột D, đặt tiêu đề Đơn giá, sao chép đơn giá từ trang tính 3.","b":"Tạo trang tính 5. Tổng kết, sao chép dữ liệu trang tính 4, sửa tên bảng ở A2.","c":"Định dạng trang tính và lưu kết quả.","d":"Tạo cột Chi phí (N), nhập công thức Chi phí = Đơn giá × Tổng số cây, tính tổng chi phí."},"ans":["b","a","d","c"],"start":["a","b","c","d"]},{"id":"nv2","type":"mcq","q":"Sau khi chèn cột D (Đơn giá), cột Tổng số cây chuyển sang cột L. Công thức tính Chi phí của Hoa Mười giờ tại ô N4 là:","k":"<b>=D4*L4</b> (Đơn giá × Tổng số cây), rồi sao chép xuống các hàng cây khác.","o":["=D4*K4","=D4*L4","=D4+L4","=SUM(D4:L4)"],"a":1},{"id":"nvkq","type":"open","q":"Báo cáo kết quả: chi phí cây hoa, cây ăn quả, cây bóng mát và tổng chi phí toàn bộ dự án là bao nhiêu? Em đã định dạng cột Chi phí như thế nào?","k":"Cây hoa <b>9,371,000</b>; cây ăn quả <b>10,359,000</b>; cây bóng mát <b>10,962,200</b>; tổng <b>30,692,200</b> đồng. Cột Chi phí định dạng Number, có dấu phân tách hàng nghìn (có thể 0 hoặc 2 chữ số thập phân).","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Có thể sao chép công thức từ trang tính này sang trang tính khác được không?","k":"<b>Có.</b> Chọn ô chứa công thức, Ctrl+C, chuyển sang trang tính khác, chọn ô đích, Ctrl+V. Địa chỉ trong công thức được điều chỉnh tương đối và tham chiếu tới các ô trên trang tính mới.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"mcq","q":"Phần mềm bảng tính điện tử có thể gộp các ô trong một vùng không là hình chữ nhật không?","k":"<b>Không.</b> Vùng dữ liệu luôn là hình chữ nhật nên ô gộp cũng là hình chữ nhật.","o":["Có.","Không, vùng được gộp luôn là hình chữ nhật."],"a":1},{"id":"vd1","type":"open","q":"Quan sát Bảng 5. Dự kiến phân bổ cây dự án Trường học xanh ở Hình 9.13 và trả lời: a) Tổng số cây của toàn bộ khối 7 sẽ trồng là bao nhiêu? b) Trung bình mỗi lớp sẽ trồng bao nhiêu cây?","k":"a) <b>623</b> cây (ô L25 sau khi chèn cột). b) <b>89</b> cây (ô M25, hoặc =AVERAGE(E25:K25)).","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Giả sử chỉ tiêu trồng mỗi loại cây hoa là 50. Dựa trên Bảng 5, hãy tính tỉ lệ phần trăm của từng loại cây hoa được phân bổ so với chỉ tiêu đã giao. Ghi công thức và kết quả.","k":"Tỉ lệ = Tổng số cây / 50, định dạng <b>Percentage</b>: Mười giờ 56/50 = <b>112%</b>; Dạ yến thảo 35/50 = <b>70%</b>; Dừa cạn 63/50 = <b>126%</b>; Cúc vàng 75/50 = <b>150%</b>; Hồng 58/50 = <b>116%</b>. Ví dụ ô O4: =L4/50.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Có thể định dạng dữ liệu số theo các kiểu khác nhau như xác định <b>số chữ số thập phân</b>, <b>phân tách hàng nghìn</b>, hàng triệu,…</li><li>Có thể định dạng số theo kiểu <b>phần trăm</b> và định dạng dữ liệu <b>ngày tháng của Việt Nam</b> (dd/mm/yyyy).</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Chèn: <b>Insert</b> (hàng mới ở trên, cột mới bên trái); xoá: <b>Delete</b>; ẩn: <b>Hide</b>; hiện lại: <b>Unhide</b>.</li><li>Gộp ô: <b>Home → Alignment → Merge &amp; Center</b>. Ô gộp có địa chỉ là ô đầu tiên bên trái; dữ liệu các ô khác bị xoá.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Các hàm SUM, AVERAGE, COUNT, MIN, MAX chỉ tính toán trên các ô chứa <b>dữ liệu số</b> và <b>bỏ qua</b> các ô chứa văn bản hoặc ô trống.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Chi phí = Đơn giá × Tổng số cây: <b>=D4*L4</b>, sao chép xuống.</li><li>Định dạng số tiền: Format Cells → <b>Number</b>, <b>Use 1000 Separator</b>.</li></ul>"}]},"tin7-ung-xu-tren-mang":{"id":"tin7-bai5","ten":"Bài 5. Ứng xử trên mạng","cau":[{"id":"kd1","type":"open","q":"Đọc đoạn mở đầu. Theo em, vì sao ứng xử trên mạng có văn hoá và sử dụng Internet hợp lí lại giúp chúng ta có cuộc sống văn minh, an toàn hơn? Em đã từng nghe về sự việc đáng tiếc nào liên quan đến việc sử dụng mạng chưa?","k":"Internet có <b>hai mặt</b>: rất có ích nhưng cũng có tác động tiêu cực. Nhiều sự việc đau lòng xảy ra do <b>bắt nạt trên mạng</b>, <b>nghiện Internet</b>, nghiện trò chơi trực tuyến,… Ứng xử văn hoá, đúng quy tắc giúp bảo vệ mình và người khác.","label":"Mở đầu"},{"id":"hd1a","type":"open","q":"Em biết những phương thức giao tiếp qua mạng nào? Em đã từng sử dụng những phương thức nào?","k":"Gửi, nhận <b>thư điện tử</b>; <b>nhắn tin</b>, nói chuyện trực tuyến qua các ứng dụng (Zalo, Messenger,…); trao đổi trên <b>diễn đàn</b>, <b>mạng xã hội</b>,…","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Theo em những đặc điểm khác nhau giữa giao tiếp gặp gỡ trực tiếp và giao tiếp qua mạng là gì?","k":"Qua mạng: <b>không nhìn thấy</b> nét mặt, cử chỉ; có thể <b>giấu tên</b>; giao tiếp với <b>rất nhiều người</b>, kể cả người lạ; thông tin lan nhanh, khó xoá. Trực tiếp: thấy nhau, biết rõ người đối diện, phản hồi ngay.","label":"HĐ1 – Câu 2"},{"id":"hd1c","type":"open","q":"Tại sao có những bạn khi giao tiếp qua mạng lại thiếu văn minh hơn so với khi giao tiếp trực tiếp?","k":"Vì nghĩ rằng <b>không ai nhìn thấy, không ai biết mình là ai</b>, không thấy được cảm xúc của người kia; các mối quan hệ trên mạng rộng, đa dạng, <b>khó kiểm soát</b> hơn ngoài đời thực.","label":"HĐ1 – Câu 3"},{"id":"hd2","type":"sort","q":"Thảo luận và sắp xếp mỗi việc dưới đây vào nhóm Nên hoặc Không nên khi giao tiếp qua mạng.","k":"<b>Nên</b>: a, c, d, f, i. <b>Không nên</b>: b, e, g, h, j. Luôn sử dụng <b>ngôn ngữ lịch sự</b> và ứng xử có văn hoá khi tham gia giao tiếp qua mạng.","cats":["Nên","Không nên"],"items":[["a) Tôn trọng mọi người khi giao tiếp qua mạng.",0],["b) Giấu bố mẹ, thầy cô vấn đề khiến em căng thẳng, sợ hãi khi sử dụng mạng.",1],["c) Sử dụng ngôn ngữ, hình ảnh, biểu tượng,… văn minh, lịch sự.",0],["d) Bảo vệ tài khoản cá nhân trên mạng (ví dụ thư điện tử) của mình.",0],["e) Nói bậy, nói xấu người khác, sử dụng tiếng lóng, hình ảnh không lành mạnh.",1],["f) Tìm sự hỗ trợ của bố mẹ, thầy cô, người tư vấn khi bị bắt nạt trên mạng.",0],["g) Đưa thông tin, hình ảnh cá nhân của người khác lên mạng khi chưa được họ cho phép.",1],["h) Dành quá nhiều thời gian truy cập mạng, ảnh hưởng tới học tập và sinh hoạt.",1],["i) Tự chủ bản thân để sử dụng mạng hợp lí.",0],["j) Đọc thông tin trong hộp thư điện tử của người khác.",1]]},{"id":"p24a","type":"mcq","q":"Cách tốt nhất em nên làm khi bị ai đó bắt nạt trên mạng là gì?","k":"<b>C</b>. Nhờ <b>bố mẹ, thầy cô</b> giúp đỡ, tư vấn. Không đáp trả bằng lời xúc phạm, đe doạ; cũng không im lặng chịu đựng một mình.","o":["Nói lời xúc phạm người đó.","Cố gắng quên đi và tiếp tục chịu đựng.","Nhờ bố mẹ, thầy cô giáo giúp đỡ, tư vấn.","Đe doạ người bắt nạt mình."],"a":2},{"id":"p24b","type":"open","q":"Là một người ứng xử có văn hoá khi tham gia giao tiếp qua mạng, em sẽ có những hành động cụ thể nào? (Gợi ý: không nên có lời nói, cách ứng xử nào qua mạng mà em không thực hiện như vậy khi gặp trực tiếp!)","k":"Ví dụ: chào hỏi, xưng hô lịch sự; không nói bậy, không bình luận xúc phạm; không chia sẻ ảnh, thông tin của người khác khi chưa được phép; kiểm chứng trước khi chia sẻ; <b>không nói qua mạng điều mình không nói khi gặp trực tiếp</b>.","label":"Câu hỏi tr.24 – câu 2"},{"id":"hd3","type":"open","q":"Khi em đang truy cập mạng, máy tính thỉnh thoảng lại hiện lên những trang web có nội dung bạo lực, nội dung không phù hợp với lứa tuổi của em, em sẽ làm gì?","k":"<b>Đóng ngay</b> trang web đó; không nháy vào, không chia sẻ cho bạn; <b>báo cho bố mẹ, thầy cô</b> để được giúp đỡ, nhờ cài phần mềm chặn trang web xấu.","label":"HĐ3 – Xử lí tình huống"},{"id":"p25","type":"sort","q":"Những cách ứng xử nào sau đây là hợp lí khi truy cập một trang web có nội dung xấu?","k":"Hợp lí: <b>B</b> và <b>C</b>. Tiếp tục truy cập hay gửi cho bạn bè xem đều làm thông tin xấu ảnh hưởng tới mình và lan rộng hơn.","cats":["Hợp lí","Không hợp lí"],"items":[["A. Tiếp tục truy cập trang web đó.",1],["B. Đóng ngay trang web đó.",0],["C. Đề nghị bố mẹ, thầy cô hoặc người có trách nhiệm ngăn chặn truy cập trang web đó.",0],["D. Gửi trang web đó cho bạn bè xem.",1]]},{"id":"hd4a","type":"open","q":"1. Trung bình một ngày em sử dụng máy tính bao nhiêu giờ? 2. Em có chơi trò chơi điện tử và sử dụng mạng xã hội không? Nếu có thì khoảng bao nhiêu giờ một tuần?","k":"Học sinh tự trả lời trung thực. Giáo viên tổng hợp để cả lớp tự so sánh, nhận ra ai đang dùng quá nhiều thời gian.","label":"HĐ4 – Câu 1, 2"},{"id":"hd4b","type":"open","q":"Theo em các biểu hiện và tác hại của bệnh nghiện Internet là gì?","k":"Biểu hiện: chơi trò chơi điện tử quá nhiều, dùng mạng xã hội liên tục, ảnh hưởng tới gia đình, bạn bè, học tập. Tác hại: <b>thiếu giao tiếp</b> với thế giới xung quanh, <b>khó tập trung</b> học tập, tăng nguy cơ <b>bắt nạt trên mạng</b>, bị <b>dẫn dắt</b> đến thông tin xấu, <b>nghiện trò chơi</b> trực tuyến.","label":"HĐ4 – Câu 3"},{"id":"tachai","type":"sort","q":"Đọc mục 3 (SGK trang 25–26). Mỗi tình huống dưới đây thể hiện tác hại nào của nghiện Internet?","k":"Năm tác hại: <b>thiếu giao tiếp</b>, <b>khó tập trung</b>, tăng nguy cơ <b>bắt nạt trên mạng</b>, dễ bị <b>dẫn dắt</b> đến trang thông tin xấu, dễ bị <b>nghiện trò chơi</b>. Nghiện Internet ảnh hưởng xấu tới sức khoẻ thể chất, tinh thần, kết quả học tập và khả năng giao tiếp.","cats":["Thiếu giao tiếp","Khó tập trung học tập","Bắt nạt trên mạng","Dẫn dắt tới thông tin xấu","Nghiện trò chơi trực tuyến"],"items":[["Nam chỉ muốn ở một mình trong phòng với máy tính, không muốn nói chuyện với ai.",0],["Cứ 10 phút Lan lại mở điện thoại xem tin nhắn nên làm bài mãi không xong.",1],["Một bạn gửi tin nhắn chê bạn khác là “béo, xấu xí”.",2],["Đang xem video học tập, Hùng nháy theo các đường liên kết rồi lạc vào trang có nội dung bạo lực.",3],["Minh thấy bồn chồn, cáu gắt mỗi khi không được chơi trò chơi trực tuyến.",4]]},{"id":"loikhuyen","type":"sort","q":"Mỗi việc làm dưới đây ứng với lời khuyên nào: Chia sẻ, Rời xa, Giới hạn hay Theo đuổi?","k":"<b>Chia sẻ</b> với người tin tưởng; <b>Rời xa</b>: đưa thiết bị ra nơi sinh hoạt chung; <b>Giới hạn</b> thời gian sử dụng; <b>Theo đuổi</b> sở thích, thói quen tốt (thể thao, đọc sách, từ thiện).","cats":["Chia sẻ","Rời xa","Giới hạn","Theo đuổi"],"items":[["Kể với mẹ khi em thấy mình dùng điện thoại quá nhiều.",0],["Đặt máy tính ở phòng khách thay vì trong phòng ngủ.",1],["Cài phần mềm giới hạn mỗi ngày chỉ dùng máy 1 giờ.",2],["Tham gia câu lạc bộ bóng đá, đọc sách mỗi tối.",3]]},{"id":"hd5","type":"open","q":"Cùng nhóm vẽ cây (hoặc dùng cây trong bảng mô phỏng), ghi lên lá, hoa những điều nên làm để phòng tránh bệnh nghiện Internet. Nhóm em đã ghi những điều gì?","k":"Ví dụ: đặt giới hạn thời gian dùng máy; để máy ở phòng chung; chơi thể thao, đọc sách; trò chuyện với gia đình; ngủ đủ giấc; tắt thông báo khi học; tham gia hoạt động tình nguyện,…","label":"HĐ5 – Hồi sinh cây"},{"id":"lt1","type":"sort","q":"Khi giao tiếp qua mạng, những điều nào sau đây nên tránh?","k":"Nên tránh: <b>B, C, E</b>. A và D là những việc nên làm.","cats":["Nên tránh","Không cần tránh (nên làm)"],"items":[["A. Tôn trọng người đang giao tiếp với mình.",1],["B. Nói bất cứ điều gì xuất hiện trong đầu.",0],["C. Kết bạn với những người mình không quen biết.",0],["D. Bảo vệ thông tin cá nhân của mình.",1],["E. Truy cập bất cứ liên kết nào nhận được.",0]]},{"id":"lt2","type":"sort","q":"Theo em, hai hoạt động trên mạng nào sau đây dễ gây bệnh nghiện Internet nhất?","k":"<b>A</b> và <b>C</b>: trò chơi trực tuyến và mạng xã hội dễ cuốn người dùng vào liên tục, khó dừng lại.","cats":["Dễ gây nghiện nhất","Ít gây nghiện hơn"],"items":[["A. Chơi trò chơi trực tuyến.",0],["B. Đọc tin tức.",1],["C. Sử dụng mạng xã hội.",0],["D. Học tập trực tuyến.",1],["E. Trao đổi thông tin qua thư điện tử.",1]]},{"id":"vd1","type":"open","q":"Em hãy cùng một nhóm bạn tạo ra một sản phẩm (áp phích, đoạn kịch ngắn, sơ đồ tư duy, bài trình chiếu,…) về chủ đề “Ứng xử trên mạng” để trình bày với các bạn trong lớp. Mô tả ngắn sản phẩm của nhóm.","k":"Học sinh tự làm. Sản phẩm tốt nêu được: những điều nên và không nên khi giao tiếp qua mạng, cách xử lí khi gặp thông tin xấu, bị bắt nạt, cách phòng tránh nghiện Internet.","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Nếu một trong những người bạn của em có biểu hiện nghiện trò chơi trực tuyến, em sẽ làm gì để giúp bạn?","k":"Trò chuyện, chia sẻ với bạn về tác hại; rủ bạn chơi thể thao, đọc sách, tham gia hoạt động chung; nhắc bạn đặt giới hạn thời gian; nếu cần, <b>báo với thầy cô, bố mẹ</b> của bạn để cùng giúp đỡ.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Luôn sử dụng <b>ngôn ngữ lịch sự</b> và ứng xử có văn hoá khi tham gia giao tiếp qua mạng.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Chỉ truy cập vào các trang web có thông tin <b>phù hợp với lứa tuổi</b>.</li><li>Nhờ người lớn cài phần mềm <b>chặn truy cập</b> các trang web xấu.</li><li>Hỏi ý kiến người lớn trong trường hợp cần thiết khi truy cập mạng.</li><li><b>Đóng ngay</b> các trang thông tin có nội dung xấu, không phù hợp lứa tuổi nếu vô tình truy cập vào.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Nghiện Internet gây ảnh hưởng xấu tới <b>sức khoẻ</b> thể chất, tinh thần, <b>kết quả học tập</b> và khả năng <b>giao tiếp</b> với mọi người xung quanh.</li><li>Dành thời gian với người thân và bạn bè, hạn chế để thiết bị kết nối Internet trong phòng riêng, <b>giới hạn thời gian</b> sử dụng, theo đuổi những sở thích không liên quan quá nhiều đến thiết bị điện tử là những cách thức tốt để phòng tránh nguy cơ nghiện Internet.</li></ul>"}]},"tin8-ban-mau-trinh-chieu":{"id":"tin8-bai11a","ten":"Bài 11a. Sử dụng bản mẫu tạo bài trình chiếu","cau":[{"id":"kd1","type":"open","q":"Quan sát hai trang chiếu trong Hình 11a.1, so sánh hai trang chiếu này với trang chiếu số 1 em đã tạo ở phần thực hành Bài 10a và đưa ra nhận xét.","k":"Hai trang chiếu ở Hình 11a.1 có cùng nội dung nhưng <b>đẹp, chuyên nghiệp hơn</b>: có hình nền, hình minh hoạ, bố cục và màu sắc phối hợp hài hoà. Trang chiếu ở Bài 10a đơn giản hơn (chủ yếu là chữ trên nền một mẫu định dạng).","label":"Khởi động"},{"id":"hd1a","type":"mcq","q":"Sử dụng phần mềm trình chiếu có tạo được các trang chiếu như Hình 11a.1 không?","k":"<b>Có.</b> Phần mềm trình chiếu tạo được các trang chiếu như vậy.","o":["Có.","Không, phải dùng phần mềm đồ hoạ chuyên nghiệp.","Chỉ tạo được trang chiếu chỉ có chữ.","Chỉ tạo được nếu có kết nối Internet."],"a":0},{"id":"hd1b","type":"mcq","q":"Để tạo được các trang chiếu đó có cần nhiều thời gian không?","k":"Nếu tự thiết kế từng trang thì mất nhiều thời gian; dùng <b>bản mẫu (Template)</b> có sẵn thì nhanh, chỉ cần chỉnh sửa nội dung.","o":["Không cần nhiều thời gian nếu sử dụng bản mẫu có sẵn.","Luôn cần rất nhiều thời gian.","Không thể tạo được.","Chỉ mất thời gian nhập chữ."],"a":0},{"id":"hd1c","type":"open","q":"Làm thế nào để tạo được các trang chiếu đó?","k":"Sử dụng <b>bản mẫu</b> có sẵn trong phần mềm trình chiếu (File → New, chọn bản mẫu theo chủ đề) hoặc bản mẫu được chia sẻ trên mạng, rồi thay nội dung, hình ảnh cho phù hợp.","label":"HĐ1 – Câu 3"},{"id":"bm","type":"sort","q":"Mỗi thành phần dưới đây có ở cả mẫu định dạng (Themes) và bản mẫu (Template), hay chỉ bản mẫu mới có?","k":"Mẫu định dạng (Themes) là tập hợp <b>màu sắc, phông chữ, hiệu ứng hình ảnh</b>. Bản mẫu (Template) chứa thêm <b>bố cục, kiểu nền và cả nội dung</b> gợi ý cho một chủ đề.","cats":["Cả hai đều có","Chỉ bản mẫu có"],"items":[["Màu sắc",0],["Phông chữ",0],["Hiệu ứng hình ảnh",0],["Bố cục các trang chiếu",1],["Gợi ý các nội dung cần có cho bài trình chiếu",1],["Hướng dẫn cách nhập nội dung, cách trình bày",1]]},{"id":"ext","type":"mcq","q":"Bản mẫu được lưu dưới dạng một tệp có phần mở rộng là:","k":"Bản mẫu được lưu dưới dạng tệp <b>.potx</b> (bài trình chiếu thường là .pptx).","o":[".potx",".pptx",".docx",".xlsx"],"a":0},{"id":"p52","type":"open","q":"Em hãy cho biết bản mẫu khác với mẫu định dạng thế nào.","k":"<b>Mẫu định dạng</b> chỉ quy định giao diện (màu sắc, phông chữ, hiệu ứng hình ảnh). <b>Bản mẫu</b> có thêm bố cục, kiểu nền, các trang chiếu và <b>gợi ý nội dung</b> cho một mục đích, chủ đề cụ thể; được lưu thành tệp .potx để tái sử dụng, chia sẻ.","label":"Câu hỏi tr.52"},{"id":"nv","type":"order","q":"Sắp xếp các bước thực hiện nhiệm vụ “An toàn trong phòng thực hành” theo đúng thứ tự (dùng nút ↑ ↓).","k":"Chọn bản mẫu → nhập nội dung → chỉnh sửa bản mẫu → đưa đường dẫn video vào trang tiêu đề → lưu tệp.","items":{"a":"Chọn File/New → Education → chọn bản mẫu Lab Safety.","b":"Nhập nội dung theo các gợi ý trong bản mẫu.","c":"Thay đổi phông chữ, cỡ chữ, màu nền, thêm hoặc bớt trang cho phù hợp.","d":"Chọn hình ảnh ở trang tiêu đề → Insert/Links/Link → chọn tệp video.","e":"Chọn File/Save, lưu tệp AnToanPhongThucHanh.pptx."},"ans":["a","b","c","d","e"],"start":["c","e","a","d","b"]},{"id":"link","type":"mcq","q":"Để đưa vào trang tiêu đề đường dẫn đến tệp video NhungSuCoPhongThucHanh.mp4, em làm thế nào?","k":"Chọn đối tượng (hình ảnh) → <b>Insert/Links/Link</b> → trong cửa sổ <b>Insert Hyperlink</b> chọn đường dẫn đến tệp → <b>OK</b>. Khi trình chiếu, nháy vào hình để mở video.","o":["Chọn hình ảnh minh hoạ, chọn Insert/Links/Link, chọn tệp video trong cửa sổ Insert Hyperlink rồi OK.","Chọn Design/Themes, chọn tệp video.","Chọn File/New, chọn tệp video.","Kéo tệp video vào khung tiêu đề."],"a":0},{"id":"nv3","type":"open","q":"Báo cáo kết quả: bài trình chiếu AnToanPhongThucHanh.pptx của em có bao nhiêu trang? Em đã chỉnh sửa bản mẫu những gì? Đường dẫn đến video được gắn vào đối tượng nào?","k":"Ví dụ: 8 trang theo bản mẫu; thay các dòng gợi ý bằng nội dung an toàn phòng thực hành; đổi cỡ chữ, màu tiêu đề; gắn liên kết vào hình chiếc bình ở trang tiêu đề.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"mcq","q":"Phương án nào sau đây mô tả các bước sử dụng bản mẫu?","k":"<b>D</b>. File/New hiện ra các bản mẫu có sẵn theo chủ đề. (Design/Themes là chọn mẫu định dạng.)","o":["Nháy chuột chọn Design/Themes, chọn bản mẫu.","Nháy chuột chọn Design/Variants, chọn bản mẫu.","Nháy chuột chọn Insert/Text, chọn bản mẫu.","Nháy chuột chọn File/New, chọn bản mẫu."],"a":3},{"id":"lt2","type":"open","q":"Thêm vào trang chiếu tiêu đề của tệp AnToanPhongThucHanh.pptx đường dẫn đến tệp văn bản lưu trữ các kí hiệu cảnh báo trong phòng thực hành để có thể mở ra giới thiệu cho người nghe trong khi trình chiếu. Em đã gắn đường dẫn vào đối tượng nào?","k":"Chọn một đối tượng khác trên trang tiêu đề (ví dụ tiêu đề hoặc hình kính hiển vi) → Insert/Links/Link → chọn tệp văn bản (ví dụ KiHieuCanhBao.docx) → OK. Mỗi đối tượng gắn một liên kết.","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Tìm một bản mẫu (có sẵn trong phần mềm trình chiếu hoặc được chia sẻ trên mạng) và sử dụng để tạo lại bài trình chiếu trong tệp LeRaMatCLBTinhoc.pptx. Thực hiện thay đổi các định dạng cần thiết để tạo một bản mẫu phù hợp với bài trình chiếu, ghi lại tệp dưới dạng bản mẫu (.potx). Mô tả ngắn bài của em.","k":"File/New → chọn bản mẫu → chép nội dung 4 trang của Bài 10a → chỉnh màu, phông, hình → File/Save As, chọn <b>PowerPoint Template (*.potx)</b> để tái sử dụng và chia sẻ.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Bản mẫu chứa bố cục, màu sắc, phông chữ, hiệu ứng, kiểu nền,… và cả nội dung.</li><li>Bản mẫu giúp bài trình chiếu có giao diện <b>thống nhất, chuyên nghiệp</b> mà không tốn thời gian.</li><li>Bản mẫu giúp <b>gợi ý các nội dung</b> cần có cho bài trình chiếu.</li><li>Có thể <b>chỉnh sửa, chia sẻ, tái sử dụng</b> bản mẫu.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Dùng bản mẫu: <b>File/New</b> → chọn chủ đề → chọn bản mẫu.</li><li>Đưa đường dẫn đến video, tài liệu: chọn đối tượng → <b>Insert/Links/Link</b> → chọn tệp → OK.</li></ul>"}]},"tin8-bang-tinh-bai-toan-thuc-te":{"id":"tin8-bai5","ten":"Bài 5. Sử dụng bảng tính giải quyết bài toán thực tế","cau":[{"id":"kd1","type":"open","q":"Theo em, bảng tính bạn Khoa tạo ra ở Hình 5.1 có cần bổ sung thông tin gì không?","k":"Cần bổ sung dữ liệu cho cột <b>Doanh thu</b> (đang trống) – tính bằng công thức Đơn giá × Số lượt mua; có thể thêm <b>tỉ lệ doanh thu của công ti</b> và cột <b>Doanh thu của công ti</b>, dòng <b>tổng doanh thu</b>.","label":"Mở đầu"},{"id":"hd1a","type":"mcq","q":"Công thức để tính Doanh thu của phần mềm Quản lí thời gian (ô E4) dựa trên Đơn giá và Số lượt mua là:","k":"Doanh thu = Đơn giá × Số lượt mua, nên tại ô E4 nhập <b>=C4*D4</b> (kết quả 1 999 950 000).","o":["=C4+D4","=C4*D4","=B4*C4","=C4/D4"],"a":1},{"id":"hd1b","type":"open","q":"Thao tác nào giúp em tính doanh thu cho các phần mềm còn lại mà không cần gõ công thức vào từng ô? Khi thực hiện thao tác đó, địa chỉ ô trong công thức sẽ thay đổi như thế nào?","k":"<b>Sao chép công thức</b>: chọn ô E4, kéo thả <b>nút điền</b> (góc dưới bên phải ô) xuống E9, hoặc Copy rồi Paste. Khi sao chép xuống một hàng, các địa chỉ trong công thức <b>tăng một hàng</b>: E5 có =C5*D5, E6 có =C6*D6,…","label":"HĐ1 – Câu 2"},{"id":"p22","type":"match","q":"Nếu sao chép công thức từ ô E4 (=C4*D4) đến các ô E6, E7, E8 và E9 thì công thức trong các ô đó là gì?","k":"E6: =C6*D6; E7: =C7*D7; E8: =C8*D8; E9: =C9*D9. Địa chỉ tương đối thay đổi theo vị trí ô chứa công thức.","items":[["1) Ô E6",1],["2) Ô E7",2],["3) Ô E8",3],["4) Ô E9",4]],"opts":["a) =C6*D6","b) =C7*D7","c) =C8*D8","d) =C9*D9","e) =C4*D4"]},{"id":"hd2a","type":"open","q":"Em hãy nhập công thức để tính Doanh thu của công ti cho phần mềm Quản lí thời gian và Trò chơi sáng tạo vào ô F4 và F5, biết rằng Doanh thu của công ti = Doanh thu × Tỉ lệ (được lưu tại ô F2).","k":"F4: <b>=E4*F2</b>; F5: <b>=E5*F2</b>. Ô F2 (tỉ lệ 70%) dùng chung cho mọi phần mềm.","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Nếu sao chép công thức =E4*F2 từ ô F4 vào ô F5 thì công thức nhận được tại ô F5 có đúng yêu cầu không? Vì sao?","k":"<b>Không đúng.</b> Sao chép xuống một hàng, F5 nhận công thức <b>=E5*F3</b>: địa chỉ F2 cũng bị đổi thành F3 (ô chứa tiêu đề, không phải tỉ lệ). Cần giữ cố định ô F2 bằng <b>địa chỉ tuyệt đối $F$2</b>: F4 nhập =E4*$F$2.","label":"HĐ2 – Câu 2"},{"id":"p24a","type":"mcq","q":"Trong Hình 5.3, công thức tại ô F5 là =E5*$F$2. Sao chép công thức này đến ô F6, kết quả sao chép là:","k":"E5 là địa chỉ tương đối → đổi thành <b>E6</b>; $F$2 là địa chỉ tuyệt đối → <b>giữ nguyên</b>. Kết quả: <b>=E6*$F$2</b>.","o":["=E6*F3","=E6*$F$2","=$E$6*F3","=$E$6*$F$2"],"a":1},{"id":"p24b","type":"mcq","q":"Cách nhập kí hiệu $ cho địa chỉ tuyệt đối là:","k":"Có thể <b>gõ $ từ bàn phím</b> hoặc nhập địa chỉ rồi <b>nhấn phím F4</b>. Phím F2 dùng để sửa nội dung ô, không chuyển địa chỉ.","o":["Gõ kí hiệu $ từ bàn phím khi nhập địa chỉ ô.","Sau khi nhập địa chỉ tương đối, nhấn phím F4 để chuyển thành địa chỉ tuyệt đối.","Sau khi nhập địa chỉ tương đối, nhấn phím F2 để chuyển thành địa chỉ tuyệt đối.","Thực hiện được theo cả hai cách A và B."],"a":3},{"id":"th1","type":"order","q":"Sắp xếp các bước thực hành tính Doanh thu và Doanh thu của công ti theo đúng thứ tự (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → c → d → a → e</b>.","items":{"a":"Tại ô F4 nhập =E4*$F$2 rồi sao chép đến F5:F9.","b":"Nhập dữ liệu, định dạng bảng tính như Hình 5.1.","c":"Tại ô E4 nhập =C4*D4 rồi sao chép đến E5:E9.","d":"Tại ô D2 nhập “Tỉ lệ doanh thu của công ti”, tại ô F2 nhập 70%; ô F3 nhập tiêu đề.","e":"Lưu tệp."},"ans":["b","c","d","a","e"],"start":["a","b","c","d","e"]},{"id":"th2","type":"mcq","q":"Với Doanh thu của phần mềm Quản lí thời gian là 1 999 950 000 đồng và tỉ lệ 70%, ô F4 hiển thị kết quả nào?","k":"1 999 950 000 × 70% = <b>1 399 965 000</b> (đồng).","o":["1 399 965 000","599 985 000","1 999 950 000","2 857 071 429"],"a":0},{"id":"cp","type":"order","q":"Sắp xếp các bước sao chép bảng số liệu (Bảng 5.1) từ phần mềm soạn thảo văn bản sang phần mềm bảng tính (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → e → c</b>. Chọn bảng → Copy → chọn ô góc trên trái, Paste → đóng tệp văn bản → lưu Khaosat.xlsx.","items":{"a":"Trong bảng tính mới, chọn ô ở góc trên cùng bên trái của vùng muốn dán, chọn lệnh Paste.","b":"Trong phần mềm soạn thảo, chọn các hàng, cột của bảng.","c":"Lưu tệp bảng tính với tên Khaosat.xlsx.","d":"Chọn lệnh Copy (hoặc nhấn Ctrl + C).","e":"Đóng tệp văn bản."},"ans":["b","d","a","e","c"],"start":["a","b","c","d","e"]},{"id":"ks","type":"mcq","q":"Sau khi sao chép Bảng 5.1 sang bảng tính, em dùng hàm SUM để tính tổng số học sinh đã chọn. Kết quả là bao nhiêu?","k":"46 + 25 + 78 + 42 = <b>191</b> học sinh. Công thức ví dụ: =SUM(D2:D5).","o":["181","191","201","78"],"a":1},{"id":"lt1","type":"mcq","q":"Công thức tại ô C1 (Hình 5.6) là =A1*B1. Sao chép công thức trong ô C1 vào ô E2 thì công thức tại ô E2 sau khi sao chép là:","k":"Từ C1 đến E2: <b>sang phải 2 cột, xuống 1 hàng</b>. A1 → C2, B1 → D2. Kết quả: <b>=C2*D2</b>.","o":["=C1*D2","=C2*D1","=C2*D2","=B2*C2"],"a":2},{"id":"lt2","type":"mcq","q":"Trong Hình 5.7, cột C là Đơn giá, ô D2 lưu tỉ lệ giảm giá 20%. Công thức nhập tại ô D5 để tính đơn giá đã giảm, sao cho sao chép được xuống D10, là:","k":"Đơn giá đã giảm = Đơn giá × (1 − tỉ lệ giảm). Ô D2 phải cố định nên dùng <b>=C5*(1-$D$2)</b>. Cũng có thể viết =C5-C5*$D$2.","o":["=C5*D2","=C5*(1-D2)","=C5*(1-$D$2)","=C5-$D$2"],"a":2},{"id":"lt3","type":"open","q":"Bổ sung cột Số lượng (E) và Tổng tiền (F). Viết công thức tại ô F5 để tính Tổng tiền = Số lượng × Đơn giá đã giảm, và công thức tại ô F11 tính tổng tiền phải trả cho tất cả các mặt hàng.","k":"F5: <b>=E5*D5</b> (sao chép xuống F10). F11: <b>=SUM(F5:F10)</b>. Ở đây không cần địa chỉ tuyệt đối vì mỗi hàng dùng số lượng, đơn giá của chính hàng đó.","label":"Luyện tập – câu 2d, e, f"},{"id":"vd1","type":"open","q":"Truy cập một số chợ ứng dụng để tìm thông tin về năm phần mềm ứng dụng mà em quan tâm (đơn giá, số lượt mua,…), tạo bảng tính theo mẫu Hình 5.5. Ghi lại công thức em dùng để tính Doanh thu và Doanh thu của công ti (giả sử công ti nhận được 75% Doanh thu).","k":"Ví dụ: nhập 75% vào ô F2; E4: <b>=C4*D4</b> sao chép đến E8; F4: <b>=E4*$F$2</b> sao chép đến F8. Nguồn: Google Play, App Store (ghi rõ ngày tra cứu).","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Địa chỉ tương đối</b> tự động thay đổi khi sao chép công thức nhưng vẫn giữ nguyên vị trí tương đối giữa ô chứa công thức và ô có địa chỉ trong công thức.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Địa chỉ tuyệt đối</b> không thay đổi khi sao chép công thức.</li><li>Địa chỉ tuyệt đối có kí hiệu <b>$</b> trước tên cột và trước tên hàng, ví dụ $F$2.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Dùng địa chỉ tương đối cho dữ liệu thay đổi theo từng hàng; dùng địa chỉ tuyệt đối cho giá trị dùng chung (tỉ lệ, đơn giá chung,…).</li><li>Có thể sao chép bảng dữ liệu từ văn bản, trang trình chiếu sang bảng tính bằng <b>Copy</b> và <b>Paste</b> để tính toán nhanh, hiệu quả.</li></ul>"}]},"tin8-bieu-dien-du-lieu":{"id":"tin8-bai13","ten":"Bài 13. Biểu diễn dữ liệu","cau":[{"id":"kd1","type":"open","q":"Trong chương trình Tin học lớp 7, em đã được học về các kiểu dữ liệu trong phần mềm bảng tính. Em hãy cho biết đó là những kiểu dữ liệu nào.","k":"Kiểu <b>số</b> (số nguyên, số thập phân), kiểu <b>văn bản</b> (kí tự), kiểu <b>ngày tháng</b>. Ngoài ra kết quả so sánh trong bảng tính là giá trị <b>TRUE/FALSE</b> (lôgic).","label":"Khởi động"},{"id":"hd1a","type":"match","q":"Ghép mỗi dòng ở cột Dữ liệu với một dòng phù hợp ở cột Kiểu dữ liệu trong Hình 13.1.","k":"<b>Tin học</b> – kiểu văn bản; <b>3.141592</b> – kiểu số.","items":[["Tin học",1],["3.141592",2]],"opts":["a) Văn bản","b) Số"]},{"id":"hd1b","type":"mcq","q":"Nhập dữ liệu và công thức như Hình 13.2 vào phần mềm bảng tính. Kết quả hiển thị ở các ô C1, C2, C3 lần lượt là:","k":"C1 = 3 + 5 = <b>8</b> (số); C2 ghép kí tự 3 và 5 → <b>35</b> (xâu kí tự); C3 kiểm tra 3 &lt; 5 → <b>TRUE</b> (lôgic).","o":["8; 35; TRUE","35; 8; TRUE","8; 8; FALSE","8; 35; FALSE"],"a":0},{"id":"kieu","type":"sort","q":"Mỗi giá trị dưới đây thuộc kiểu dữ liệu nào trong Scratch?","k":"<b>Số</b>: số nguyên, số thập phân (15, 3.141592). <b>Xâu kí tự</b>: kí tự hoặc xâu kí tự (@, Computer, kết quả ghép). <b>Lôgic</b>: true hoặc false (kết quả so sánh).","cats":["Số","Xâu kí tự","Lôgic"],"items":[["15",0],["3.141592",0],["@",1],["Computer",1],["true",2],["false",2],["Kết quả ghép kí tự 3 với kí tự 5 (35 ở ô C2)",1],["Kết quả của phép so sánh 3 < 5",2]]},{"id":"pt","type":"match","q":"Ghép mỗi phép toán với kết quả của nó (thử trên mô phỏng).","k":"13 chia lấy dư 4 = 1; kết hợp → “táochuối”; 70 &gt; 50 → true; và chỉ đúng khi cả hai đều đúng → false; hoặc chỉ sai khi cả hai đều sai → true; không phải (true) → false.","items":[["13 chia lấy dư 4",1],["kết hợp “táo” “chuối”",2],["70 > 50",3],["⟨70 > 50⟩ và ⟨80 < 50⟩",4],["⟨50 = 50⟩ hoặc ⟨30 > 50⟩",3],["không phải ⟨50 = 50⟩",4]],"opts":["a) 1","b) táochuối","c) true","d) false"]},{"id":"p77","type":"match","q":"Ghép mỗi phép toán với một kiểu dữ liệu kết quả cho phù hợp.","k":"kết hợp → <b>xâu kí tự</b>; phép so sánh = → <b>lôgic</b>; làm tròn → <b>số</b>.","items":[["kết hợp “Diện tích hình tròn là:” (s)",2],["⟨(n chia lấy dư 2) = 0⟩",3],["làm tròn (3.141592 × r × r)",1]],"opts":["Số","Xâu kí tự","Lôgic"]},{"id":"hd2","type":"open","q":"Ở Bài 12, chương trình cho Bọ rùa di chuyển theo tam giác đều. Làm thế nào để tổng quát bài toán với đường đi của nhân vật là một hình đa giác đều có số cạnh bất kì được nhập vào từ bàn phím?","k":"Dùng một <b>biến</b> n lưu số cạnh, nhận giá trị nhập từ bàn phím (hỏi … và đợi, trả lời). Tính độ dài cạnh và góc quay bằng <b>biểu thức</b> (ví dụ 900 / n và 360 / n); lặp lại n lần.","label":"HĐ2 – Hằng, biến, biểu thức"},{"id":"hbt","type":"sort","q":"Mỗi thành phần dưới đây là hằng, biến hay biểu thức?","k":"<b>Hằng</b>: giá trị không đổi (3.14, “Xin chào!”, true). <b>Biến</b>: lưu giá trị có thể thay đổi, có tên (n, r). <b>Biểu thức</b>: kết hợp biến, hằng, phép toán (2 × 3.14 × r; 360 / n).","cats":["Hằng","Biến","Biểu thức"],"items":[["3.14",0],["“Xin chào!”",0],["true",0],["n (số cạnh nhập từ bàn phím)",1],["r (bán kính hình tròn)",1],["2 × 3.14 × r",2],["360 / n",2]]},{"id":"p78","type":"sort","q":"Chỉ ra hằng, biến, biểu thức được sử dụng trong chương trình ở Hình 13.4.","k":"Hằng: “Hãy nhập số cạnh:”, “Đường đi là hình có”, “cạnh bằng nhau” (xâu kí tự); 900, 360, 1 (số). Biến: n, số bước, góc quay (kiểu số). Biểu thức: 900 / n, 360 / n (kiểu số); kết hợp … (kiểu xâu kí tự).","cats":["Hằng","Biến","Biểu thức"],"items":[["“Hãy nhập số cạnh:”",0],["900",0],["360",0],["n",1],["số bước",1],["góc quay",1],["900 / n",2],["360 / n",2],["kết hợp “Đường đi là hình có” (kết hợp n “cạnh bằng nhau”)",2]]},{"id":"nv1","type":"mcq","q":"Chạy chương trình DuongDi.sb3 và nhập 4. Nhân vật vẽ hình gì, mỗi cạnh dài bao nhiêu bước, quay bao nhiêu độ?","k":"n = 4: số bước = 900 / 4 = <b>225</b>, góc quay = 360 / 4 = <b>90</b> → hình vuông. Chu vi luôn là 900 bước.","o":["Hình vuông, cạnh 225 bước, quay 90 độ.","Hình vuông, cạnh 900 bước, quay 360 độ.","Tam giác đều, cạnh 300 bước, quay 120 độ.","Hình vuông, cạnh 60 bước, quay 90 độ."],"a":0},{"id":"nv2","type":"open","q":"Báo cáo kết quả: em đã tạo những biến nào, mỗi biến lưu giá trị gì? Em đã thử nhập những số cạnh nào và nhân vật vẽ ra hình gì?","k":"Biến n (số cạnh nhập vào), số bước (900 / n), góc quay (360 / n). Ví dụ: 3 → tam giác đều, 4 → hình vuông, 6 → lục giác đều.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"match","q":"r là biến lưu giá trị của bán kính hình tròn. Cho r = 5, ghép mỗi biểu thức với giá trị trả lại và kiểu dữ liệu của nó.","k":"a) <b>true</b> (lôgic); b) <b>31.4</b> (số); c) <b>“Chu vi đường tròn là31.4”</b> (xâu kí tự – phép kết hợp ghép liền, không tự thêm dấu cách).","items":[["a) ⟨r > 0⟩",1],["b) 2 × 3.14 × r",2],["c) kết hợp “Chu vi đường tròn là” (2 × 3.14 × r)",3]],"opts":["true – kiểu lôgic","31.4 – kiểu số","Chu vi đường tròn là31.4 – kiểu xâu kí tự"]},{"id":"lt2","type":"open","q":"Viết chương trình tính chu vi đường tròn, diện tích hình tròn với giá trị của bán kính được nhập vào từ bàn phím, thông báo kết quả ra màn hình. Mô tả chương trình của em.","k":"hỏi “Nhập bán kính:” và đợi → đặt r thành trả lời → nói kết hợp “Chu vi là ” (2 × 3.14 × r) trong 2 giây → nói kết hợp “Diện tích là ” (3.14 × r × r).","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Viết chương trình Scratch của riêng em để giải quyết một bài toán cụ thể trong một môn học như Khoa học tự nhiên, Toán,… trong đó có sử dụng hằng, biến và biểu thức. Mô tả bài toán và chương trình.","k":"Ví dụ: tính vận tốc v = s / t (KHTN); diện tích hình chữ nhật; đổi độ C sang độ F (F = C × 1.8 + 32); kiểm tra số chẵn (n chia lấy dư 2 = 0).","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Mỗi <b>kiểu dữ liệu</b> là một tập hợp các giá trị mà một biến thuộc kiểu đó có thể nhận. Mỗi kiểu dữ liệu được trang bị một số phép toán.</li><li>Ba kiểu dữ liệu phổ biến trong ngôn ngữ lập trình trực quan là: <b>kiểu số, kiểu xâu kí tự, kiểu lôgic</b>.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Biến</b> được dùng để lưu trữ giá trị có thể thay đổi trong quá trình thực hiện chương trình. Biến được nhận biết qua tên của nó và thuộc một kiểu dữ liệu nhất định.</li><li><b>Hằng</b> là giá trị không đổi trong quá trình thực hiện chương trình. Mỗi hằng thuộc một kiểu dữ liệu nhất định (hằng kiểu số, hằng kiểu xâu kí tự, hằng kiểu lôgic,…).</li><li><b>Biểu thức</b> là sự kết hợp của biến, hằng, dấu ngoặc, phép toán và các hàm để trả lại giá trị thuộc một kiểu dữ liệu nhất định.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Tạo biến: nhóm <b>Các biến số</b> → Tạo một biến. Gán giá trị: <b>đặt … thành …</b>.</li><li>Nhập từ bàn phím: <b>hỏi … và đợi</b> (Cảm biến), giá trị nhập được lưu trong <b>trả lời</b>.</li></ul>"}]},"tin8-bieu-do":{"id":"tin8-bai7","ten":"Bài 7. Trình bày dữ liệu bằng biểu đồ","cau":[{"id":"kd1","type":"open","q":"Hình 7.1 và Hình 7.2 mô tả hai cách trình bày kết quả khảo sát những nội dung Tin học mà các bạn học sinh lớp 8A muốn tìm hiểu thêm. Em hãy nhận xét về hai cách trình bày này.","k":"<b>Bảng</b> (Hình 7.1) cho biết chính xác từng con số nhưng khó so sánh nhanh. <b>Biểu đồ cột</b> (Hình 7.2) trực quan, nhìn là thấy ngay nội dung nào nhiều, ít học sinh quan tâm (Đồ hoạ máy tính cao nhất, Soạn thảo văn bản thấp nhất).","label":"Mở đầu"},{"id":"hd1a","type":"mcq","q":"Trong hai cách trình bày dữ liệu ở Hình 7.1 và Hình 7.2, cách nào hiệu quả hơn để so sánh trực quan số học sinh quan tâm các nội dung Tin học?","k":"<b>Biểu đồ</b> giúp so sánh trực quan: chiều cao các cột cho thấy ngay nội dung nào được quan tâm nhiều nhất, ít nhất.","o":["Trình bày bằng bảng (Hình 7.1).","Trình bày bằng biểu đồ (Hình 7.2).","Hai cách như nhau.","Không cách nào so sánh được."],"a":1},{"id":"hd1b","type":"mcq","q":"Nếu cần so sánh tỉ lệ phần trăm số học sinh của mỗi nội dung Tin học trên tổng số học sinh được khảo sát, em sẽ dùng cách nào để thể hiện dữ liệu?","k":"<b>Biểu đồ hình quạt tròn</b> rất hữu ích khi cần so sánh các phần với tổng thể (Hình 7.4).","o":["Biểu đồ cột.","Biểu đồ đoạn thẳng.","Biểu đồ hình quạt tròn.","Bảng dữ liệu không có tổng."],"a":2},{"id":"loai","type":"match","q":"Đọc mục 1 (SGK trang 32–33). Mỗi tình huống dưới đây nên dùng loại biểu đồ nào?","k":"1 – a, 2 – b, 3 – c, 4 – b, 5 – a. <b>Cột</b>: so sánh dữ liệu; <b>đoạn thẳng</b>: xu hướng tăng giảm theo thời gian; <b>hình quạt tròn</b>: so sánh các phần với tổng thể.","items":[["1) So sánh số học sinh quan tâm mỗi nội dung Tin học",1],["2) Quan sát xu hướng số ứng dụng được tải về từ năm 2017 đến 2020",2],["3) Tỉ lệ phần trăm học sinh mỗi nội dung trên tổng số học sinh khảo sát",3],["4) Nhiệt độ trung bình của một thành phố qua 12 tháng",2],["5) So sánh điểm trung bình môn Tin học của 5 lớp",1]],"opts":["a) Biểu đồ cột","b) Biểu đồ đoạn thẳng","c) Biểu đồ hình quạt tròn"]},{"id":"it","type":"mcq","q":"Theo biểu đồ cột ở Hình 7.2, nội dung Tin học nào ít học sinh quan tâm nhất?","k":"Cột thấp nhất là <b>Soạn thảo văn bản</b> (2 học sinh). Cột cao nhất là Đồ hoạ máy tính (15), sau đó là Ngôn ngữ lập trình (8).","o":["Bảng tính điện tử","Soạn thảo văn bản","Phần mềm trình chiếu","Mạng máy tính"],"a":1},{"id":"p33","type":"open","q":"Em hãy nêu một số tình huống thực tế cần tạo biểu đồ.","k":"Ví dụ: biểu đồ cột so sánh điểm trung bình các môn học của em; biểu đồ đoạn thẳng theo dõi chiều cao, cân nặng của em qua các năm, nhiệt độ trong tuần; biểu đồ hình quạt tròn thể hiện tỉ lệ chi tiêu của gia đình, tỉ lệ học sinh giỏi, khá, trung bình của lớp.","label":"Câu hỏi tr.33"},{"id":"bc","type":"order","q":"Sắp xếp các bước tạo biểu đồ cột so sánh số học sinh quan tâm các nội dung Tin học (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → e → d → a → c</b>. Nhập dữ liệu → chọn B2:C8 → Insert/Insert Column or Bar Chart → Clustered Column → Chart Elements.","items":{"a":"Trong nhóm 2-D Column, chọn kiểu Clustered Column.","b":"Khởi động phần mềm bảng tính và nhập dữ liệu như Hình 7.1.","c":"Chọn biểu đồ, nháy nút Chart Elements để bổ sung thông tin.","d":"Trong thẻ Insert, nhóm Charts, chọn lệnh Insert Column or Bar Chart.","e":"Chọn vùng dữ liệu B2:C8."},"ans":["b","e","d","a","c"],"start":["a","b","c","d","e"]},{"id":"ce","type":"mcq","q":"Nút lệnh Chart Elements ở góc trên bên phải biểu đồ dùng để làm gì?","k":"Chart Elements dùng để <b>bổ sung thông tin</b> cho biểu đồ: Axes (trục), Chart Title (tiêu đề), Data Labels (nhãn dữ liệu), Gridlines (lưới), Legend (chú giải),…","o":["Xoá biểu đồ.","Bổ sung thông tin cho biểu đồ: tiêu đề, nhãn dữ liệu, chú giải, lưới,…","Đổi tên trang tính.","Sắp xếp dữ liệu."],"a":1},{"id":"pt","type":"mcq","q":"Khi tạo biểu đồ hình quạt tròn, để hiển thị nhãn dữ liệu là tỉ lệ phần trăm, em làm thế nào?","k":"Chọn <b>Chart Elements → Data Labels → More Options…</b>, trong khung Label Options đánh dấu chọn <b>Percentage</b>.","o":["Chart Elements → Data Labels → More Options… → đánh dấu chọn Percentage.","Chọn lệnh Sort.","Chọn lệnh Filter.","Nhập dấu % vào các ô dữ liệu."],"a":0},{"id":"pt2","type":"mcq","q":"Tổng số học sinh khảo sát là 41, trong đó 15 học sinh quan tâm Đồ hoạ máy tính. Trên biểu đồ hình quạt tròn, phần Đồ hoạ máy tính chiếm khoảng bao nhiêu phần trăm?","k":"15 : 41 × 100% ≈ <b>37%</b> (Hình 7.4). Phần mềm bảng tính tự tính tỉ lệ phần trăm khi chọn Percentage.","o":["15%","27%","37%","50%"],"a":2},{"id":"lt1a","type":"mcq","q":"Từ bảng tổng số học sinh sử dụng thiết bị số trong mỗi khoảng thời gian (Hình 7.8), em vẽ biểu đồ cột. Khoảng thời gian nào có nhiều học sinh nhất?","k":"Cột cao nhất là <b>1–2 giờ</b> (146 học sinh), tiếp theo là Dưới 1 giờ (131). Nhận xét: phần lớn học sinh khối 8 dùng thiết bị số dưới 2 giờ mỗi ngày; vẫn có 72 học sinh dùng 3–4 giờ và 12 học sinh từ 5 giờ trở lên – cần chú ý.","o":["Không sử dụng","Dưới 1 giờ","1–2 giờ","3–4 giờ"],"a":2},{"id":"lt1b","type":"mcq","q":"Tổng số học sinh khảo sát là 429. Trên biểu đồ hình quạt tròn, phần “Từ 5 giờ trở lên” (12 học sinh) chiếm khoảng bao nhiêu phần trăm?","k":"12 : 429 × 100% ≈ <b>2,8%</b> (khoảng 3%). Các phần khác: Không sử dụng ≈ 16%, Dưới 1 giờ ≈ 31%, 1–2 giờ ≈ 34%, 3–4 giờ ≈ 17%.","o":["Khoảng 3%","Khoảng 12%","Khoảng 17%","Khoảng 34%"],"a":0},{"id":"lt2a","type":"mcq","q":"Từ biểu đồ Hình 7.9, em có nhận xét gì về doanh thu công nghiệp phần mềm giai đoạn 2016 – 2020?","k":"Doanh thu <b>tăng liên tục</b> qua các năm: 3 038 → 3 779 → 4 447 → 4 932 → 5 439 triệu USD; năm 2020 gần gấp 1,8 lần năm 2016.","o":["Giảm dần qua các năm.","Tăng liên tục qua các năm, từ 3 038 lên 5 439 triệu USD.","Không thay đổi.","Tăng rồi giảm."],"a":1},{"id":"lt2bc","type":"open","q":"Tạo bảng dữ liệu trong phần mềm bảng tính từ biểu đồ Hình 7.9, rồi tạo biểu đồ cột từ bảng dữ liệu đó. Ghi lại vùng dữ liệu em đã chọn và kiểu biểu đồ.","k":"Bảng hai cột: <b>Năm</b> (2016–2020) và <b>Doanh thu (triệu USD)</b> (3038, 3779, 4447, 4932, 5439). Chọn vùng dữ liệu (ví dụ A1:B6) → Insert → Insert Column or Bar Chart → Clustered Column. Lưu ý: nhập năm dạng văn bản hoặc chỉ chọn cột Doanh thu rồi đặt nhãn trục để năm không bị vẽ thành một cột số liệu.","label":"Luyện tập 2b, c"},{"id":"vd1","type":"open","q":"Từ bảng dữ liệu doanh thu công nghiệp phần mềm giai đoạn 2016 – 2020 đã tạo ở Luyện tập câu 2, em hãy tạo biểu đồ đoạn thẳng, từ đó nhận xét xu hướng thay đổi của dữ liệu.","k":"Chọn vùng dữ liệu → Insert → <b>Insert Line or Area Chart</b> → Line. Đường biểu diễn <b>đi lên liên tục</b>: doanh thu có xu hướng tăng đều; mức tăng mạnh nhất là 2016–2017 (+741) và 2017–2018 (+668) triệu USD.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Biểu đồ là cách minh hoạ dữ liệu trực quan. Nhờ biểu đồ, em dễ dàng so sánh, nhận định xu hướng thay đổi của dữ liệu.</li><li>Cần sử dụng loại biểu đồ phù hợp với mục đích của việc biểu diễn và thể hiện dữ liệu.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Tạo biểu đồ: chọn vùng dữ liệu → thẻ <b>Insert</b>, nhóm <b>Charts</b> → chọn loại, kiểu biểu đồ.</li><li>Bổ sung thông tin: chọn biểu đồ → <b>Chart Elements</b> (tiêu đề, nhãn dữ liệu, chú giải,…).</li><li>Biểu đồ hình quạt tròn: Data Labels → More Options… → <b>Percentage</b> để hiện tỉ lệ phần trăm.</li></ul>"}]},"tin8-cau-truc-dieu-khien":{"id":"tin8-bai14","ten":"Bài 14. Cấu trúc điều khiển","cau":[{"id":"kd1","type":"open","q":"Ở lớp 6, chúng ta đã biết cách biểu diễn thuật toán bằng cách sử dụng các cấu trúc điều khiển cơ bản. Đó là những cấu trúc nào? Theo em, trong ngôn ngữ lập trình Scratch có cách nào để biểu diễn các cấu trúc đó không?","k":"Ba cấu trúc điều khiển cơ bản: <b>tuần tự</b>, <b>rẽ nhánh</b>, <b>lặp</b>. Scratch có các khối lệnh tương ứng: lắp ghép các khối từ trên xuống (tuần tự), khối <b>nếu … thì</b> (rẽ nhánh), khối <b>lặp lại</b> (lặp).","label":"Khởi động"},{"id":"hd1","type":"open","q":"Máy tính lấy ngẫu nhiên một số bí mật trong khoảng từ 1 đến 100. Em được đoán nhiều lần cho đến khi đoán đúng; mỗi lần đoán sai, máy tính cho biết số em đoán là nhỏ hơn hay lớn hơn số bí mật. Hãy mô tả kịch bản của trò chơi dưới dạng một thuật toán.","k":"1) Máy lấy ngẫu nhiên số bí mật (1–100). 2) Hỏi, nhận số người chơi đoán (trả lời). 3) Lặp cho đến khi trả lời = số bí mật: nếu trả lời &lt; số bí mật thì báo “Quá thấp”, ngược lại báo “Quá cao”; hỏi lại. 4) Thông báo “HOAN HÔ!”, kết thúc.","label":"HĐ1 – Trò chơi Đoán số"},{"id":"tt","type":"order","q":"Sắp xếp các bước của thuật toán đọc và hiển thị dữ liệu (Hình 14.1a) theo đúng thứ tự.","k":"Các bước thực hiện lần lượt từ trên xuống dưới: Bắt đầu → gán số bí mật → hỏi, nhận trả lời → hiển thị số bí mật → hiển thị trả lời → Kết thúc. Đó là <b>cấu trúc tuần tự</b>.","items":{"a":"Bắt đầu.","b":"Gán cho số bí mật một giá trị ngẫu nhiên trong khoảng từ 1 đến 100.","c":"Hỏi và nhận giá trị từ bàn phím, lưu vào biến trả lời.","d":"Hiển thị số bí mật trong 2 giây.","e":"Hiển thị trả lời trong 2 giây.","f":"Kết thúc."},"ans":["a","b","c","d","e","f"],"start":["d","a","f","c","b","e"]},{"id":"rn","type":"mcq","q":"Số bí mật là 45, người chơi nhập 30. Thuật toán ở Hình 14.2 thông báo gì?","k":"30 ≠ 45 nên kiểm tra tiếp; 30 &lt; 45 đúng → <b>“Quá thấp”</b>. Không cần kiểm tra trường hợp “lớn hơn” vì ba trường hợp loại trừ lẫn nhau.","o":["“Quá thấp”","“Quá cao”","“HOAN HÔ!”","Không thông báo gì"],"a":0},{"id":"ct","type":"sort","q":"Mỗi khối lệnh hoặc cách viết dưới đây thể hiện cấu trúc điều khiển nào?","k":"Tuần tự: lắp ghép các khối theo trình tự. Rẽ nhánh: <b>nếu … thì</b> (dạng khuyết), <b>nếu … thì … nếu không thì</b> (dạng đầy đủ). Lặp: <b>lặp lại n</b>, <b>liên tục</b>, <b>lặp lại cho đến khi</b>.","cats":["Tuần tự","Rẽ nhánh","Lặp"],"items":[["Lắp ghép các khối lệnh theo trình tự từ trên xuống dưới",0],["nếu ⟨ ⟩ thì",1],["nếu ⟨ ⟩ thì … nếu không thì …",1],["lặp lại 10",2],["liên tục",2],["lặp lại cho đến khi ⟨ ⟩",2]]},{"id":"lap","type":"match","q":"Ghép mỗi khối lệnh lặp trong Scratch với dạng lặp tương ứng (Hình 14.4).","k":"lặp lại 10 – a; liên tục – b; lặp lại cho đến khi – c (dừng khi điều kiện đúng).","items":[["lặp lại 10",1],["liên tục",2],["lặp lại cho đến khi ⟨trả lời = số bí mật⟩",3]],"opts":["a) Lặp với số lần định trước","b) Lặp vô hạn","c) Lặp có điều kiện kết thúc"]},{"id":"p82","type":"mcq","q":"Cấu trúc lặp nào sau đây KHÔNG được cho trước trong các nhóm lệnh của Scratch?","k":"<b>D</b>. Scratch có lặp lại n lần, liên tục và <b>lặp lại cho đến khi</b> (kiểm tra điều kiện <b>trước</b> mỗi lần thực hiện); không có sẵn khối kiểm tra điều kiện sau khi thực hiện.","o":["Lặp một khối lệnh với số lần định trước.","Lặp một khối lệnh vô hạn lần.","Lặp với điều kiện được kiểm tra trước khi thực hiện khối lệnh.","Lặp với điều kiện được kiểm tra sau khi thực hiện khối lệnh."],"a":3},{"id":"nv1","type":"mcq","q":"Trong chương trình Hình 14.7, vòng lặp “lặp lại cho đến khi ⟨trả lời = số bí mật⟩” kết thúc khi nào?","k":"Vòng lặp chỉ thực hiện khi người chơi đoán sai; <b>đoán đúng</b> là điều kiện kết thúc vòng lặp, sau đó máy nói “HOAN HÔ!”.","o":["Khi người chơi đoán đúng số bí mật.","Sau 10 lần đoán.","Khi người chơi đoán sai.","Không bao giờ kết thúc."],"a":0},{"id":"nv2","type":"open","q":"Chơi trò chơi Đoán số vài lần. Em cần nhiều nhất bao nhiêu lần đoán để tìm được số bí mật? Em đã đoán theo chiến thuật nào?","k":"Đoán số ở giữa khoảng còn lại (50, rồi 25 hoặc 75,…) – giống <b>tìm kiếm nhị phân</b> (Tin 7, Bài 15): mỗi lần loại một nửa, nhiều nhất <b>7</b> lần với 100 số.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"match","q":"Ghép mỗi đoạn lệnh ở Bảng 14.1 với kết quả tương ứng mà đoạn lệnh đó vẽ.","k":"a – 2 (bốn cạnh); b – 3 (năm cạnh); c – 4 (sáu cạnh); d – 1 (ba cạnh). Số lần lặp = số cạnh, góc quay = 360 : số cạnh.","items":[["a) lặp lại 4: di chuyển 100, xoay 90",2],["b) lặp lại 5: di chuyển 100, xoay 72",3],["c) lặp lại 6: di chuyển 100, xoay 60",4],["d) lặp lại 3: di chuyển 100, xoay 120",1]],"opts":["1) Hình ba cạnh","2) Hình bốn cạnh","3) Hình năm cạnh","4) Hình sáu cạnh"]},{"id":"vd1","type":"match","q":"Ghép các khối lệnh a, b, c, d (Hình 14.8) vào các vị trí 1, 2, 3, 4 để được chương trình giải phương trình ax + b = 0 với a, b nhập từ bàn phím.","k":"1 – b (nhập a, b); 2 – d (kiểm tra a = 0); 3 – c (a = 0: vô số nghiệm hoặc vô nghiệm); 4 – a (a ≠ 0: nghiệm −b/a).","items":[["Vị trí 1",2],["Vị trí 2",4],["Vị trí 3",3],["Vị trí 4",1]],"opts":["a) nói nghiệm của phương trình là −b/a","b) hỏi và đặt hệ số a, b","c) nếu b = 0 thì vô số nghiệm, nếu không thì vô nghiệm","d) nếu a = 0 thì [3] nếu không thì [4]"]},{"id":"vd2","type":"order","q":"Sắp xếp các khối lệnh của Hình 14.10 (theo số thứ tự) thành chương trình tính ước chung lớn nhất của hai số nguyên không âm, theo sơ đồ khối Hình 14.9.","k":"7 → 5 → 6 → 3 { 9 { 1 } nếu không thì { 2 } } → 4 → 8. Khi a × b = 0 thì một số bằng 0, số còn lại (= a + b) là ước chung lớn nhất.","items":{"k7":"7) Khi bấm vào lá cờ xanh","k5":"5) hỏi a và đợi; đặt a thành trả lời","k6":"6) hỏi b và đợi; đặt b thành trả lời","k3":"3) lặp lại cho đến khi ⟨a × b = 0⟩","k9":"9) nếu ⟨a > b⟩ thì … nếu không thì …","k1":"1) đặt a thành (a chia lấy dư b) – trong nhánh “thì”","k2":"2) đặt b thành (b chia lấy dư a) – trong nhánh “nếu không thì”","k4":"4) nói (a + b) trong 5 giây","k8":"8) dừng lại tất cả"},"ans":["k7","k5","k6","k3","k9","k1","k2","k4","k8"],"start":["k1","k2","k3","k4","k5","k6","k7","k8","k9"]}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Cấu trúc tuần tự</b> được thể hiện bằng cách lắp ghép các khối lệnh theo trình tự của các hoạt động, từ trên xuống dưới.</li><li><b>Cấu trúc rẽ nhánh</b> có hai dạng: dạng khuyết và dạng đầy đủ.</li><li><b>Cấu trúc lặp</b> có ba dạng: lặp với số lần định trước, lặp vô hạn và lặp có điều kiện kết thúc.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Số bí mật: <b>đặt số bí mật thành lấy ngẫu nhiên từ 1 đến 100</b>.</li><li>Lặp đến khi đoán đúng: <b>lặp lại cho đến khi ⟨trả lời = số bí mật⟩</b>, bên trong là <b>nếu ⟨trả lời &lt; số bí mật⟩ thì … nếu không thì …</b>.</li></ul>"}]},"tin8-danh-sach-hinh-anh":{"id":"tin8-bai8a","ten":"Bài 8a. Làm việc với danh sách dạng liệt kê và hình ảnh trong văn bản","cau":[{"id":"kd1","type":"open","q":"Phiếu khảo sát của bạn An có một danh sách các nội dung Tin học được đánh số thứ tự. Theo em, An có cần gõ từng số thứ tự không? Nếu danh sách có hàng trăm mục thì làm thế nào để tiết kiệm thời gian và không bị nhầm thứ tự?","k":"Không cần gõ tay. Dùng chức năng <b>danh sách có thứ tự</b> (Numbering) của phần mềm soạn thảo: số thứ tự được <b>tự động tạo</b> và <b>tự động cập nhật</b> khi thêm, bớt mục, nên nhanh và không nhầm.","label":"Mở đầu"},{"id":"hd1","type":"mcq","q":"Quan sát Hình 8a.2 và Hình 8a.3. Cách trình bày nào giúp người đọc dễ theo dõi các công việc của dự án hơn?","k":"Cách trình bày <b>dạng danh sách liệt kê</b> (Hình 8a.3) chia nhỏ nội dung thành từng mục, có số thứ tự và dấu đầu dòng, giúp văn bản <b>rõ ràng</b>, người đọc tìm thông tin <b>nhanh, dễ dàng</b>.","o":["Cách viết liền thành đoạn văn (Hình 8a.2).","Cách trình bày dạng danh sách liệt kê (Hình 8a.3).","Hai cách như nhau.","Không cách nào dễ đọc."],"a":1},{"id":"kieu","type":"sort","q":"Đọc mục 1 (SGK trang 36–37). Nội dung nào nên trình bày bằng danh sách có thứ tự, nội dung nào chỉ cần danh sách dấu đầu dòng?","k":"Khi thứ tự <b>có ý nghĩa</b> (các bước, thứ hạng) dùng <b>danh sách có thứ tự</b> (mỗi mục bắt đầu bằng số hoặc chữ cái và dấu chấm hay dấu ngoặc đơn). Khi các mục <b>ngang hàng</b> dùng <b>danh sách dấu đầu dòng</b>.","cats":["Danh sách có thứ tự","Danh sách dấu đầu dòng"],"items":[["Các bước tắt máy tính an toàn",0],["Các món ăn em yêu thích",1],["Các bước nấu cơm bằng nồi cơm điện",0],["Đồ dùng cần mang khi đi dã ngoại",1],["Thứ hạng ba đội đứng đầu giải bóng đá",0]]},{"id":"p37a","type":"sort","q":"Mỗi phương án dưới đây đúng hay sai?","k":"Phương án <b>sai</b>: <b>B</b> (dấu đầu dòng và số thứ tự được <b>tự động</b> tạo và cập nhật) và <b>C</b> (có thể <b>kết hợp</b> cả hai kiểu trong một văn bản, như Hình 8a.3).","cats":["Đúng","Sai"],"items":[["A. Phần mềm soạn thảo văn bản cung cấp hai kiểu danh sách dạng liệt kê.",0],["B. Danh sách dạng liệt kê không tự động cập nhật khi thêm hoặc bớt đoạn văn.",1],["C. Chỉ có thể sử dụng một kiểu danh sách dạng liệt kê cho một văn bản.",1],["D. Có thể sử dụng kết hợp danh sách dấu đầu dòng và danh sách có thứ tự.",0]]},{"id":"p37b","type":"mcq","q":"Với danh sách có thứ tự gồm 4 mục (1. Ngôn ngữ lập trình; 2. Mạng máy tính; 3. Đồ hoạ máy tính; 4. Bảng tính điện tử), em đặt con trỏ soạn thảo ở cuối dòng thứ hai rồi nhấn phím Enter. Kết quả là:","k":"Nhấn Enter tạo một <b>mục mới</b> trong danh sách: mục mới mang số 3 (còn trống), Đồ hoạ máy tính thành 4, Bảng tính điện tử thành 5 – đúng như Hình 8a.4b. Thứ tự được <b>tự động cập nhật</b>.","o":["Danh sách không đổi, chỉ xuống dòng không có số.","Xuất hiện mục mới “3.” để trống; các mục sau tự đánh số lại thành 4 và 5.","Xuất hiện mục mới nhưng các mục sau vẫn giữ số 3 và 4.","Danh sách bị xoá số thứ tự."],"a":1},{"id":"hd2a","type":"open","q":"a) Tờ rơi ở Hình 8a.5 gồm những thông tin dạng nào? b) Tờ rơi ở Hình 8a.6 gồm những thông tin dạng nào?","k":"Tờ rơi Hình 8a.5 chỉ có thông tin dạng <b>văn bản</b> (chữ). Tờ rơi Hình 8a.6 có <b>văn bản</b>, <b>hình ảnh</b> (ảnh nền) và <b>hình đồ hoạ</b> (mũi tên, hình trang trí).","label":"HĐ2 – Câu a, b"},{"id":"hd2c","type":"open","q":"Em ấn tượng với tờ rơi nào hơn? Vì sao?","k":"Thường là tờ rơi <b>có hình minh hoạ</b> (Hình 8a.6): màu sắc bắt mắt, hình ảnh gợi chủ đề công nghệ, hình đồ hoạ làm nổi bật thông tin, thu hút người xem hơn.","label":"HĐ2 – Câu c"},{"id":"hd2d","type":"mcq","q":"Dùng phần mềm soạn thảo văn bản có tạo ra được sản phẩm như tờ rơi có hình minh hoạ (Hình 8a.6) không?","k":"<b>Có.</b> Phần mềm soạn thảo cung cấp <b>công cụ xử lí hình ảnh</b> (chèn, xoá, thay đổi kích thước, vị trí, lớp của ảnh) và thư viện <b>mẫu hình đồ hoạ</b> để vẽ hình trong văn bản.","o":["Không, phải dùng phần mềm vẽ chuyên dụng.","Có, phần mềm soạn thảo có công cụ xử lí hình ảnh và vẽ hình đồ hoạ.","Chỉ chèn được chữ.","Chỉ chèn được bảng."],"a":1},{"id":"p39","type":"mcq","q":"Phương án nào sau đây là SAI?","k":"Phương án <b>D</b> sai, vì phần mềm soạn thảo có thư viện mẫu hình đồ hoạ (Insert → Shapes) để vẽ hình trong văn bản.","o":["Có thể chèn hình ảnh vào văn bản để minh hoạ cho nội dung.","Có thể vẽ hình đồ hoạ trong phần mềm soạn thảo văn bản.","Có thể chèn thêm, xoá bỏ, thay đổi kích thước của hình ảnh và hình đồ hoạ trong văn bản.","Không thể vẽ hình đồ hoạ trong phần mềm soạn thảo văn bản."],"a":3},{"id":"nv1","type":"order","q":"Sắp xếp các bước tạo danh sách có thứ tự cho các nội dung trong Phiếu khảo sát (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → c</b>. Sau đó lưu tệp với tên PhieuKhaoSat.docx (File → Save).","items":{"a":"Nháy chuột vào hình tam giác nhỏ bên cạnh lệnh Numbering.","b":"Chọn các đoạn văn bản muốn tạo danh sách có thứ tự.","c":"Chọn kiểu danh sách có thứ tự (ví dụ 1. 2. 3.).","d":"Chọn thẻ Home."},"ans":["b","d","a","c"],"start":["a","b","c","d"]},{"id":"ki","type":"mcq","q":"Để nhập kí hiệu ô vuông ☐ ở cuối mỗi dòng của Phiếu khảo sát, em dùng lệnh nào?","k":"Chọn <b>Insert → Symbol</b> để nhập các kí hiệu đặc biệt như ☐.","o":["Insert/Symbol","Home/Numbering","Insert/Picture","File/Save"],"a":0},{"id":"nv2a","type":"mcq","q":"Ảnh nền vừa chèn che mất (hoặc đẩy xuống) nội dung tờ rơi. Để ảnh nằm ở lớp dưới, văn bản nằm ở lớp trên, em chọn ảnh, chọn Format, trong nhóm Arrange chọn Wrap Text rồi chọn:","k":"Chọn <b>Behind Text</b> để ảnh nằm sau chữ. Sau đó kéo thả hình vuông nhỏ ở góc dưới bên phải ảnh để ảnh phủ kín tờ rơi. Với ảnh nhỏ ở góc trên bên phải, chọn <b>Square</b> để đặt đúng vị trí.","o":["Square","In Front of Text","Behind Text","In Line with Text"],"a":2},{"id":"nv2b","type":"mcq","q":"Để vẽ hình mũi tên cong trên tờ rơi rồi tô màu vàng cho hình, em dùng các lệnh nào?","k":"Vẽ hình: <b>Insert → Shapes → Block Arrows</b> (ví dụ Arrow: Curved Right), kéo thả chuột để vẽ. Đổi màu: chọn hình, <b>Format → Shape Styles → Shape Fill</b> → màu vàng. Muốn xoá hình: chọn hình rồi nhấn Delete.","o":["Insert → Shapes → nhóm Block Arrows; rồi Format → Shape Fill → chọn màu vàng.","Home → Numbering; rồi Font Color.","Insert → Picture; rồi Wrap Text.","Insert → Symbol; rồi Highlight."],"a":0},{"id":"nv2c","type":"open","q":"Báo cáo kết quả Nhiệm vụ 2: tờ rơi TuyenThanhVien.docx của em có những đối tượng nào (ảnh nền, văn bản, hình đồ hoạ, ảnh nhỏ)? Em đã chỉnh sửa vị trí, màu sắc những gì?","k":"Ví dụ: ảnh nền phủ kín tờ rơi (Behind Text); dòng chữ “TUYỂN THÀNH VIÊN” đổi màu vàng, đặt giữa hình cầu; hai hình mũi tên cong màu vàng; ảnh nhỏ ở góc trên bên phải (Square); thông tin thời gian, địa điểm ở dưới. Lưu với tên TuyenThanhVien.docx.","label":"Thực hành NV2 – Kết quả"},{"id":"lt1","type":"open","q":"Sử dụng phần mềm soạn thảo văn bản nhập dữ liệu cho dự án Thành lập CLB Tin học, tạo danh sách dạng liệt kê theo mẫu như Hình 8a.3 (kết hợp danh sách có thứ tự và danh sách dấu đầu dòng) và lưu tệp với tên CLBTinhoc.docx. Em đã dùng kiểu danh sách nào cho những dòng nào?","k":"Các nhóm công việc lớn (1) Khảo sát, (2) Xử lí dữ liệu, (3) Quảng cáo và tuyển thành viên, (4) Tổ chức buổi ra mắt dùng <b>danh sách có thứ tự</b>; các công việc nhỏ bên trong dùng <b>danh sách dấu đầu dòng</b> (thụt vào bằng Increase Indent hoặc phím Tab).","label":"Luyện tập"},{"id":"vd1","type":"open","q":"Ngoài các mẫu có sẵn, em có thể tự tạo mẫu dấu đầu dòng, mẫu thứ tự theo ý thích. Em hãy tìm hiểu cách làm và tạo ba mẫu dấu đầu dòng, mẫu thứ tự mới. Ghi lại cách làm.","k":"Dấu đầu dòng mới: mũi tên cạnh lệnh <b>Bullets</b> → <b>Define New Bullet…</b> → Symbol (chọn kí hiệu) hoặc Picture (chọn ảnh) → OK. Thứ tự mới: mũi tên cạnh lệnh <b>Numbering</b> → <b>Define New Number Format…</b> → chọn kiểu số, định dạng (ví dụ “Bước 1.”, “Phần I –”) → OK.","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Sử dụng phần mềm soạn thảo văn bản tạo một tờ rơi quảng cáo cho một CLB của trường (CLB Tiếng Anh, CLB Rubik, CLB bóng rổ,…), có sử dụng hình ảnh minh hoạ, hình đồ hoạ và mẫu dấu đầu dòng, mẫu thứ tự em đã tạo ở câu 1. Mô tả ngắn tờ rơi của em.","k":"Học sinh tự làm. Tờ rơi cần có: tên CLB nổi bật; ảnh minh hoạ (ghi nguồn hoặc tự chụp) đặt Behind Text hoặc Square; hình đồ hoạ (mũi tên, ngôi sao,…); danh sách lợi ích khi tham gia dùng dấu đầu dòng tự tạo; các bước đăng kí dùng danh sách có thứ tự; thời gian, địa điểm.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Phần mềm soạn thảo văn bản cung cấp hai kiểu danh sách dạng liệt kê: <b>danh sách dấu đầu dòng</b> và <b>danh sách có thứ tự</b>.</li><li>Dấu đầu dòng và thứ tự được <b>tự động tạo và cập nhật</b> khi thêm hoặc bớt đoạn văn bản.</li><li>Danh sách dạng liệt kê giúp trình bày văn bản <b>rõ ràng</b> và có tính thẩm mĩ.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Phần mềm soạn thảo văn bản cung cấp nhiều công cụ nâng cao để làm việc với <b>hình ảnh</b> và <b>hình đồ hoạ</b>.</li><li>Sử dụng các chức năng nâng cao, em có thể tạo được các sản phẩm có tính thẩm mĩ phục vụ nhu cầu thực tế.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Danh sách có thứ tự: Home → Numbering → chọn kiểu. Kí hiệu đặc biệt: Insert → Symbol.</li><li>Chèn ảnh: Insert → Picture; ảnh nằm dưới chữ: Format → Wrap Text → <b>Behind Text</b>.</li><li>Vẽ hình: Insert → Shapes; tô màu: Format → <b>Shape Fill</b>.</li></ul>"}]},"tin8-dao-duc-van-hoa-so":{"id":"tin8-bai4","ten":"Bài 4. Đạo đức và văn hoá trong sử dụng công nghệ kĩ thuật số","cau":[{"id":"kd1","type":"mcq","q":"Khoa chia sẻ cho An bức ảnh ruộng bậc thang mà mình đã chụp. Theo em, An nên làm theo cách nào?","k":"An nên làm theo <b>trường hợp 2</b>: An <b>xin phép</b> tác giả, <b>ghi rõ người chụp</b> và chú thích <b>trung thực</b>. Trường hợp 1 không tôn trọng quyền tác giả của Khoa và chú thích làm người xem hiểu nhầm là An đã đến nơi đó (không trung thực).","o":["Trường hợp 1: không hỏi ý kiến Khoa, tự chỉnh sửa ảnh, dùng làm nền cho ảnh của mình, đăng lên mạng xã hội với chú thích “Thật tuyệt khi được đến thăm nơi này”.","Trường hợp 2: xin phép Khoa, chỉnh sửa ảnh rồi đăng lên mạng xã hội với chú thích “Đất nước ta thật là đẹp (người chụp Lê Khoa)”."],"a":1},{"id":"kd2","type":"open","q":"Vì sao em chọn cách làm đó?","k":"Vì bức ảnh là sản phẩm của Khoa: dùng ảnh của người khác phải <b>xin phép</b> và <b>ghi nguồn</b>. Ngoài ra, chú thích phải <b>trung thực</b>, không làm người khác hiểu sai.","label":"Mở đầu – Vì sao?"},{"id":"hd1","type":"open","q":"Từ hiểu biết của em, hãy thảo luận với các bạn về một vài biểu hiện vi phạm đạo đức và pháp luật hay biểu hiện thiếu văn hoá khi sử dụng công nghệ kĩ thuật số.","k":"Ví dụ: quay phim trong rạp chiếu phim; chụp ảnh ở nơi không cho phép; ghi âm trái phép cuộc nói chuyện; tải bài hát, phim có bản quyền mà chưa được phép; sao chép thông tin trên mạng rồi coi là của mình; dùng phần mềm bẻ khoá; livestream, chia sẻ cảnh bạo lực học đường; đưa thông tin cá nhân của người khác lên mạng khi chưa được phép; chia sẻ trang web cổ vũ bạo lực, đánh bạc; bình luận thô tục, xúc phạm người khác.","label":"HĐ1 – Biểu hiện nào là vi phạm?"},{"id":"bh","type":"sort","q":"Đọc mục 1 (SGK trang 18–19). Mỗi hành động dưới đây có vi phạm đạo đức, pháp luật hay thiếu văn hoá không?","k":"Bốn hành động đầu là vi phạm. Nghe nhạc trên ứng dụng có bản quyền, dùng ảnh khi đã xin phép và ghi tên tác giả là <b>đúng đắn</b>.","cats":["Vi phạm","Không vi phạm"],"items":[["Quay phim trong rạp chiếu phim",0],["Chụp ảnh ở nơi có biển cấm chụp ảnh (Hình 4.1)",0],["Cài phần mềm đã bị bẻ khoá",0],["Phát trực tiếp (livestream) một vụ bạo lực học đường",0],["Nghe nhạc trên ứng dụng có bản quyền",1],["Dùng ảnh của bạn khi đã xin phép và ghi tên tác giả",1]]},{"id":"p19a","type":"mcq","q":"Hành động nào sau đây KHÔNG vi phạm đạo đức và pháp luật?","k":"Đĩa nhạc có bản quyền em đã mua là tài sản của em, <b>tặng cho người khác</b> là hợp pháp. Các hành động còn lại đều vi phạm.","o":["Đăng tải thông tin sai sự thật lên mạng.","Cố ý nghe, ghi âm trái phép các cuộc nói chuyện.","Tặng đĩa nhạc có bản quyền em đã mua cho người khác.","Tải một bài trình chiếu của người khác từ Internet và sử dụng như là của mình tạo ra."],"a":2},{"id":"p19b","type":"open","q":"Nêu một vài hành động chưa đúng của em khi sử dụng công nghệ kĩ thuật số mà em đã mắc phải. Nêu cách em sẽ phòng tránh hoặc từ bỏ vi phạm.","k":"Học sinh tự liên hệ. Ví dụ: tải phim lậu → chuyển sang xem trên ứng dụng có bản quyền; chép bài văn trên mạng nộp cho cô → tự viết, chỉ tham khảo và ghi nguồn; đăng ảnh bạn khi chưa hỏi → xin phép trước khi đăng; bình luận thiếu văn hoá → suy nghĩ trước khi viết.","label":"Câu hỏi tr.19 – câu 2"},{"id":"sp","type":"sort","q":"Đọc mục 2 (SGK trang 19–20). Khi tạo ra sản phẩm số, việc nào nên làm, việc nào không nên làm?","k":"Khi tạo sản phẩm số cần: <b>luôn trung thực</b> (không dùng tin giả, không sao chép, chỉnh sửa thông tin của người khác rồi coi là của mình); <b>dùng thông tin do mình tự tạo</b>, không dùng tài liệu có bản quyền nếu chưa mua hoặc chưa xin phép; <b>nội dung, hình thức</b> không vi phạm chuẩn mực đạo đức, văn hoá.","cats":["Nên làm","Không nên"],"items":[["Dùng ảnh, video do chính mình quay, chụp",0],["Ghi rõ nguồn khi trích dẫn thông tin của người khác",0],["Dùng thông tin giả, không đáng tin cậy cho hấp dẫn",1],["Sao chép bài viết của người khác rồi coi là của mình",1],["Dùng hình ảnh giật gân, ngôn ngữ thiếu lịch sự",1],["Mua hoặc xin phép trước khi dùng tài liệu có bản quyền",0]]},{"id":"p20a","type":"open","q":"Em có cảnh báo và lời khuyên gì với bạn trong tình huống: Bạn em quay video các bạn trong lớp có hành vi bạo lực và đăng lên mạng xã hội.","k":"<b>Cảnh báo:</b> đăng video bạo lực là vi phạm pháp luật, lan truyền hình ảnh xấu, làm tổn thương bạn bị đánh. <b>Lời khuyên:</b> gỡ video ngay; không quay, không chia sẻ cảnh bạo lực; khi thấy bạo lực hãy báo cho thầy cô, người lớn để can thiệp.","label":"Câu hỏi tr.20 – a"},{"id":"p20b","type":"open","q":"Em có cảnh báo và lời khuyên gì với bạn trong tình huống: Một người bạn sử dụng ảnh em chụp để tham gia một cuộc thi ảnh nhưng chưa có sự đồng ý của em.","k":"<b>Cảnh báo:</b> dùng ảnh của người khác dự thi khi chưa được phép là <b>vi phạm quyền tác giả</b>, không trung thực, có thể bị loại khỏi cuộc thi. <b>Lời khuyên:</b> rút ảnh khỏi cuộc thi; muốn dùng thì phải xin phép và ghi đúng tên tác giả; tốt nhất là tự chụp ảnh để dự thi.","label":"Câu hỏi tr.20 – b"},{"id":"lt1","type":"sort","q":"Em hãy xác định các hành động dưới đây có phạm hay không vi phạm đạo đức, pháp luật và văn hoá khi sử dụng công nghệ kĩ thuật số.","k":"Vi phạm: <b>a, c, e, f</b> (buôn bán động vật hoang dã, bạo lực, cờ bạc, vi phạm bản quyền). Không vi phạm: <b>b, d</b>.","cats":["Vi phạm","Không vi phạm"],"items":[["a) Chia sẻ thông tin mua bán động vật hoang dã quý hiếm.",0],["b) Tạo một trang cá nhân để chia sẻ những kinh nghiệm học tập của mình.",1],["c) Quay và lan truyền video bạo lực học đường.",0],["d) Sáng tác một bài thơ về lớp và gửi bạn bè cùng đọc.",1],["e) Tham gia cá cược bóng đá qua Internet.",0],["f) Chia sẻ địa chỉ một website có chứa các bộ phim không có bản quyền sử dụng.",0]]},{"id":"vd1","type":"open","q":"Em hãy tạo một sản phẩm số theo cách sáng tạo để hướng dẫn các bạn hiểu đúng về việc sử dụng công nghệ kĩ thuật số, bảo đảm thể hiện được đạo đức, tính văn hoá và không vi phạm pháp luật. Ghi lại: loại sản phẩm, nội dung chính, nguồn hình ảnh, tư liệu em dùng.","k":"Ví dụ: <b>poster</b> “5 điều nên làm khi dùng mạng xã hội”, <b>video ngắn</b> tự quay, <b>truyện tranh</b> tự vẽ, bài trình chiếu. Nội dung: xin phép khi dùng ảnh của người khác, ghi nguồn, không chia sẻ tin giả, không bình luận thô tục, không dùng phần mềm lậu. Hình ảnh <b>tự chụp, tự vẽ</b> hoặc lấy từ nguồn cho phép sử dụng miễn phí và ghi nguồn.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<p>Ba điều lưu ý để tránh các vi phạm khi sử dụng công nghệ kĩ thuật số:</p><ul><li>Tìm hiểu thông tin, trang bị cho mình những kiến thức cần thiết.</li><li>Chỉ sử dụng những sản phẩm số khi có sự cho phép của tác giả hoặc có bản quyền sử dụng.</li><li>Hầu hết thông tin trên Internet là có bản quyền.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Cần bảo đảm tính văn hoá, thể hiện được đạo đức và tuân thủ pháp luật khi tạo ra các sản phẩm số, giúp tránh được việc lan truyền thông tin sai trái, đồng thời góp phần tạo ra một xã hội số lành mạnh và hợp pháp.</li></ul>"}]},"tin8-dau-trang-chan-trang":{"id":"tin8-bai9a","ten":"Bài 9a. Tạo đầu trang, chân trang cho văn bản","cau":[{"id":"kd1","type":"open","q":"Quan sát Hình 9a.1 và Hình 9a.2, tìm những phần khác nhau trong hai trang văn bản. Trong các cuốn sách, truyện em đã đọc có các thành phần văn bản đó không? Tác dụng của chúng là gì?","k":"Hình 9a.2 có thêm dòng <b>“Tài liệu dự án”</b> ở trên cùng bên phải, <b>số trang “1”</b> và dòng <b>“CLB Tin học”</b> ở dưới cùng. Sách, truyện thường có số trang, tên sách, tên chương ở trên/dưới mỗi trang: giúp người đọc biết đang đọc tài liệu nào, trang nào, dễ tìm và dễ theo dõi.","label":"Khởi động"},{"id":"hd1","type":"mcq","q":"Trong trang văn bản ở Hình 9a.2, phần văn bản màu cam có nội dung “Tài liệu dự án” và “CLB Tin học” cho em biết điều gì?","k":"Cho biết tên văn bản là <b>“Tài liệu dự án”</b> và văn bản thuộc về <b>“CLB Tin học”</b>. Thông tin này xuất hiện ở <b>tất cả các trang</b>.","o":["Văn bản là một tài liệu dự án, thuộc về CLB Tin học.","Tên tác giả của văn bản.","Số trang của văn bản.","Ngày tạo văn bản."],"a":0},{"id":"vitri","type":"sort","q":"Mỗi thông tin dưới đây thường đặt ở đầu trang, chân trang hay ở phần nội dung văn bản?","k":"Đầu trang, chân trang chứa <b>thông tin ngắn gọn</b> lặp lại ở mọi trang: số trang, tên văn bản, tên tác giả, chú thích, logo. Nội dung chính nằm ở phần <b>nội dung văn bản</b>.","cats":["Đầu trang, chân trang","Nội dung văn bản"],"items":[["Số trang",0],["Tên văn bản, tên tác giả",0],["Danh sách các công việc cần làm của dự án",1],["Tên tổ chức (CLB Tin học), logo",0],["Câu hỏi của Phiếu khảo sát",1],["Chú thích ngắn",0]]},{"id":"p43","type":"sort","q":"Mỗi phương án dưới đây đúng hay sai?","k":"Phương án <b>đúng: B, C</b>. A sai vì đầu trang, chân trang là <b>phần riêng biệt</b> với văn bản chính (nằm ở lề trên, lề dưới). D sai vì đầu trang, chân trang <b>có thể chứa hình ảnh</b>, hình đồ hoạ.","cats":["Đúng","Sai"],"items":[["A. Đầu trang và chân trang là đoạn văn bản đầu tiên và cuối cùng trong một trang.",1],["B. Thông tin ở phần đầu trang và chân trang thường ngắn gọn và được tự động thêm vào tất cả các trang trong văn bản sau khi tạo.",0],["C. Đầu trang và chân trang là văn bản hoặc hình ảnh được chèn vào lề trên và lề dưới.",0],["D. Không thể đưa hình ảnh vào đầu trang và chân trang.",1]]},{"id":"hd2","type":"open","q":"Trong các cuốn sách giáo khoa, sách văn học, truyện mà em đọc, em có nhìn thấy số trang của sách không? Số trang sách thường nằm ở đâu?","k":"Có. Số trang thường nằm ở <b>chân trang</b> (giữa hoặc góc ngoài) hoặc ở <b>đầu trang</b>. Ví dụ SGK Tin học 8 đặt số trang ở chân trang, góc ngoài.","label":"HĐ2 – Số trang trong văn bản"},{"id":"p44","type":"mcq","q":"Em hãy chọn phương án SAI trong các phương án sau:","k":"<b>D</b> sai: phần mềm soạn thảo có chức năng <b>đánh số trang tự động</b> (Insert → Page Number).","o":["Đánh số trang giúp người đọc biết độ dài của văn bản (nhìn số trang cuối).","Đánh số trang, cùng với mục lục, giúp người đọc dễ dàng tìm thấy các phần cụ thể của văn bản.","Đánh số trang cho phép trích dẫn một trang cụ thể của văn bản.","Phần mềm soạn thảo văn bản không có chức năng đánh số trang tự động."],"a":3},{"id":"nv1","type":"order","q":"Sắp xếp các bước thực hiện nhiệm vụ (văn bản như Hình 9a.5) theo đúng thứ tự (dùng nút ↑ ↓).","k":"Mở tệp → đánh số trang (Bottom of Page / Plain Number 2) → Header → Footer → <b>Close Header and Footer</b> → lưu văn bản.","items":{"a":"Mở tệp CLBTinhoc.docx, bổ sung nội dung.","b":"Insert → Page Number → Bottom of Page → Plain Number 2.","c":"Insert → Header → Blank, nhập “Tài liệu dự án”, căn phải, chữ nghiêng, màu cam.","d":"Insert → Footer → Blank, nhập “CLB Tin học”, căn phải, chữ nghiêng, màu cam.","e":"Chọn Close Header and Footer.","f":"Lưu văn bản."},"ans":["a","b","c","d","e","f"],"start":["c","a","f","b","e","d"]},{"id":"nv2","type":"mcq","q":"Chọn Page Number → Bottom of Page → Plain Number 2 thì số trang được đặt ở đâu?","k":"<b>Bottom of Page</b> = chân trang; <b>Plain Number 2</b> = ở <b>giữa</b>. (Plain Number 1: bên trái, Plain Number 3: bên phải.)","o":["Ở giữa, bên dưới trang văn bản (chân trang).","Ở giữa, bên trên trang văn bản (đầu trang).","Bên trái chân trang.","Bên phải đầu trang."],"a":0},{"id":"nv3","type":"open","q":"Báo cáo kết quả: văn bản CLBTinhoc.docx của em có số trang ở đâu? Đầu trang, chân trang có nội dung gì, định dạng thế nào? Khi thêm trang mới, đầu trang và chân trang có tự xuất hiện không?","k":"Số trang ở <b>giữa chân trang</b>; đầu trang “Tài liệu dự án”, chân trang “CLB Tin học” đều căn phải, chữ nghiêng, màu cam. Trang mới <b>tự động</b> có đầu trang, chân trang và số trang tăng dần.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Mở tệp CLBTinhoc.docx và: a) Bổ sung thêm tên người hoặc tên nhóm thực hiện dự án vào đầu trang. b) Đặt lại số trang vào vị trí bên trái của chân trang. Em đã làm thế nào?","k":"a) Nháy đúp vào đầu trang (hoặc Header → Edit Header), nhập tên nhóm ở bên trái (có thể dùng mẫu <b>Blank (Three Columns)</b> hoặc phím Tab). b) Insert → Page Number → <b>Bottom of Page → Plain Number 1</b>.","label":"Luyện tập"},{"id":"vd1","type":"open","q":"Tìm hiểu cách thêm hình ảnh, hình đồ hoạ vào đầu trang và chân trang rồi bổ sung vào đầu trang và chân trang trong tệp CLBTinhoc.docx một đường thẳng theo mẫu như Hình 9a.7. Em đã làm thế nào?","k":"Nháy đúp vào đầu trang (chân trang) để sửa, rồi dùng <b>Insert → Pictures</b> (chèn ảnh) hoặc <b>Insert → Shapes → Line</b> (vẽ đường thẳng, giữ Shift để thẳng), đổi màu bằng Shape Outline; cuối cùng chọn Close Header and Footer.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Đầu trang và chân trang</b> là phần riêng biệt với văn bản chính; thường chứa thông tin ngắn gọn; thường được <b>tự động thêm vào tất cả các trang</b> trong văn bản sau khi tạo.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Số trang</b> trong văn bản được <b>đánh tự động</b> và được đặt ở đầu trang hoặc chân trang.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Insert → nhóm <b>Header &amp; Footer</b>: <b>Header</b> (đầu trang), <b>Footer</b> (chân trang), <b>Page Number</b> (số trang).</li><li>Có thể đổi vị trí, căn lề, phông chữ, cỡ chữ, màu sắc… cho đầu trang, chân trang giống như với phần nội dung.</li></ul>"}]},"tin8-go-loi":{"id":"tin8-bai15","ten":"Bài 15. Gỡ lỗi","cau":[{"id":"kd1","type":"open","q":"An nghĩ đã tạo xong chương trình trò chơi Đoán số ở Bài 14. Khoa nói: “Chưa xong đâu, chúng ta cần phải thực hiện một việc nữa, đó là gỡ lỗi.” Theo em, gỡ lỗi là làm những gì?","k":"Gỡ lỗi là <b>chạy thử</b> chương trình để <b>phát hiện</b> lỗi, <b>tìm</b> lệnh gây ra lỗi và <b>sửa</b> lỗi, để chương trình chạy đúng kịch bản.","label":"Khởi động"},{"id":"hd1","type":"open","q":"Chương trình Hình 15.1 được bổ sung biến số lần đoán để đếm và thông báo số lần người chơi đoán khi đoán đúng. Hãy kiểm tra trò chơi (chạy thử hoặc bấm Kiểm thử trên mô phỏng) và mô tả tình huống chương trình chạy không đúng kịch bản (nếu có).","k":"Khi chạy thử, số lần đoán mà máy tính hiển thị <b>luôn kém số lần thực tế một đơn vị</b>. Ví dụ đoán đúng ngay lần đầu thì máy báo “Số lần đoán: 0”.","label":"HĐ1 – Đếm số lần đoán"},{"id":"hd2","type":"mcq","q":"Chương trình đã cho trong Hình 15.1 không hoạt động được hay nó có hoạt động nhưng đã thực hiện không đúng kịch bản?","k":"Máy tính vẫn hỏi và trả lời theo các khối lệnh, nhưng <b>số lần đoán</b> hiển thị không đúng với số lần thực tế → chương trình <b>làm việc sai</b>.","o":["Có hoạt động (vẫn hỏi, trả lời, thông báo) nhưng thực hiện không đúng kịch bản: số lần đoán sai.","Không hoạt động được.","Hoạt động hoàn toàn đúng.","Chỉ hoạt động khi đoán đúng ngay lần đầu."],"a":0},{"id":"loai","type":"sort","q":"Mỗi lỗi dưới đây là lỗi cú pháp hay lỗi lôgic?","k":"<b>Lỗi cú pháp</b>: viết sai quy tắc, chương trình không hoạt động. <b>Lỗi lôgic</b> (lỗi ngữ nghĩa): viết đúng cú pháp nhưng thực hiện sai so với kịch bản.","cats":["Lỗi cú pháp","Lỗi lôgic"],"items":[["Câu lệnh viết sai quy tắc của ngôn ngữ lập trình, chương trình không hoạt động",0],["Gõ sai tên lệnh (viết prnt thay cho print) trong ngôn ngữ lập trình dạng văn bản",0],["Số lần đoán hiển thị kém số lần thực tế 1 đơn vị",1],["Dùng phép “+” thay cho “kết hợp” khi ghép chữ với số",1],["Trò chơi cho đoán quá 7 lần dù kịch bản chỉ cho 7 lần",1]]},{"id":"p87","type":"mcq","q":"Chọn phát biểu đúng nhất về hoạt động gỡ lỗi.","k":"<b>D</b>. Gỡ lỗi gồm cả phát hiện <b>và loại bỏ</b> lỗi, là một phần quan trọng của lập trình.","o":["Gỡ lỗi là phát hiện và loại bỏ lỗi. Trong lập trình, không nhất thiết phải gỡ lỗi.","Gỡ lỗi là chạy thử chương trình để phát hiện lỗi. Trong lập trình, không nhất thiết phải gỡ lỗi.","Gỡ lỗi là chạy thử chương trình để phát hiện lỗi. Gỡ lỗi là một phần quan trọng của lập trình.","Gỡ lỗi là phát hiện và loại bỏ lỗi. Gỡ lỗi là một phần quan trọng của lập trình."],"a":3},{"id":"hd3a","type":"mcq","q":"Theo kịch bản, biến số lần đoán sẽ thay đổi trong tình huống nào?","k":"Số lần đoán phải <b>tăng 1</b> mỗi khi người chơi nhập một giá trị số đoán – ở các lệnh (4), (7) và (8).","o":["Mỗi khi người chơi nhập một số đoán (kể cả lần đầu tiên).","Chỉ khi người chơi đoán đúng.","Chỉ khi người chơi đoán sai.","Không bao giờ thay đổi."],"a":0},{"id":"hd3b","type":"mcq","q":"Những khối lệnh nào làm thay đổi biến số lần đoán trong chương trình Hình 15.1?","k":"Các khối liên quan đến biến số lần đoán: <b>(2)</b> khởi tạo, <b>(9)</b> thay đổi giá trị, <b>(11)</b> hiển thị.","o":["Lệnh (2) khởi tạo giá trị và lệnh (9) tăng giá trị; lệnh (11) chỉ hiển thị.","Chỉ lệnh (11).","Lệnh (4) và (5).","Lệnh (3) và (10)."],"a":0},{"id":"hd3c","type":"mcq","q":"Có điều gì khác nhau giữa kịch bản và những khối lệnh tương ứng?","k":"Kịch bản: tăng 1 sau mỗi lần nhập ở (4), (7), (8). Chương trình: chỉ tăng sau (7) hoặc (8) → <b>thiếu lần nhập đầu tiên ở lệnh (4)</b>.","o":["Lệnh (9) tăng số lần đoán sau (7) hoặc (8), nhưng không có lệnh nào tăng số lần đoán sau lần nhập đầu tiên ở lệnh (4).","Lệnh (2) phải đặt số lần đoán thành 100.","Lệnh (11) phải dùng phép “+”.","Không có gì khác nhau."],"a":0},{"id":"sua","type":"mcq","q":"Cách sửa lỗi được nêu trong SGK là:","k":"Tăng giá trị số lần đoán lên 1 sau lần đoán đầu tiên: thêm lệnh <b>(4a) thay đổi số lần đoán một lượng 1</b> vào sau lệnh (4).","o":["Bổ sung lệnh (4a) “thay đổi số lần đoán một lượng 1” giống lệnh (9) vào ngay sau lệnh (4).","Xoá lệnh (9).","Đổi lệnh (2) thành đặt số lần đoán thành 100.","Đổi “trả lời = số bí mật” thành “trả lời < số bí mật”."],"a":0},{"id":"p89","type":"open","q":"Gỡ lỗi đoạn chương trình xác định một số n nhập từ bàn phím là số chẵn hay số lẻ (Hình 15.3). Em phát hiện những lỗi nào, sửa thế nào?","k":"Lỗi 1: chưa gán giá trị nhập vào cho n (n luôn là 0) → thêm <b>đặt n thành trả lời</b> sau lệnh hỏi (hoặc dùng trả lời thay n). Lỗi 2: hai thông báo bị đổi chỗ: n chia lấy dư 2 = 0 là số <b>CHẴN</b>, ngược lại là số <b>LẺ</b>.","label":"Câu hỏi tr.89"},{"id":"nv1","type":"mcq","q":"Tình huống đoán đúng: thông báo hiển thị số lần đoán không xuất hiện cụm từ “Số lần đoán:”. Lỗi ở đâu?","k":"“Số lần đoán:” + số lần đoán là phép cộng số (chữ được coi là 0) → chỉ hiện con số. Sửa thành <b>kết hợp “Số lần đoán:” (số lần đoán)</b>.","o":["Lệnh (14): phép toán ghép nối các chữ là “kết hợp” chứ không phải dấu “+”.","Lệnh (2).","Lệnh (6).","Lệnh (13)."],"a":0},{"id":"nv2","type":"mcq","q":"Tình huống đoán sai 7 lần: chương trình không kết thúc mà cho đoán thêm một lần nữa. Điều kiện ở lệnh (6) cần đổi thành:","k":"Mỗi người không đoán quá 7 lần nên vòng lặp phải kết thúc khi số lần đoán bằng 7: dùng <b>số lần đoán &gt; 6</b> hoặc <b>số lần đoán = 7</b>.","o":["⟨trả lời = số bí mật⟩ hoặc ⟨số lần đoán > 6⟩ (hoặc ⟨số lần đoán = 7⟩)","⟨trả lời = số bí mật⟩ và ⟨số lần đoán > 7⟩","⟨số lần đoán > 7⟩","⟨trả lời < số bí mật⟩"],"a":0},{"id":"nv3","type":"mcq","q":"Sau 7 lần đoán vẫn có thể đoán đúng hoặc đoán sai, nên số lần đoán không cho biết kết quả. Điều kiện rẽ nhánh ở lệnh (11) cần sửa thành:","k":"Kết quả thắng/thua phụ thuộc vào <b>trả lời = số bí mật</b>, không phụ thuộc số lần đoán. Đổi chỗ hai nhánh như Hình 15.5.","o":["⟨trả lời = số bí mật⟩ (thì: HOAN HÔ và số lần đoán; nếu không thì: Bạn đã thua!)","⟨số lần đoán > 6⟩","⟨số lần đoán = 7⟩","⟨trả lời > số bí mật⟩"],"a":0},{"id":"lt1","type":"open","q":"Chọn một cách khác với cách đã nêu trong phần b) Sửa lỗi của mục 2 để sửa lỗi của chương trình Hình 15.1. Mô tả cách của em.","k":"Ví dụ: đặt <b>số lần đoán thành 1</b> ở lệnh (2) (đã tính lần đoán đầu tiên); hoặc hiển thị kết hợp “Số lần đoán” với (số lần đoán + 1) ở lệnh (11).","label":"Luyện tập"},{"id":"vd1","type":"open","q":"Đổi vai trò máy tính và người chơi trong trò chơi Đoán số: em chọn một số nguyên từ 1 đến 120; máy tính hiển thị một số, em trả lời “d”, “c” hoặc “t” (đúng, cao hơn, thấp hơn số em chọn). Viết chương trình để sau một số bước, càng ít càng tốt, máy tính tìm ra số em đã chọn. Chạy thử, phát hiện và sửa lỗi. Mô tả chương trình và các lỗi em đã sửa.","k":"Dùng tìm kiếm nhị phân: đầu ← 1, cuối ← 120; lặp: đoán ← làm tròn((đầu + cuối) / 2); hỏi; nếu “c” thì cuối ← đoán − 1; nếu “t” thì đầu ← đoán + 1; cho đến khi trả lời “d”. Nhiều nhất <b>7</b> lần (2⁷ = 128 ≥ 120).","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Cần phải <b>chạy thử</b> chương trình để phát hiện và loại bỏ lỗi.</li><li>Có hai loại lỗi: <b>lỗi cú pháp</b> và <b>lỗi lôgic</b>.</li><li>Lỗi cú pháp là lỗi viết câu lệnh sai quy tắc, làm cho chương trình không hoạt động.</li><li>Lỗi lôgic là lỗi câu lệnh, tuy được viết đúng quy tắc nhưng thực hiện sai so với kịch bản.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Hai phương pháp phổ biến để phát hiện lỗi lôgic: <b>tập trung vào những khối lệnh</b> trực tiếp gây ra lỗi và những khối lệnh liên quan lôgic đến nó theo các cấu trúc điều khiển; <b>chạy chương trình từng bước</b>, kết hợp theo dõi sự thay đổi của các biến, các giá trị đầu ra và so sánh với các giá trị tính được theo cách thủ công.</li></ul>"}]},"tin8-khai-thac-thong-tin-so":{"id":"tin8-bai3","ten":"Bài 3. Thực hành: Khai thác thông tin số","cau":[{"id":"kd1","type":"sort","q":"Mỗi nguồn năng lượng dưới đây là năng lượng tái tạo (không cạn kiệt) hay nhiên liệu hoá thạch (có thể cạn kiệt)?","k":"Năng lượng tái tạo: <b>gió, mặt trời, nước, sinh khối (cả rác thải)</b>,… không bao giờ cạn kiệt. Nhiên liệu hoá thạch: <b>than, dầu mỏ, khí đốt</b> phải mất hàng triệu năm để tạo ra và có thể cạn kiệt.","cats":["Năng lượng tái tạo","Nhiên liệu hoá thạch"],"items":[["Gió",0],["Ánh sáng mặt trời",0],["Nước (thuỷ điện)",0],["Rác thải, sinh khối",0],["Than đá",1],["Xăng, dầu mỏ",1],["Khí đốt",1]]},{"id":"kd2","type":"open","q":"Theo em, vì sao chúng ta cần tìm hiểu về năng lượng tái tạo? Em có thể khai thác thông tin số như thế nào để làm bài trình chiếu về chủ đề này?","k":"Vì nhiên liệu hoá thạch có thể cạn kiệt và gây ô nhiễm; năng lượng tái tạo sạch, không cạn kiệt nhưng cũng có nhược điểm. Để làm bài trình chiếu, em cần: <b>xác định ý tưởng, cấu trúc</b> → <b>tìm kiếm, đánh giá thông tin</b> → <b>xử lí, trao đổi thông tin</b> (tạo, biên tập, chia sẻ bài trình chiếu).","label":"Mở đầu – Vì sao?"},{"id":"yt","type":"open","q":"Nêu một khía cạnh hay một vấn đề cụ thể về năng lượng tái tạo mà em định trình bày. Phát triển ý tưởng thành các câu hỏi để thuận lợi cho việc tìm tư liệu.","k":"Ví dụ: chủ đề “Điện mặt trời ở Ninh Thuận”. Các câu hỏi: (1) Năng lượng tái tạo là gì? (2) Nguồn năng lượng nào sản xuất ra điện ở nơi em sinh sống? Ưu, nhược điểm? (3) Chọn một nguồn năng lượng thay thế: ưu, nhược điểm? (4) Loại năng lượng nào sẽ thay thế xăng dầu cho ô tô, xe máy? (5) Nếu thiết kế một nhà máy điện, em chọn cách nào? Vì sao?","label":"NV1 – Bước 1, 2"},{"id":"ct","type":"order","q":"Sắp xếp các trang của bài trình chiếu theo cấu trúc hợp lí (dùng nút ↑ ↓).","k":"Thứ tự: <b>tiêu đề → dàn ý → giới thiệu vấn đề → các trang nội dung → kết luận → tài liệu tham khảo</b>.","items":{"a":"Trang kết luận","b":"Trang tiêu đề","c":"Trang tài liệu tham khảo","d":"Trang giới thiệu vấn đề","e":"Trang dàn ý","f":"Các trang nội dung"},"ans":["b","e","d","f","a","c"],"start":["a","b","c","d","e","f"]},{"id":"yc","type":"sort","q":"Theo yêu cầu ở Bước 3 (mỗi trang không quá 6 mục, mỗi mục không quá 2 dòng, có ít nhất 2 hình ảnh minh hoạ), mỗi trang chiếu dưới đây đạt yêu cầu hay chưa?","k":"Bài trình chiếu khoảng 10 trang; <b>mỗi trang không quá 6 mục; mỗi mục không quá 2 dòng</b>; có <b>ít nhất 2 hình ảnh</b> minh hoạ; có trang tài liệu tham khảo.","cats":["Đạt yêu cầu","Chưa đạt"],"items":[["Trang có 5 mục, mỗi mục 1 dòng",0],["Trang có 9 mục liệt kê",1],["Một mục dài 5 dòng",1],["Bài trình chiếu có 3 hình ảnh minh hoạ",0],["Bài trình chiếu không có hình ảnh nào",1],["Có trang tài liệu tham khảo ghi rõ địa chỉ web",0]]},{"id":"tk","type":"open","q":"Dùng máy tìm kiếm với các từ khoá như “năng lượng tái tạo”, “năng lượng thay thế”, “ưu, nhược điểm của thuỷ điện”,… Ghi chép ít nhất hai kết quả tìm kiếm theo mẫu Bảng 3.1: nội dung, địa chỉ trang web, nguồn gốc, thời gian.","k":"Ví dụ: (1) Quy hoạch điện VIII: ưu tiên phát triển năng lượng tái tạo – moit.gov.vn – Bộ Công Thương – 2021; (2) Năng lượng tái tạo sẽ thống trị công suất điện toàn thế giới – evn.com.vn – Tập đoàn Điện lực Việt Nam – 2022. Ghi chép đủ <b>4 cột</b> giúp đánh giá và trích dẫn tài liệu tham khảo.","label":"NV2 – Bước 1, 2: Tìm kiếm"},{"id":"gov","type":"mcq","q":"Với nội dung quy hoạch cơ cấu nguồn điện của Việt Nam, nguồn thông tin nào đáng tin cậy nhất?","k":"Trang web có địa chỉ <b>…gov.vn</b> là trang thông tin của <b>cơ quan chính phủ</b> (Hình 3.1). Với nội dung quy hoạch cơ cấu nguồn điện, thông tin từ cơ quan chính phủ đáng tin cậy hơn thông tin trên các diễn đàn hay trang web của doanh nghiệp.","o":["Một diễn đàn trao đổi trên mạng.","Trang web của một doanh nghiệp bán pin mặt trời.","Trang web của Bộ Công Thương (đuôi .gov.vn).","Một bài đăng trên mạng xã hội."],"a":2},{"id":"b31","type":"sort","q":"Quan sát Bảng 3.1. Mỗi kết quả tìm kiếm dưới đây có độ tin cậy cao hay cần thận trọng khi dùng?","k":"Kết quả 1 lấy từ <b>diễn đàn</b> và đã <b>cũ</b> (2008) nên cần thận trọng, đối chiếu thêm. Kết quả 2 từ Tập đoàn Điện lực Việt Nam, khá mới. Kết quả 3 từ <b>Bộ Công Thương</b> (cơ quan chính phủ) – đáng tin cậy nhất.","cats":["Tin cậy cao","Cần thận trọng"],"items":[["Khái niệm chung về các nguồn năng lượng – diễn đàn hvacr.vn – năm 2008",1],["Năng lượng tái tạo sẽ thống trị công suất điện toàn thế giới – evn.com.vn – năm 2022",0],["Quy hoạch điện VIII – erea.gov.vn (Bộ Công Thương) – năm 2021",0]]},{"id":"dg","type":"open","q":"Đánh giá lợi ích của thông tin em tìm được bằng cách trả lời: Thông tin có thực sự phù hợp với nội dung trình bày không? Nguồn tin có đáng tin cậy không?","k":"Ví dụ: thông tin “Quy hoạch điện VIII” <b>phù hợp</b> với câu hỏi về năng lượng tái tạo trong tương lai; nguồn là Bộ Công Thương nên <b>đáng tin cậy</b>. Còn kiến thức chung về các nguồn năng lượng thì không đáp ứng được yêu cầu dự báo phát triển, nên không dùng cho phần đó.","label":"NV2 – Bước 3: Đánh giá"},{"id":"bd","type":"mcq","q":"Theo trang nội dung “Quy hoạch cơ cấu nguồn điện” (Hình 3.3), tỉ lệ điện gió và điện mặt trời cộng lại thay đổi thế nào từ năm 2030 đến năm 2045?","k":"Năm 2030: 14% + 13% = <b>27%</b>; năm 2045: 22% + 20% = <b>42%</b>. Tỉ lệ điện gió và điện mặt trời tăng mạnh, trong khi nhiệt điện than giảm từ 28% xuống 18%.","o":["Giảm từ 42% xuống 27%.","Tăng từ 27% lên 42%.","Không thay đổi.","Tăng từ 14% lên 22%."],"a":1},{"id":"bt","type":"open","q":"Tạo bài trình chiếu theo cấu trúc đã định và biên tập nội dung (mỗi trang không quá 6 mục, mỗi mục không quá 2 dòng; dùng phần mềm xử lí ảnh để tạo, sửa hình minh hoạ). Báo cáo: bài của em gồm những trang nào, dùng tư liệu nào?","k":"Ví dụ: (1) Tiêu đề; (2) Dàn ý; (3) Giới thiệu chủ đề; (4) Năng lượng tái tạo là gì?; (5) Nguồn năng lượng sản xuất điện tại tỉnh…; (6) Quy hoạch cơ cấu nguồn điện (bảng Hình 3.3); (7) Nhà máy điện tương lai; (8) Kết luận; (9) Tài liệu tham khảo (Hình 3.4). Có ảnh nhà máy điện gió, tấm pin mặt trời.","label":"NV3 – Bước 1, 2: Tạo và biên tập"},{"id":"cs","type":"open","q":"Em chọn phương tiện kĩ thuật số nào để chia sẻ bài trình chiếu (thư điện tử, mạng xã hội, không gian lưu trữ dùng chung,…)? Giải thích lựa chọn theo các tiêu chí: dễ sử dụng và an toàn dữ liệu.","k":"Ví dụ: chọn <b>không gian lưu trữ dùng chung</b> (Google Drive, OneDrive): dễ sử dụng (gửi một liên kết, mọi người cùng xem, cùng sửa), an toàn (chỉ chia sẻ cho người cần, đặt quyền xem/sửa, có bản sao lưu). Thư điện tử cũng an toàn nhưng tệp lớn khó gửi; mạng xã hội dễ dùng nhưng dễ lan truyền ngoài ý muốn.","label":"NV3 – Bước 3: Chia sẻ"},{"id":"lt1","type":"mcq","q":"Để tìm hiểu về cách sử dụng một chiếc máy ảnh mới, nguồn thông tin nào sau đây cần được tham khảo nhất?","k":"<b>Hướng dẫn sử dụng của nhà sản xuất</b> là nguồn có thẩm quyền, chính xác và đầy đủ nhất về chiếc máy ảnh đó.","o":["Hướng dẫn của một người đã từng chụp ảnh.","Hướng dẫn sử dụng của nhà sản xuất.","Hướng dẫn của một người giỏi Tin học.","Câu trả lời trên một số diễn đàn về chụp ảnh."],"a":1},{"id":"lt2","type":"mcq","q":"Để tìm hiểu về một đội bóng đá ở châu Phi, nguồn thông tin nào sau đây đáng tin cậy nhất?","k":"<b>Liên đoàn bóng đá châu Phi</b> là tổ chức có thẩm quyền, khách quan. Người hâm mộ có thể thiên vị, đội đối thủ có thể hạ thấp, diễn đàn ở xa thiếu thông tin chính xác.","o":["Nguồn tin từ câu lạc bộ người hâm mộ đội bóng đó.","Nguồn tin từ câu lạc bộ của đội bóng đối thủ.","Nguồn tin từ Liên đoàn bóng đá châu Phi.","Nguồn tin từ diễn đàn Bóng đá Việt Nam."],"a":2},{"id":"vd1","type":"open","q":"Em hãy tìm thông tin về một đội bóng, một cầu thủ hay một nghệ sĩ mà em hâm mộ. Hãy đánh giá những nguồn thông tin tìm được.","k":"Học sinh tự làm. Cần ghi theo mẫu Bảng 3.1 (nội dung, địa chỉ, nguồn gốc, thời gian) và đánh giá: nguồn có <b>thẩm quyền</b> không (trang chính thức, liên đoàn, báo uy tín); thông tin có <b>mới</b> không; có <b>phù hợp</b> với điều em cần tìm hiểu không.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Hình thành ý tưởng: chọn một khía cạnh cụ thể, phát triển thành các <b>câu hỏi</b> theo trình tự lôgic để thuận lợi cho việc tìm tư liệu.</li><li>Xác định cấu trúc, yêu cầu cụ thể của bài trình chiếu trước khi tìm kiếm.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Ghi chép kết quả tìm kiếm (nội dung, địa chỉ, nguồn gốc, thời gian) để thuận tiện đánh giá và tham khảo.</li><li>Trước khi dùng thông tin, cần đánh giá: thông tin có <b>phù hợp</b> không? Nguồn tin có <b>đáng tin cậy</b> không?</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Tạo bài trình chiếu theo cấu trúc đã định, biên tập nội dung ngắn gọn, có hình ảnh minh hoạ.</li><li>Chọn phương tiện chia sẻ <b>dễ sử dụng</b> và <b>an toàn dữ liệu</b>.</li></ul>"}]},"tin8-luoc-su-cong-cu-tinh-toan":{"id":"tin8-bai1","ten":"Bài 1. Lược sử công cụ tính toán","cau":[{"id":"kd1","type":"open","q":"Từ xa xưa đến nay, con người đã dùng những công cụ nào để tính toán? Em hãy kể tên những công cụ tính toán mà em biết.","k":"Ngón tay; que tính, hòn sỏi; <b>bàn tính</b> (hơn 2000 năm trước Công nguyên); thước tính; máy tính cơ học (Pascaline); máy tính bỏ túi; máy tính điện tử, điện thoại thông minh,… Cách ghi số phổ biến nhất là <b>hệ thập phân</b> (dùng 10 chữ số từ 0 đến 9), bắt nguồn từ việc đếm bằng 10 ngón tay.","label":"Mở đầu"},{"id":"kd2","type":"mcq","q":"Bàn tính trong Hình 1.1 đang hiển thị số nào?","k":"Bàn tính hiển thị số <b>6 302 715 408</b>. Bàn tính là một trong những công cụ tính toán sớm nhất của con người.","o":["8 045 172 036","6 302 715 408","6 302 715","630 271 540"],"a":1},{"id":"hd1a","type":"open","q":"Tên của một trong những chiếc máy tính đầu tiên là gì?","k":"Máy tính cơ học <b>Pascaline</b> do nhà bác học người Pháp <b>Blaise Pascal</b> sáng chế năm <b>1642</b> (Hình 1.2).","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Chiếc máy đó có thể làm được những gì?","k":"Máy Pascaline thực hiện được phép tính <b>cộng và trừ</b> nhờ hệ thống <b>bánh răng</b>. Sau đó, Leibniz cải tiến, thêm phép <b>nhân, chia</b>.","label":"HĐ1 – Câu 2"},{"id":"hd1c","type":"open","q":"Ý tưởng nào đã thúc đẩy sự phát minh ra máy tính?","k":"Ý tưởng <b>cơ giới hoá việc tính toán</b> (dùng máy móc để tính thay con người), giúp tính nhanh, tránh sai sót. Pascal làm máy để giúp cha trong việc tính thuế.","label":"HĐ1 – Câu 3"},{"id":"p6","type":"mcq","q":"Máy tính trong dự án của Babbage có những đặc điểm gì?","k":"Máy tính của Babbage là <b>máy tính cơ học</b>, <b>đa năng</b>, thực hiện tính toán <b>tự động</b>, có ứng dụng ngoài tính toán thuần tuý và có nguyên lí thiết kế <b>giống máy tính ngày nay</b>. Ông được coi là <b>cha của máy tính</b>.","o":["Máy tính cơ học, thực hiện tự động.","Máy tính có những ứng dụng ngoài tính toán thuần tuý.","Có thiết kế giống với máy tính ngày nay.","Cả ba đặc điểm trên."],"a":3},{"id":"nguoi","type":"match","q":"Đọc mục 1 và đầu mục 2 (SGK trang 5–7). Ghép mỗi nhà khoa học với đóng góp của họ.","k":"1 – a, 2 – b, 3 – c, 4 – d, 5 – e, 6 – f.","items":[["1) Blaise Pascal",1],["2) Gottfried Leibniz",2],["3) Charles Babbage",3],["4) Claude Shannon",4],["5) Howard Aiken",5],["6) John Von Neumann",6]],"opts":["a) Năm 1642 chế tạo máy tính cơ học Pascaline (cộng, trừ)","b) Cải tiến máy của Pascal, thêm phép nhân, chia","c) Năm 1833 thiết kế máy tính đa năng, tự động; được coi là cha của máy tính","d) Chỉ ra có thể dùng các rơ le để thực hiện các thao tác tính toán trên dãy bit","e) Năm 1944 chế tạo máy tính điện – cơ Harvard Mark I","f) Năm 1945 trình bày nguyên lí “chương trình được lưu trữ”"]},{"id":"vn","type":"mcq","q":"Theo nguyên lí “chương trình được lưu trữ” của Von Neumann, điều nào sau đây là đúng?","k":"Nguyên lí Von Neumann: (1) các lệnh của chương trình được <b>lưu trữ trong bộ nhớ giống như dữ liệu</b>; (2) để thực hiện nhiệm vụ nào, chỉ cần tải chương trình tương ứng vào bộ nhớ; (3) chương trình được nạp từ bộ nhớ vào bộ xử lí <b>từng lệnh một</b>, thực hiện <b>tuần tự</b>. Máy tính gồm bộ xử lí, bộ nhớ, thiết bị vào – ra (Hình 1.3).","o":["Chương trình được viết trên giấy, máy đọc từng dòng.","Các lệnh của chương trình được lưu trữ trong bộ nhớ giống như dữ liệu; bộ xử lí lấy từng lệnh ra thực hiện tuần tự.","Mỗi phép tính phải nối dây lại bằng tay.","Máy tính không cần bộ nhớ."],"a":1},{"id":"the","type":"match","q":"Đọc mục 2 (SGK trang 7–8). Ghép mỗi thế hệ máy tính điện tử với thành phần điện tử chính của nó.","k":"1 – a, 2 – b, 3 – c, 4 – d, 5 – e. Mỗi thế hệ được đánh dấu bởi tiến bộ công nghệ nhằm <b>thu nhỏ linh kiện điện tử</b>, tích hợp vào thiết bị nhỏ hơn, nhanh hơn, tiết kiệm năng lượng hơn.","items":[["1) Thế hệ thứ nhất (1945 – 1955)",1],["2) Thế hệ thứ hai (1955 – 1965)",2],["3) Thế hệ thứ ba (1965 – 1974)",3],["4) Thế hệ thứ tư (1974 – 1990)",4],["5) Thế hệ thứ năm (1990 – ngày nay)",5]],"opts":["a) Đèn điện tử chân không","b) Bóng bán dẫn","c) Mạch tích hợp (IC)","d) Mạch tích hợp cỡ rất lớn (VLSI) và bộ vi xử lí","e) Mạch tích hợp cỡ siêu lớn (ULSI)"]},{"id":"vd","type":"match","q":"Mỗi máy tính dưới đây thuộc thế hệ thứ mấy?","k":"1 – a, 2 – b, 3 – c, 4 – d, 5 – e.","items":[["1) ENIAC (Hình 1.4)",1],["2) IBM 7090, Minsk-22 (Hình 1.5)",2],["3) IBM System/360 (Hình 1.6)",3],["4) Micral, IBM PC, Apple II",4],["5) Điện thoại thông minh, loa thông minh",5]],"opts":["a) Thế hệ thứ nhất","b) Thế hệ thứ hai","c) Thế hệ thứ ba","d) Thế hệ thứ tư","e) Thế hệ thứ năm"]},{"id":"bm","type":"sort","q":"Bộ nhớ dưới đây được dùng chủ yếu ở máy tính thế hệ cũ (thứ nhất, thứ hai) hay thế hệ mới (thứ tư trở đi)?","k":"Thế hệ thứ nhất: <b>trống từ</b>; thế hệ thứ hai: <b>lõi từ, băng từ</b>; thế hệ thứ tư: <b>CD, RAM, ROM, USB, SSD</b>,…","cats":["Thế hệ cũ","Thế hệ mới"],"items":[["Trống từ",0],["Lõi từ, băng từ",0],["CD, RAM, ROM",1],["USB, SSD",1]]},{"id":"p8","type":"mcq","q":"Bộ vi xử lí là linh kiện máy tính dựa trên công nghệ nào?","k":"Bộ vi xử lí dựa trên công nghệ <b>mạch tích hợp cỡ rất lớn (VLSI)</b>, chứa hàng chục nghìn đến hàng triệu linh kiện bán dẫn trên một khối, xuất hiện từ thế hệ thứ tư.","o":["Đèn điện tử chân không.","Linh kiện bán dẫn đơn giản.","Mạch tích hợp hàng chục, hàng trăm linh kiện bán dẫn.","Mạch tích hợp cỡ lớn, gồm hàng chục nghìn đến hàng triệu linh kiện bán dẫn."],"a":3},{"id":"hd2","type":"open","q":"Em hãy lấy ba ví dụ cho thấy máy tính làm thay đổi sâu sắc cuộc sống của con người.","k":"Ví dụ: <b>học trực tuyến</b>, tra cứu tài liệu trên Internet; <b>đồng hồ thông minh</b> theo dõi sức khoẻ, báo động khi bất thường; <b>mua bán, thanh toán</b> qua điện thoại; gọi video với người thân ở xa; <b>camera an ninh</b> phát hiện vi phạm; máy bay không người lái quan sát vùng trời, vùng biển.","label":"HĐ2 – Sự thay đổi"},{"id":"lv","type":"match","q":"Đọc mục 3 (SGK trang 9). Ghép mỗi ví dụ với lĩnh vực mà máy tính đã làm thay đổi.","k":"1 – a, 2 – b, 3 – c, 4 – d, 5 – e.","items":[["1) Đồng hồ thông minh đo sức khoẻ, tự động báo cho người thân, cơ sở y tế",1],["2) Học sinh học mọi nơi, mọi lúc; học từ xa với giáo viên, chuyên gia",2],["3) Giao dịch, mua bán trong môi trường kĩ thuật số",3],["4) Thiết bị bay thông minh quan sát vùng trời, vùng biển, lãnh thổ",4],["5) Camera an ninh phát hiện hiện tượng vi phạm pháp luật",5]],"opts":["a) Y tế","b) Giáo dục","c) Kinh tế","d) Quốc phòng","e) An toàn xã hội"]},{"id":"lt1","type":"open","q":"Em hãy nêu một ví dụ cho thấy sự khác nhau rõ ràng trong hoạt động học tập khi chưa có và khi có các thiết bị công nghệ số hiện nay.","k":"Ví dụ tra cứu kiến thức: <b>trước đây</b> phải đến thư viện, tìm sách, mất nhiều thời gian; <b>ngày nay</b> tìm trên Internet trong vài giây, xem video bài giảng, hỏi thầy cô qua tin nhắn, làm bài kiểm tra trực tuyến.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"open","q":"Em hãy nêu ví dụ về một ứng dụng mà em cho là thông minh của những máy tính thế hệ mới.","k":"Ví dụ: trợ lí ảo nhận giọng nói (Google Assistant, Siri); ứng dụng dịch hình ảnh trực tiếp; mở khoá điện thoại bằng khuôn mặt; bản đồ chỉ đường tránh tắc; chatbot trí tuệ nhân tạo trả lời câu hỏi. Đó là khả năng <b>cảm nhận, suy luận, tương tác</b> giống con người.","label":"Luyện tập – câu 2"},{"id":"vd1","type":"mcq","q":"Vào thời điểm đất nước ta hoàn toàn thống nhất, năm 1975, những thế hệ máy tính điện tử nào đã xuất hiện ở nước ta?","k":"Theo SGK: chiếc máy tính thế hệ thứ hai <b>Minsk-22</b> được đưa vào nước ta năm <b>1968</b>; máy tính thế hệ thứ ba thuộc họ <b>IBM System/360</b> được đưa vào nước ta năm <b>1967</b>. Vậy năm 1975 nước ta đã có máy tính <b>thế hệ thứ hai và thứ ba</b>.","o":["Chỉ thế hệ thứ nhất.","Thế hệ thứ hai và thế hệ thứ ba.","Thế hệ thứ tư và thế hệ thứ năm.","Chưa có máy tính điện tử nào."],"a":1},{"id":"vd2","type":"open","q":"Em hãy đưa ra một dự báo về ứng dụng của máy tính trong tương lai. Hãy giải thích cơ sở của dự báo đó.","k":"Ví dụ: ô tô tự lái phổ biến; robot chăm sóc người già; bác sĩ AI chẩn đoán bệnh; lớp học thực tế ảo. <b>Cơ sở:</b> máy tính ngày càng nhỏ, nhanh, rẻ; trí tuệ nhân tạo phát triển mạnh; kết nối Internet tốc độ cao ở khắp nơi; hiện đã có các sản phẩm thử nghiệm.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Ý tưởng <b>cơ giới hoá việc tính toán</b> đóng vai trò quan trọng trong lịch sử phát triển của máy tính. Năm 1642, nhà bác học Blaise Pascal đã sáng chế ra chiếc máy tính cơ học Pascaline.</li><li>Năm 1833, nhà Toán học Charles Babbage đã thiết kế máy tính đa năng, tính toán tự động tương tự như máy tính ngày nay.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Máy tính điện tử ra đời vào những năm 1940. Năm thế hệ của máy tính điện tử được đánh dấu bởi những tiến bộ công nghệ nhằm thu nhỏ các linh kiện điện tử, tích hợp chúng vào những thiết bị nhỏ, có tốc độ xử lí lớn, độ tin cậy cao, có khả năng kết nối toàn cầu, tiêu thụ ít năng lượng và được trang bị nhiều ứng dụng thân thiện với con người.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Thế giới đang biến đổi nhanh chóng và sâu sắc nhờ sự phát triển của công nghệ máy tính.</li></ul>"}]},"tin8-sap-xep-va-loc-du-lieu":{"id":"tin8-bai6","ten":"Bài 6. Sắp xếp và lọc dữ liệu","cau":[{"id":"hd1","type":"open","q":"Phiếu khảo sát (Hình 6.1) được phát cho các bạn trong lớp. Câu trả lời của các bạn cần được lưu trữ trong bảng tính. Theo em, bảng tính gồm các cột nào? Mỗi hàng của bảng lưu trữ dữ liệu gì?","k":"Bảng tính gồm các cột: <b>TT</b>, <b>Họ đệm</b>, <b>Tên</b> (tách họ và tên để dễ sắp xếp, tìm kiếm), <b>Tổ</b>, <b>Nội dung</b>. Mỗi hàng lưu <b>kết quả một phiếu khảo sát</b> (của một học sinh).","label":"HĐ1 – Phiếu khảo sát"},{"id":"cn","type":"sort","q":"Đọc mục 1 (SGK trang 27–28). Mỗi yêu cầu xử lí dữ liệu dưới đây nên dùng chức năng sắp xếp hay lọc dữ liệu?","k":"<b>Sắp xếp</b>: đổi thứ tự các hàng theo một hay nhiều tiêu chí. <b>Lọc</b>: chỉ hiển thị các hàng thoả mãn điều kiện, các hàng khác bị ẩn đi.","cats":["Sắp xếp","Lọc"],"items":[["Sắp xếp họ tên học sinh theo thứ tự bảng chữ cái để dễ tìm kiếm",0],["Lấy danh sách học sinh muốn tìm hiểu Ngôn ngữ lập trình",1],["Lấy danh sách học sinh Tổ 1 muốn tìm hiểu Đồ hoạ máy tính",1],["Xếp các lớp theo số học sinh không dùng thiết bị số từ nhiều đến ít",0],["Chỉ hiện các lớp không có học sinh dùng thiết bị số từ 5 giờ trở lên",1]]},{"id":"p28","type":"mcq","q":"Em hãy nêu tiêu chí sắp xếp danh sách học sinh theo thứ tự của bảng chữ cái trong bảng kết quả ở Hình 6.2.","k":"Tiêu chí: cột <b>Tên</b>, thứ tự <b>A to Z</b>. Nếu trùng tên thì thêm tiêu chí thứ hai là cột <b>Họ đệm</b>. Lưu ý: việc sắp xếp theo bảng mã Unicode sẽ không hoàn toàn đúng với thứ tự trong tiếng Việt.","o":["Sắp xếp theo cột TT, từ nhỏ đến lớn.","Sắp xếp theo cột Tên, theo thứ tự bảng chữ cái (A đến Z).","Sắp xếp theo cột Tổ.","Sắp xếp theo cột Nội dung."],"a":1},{"id":"nd","type":"mcq","q":"Theo bảng kết quả khảo sát lớp 8A (Hình 6.2), nội dung Tin học nào có nhiều học sinh lựa chọn nhất?","k":"<b>Ngôn ngữ lập trình</b> có 4 học sinh chọn: Vũ Thị Minh An, Trần Minh Châu, Đặng Mai Trang, Phùng Khánh Toàn. Có thể dùng chức năng lọc theo cột Nội dung để lấy danh sách này.","o":["Mạng máy tính","Đồ hoạ máy tính","Ngôn ngữ lập trình","Bảng tính điện tử"],"a":2},{"id":"sx1","type":"order","q":"Sắp xếp các bước sắp xếp cột Tên của Bảng kết quả khảo sát lớp 8A theo thứ tự bảng chữ cái (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → c</b>. Chọn vùng A2:E12 → Data/Sort → thiết lập trong hộp thoại Sort → OK.","items":{"a":"Trong hộp thoại Sort: chọn My data has headers, chọn cột Tên, chọn A to Z.","b":"Chọn vùng dữ liệu cần sắp xếp A2:E12.","c":"Chọn OK.","d":"Trong thẻ Data, nhóm Sort & Filter, chọn lệnh Sort."},"ans":["b","d","a","c"],"start":["a","b","c","d"]},{"id":"hd","type":"mcq","q":"Vì sao cần chọn “My data has headers” trong hộp thoại Sort?","k":"Vùng A2:E12 có hàng 2 là <b>tiêu đề</b>. Chọn My data has headers để dòng tiêu đề <b>không bị sắp xếp</b> lẫn vào dữ liệu.","o":["Để sắp xếp cả dòng tiêu đề.","Để không sắp xếp dòng tiêu đề (hàng 2 là tiêu đề của bảng).","Để sắp xếp theo màu.","Để xoá dòng tiêu đề."],"a":1},{"id":"sx2","type":"mcq","q":"Có hai học sinh cùng tên là Trang. Sau khi sắp xếp theo tiêu chí thứ nhất là Tên, tiêu chí thứ hai (Add Level) là Họ đệm, bạn nào đứng trước?","k":"Khi cùng tên Trang, bảng tính sắp xếp theo cột Họ đệm: <b>Đặng Mai</b> (chữ Đ) đứng trước <b>Ngô Hà</b> (chữ N), như Hình 6.6.","o":["Ngô Hà Trang","Đặng Mai Trang","Hai bạn giữ nguyên thứ tự cũ","Không xác định được"],"a":1},{"id":"p30","type":"mcq","q":"Sắp xếp bảng kết quả khảo sát lớp 8A theo Tổ; nếu cùng tổ thì theo Tên; nếu cùng tên thì theo Họ đệm. Học sinh nào đứng đầu danh sách?","k":"Có thể sắp xếp được, dùng <b>ba tiêu chí</b>: Tổ → Tên → Họ đệm (Add Level hai lần). Tổ 1 gồm An, Toàn, Trang, Trang; đứng đầu là <b>Phạm Hoàng Bảo An</b>. Em thử ngay trên bảng mô phỏng.","o":["Vũ Thị Minh An (Tổ 3)","Trần Minh Châu (Tổ 2)","Phạm Hoàng Bảo An (Tổ 1)","Đặng Mai Trang (Tổ 1)"],"a":2},{"id":"loc1","type":"order","q":"Sắp xếp các bước lọc danh sách học sinh muốn tìm hiểu Ngôn ngữ lập trình (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → c</b>. Để bỏ lọc, chọn lại <b>Select All</b>.","items":{"a":"Nháy chuột vào nút mũi tên ở ô tiêu đề cột Nội dung.","b":"Chọn vùng dữ liệu cần lọc A2:E12.","c":"Bỏ chọn tất cả (Select All), chọn Ngôn ngữ lập trình, chọn OK.","d":"Trong thẻ Data, nhóm Sort & Filter, chọn lệnh Filter."},"ans":["b","d","a","c"],"start":["a","b","c","d"]},{"id":"loc2","type":"mcq","q":"Lọc danh sách học sinh của Tổ 1 muốn tìm hiểu nội dung Đồ hoạ máy tính (lọc theo hai cột Nội dung và Tổ). Kết quả là:","k":"Có hai bạn chọn Đồ hoạ máy tính: Ngô Hà Trang (Tổ 1) và Phạm Ngọc Linh (Tổ 3). Lọc thêm Tổ = 1 chỉ còn <b>Ngô Hà Trang</b>.","o":["Ngô Hà Trang","Ngô Hà Trang và Phạm Ngọc Linh","Phạm Ngọc Linh","Đặng Mai Trang"],"a":0},{"id":"an","type":"mcq","q":"Khi lọc dữ liệu, các hàng không đúng với điều kiện lọc sẽ:","k":"Dữ liệu không đúng với điều kiện lọc sẽ <b>bị ẩn đi</b>, không bị xoá. Bỏ lọc bằng cách chọn <b>Select All</b>.","o":["Bị xoá vĩnh viễn.","Bị ẩn đi, chọn Select All để hiện lại.","Bị chuyển xuống cuối bảng.","Được tô màu đỏ."],"a":1},{"id":"ltb","type":"mcq","q":"Sắp xếp bảng dữ liệu Hình 6.9 với hai tiêu chí: giá trị giảm dần của cột Không sử dụng, nếu bằng nhau thì giá trị giảm dần của cột Dưới 1 giờ. Ba lớp đứng đầu danh sách là:","k":"Không sử dụng lớn nhất: 8A8 (9). Ba lớp cùng 8: so cột Dưới 1 giờ: 8A1 (12) &gt; 8A4 (11) &gt; 8A5 (10). Ba lớp đầu: <b>8A8, 8A1, 8A4</b>. Thứ tự đầy đủ: 8A8, 8A1, 8A4, 8A5, 8A6, 8A2, 8A3, 8A9, 8A7, 8A10.","o":["8A1, 8A4, 8A5","8A8, 8A1, 8A4","8A8, 8A5, 8A4","8A7, 8A10, 8A3"],"a":1},{"id":"ltd","type":"sort","q":"Lọc danh sách các lớp không có học sinh sử dụng thiết bị số từ 5 giờ trở lên (ô cột “Từ 5 giờ trở lên” để trống). Mỗi lớp dưới đây có nằm trong kết quả lọc không?","k":"Kết quả lọc: <b>8A2, 8A5, 8A6, 8A7, 8A8</b> (ô trống). Trong Excel, ở cột “Từ 5 giờ trở lên” chỉ chọn <b>(Blanks)</b>.","cats":["Có trong kết quả","Không có"],"items":[["8A1",1],["8A2",0],["8A3",1],["8A5",0],["8A6",0],["8A7",0],["8A8",0],["8A10",1]]},{"id":"vd1","type":"mcq","q":"Dùng Number Filters để lọc danh sách các lớp có số học sinh sử dụng thiết bị số từ 3 đến 4 giờ lớn hơn hoặc bằng 10 học sinh. Kết quả là:","k":"Cột 3–4 giờ: chỉ <b>8A5</b> có 11 học sinh (≥ 10); các lớp khác đều dưới 10. Cách làm: nháy mũi tên cột 3–4 giờ → <b>Number Filters</b> → <b>Greater Than Or Equal To…</b> → nhập 10 → OK.","o":["8A4 và 8A5","8A5","8A7 và 8A4","Không có lớp nào"],"a":1},{"id":"vd2","type":"open","q":"Em hãy dùng Number Filters để đặt thêm một điều kiện lọc khác trên tệp TGSDThietbiso.xlsx (ví dụ: lớp có từ 15 học sinh dùng thiết bị 1–2 giờ trở lên). Ghi lại điều kiện và kết quả.","k":"Ví dụ: cột 1–2 giờ, Greater Than Or Equal To 15 → 8A1, 8A2, 8A3, 8A7, 8A8, 8A9, 8A10. Học sinh tự đặt điều kiện khác và kiểm tra kết quả.","label":"Vận dụng – Thử thêm"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Chức năng <b>sắp xếp</b> và <b>lọc</b> dữ liệu của phần mềm bảng tính giúp giải quyết nhiều bài toán thực tế: sắp xếp danh sách, tìm nhóm dữ liệu thoả mãn điều kiện,…</li><li>Sắp xếp theo bảng mã Unicode không hoàn toàn đúng với thứ tự trong tiếng Việt.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Sắp xếp: chọn vùng dữ liệu → <b>Data/Sort</b> → chọn cột, thứ tự (A to Z, Z to A) → OK.</li><li>Sắp xếp nhiều tiêu chí: <b>Add Level</b> để thêm tiêu chí; <b>Delete Level</b> để xoá tiêu chí.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Lọc: chọn vùng dữ liệu → <b>Data/Filter</b> → nháy mũi tên ở cột cần lọc → chọn giá trị → OK.</li><li>Dữ liệu không đúng điều kiện lọc bị <b>ẩn đi</b>; chọn <b>Select All</b> để bỏ lọc.</li></ul>"}]},"tin8-thong-tin-trong-moi-truong-so":{"id":"tin8-bai2","ten":"Bài 2. Thông tin trong môi trường số","cau":[{"id":"hd1a","type":"open","q":"An có thể nhận được ảnh bằng cách nào?","k":"An nhận ảnh qua <b>thư điện tử</b> (hoặc qua mạng xã hội, ứng dụng nhắn tin) bằng máy tính hay điện thoại có kết nối <b>Internet</b>, không cần đến nhà Khoa.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Sau khi An nhận được ảnh, Khoa có bị mất bức ảnh gốc không?","k":"<b>Không.</b> Khoa vẫn còn bức ảnh in và ảnh chụp trong điện thoại. Gửi ảnh số là gửi một <b>bản sao</b>, người gửi không bị mất ảnh.","label":"HĐ1 – Câu 2"},{"id":"hd1c","type":"open","q":"An có thể lưu trữ ảnh vào những thiết bị nào?","k":"Điện thoại thông minh, máy tính, máy tính bảng, thẻ nhớ, USB, ổ cứng; hoặc lưu trực tuyến trên <b>dịch vụ lưu trữ đám mây</b> (Google Drive, OneDrive,…).","label":"HĐ1 – Câu 3"},{"id":"dd","type":"sort","q":"Đọc mục a) Thông tin số (SGK trang 10–11). Mỗi nhận định dưới đây đúng hay sai?","k":"Thông tin số được mã hoá thành <b>dãy bit</b>; <b>dễ nhân bản, lan truyền nhưng khó bị xoá bỏ hoàn toàn</b>; có thể được <b>truy cập từ xa</b> nếu người quản lí cho phép. Gửi đi là gửi bản sao, không mất bản gốc.","cats":["Đúng","Sai"],"items":[["Thông tin số dễ dàng được nhân bản và lan truyền",0],["Thông tin số đã đưa lên mạng thì xoá được hoàn toàn dễ dàng",1],["Thông tin số có thể được truy cập từ xa nếu người quản lí cho phép",0],["Gửi ảnh số cho bạn thì người gửi sẽ mất ảnh gốc",1],["Thông tin số là thông tin được mã hoá thành dãy bit",0]]},{"id":"hd2a","type":"open","q":"Máy chủ của dịch vụ thư điện tử có lưu trữ bức ảnh Khoa gửi không?","k":"<b>Có.</b> Bức ảnh được lưu trên máy chủ của nhà cung cấp dịch vụ thư điện tử (trong hộp thư của Khoa và của An).","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Những ai có thể xem được bức ảnh An đưa lên mạng xã hội?","k":"Tuỳ chế độ chia sẻ An chọn: <b>công khai</b> (mọi người), <b>bạn bè</b>, hoặc một nhóm người được phép; ngoài ra còn nhà cung cấp mạng xã hội. Người đã xem có thể tải về, chia sẻ tiếp.","label":"HĐ2 – Câu 2"},{"id":"hd2c","type":"open","q":"An có thể gửi ảnh sau khi chỉnh sửa cho Khoa hoặc các bạn khác được không?","k":"<b>Được.</b> Ảnh số dễ dàng được chỉnh sửa, nhân bản và tiếp tục chia sẻ cho người khác. Tuy nhiên ảnh là của Khoa chụp, An nên <b>xin phép</b> Khoa trước khi chia sẻ (tôn trọng quyền tác giả).","label":"HĐ2 – Câu 3"},{"id":"p12","type":"mcq","q":"Thông tin số được nhiều tổ chức và cá nhân lưu trữ với dung lượng rất lớn,","k":"Thông tin số <b>được bảo hộ quyền tác giả</b> và <b>có độ tin cậy khác nhau</b>, phụ thuộc vào nguồn gốc và mục tiêu thông tin. Không phải được truy cập tự do, cũng không phải tất cả đều đáng tin hay không đáng tin.","o":["được truy cập tự do và có độ tin cậy khác nhau.","được bảo hộ quyền tác giả và không đáng tin cậy.","được bảo hộ quyền tác giả và có độ tin cậy khác nhau.","được bảo hộ quyền tác giả và rất đáng tin cậy."],"a":2},{"id":"hd3a","type":"open","q":"Em hãy kể lại một nội dung trên mạng mà em biết đó là tin giả.","k":"Ví dụ: tin “uống nước chanh muối chữa khỏi bệnh”; tin “ngày mai học sinh được nghỉ học” do tài khoản lạ đăng; ảnh ghép một người nổi tiếng nói điều họ không nói; tin “nhận quà miễn phí, chỉ cần bấm vào liên kết”,…","label":"HĐ3 – Câu 1"},{"id":"hd3b","type":"open","q":"Tin giả đó gây ra tác hại gì nếu người đọc tin vào điều đó?","k":"Người đọc có thể làm theo sai (ảnh hưởng sức khoẻ), mất tiền, lộ thông tin cá nhân, hoang mang lo lắng, hiểu sai về người khác, gây mất trật tự xã hội.","label":"HĐ3 – Câu 2"},{"id":"hd3c","type":"open","q":"Làm thế nào để em biết đó là tin giả?","k":"Kiểm tra <b>nguồn tin</b> (ai đăng, có uy tín không); đối chiếu với báo chính thống, cơ quan có thẩm quyền; xem có <b>chứng cứ</b> không; xem <b>thời điểm</b> đăng; phân biệt <b>ý kiến</b> với <b>sự kiện</b>; hỏi thầy cô, bố mẹ.","label":"HĐ3 – Câu 3"},{"id":"cach","type":"match","q":"Đọc mục 2 (SGK trang 12–13). Mỗi việc làm dưới đây ứng với cách xác định thông tin đáng tin cậy nào?","k":"1 – a, 2 – b, 3 – c, 4 – d.","items":[["1) Xem tin được đăng trên báo chính thống hay trên một blog cá nhân",1],["2) Nhận ra câu “Tôi nghĩ đây là phim hay nhất” chỉ là quan điểm cá nhân",2],["3) Tìm xem kết luận trong bài có số liệu, dẫn chứng hay không",3],["4) Xem trang web được cập nhật lần cuối khi nào",4]],"opts":["a) Xác định nguồn thông tin","b) Phân biệt ý kiến và sự kiện","c) Kiểm tra chứng cứ của kết luận","d) Đánh giá tính thời sự của thông tin"]},{"id":"ys","type":"sort","q":"Mỗi câu dưới đây là ý kiến (quan điểm cá nhân) hay sự kiện (đã xảy ra, kiểm chứng được)?","k":"Ý kiến là quan điểm, không phải sự kiện; ý kiến thường mang nhiều cảm xúc, định kiến cá nhân nên có <b>độ tin cậy thấp hơn</b> sự kiện. Sự kiện là điều đã xảy ra, <b>kiểm chứng được</b>.","cats":["Ý kiến","Sự kiện"],"items":[["“Tôi tin rằng việc đó đã xảy ra!”",0],["“Tôi nghĩ đây là bộ phim hoạt hình hay nhất mọi thời đại.”",0],["Năm 1642, Blaise Pascal chế tạo máy tính cơ học Pascaline.",1],["“Món ăn này chắc chắn ngon nhất thành phố.”",0],["Đội tuyển Việt Nam thắng 2–0 trong trận đấu tối qua.",1]]},{"id":"lt1","type":"open","q":"Em hãy kể tên ba ứng dụng thu thập nhiều thông tin từ người sử dụng và trả lời: a) Tổ chức, cá nhân nào sở hữu các ứng dụng đó? b) Mỗi ứng dụng thu thập dạng thông tin nào?","k":"Ví dụ:<ul><li><b>Facebook</b> – công ty Meta: thông tin cá nhân, ảnh, video, bài đăng, bạn bè, vị trí.</li><li><b>Zalo</b> – công ty VNG: số điện thoại, danh bạ, tin nhắn, ảnh.</li><li><b>Google Maps</b> – Google: vị trí, lịch sử di chuyển, đánh giá địa điểm.</li><li>Khác: TikTok (ByteDance), YouTube (Google), Shopee (Sea Group),…</li></ul>","label":"Luyện tập – câu 1"},{"id":"lt2","type":"open","q":"Em hãy đánh giá độ tin cậy của thông tin được cung cấp từ ba ứng dụng ở Câu 1.","k":"Độ tin cậy <b>khác nhau</b> tuỳ nguồn: thông tin bản đồ của Google Maps khá tin cậy nhưng đánh giá địa điểm có thể không khách quan; bài đăng trên Facebook, TikTok do mọi người tự đăng nên độ tin cậy thấp, cần kiểm chứng; tin từ trang chính thức của cơ quan, báo chí trên các ứng dụng đó đáng tin hơn.","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Em hãy tìm kiếm trên Internet thông tin về một đội bóng, một cầu thủ hoặc một nhân vật mà em yêu thích. Phân tích mức độ tin cậy của nguồn tin tìm được và trình bày một bài giới thiệu ngắn.","k":"Học sinh tự làm. Cần: ghi rõ <b>nguồn</b> (trang chính thức của câu lạc bộ, liên đoàn bóng đá, báo thể thao uy tín đáng tin hơn trang người hâm mộ); phân biệt sự kiện (số bàn thắng, danh hiệu) với ý kiến (“cầu thủ hay nhất”); kiểm tra thời điểm cập nhật.","label":"Vận dụng – câu 1, 2"},{"id":"vd3","type":"open","q":"Em hãy kể một ví dụ về tin đồn (trong cuộc sống hoặc trên mạng) và trả lời: a) Tin đồn đó xuất hiện từ sự việc nào? b) Tác hại của tin đồn đó là gì?","k":"Ví dụ: tin đồn “sắp hết muối, phải mua tích trữ” xuất hiện sau tin về sự cố hạt nhân ở nước ngoài → người dân đổ xô mua, giá tăng vọt, gây hoang mang, mất trật tự. Tin đồn thường <b>thiếu căn cứ</b>, dẫn đến kết luận và quyết định sai.","label":"Vận dụng – câu 3"}],"the":[{"t":"Ghi nhớ","b":"<p>Thông tin số có những đặc điểm chính sau:</p><ul><li>Thông tin số <b>dễ dàng được nhân bản và lan truyền</b> nhưng <b>khó bị xoá bỏ hoàn toàn</b>.</li><li>Thông tin số có thể được <b>truy cập từ xa</b> nếu người quản lí thông tin đó cho phép.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Thông tin số <b>đa dạng</b>, được thu thập nhanh, được lưu trữ với dung lượng rất lớn bởi nhiều tổ chức và cá nhân.</li><li>Có nhiều công cụ hỗ trợ tìm kiếm, truy cập, lưu trữ, xử lí và chia sẻ thông tin số.</li><li><b>Quyền tác giả</b> của thông tin số được pháp luật bảo hộ.</li><li>Thông tin số có <b>mức độ tin cậy khác nhau</b>.</li><li>Thông tin số cần được quản lí, khai thác an toàn và có trách nhiệm.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Thông tin đáng tin cậy giúp em đưa ra kết luận đúng, quyết định hành động đúng và giải quyết được các vấn đề đặt ra.</li><li>Một số cách xác định thông tin có đáng tin cậy hay không: <b>kiểm tra nguồn thông tin</b>; <b>phân biệt ý kiến với sự kiện</b>; <b>kiểm tra chứng cứ của kết luận</b>; <b>đánh giá tính thời sự</b> của thông tin.</li></ul>"}]},"tin8-tin-hoc-nghe-nghiep":{"id":"tin8-bai16","ten":"Bài 16. Tin học với nghề nghiệp","cau":[{"id":"kd1","type":"open","q":"An, Minh, Khoa sôi nổi trò chuyện về chủ đề: Những nghề nghiệp mà ứng dụng tin học giúp tăng hiệu quả công việc rõ ràng nhất. An nói về nghề kế toán, Khoa nói về nghề giáo viên, Minh nói về nghề hoạ sĩ. Còn ý kiến của em thì sao?","k":"Gợi ý: hầu hết các nghề đều được tin học hỗ trợ: bác sĩ (hồ sơ sức khoẻ điện tử, khám bệnh từ xa), kiến trúc sư (vẽ thiết kế, in 3D), nhà báo (báo điện tử), lái xe (bản đồ, đặt xe),… Em nêu nghề và ví dụ cụ thể.","label":"Khởi động"},{"id":"hd1","type":"open","q":"Cùng các bạn lựa chọn một vài nghề nghiệp mà em biết để thảo luận và chỉ ra những ví dụ mà tin học được ứng dụng trong các nghề nghiệp đó.","k":"Ví dụ: <b>bác sĩ</b> – hồ sơ sức khoẻ điện tử, khám bệnh từ xa; <b>giáo viên</b> – bài giảng điện tử, lớp học trực tuyến; <b>nông dân</b> – tưới nước tự động, IoT; <b>người bán hàng</b> – bán hàng online, phần mềm quản lí.","label":"HĐ1 – Ứng dụng tin học trong nghề nghiệp"},{"id":"li","type":"sort","q":"Mỗi ví dụ dưới đây thể hiện lợi ích nào của việc ứng dụng tin học?","k":"Bốn lợi ích: tăng <b>tốc độ</b> xử lí; <b>liên lạc</b>, trao đổi thông tin dễ dàng; hỗ trợ <b>làm việc nhóm</b>, mở rộng phạm vi làm việc; nâng cao <b>tay nghề</b>, bổ sung kiến thức, hỗ trợ thông tin.","cats":["Tăng tốc độ xử lí, tiết kiệm thời gian","Liên lạc, trao đổi thông tin dễ dàng","Làm việc nhóm, mở rộng phạm vi làm việc","Nâng cao tay nghề, hỗ trợ thông tin"],"items":[["Kế toán tính toán bằng phần mềm chỉ trong vài phút; thanh toán, chuyển tiền gần như lập tức",0],["Tài liệu, tin nhắn công việc được gửi ngay tới đồng nghiệp, khách hàng trên toàn thế giới",1],["Lập trình viên làm việc xuyên biên giới, cùng một tài liệu chia sẻ trên công nghệ đám mây",2],["Lái xe taxi dùng ứng dụng đặt xe, bản đồ, thông báo tình trạng giao thông để tìm đường",3]]},{"id":"nghe","type":"sort","q":"Mỗi nghề dưới đây thuộc lĩnh vực tin học hay là nghề liên quan đến ứng dụng tin học?","k":"Lĩnh vực tin học: phát triển phần mềm, lập trình ứng dụng điện thoại, quản trị mạng, phát triển và thiết kế website. Liên quan đến ứng dụng tin học: bán hàng online, streamer, vlogger.","cats":["Nghề thuộc lĩnh vực tin học","Nghề liên quan đến ứng dụng tin học"],"items":[["Phát triển phần mềm",0],["Lập trình ứng dụng điện thoại",0],["Quản trị mạng",0],["Phát triển và thiết kế website",0],["Bán hàng online",1],["Streamer (phát sóng trực tiếp trên nền tảng online)",1],["Vlogger (tạo dựng nội dung video, đăng trên mạng xã hội)",1]]},{"id":"h161","type":"match","q":"Ghép mỗi ứng dụng tin học với nghề nghiệp tương ứng trong Hình 16.1.","k":"Bác sĩ – hồ sơ sức khoẻ, khám từ xa; Nhà báo – báo điện tử; Quản lí du lịch – website đặt chỗ; Nhân viên văn phòng – soạn thảo, lưu trữ; Kiến trúc sư – thiết kế, in 3D; Kĩ sư nông nghiệp – tưới tự động, IoT.","items":[["Hồ sơ sức khoẻ điện tử; khám bệnh từ xa",1],["Đăng bài nhanh chóng trên báo điện tử",2],["Đặt chỗ khách sạn trên website",3],["Phần mềm soạn thảo văn bản, lưu trữ hồ sơ",4],["Phần mềm thiết kế bản vẽ; in 3D tạo mẫu",5],["Tự động điều tiết nước tưới; Internet vạn vật (IoT)",6]],"opts":["a) Bác sĩ","b) Nhà báo","c) Quản lí du lịch","d) Nhân viên văn phòng","e) Kiến trúc sư","f) Kĩ sư nông nghiệp"]},{"id":"p92a","type":"match","q":"Ghép mỗi ứng dụng ở cột B với một nghề phù hợp nhất ở cột A để chứng minh cho việc ứng dụng của tin học có thể tăng hiệu quả công việc.","k":"1 – d; 2 – e; 3 – a; 4 – c; 5 – b.","items":[["1) Bác sĩ",4],["2) Giáo viên",5],["3) Kiến trúc sư",1],["4) Kế toán",3],["5) Nhà báo",2]],"opts":["a) Tạo bản vẽ 3D để khách hàng có thể hình dung rõ về căn nhà định xây dựng","b) Nhận hình ảnh tin tức thời sự được chụp bởi đồng nghiệp khác để biên tập thành bài báo","c) Tạo một báo cáo tài chính bằng phần mềm bảng tính","d) Theo dõi sức khoẻ, quá trình điều trị của bệnh nhân qua hồ sơ sức khoẻ điện tử","e) Tạo khoá học trực tuyến để học sinh có thể học bất cứ lúc nào, ở bất cứ đâu"]},{"id":"p92b","type":"open","q":"Kể ra những ứng dụng tin học mà các thầy cô giáo đã sử dụng để giúp các em nâng cao hiệu quả của việc học tập.","k":"Ví dụ: bài giảng trình chiếu, phần mềm mô phỏng, trang học tương tác, lớp học trực tuyến, phần mềm quản lí điểm, kho học liệu số, bài kiểm tra trực tuyến.","label":"Câu hỏi tr.92 – câu 2"},{"id":"hd2a","type":"open","q":"Nếu có bạn nào đó nói với em rằng “Nghề nghiệp trong lĩnh vực tin học chỉ nên dành cho nam giới”, em sẽ trả lời bạn như thế nào? Tại sao?","k":"Không đúng. Nghề nghiệp trong lĩnh vực tin học, cũng như cơ hội ứng dụng tin học, là <b>bình đẳng cho tất cả mọi người</b>. Môi trường, điều kiện công việc vẫn phù hợp cho phụ nữ phát huy khả năng; ví dụ lập trình viên đầu tiên là một phụ nữ – bà Ada Lovelace.","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Em biết những ngành nghề nào thuộc lĩnh vực tin học đang có nhiều phụ nữ làm việc?","k":"Ví dụ: kiểm thử phần mềm, phân tích dữ liệu, thiết kế website và giao diện, quản trị cơ sở dữ liệu, lập trình viên, giảng dạy tin học,…","label":"HĐ2 – Câu 2"},{"id":"bdg","type":"sort","q":"Mỗi ý dưới đây đúng hay sai?","k":"Sai: môi trường tin học <b>vẫn phù hợp</b> cho phụ nữ; lập trình viên đầu tiên là một <b>phụ nữ</b> – bà Ada Lovelace (người Anh, sinh năm 1815). Các ý còn lại đúng.","cats":["Đúng","Sai"],"items":[["Tỉ lệ nữ giới làm việc trong các ngành nghề tin học so với nam giới còn khá thấp",0],["Môi trường, điều kiện công việc tin học không phù hợp cho phụ nữ",1],["Ngày Quốc tế trẻ em gái với công nghệ thông tin được tổ chức hằng năm bởi Liên minh Viễn thông Quốc tế (ITU)",0],["DigiGirlz là chiến dịch do Microsoft khởi xướng nhằm truyền cảm hứng cho học sinh nữ theo đuổi ngành khoa học – công nghệ",0],["Lập trình viên đầu tiên trên thế giới là một nam giới",1]]},{"id":"p94","type":"mcq","q":"Phương án nào dưới đây KHÔNG đúng khi nói về việc sử dụng máy tính và ứng dụng tin học?","k":"<b>C</b> không đúng: máy tính và ứng dụng tin học giúp ích cho <b>tất cả mọi người</b>, kể cả phụ nữ và trẻ em gái.","o":["Giúp việc thông tin liên lạc giữa mọi người hiệu quả hơn.","Mọi người được tham gia vào môi trường học tập tốt hơn.","Phụ nữ và trẻ em gái không cần đến máy tính vì không giúp ích nhiều cho họ.","Mọi người đều có cơ hội học hỏi kiến thức để giúp nâng cao chất lượng cuộc sống và chăm sóc sức khoẻ tốt hơn."],"a":2},{"id":"lt1","type":"open","q":"Phỏng vấn một vài người (bố mẹ, người quen của bố mẹ, thầy cô,…) để tìm hiểu về những ứng dụng tin học giúp họ nâng cao hiệu quả công việc. Ghi lại: người được phỏng vấn, nghề nghiệp, ứng dụng tin học, lợi ích.","k":"Ghi đủ: nghề nghiệp, ứng dụng tin học cụ thể (phần mềm, thiết bị, dịch vụ), lợi ích (nhanh hơn, chính xác hơn, liên lạc dễ hơn,…).","label":"Luyện tập – câu 1"},{"id":"lt2","type":"mcq","q":"Bất bình đẳng giới trong sử dụng máy tính và ứng dụng tin học có thể dẫn tới hậu quả gì?","k":"<b>D</b>. Cả ba hậu quả trên.","o":["Phụ nữ và trẻ em gái không có cơ hội phát triển nghề nghiệp trong lĩnh vực công nghệ.","Phụ nữ và trẻ em gái không có cơ hội sử dụng công nghệ để nâng cao hiệu quả công việc và chất lượng cuộc sống.","Phụ nữ và trẻ em gái không theo kịp sự phát triển của xã hội.","Cả ba hậu quả trên."],"a":3},{"id":"vd1","type":"open","q":"Đề xuất với thầy cô giáo và các bạn tổ chức một cuộc thi thuyết trình về ứng dụng tin học trong các nghề nghiệp tại Việt Nam. Tìm hiểu và tạo ra bài thuyết trình của mình, chia sẻ với bạn bè. Ghi lại dàn ý bài thuyết trình.","k":"Dàn ý gợi ý: chọn một nghề ở Việt Nam → các ứng dụng tin học cụ thể → lợi ích (số liệu, ví dụ) → nghề tin học liên quan → kết luận. Có thể dùng bản mẫu trình chiếu (Bài 11a).","label":"Vận dụng – câu 1"},{"id":"vd2","type":"open","q":"Trong vai trò một học sinh lớp 8, em có thể làm gì để thúc đẩy bình đẳng giới ở lứa tuổi của em, ở khía cạnh sử dụng máy tính và ứng dụng tin học trong học tập?","k":"Ví dụ: khuyến khích các bạn nữ tham gia CLB Tin học, cuộc thi lập trình; chia sẻ máy tính, thiết bị công bằng khi học nhóm; giới thiệu tấm gương phụ nữ trong công nghệ; không dùng định kiến “con gái không giỏi máy tính”.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Ứng dụng tin học phù hợp trong các ngành nghề sẽ giúp <b>tăng hiệu quả công việc</b>.</li><li>Một số nghề thuộc lĩnh vực tin học và liên quan đến ứng dụng tin học ra đời và phát triển để đáp ứng yêu cầu cuộc sống và công việc.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Nghề nghiệp trong lĩnh vực tin học, cũng như cơ hội ứng dụng tin học để nâng cao hiệu quả công việc của các nghề nghiệp khác, là <b>bình đẳng cho tất cả mọi người</b>.</li></ul>"}]},"tin8-trang-chieu-nang-cao":{"id":"tin8-bai10a","ten":"Bài 10a. Định dạng nâng cao cho trang chiếu","cau":[{"id":"kd1","type":"open","q":"Bạn An được giao nhiệm vụ tạo bài trình chiếu để trình chiếu trong lễ ra mắt CLB Tin học. Với mục tiêu ngắn gọn, ấn tượng, sáng tạo,… theo em bạn An cần chú ý đến những điều gì khi tạo bài trình chiếu?","k":"Văn bản <b>ngắn gọn</b>, chỉ nêu ý chính; <b>màu sắc hài hoà</b>, hợp với chủ đề; chữ <b>đủ lớn</b>, tương phản với nền; có <b>số trang</b>, chân trang (tên CLB, ngày trình bày); có thể dùng hình ảnh, mẫu định dạng.","label":"Khởi động"},{"id":"hd1a","type":"mcq","q":"Văn bản ở hình nào chi tiết, đầy đủ hơn? Văn bản ở hình nào ngắn gọn hơn?","k":"Hình 10a.1 (văn bản trong tệp văn bản) viết thành câu <b>đầy đủ, chi tiết</b>; Hình 10a.2 (trên trang chiếu) chỉ ghi <b>ý chính, ngắn gọn</b>.","o":["Hình 10a.1 chi tiết, đầy đủ hơn; Hình 10a.2 ngắn gọn hơn.","Hình 10a.2 chi tiết, đầy đủ hơn; Hình 10a.1 ngắn gọn hơn.","Hai hình chi tiết như nhau.","Hai hình ngắn gọn như nhau."],"a":0},{"id":"hd1b","type":"mcq","q":"Văn bản trên trang chiếu có cần viết đầy đủ các thành phần của câu không?","k":"<b>Không cần.</b> Văn bản trên trang chiếu ngắn gọn, chỉ nêu ý chính; người trình bày sẽ nói thêm chi tiết.","o":["Không cần: chỉ nêu ý chính, ngắn gọn, súc tích.","Cần viết đầy đủ chủ ngữ, vị ngữ như văn bản thường.","Cần viết càng dài càng tốt.","Chỉ cần ghi tiêu đề, không cần nội dung."],"a":0},{"id":"mau","type":"sort","q":"Xếp mỗi màu vào đúng nhóm.","k":"<b>Nóng</b> (ấm áp, phấn chấn, năng nổ): đỏ, cam, vàng. <b>Lạnh</b> (bình tĩnh, hiền hoà, lắng dịu): xanh, tím. <b>Trung tính</b> (lịch sự, nhẹ nhàng): trắng, đen, be.","cats":["Màu nóng","Màu lạnh","Màu trung tính"],"items":[["Đỏ",0],["Cam",0],["Vàng",0],["Xanh lam",1],["Tím",1],["Xanh lục",1],["Trắng",2],["Đen",2],["Be",2]]},{"id":"gam","type":"sort","q":"Với mỗi bài trình chiếu dưới đây, nên dùng gam màu nào?","k":"Giải trí, lễ hội → <b>gam nóng</b>. Giáo dục, học tập → <b>gam trung tính</b>. Nghệ thuật, muốn ấn tượng mạnh, sự kiện tri ân → <b>gam lạnh</b>.","cats":["Gam màu nóng","Gam màu trung tính","Gam màu lạnh"],"items":[["Chủ đề giải trí, lễ hội",0],["Chủ đề giáo dục, học tập",1],["Chủ đề nghệ thuật, muốn mang lại ấn tượng mạnh",2],["Sự kiện tri ân",2]]},{"id":"nt","type":"sort","q":"Mỗi ý dưới đây là nên hay không nên?","k":"Nên: kết hợp màu cùng nhóm; chữ <b>tương phản cao</b> với nền; màu chủ đạo hài hoà với nội dung. Không nên: dùng <b>quá nhiều màu</b>; chữ và nền cùng tông (khó đọc).","cats":["Nên","Không nên"],"items":[["Kết hợp các màu cùng nhóm với nhau (đỏ, cam, vàng với màu nâu)",0],["Dùng thật nhiều màu trên một trang chiếu cho nổi bật",1],["Chọn màu chữ có độ tương phản cao với màu nền",0],["Chữ màu vàng trên nền vàng nhạt",1],["Chọn màu sắc chủ đạo hài hoà với nội dung",0]]},{"id":"p47","type":"mcq","q":"Em hãy chọn phương án đúng:","k":"<b>A</b>. Văn bản trên trang chiếu cần <b>ngắn gọn, súc tích</b>; dùng quá nhiều màu, nhiều phông làm rối mắt.","o":["Văn bản trên trang chiếu cần ngắn gọn, súc tích.","Văn bản trên trang chiếu càng chi tiết, đầy đủ càng tốt.","Sử dụng càng nhiều màu sắc cho văn bản trên trang chiếu càng giúp người nghe tập trung.","Sử dụng nhiều loại phông chữ cho văn bản trên trang chiếu sẽ thu hút được sự chú ý của người nghe."],"a":0},{"id":"hd2","type":"open","q":"Theo em, các trang chiếu có cần đánh số không? Có cần thêm các thông tin vào đầu trang và chân trang không? Vì sao?","k":"Có. <b>Số trang</b> giúp người trình bày và người nghe dễ theo dõi, dễ hỏi lại (“trang 3”). <b>Chân trang</b> ghi tên người trình bày, tên CLB/công ti, tiêu đề, thời gian trình chiếu → bài chuyên nghiệp, thông tin xuyên suốt.","label":"HĐ2 – Các thông tin cần thiết"},{"id":"hf","type":"match","q":"Ghép mỗi mục trong hộp thoại Header and Footer (Hình 10a.5) với tác dụng của nó.","k":"Date and time – a; Update automatically – b; Slide number – c; Footer – d; Don't show on title slide – e; Apply to All – f.","items":[["Date and time",1],["Update automatically",2],["Slide number",3],["Footer",4],["Don't show on title slide",5],["Apply to All",6]],"opts":["a) Thêm thông tin về ngày trình bày","b) Tự động cập nhật ngày trình bày","c) Chèn số trang","d) Thêm thông tin vào chân trang","e) Không thêm chân trang vào trang tiêu đề","f) Áp dụng cho tất cả các trang"]},{"id":"hf2","type":"mcq","q":"Trong phần mềm PowerPoint, muốn thêm đầu trang (Header) em làm thế nào?","k":"Ở chế độ <b>Slide</b> không thêm được đầu trang. Chỉ ở thẻ <b>Notes and Handouts</b> (in bài trình chiếu ra giấy) mới có chức năng thêm đầu trang.","o":["Chọn thẻ Notes and Handouts trong hộp thoại Header and Footer (đầu trang cho bản in phát cho người nghe).","Chọn thẻ Slide, đánh dấu Header.","Chọn Insert → Header như trong Word.","PowerPoint không có đầu trang."],"a":0},{"id":"nv1","type":"open","q":"Báo cáo kết quả: bài trình chiếu LeRaMatCLBTinhoc.pptx của em được định dạng thế nào (phông, cỡ, màu, căn lề)? Chân trang có những thông tin gì? Trang tiêu đề có chân trang không? Vì sao?","k":"Trang 1: tiêu đề Arial 60, vàng, đậm, căn giữa. Trang 2–4: tiêu đề Arial 54, xanh lá, đậm, căn giữa; nội dung Arial 32, đen, căn trái, dấu đầu dòng. Chân trang: ngày (tự cập nhật), “CLB Tin học – Trường THCS…”, số trang; trang tiêu đề <b>không có</b> chân trang vì chọn Don't show on title slide.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"mcq","q":"Em hãy chọn phương án SAI trong các phương án sau:","k":"<b>D</b> sai: bấm <b>Apply</b> chỉ áp dụng cho trang đang chọn; phải bấm <b>Apply to All</b> mới áp dụng cho tất cả các trang.","o":["Đầu trang và chân trang có thể được định dạng phông chữ, cỡ chữ, màu chữ khác nhau.","Có thể bỏ phần đầu trang và chân trang khỏi trang chiếu tiêu đề.","Có thể tự động cập nhật thông tin thời gian ở đầu trang và chân trang.","Những thông tin lựa chọn và nhập vào cửa sổ Header & Footer được tự động áp dụng cho tất cả các trang chiếu trong bài trình chiếu."],"a":3},{"id":"vd1","type":"open","q":"Tạo bài trình chiếu giới thiệu một nội dung Tin học em chọn (ví dụ: giới thiệu một ngôn ngữ lập trình, giới thiệu về bảng tính điện tử,…) để trình chiếu trong buổi sinh hoạt CLB Tin học của trường: chọn màu sắc, định dạng văn bản hài hoà, hợp lí với nội dung; đánh số trang, thêm đầu trang, chân trang. Mô tả ngắn bài của em.","k":"Ví dụ: chủ đề học tập → gam màu trung tính (nền trắng/be, chữ đen), điểm nhấn một màu; tiêu đề 40–54 pt, nội dung 24–32 pt; tối đa 2 phông; mỗi dòng một ý ngắn; chân trang có tên, ngày, số trang (Apply to All, không hiện ở trang tiêu đề).","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Văn bản trên trang chiếu cần được định dạng sao cho <b>màu sắc, cỡ chữ hài hoà, hợp lí</b> với nội dung.</li><li>Văn bản được định dạng phù hợp giúp đem lại hiệu quả cao trong việc truyền đạt nội dung trình chiếu.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Có thể <b>đánh số trang, thêm đầu trang, chân trang</b> vào các trang chiếu.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Insert → nhóm <b>Text</b> → <b>Header &amp; Footer</b> (hoặc Slide Number) mở hộp thoại Header and Footer.</li><li>Thẻ <b>Slide</b>: Date and time, Slide number, Footer, Don't show on title slide; <b>Apply</b> (trang đang chọn) hoặc <b>Apply to All</b> (mọi trang).</li><li>Đầu trang chỉ có ở thẻ <b>Notes and Handouts</b> (bản in cho người nghe).</li></ul>"}]},"tin8-tu-thuat-toan-den-chuong-trinh":{"id":"tin8-bai12","ten":"Bài 12. Từ thuật toán đến chương trình","cau":[{"id":"kd1","type":"open","q":"Bằng ngôn ngữ lập trình trực quan, bạn Khoa muốn tạo chương trình điều khiển nhân vật di chuyển theo đường đi là các hình như: tam giác đều, vuông,… Theo em, bạn Khoa cần thực hiện những công việc gì?","k":"Xác định <b>đường đi</b> (độ dài cạnh, góc quay ở mỗi đỉnh); mô tả <b>thuật toán</b> (liệt kê các bước hoặc sơ đồ khối); viết <b>chương trình</b> bằng các lệnh Scratch tương ứng; chạy thử và sửa lỗi.","label":"Khởi động"},{"id":"hd1a","type":"mcq","q":"Nhân vật di chuyển theo đường đi là một tam giác đều. Khi đi hết một cạnh, nhân vật cần quay một góc bao nhiêu độ để đi tiếp cạnh sau?","k":"Góc trong của tam giác đều là 60°, nên nhân vật phải quay <b>180° − 60° = 120°</b> (Hình 12.2).","o":["120 độ","60 độ","90 độ","180 độ"],"a":0},{"id":"hd1b","type":"order","q":"Liệt kê lần lượt các bước của thuật toán điều khiển nhân vật đi theo tam giác đều (sắp xếp bằng nút ↑ ↓).","k":"Lần lặp ← 1 → kiểm tra Lần lặp ≤ 3 → di chuyển 60 bước → quay trái 120 độ → tăng Lần lặp, quay lại kiểm tra. Đây là <b>cấu trúc lặp</b> 3 lần.","items":{"a":"Gán Lần lặp ← 1.","b":"Nếu Lần lặp ≤ 3 thì làm tiếp bước sau, ngược lại thì kết thúc.","c":"Di chuyển 60 bước.","d":"Quay trái 120 độ.","e":"Tăng Lần lặp lên 1 đơn vị, quay lại bước kiểm tra Lần lặp ≤ 3."},"ans":["a","b","c","d","e"],"start":["c","e","a","d","b"]},{"id":"map","type":"match","q":"Ghép mỗi phần của sơ đồ khối (Hình 12.3a) với lệnh Scratch tương ứng (Hình 12.3b).","k":"Bắt đầu – a; ba khối điều khiển vòng lặp – b (lặp lại 3); Di chuyển 60 bước – c; Quay trái 120 độ – d (xoay ↺ 120 độ).","items":[["Bắt đầu",1],["Lần lặp ← 1; Lần lặp ≤ 3; Tăng Lần lặp lên 1 đơn vị",2],["Di chuyển 60 bước",3],["Quay trái 120 độ",4]],"opts":["a) Khi bấm vào lá cờ xanh","b) lặp lại 3","c) di chuyển 60 bước","d) xoay ↺ 120 độ"]},{"id":"ct","type":"mcq","q":"Chương trình là:","k":"<b>Chương trình là dãy các lệnh điều khiển máy tính thực hiện một thuật toán.</b>","o":["Dãy các lệnh điều khiển máy tính thực hiện một thuật toán.","Sơ đồ khối mô tả thuật toán.","Các bước liệt kê bằng ngôn ngữ tự nhiên.","Một hình vẽ trên sân khấu Scratch."],"a":0},{"id":"p74","type":"mcq","q":"Bạn An muốn bổ sung lệnh đợi 1 giây để điều khiển nhân vật dừng lại 1 giây sau khi đi hết mỗi cạnh của tam giác. Lệnh này đặt ở đâu?","k":"Lệnh đợi phải nằm <b>bên trong vòng lặp</b> để được thực hiện sau mỗi cạnh: sau “Quay trái 120 độ” (hoặc ngay sau “Di chuyển 60 bước”). Đặt ngoài vòng lặp thì chỉ dừng 1 lần.","o":["Trong sơ đồ khối: sau “Quay trái 120 độ”, trước “Tăng Lần lặp”. Trong Scratch: bên trong khối lặp lại 3, sau lệnh xoay ↺ 120 độ.","Trước khối lặp lại 3.","Sau khối lặp lại 3 (bên ngoài vòng lặp).","Trước lệnh Khi bấm vào lá cờ xanh."],"a":0},{"id":"nv1","type":"mcq","q":"Chạy chương trình ở Nhiệm vụ 1 (Hình 12.3b), em thấy gì trên sân khấu?","k":"Nhân vật đi theo tam giác đều và trở về vị trí ban đầu. Vì <b>chưa đặt bút</b> và chạy rất nhanh nên gần như không thấy gì: cần thêm các lệnh Bút vẽ và lệnh đợi (Nhiệm vụ 2).","o":["Nhân vật đi hết 3 cạnh rất nhanh rồi trở về chỗ cũ, không để lại nét vẽ.","Nhân vật vẽ ra một hình tam giác.","Nhân vật đứng yên không làm gì.","Nhân vật vẽ ra hình vuông."],"a":0},{"id":"nv2","type":"open","q":"Báo cáo kết quả Nhiệm vụ 2: em đã thêm những lệnh nào để nhân vật vừa di chuyển vừa vẽ tam giác đều? Mỗi lệnh có tác dụng gì?","k":"<b>xoá tất cả</b> (xoá nét vẽ cũ), <b>đặt bút</b> (bắt đầu vẽ), <b>chọn bút màu</b>, <b>đợi 1 giây</b> trong vòng lặp (dừng sau mỗi cạnh để quan sát), <b>nhấc bút</b> ở cuối (thôi vẽ). Lưu tệp VeHinh.sb3.","label":"Nhiệm vụ 2"},{"id":"lt1","type":"mcq","q":"Sơ đồ khối của thuật toán điều khiển nhân vật đi theo một hình vuông khác sơ đồ khối của tam giác đều ở những chỗ nào?","k":"Hình vuông có 4 cạnh và 4 góc vuông: <b>Lần lặp ≤ 4</b>, <b>Quay trái 90 độ</b>; các khối khác giữ nguyên.","o":["Điều kiện lặp là Lần lặp ≤ 4 và quay trái 90 độ.","Điều kiện lặp là Lần lặp ≤ 3 và quay trái 90 độ.","Điều kiện lặp là Lần lặp ≤ 4 và quay trái 120 độ.","Không khác gì."],"a":0},{"id":"lt2","type":"open","q":"Nâng cấp chương trình VeHinh.sb3: bổ sung một nhân vật mới và lập trình để khi nháy chuột vào nhân vật này thì chương trình thực hiện thuật toán vẽ hình vuông. Em đã dùng những khối lệnh nào?","k":"Thêm nhân vật → khối sự kiện <b>Khi bấm vào nhân vật này</b> → xoá tất cả, đặt bút, <b>lặp lại 4</b> {di chuyển 60 bước, xoay ↺ <b>90</b> độ, đợi 1 giây}, nhấc bút.","label":"Luyện tập – câu 2"},{"id":"lt3a","type":"match","q":"Hoàn thành sơ đồ khối Hình 12.6 (xe dừng lại khi cách hòn đá nhỏ hơn 120 bước): ghép mỗi lệnh với ô phù hợp.","k":"Ô 1 (điều kiện): <b>Cách hòn đá &lt; 120 bước?</b> Ô 2 (lệnh lặp lại khi điều kiện Sai): <b>Di chuyển 5 bước</b>.","items":[["Ô số 1 (hình thoi)",1],["Ô số 2 (hình chữ nhật)",2]],"opts":["Cách hòn đá < 120 bước?","Di chuyển 5 bước"]},{"id":"lt3b","type":"open","q":"Viết chương trình Scratch thực hiện thuật toán ở câu 3a. Em dùng khối lệnh điều khiển nào?","k":"Khi bấm vào lá cờ xanh → <b>lặp lại cho đến khi</b> ⟨khoảng cách đến Hòn đá &lt; 120⟩ { di chuyển 5 bước }.","label":"Luyện tập – câu 3b"},{"id":"vd1","type":"match","q":"Đường đi của nhân vật có thể là hình vuông, lục giác đều,… Khi đó các con số nào trong chương trình ở Hình 12.3 cần phải thay đổi? Ghép mỗi hình với cặp số phù hợp.","k":"Cần thay <b>số lần lặp</b> (= số cạnh n) và <b>góc quay</b> (= 360 : n). Tam giác 3 – 120°; vuông 4 – 90°; ngũ giác 5 – 72°; lục giác 6 – 60°.","items":[["Tam giác đều",1],["Hình vuông",2],["Ngũ giác đều",3],["Lục giác đều",4]],"opts":["a) lặp lại 3, xoay 120 độ","b) lặp lại 4, xoay 90 độ","c) lặp lại 5, xoay 72 độ","d) lặp lại 6, xoay 60 độ"]}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Chương trình</b> là dãy các lệnh điều khiển máy tính thực hiện một thuật toán.</li><li>Mỗi bước của thuật toán (mô tả bằng sơ đồ khối) được thực hiện bằng lệnh tương ứng của ngôn ngữ lập trình.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Nhóm <b>Bút vẽ</b>: xoá tất cả, đặt bút, chọn bút màu, nhấc bút.</li><li>Lệnh <b>đợi … giây</b> (Điều khiển) đặt trong vòng lặp để dừng sau mỗi cạnh.</li></ul>"}]},"tin9-bai-toan-tin-hoc":{"id":"tin9-bai15","ten":"Bài 15. Bài toán tin học","cau":[{"id":"kd1","type":"open","q":"Tính lương là một phần của những vấn đề mà doanh nghiệp cần phải giải quyết. Theo em, máy tính có thể giúp doanh nghiệp những việc gì trong việc trả lương cho nhân viên?","k":"Ví dụ: tính số tiền lương của từng người theo số giờ làm, lập phiếu chi lương, lưu trữ hồ sơ lương… nhanh, chính xác.","label":"Khởi động"},{"id":"hd1","type":"mcq","q":"Hình 15.1 mô tả một quy trình thanh toán tiền lương. Bước nào trong quy trình đó thường được giao cho máy tính thực hiện?","k":"Bước <b>Tính toán tiền lương</b> thường được giao cho máy tính. Quy trình giải quyết vấn đề có những bước (vấn đề nhỏ hơn) có thể chuyển giao cho máy tính thực hiện.","o":["Tính toán tiền lương.","Bắt đầu.","Thanh toán tiền lương (trao tiền tận tay).","Kết thúc."],"a":0},{"id":"hd2","type":"open","q":"Hằng tuần, một công ti phải tính lương cho các nhân viên. Tiền lương của một nhân viên theo tuần phụ thuộc vào mức lương theo giờ và số giờ làm việc mỗi tuần (tối thiểu 1 giờ, tối đa 60 giờ). Định mức là 40 giờ/tuần; mỗi giờ vượt định mức được trả gấp 1,5 lần mức lương của họ. Hãy trình bày các bước giải quyết vấn đề tính lương của công ti.","k":"Tìm hiểu: biết mức lương theo giờ, số giờ làm (1–60), cần tính tiền lương tuần. Phân tích: chia thành giờ trong định mức (≤ 40) và giờ vượt định mức. Lựa chọn giải pháp: lương = giờ định mức × mức lương + giờ vượt × mức lương × 1,5. Thực hiện: tính cho từng nhân viên. Đánh giá: kiểm tra với vài trường hợp (dưới 40 giờ, trên 40 giờ).","label":"HĐ2 – Bài toán tính lương"},{"id":"dv","type":"sort","q":"Xếp mỗi thông tin dưới đây vào nhóm Đầu vào hoặc Đầu ra của bài toán tương ứng.","k":"<b>Đầu vào</b> là những giá trị cho trước; <b>đầu ra</b> là giá trị phải tìm hoặc kết quả của hành động.","cats":["Đầu vào","Đầu ra"],"items":[["Mức lương và số giờ làm việc trong tuần (bài toán tính lương)",0],["Tiền lương theo tuần của nhân viên",1],["Các hệ số a, b, c (giải phương trình ax² + bx + c = 0)",0],["Nghiệm của phương trình hoặc thông báo “phương trình vô nghiệm”",1],["Hai số nguyên a và b (tính ước số chung lớn nhất)",0],["Ước số chung lớn nhất của a và b",1],["Văn bản (câu) tiếng Việt (dịch sang tiếng Anh)",0],["Câu tiếng Anh dưới dạng văn bản hoặc âm thanh",1]]},{"id":"p80","type":"open","q":"Hãy mô tả đầu vào và đầu ra của bài toán xác định một số nguyên dương có phải số nguyên tố hay không.","k":"Đầu vào: một số nguyên dương n. Đầu ra: thông báo “n là số nguyên tố” hoặc “n không phải số nguyên tố”.","label":"Câu hỏi tr.80"},{"id":"hd3","type":"open","q":"Em hãy nêu các bước để chuyển bài toán tính lương (trong Hoạt động 2) cho máy tính thực hiện bằng cách lập chương trình.","k":"1) Xác định bài toán: đầu vào muc_luong, tgian_laodong; đầu ra tien_luong. 2) Xây dựng thuật toán (Hình 15.3). 3) Cài đặt thuật toán thành chương trình. 4) Gỡ lỗi và hiệu chỉnh chương trình.","label":"HĐ3 – Tính lương bằng máy tính"},{"id":"q4","type":"order","q":"Sắp xếp các bước giải một bài toán tin học theo đúng thứ tự.","k":"Xác định bài toán → Xây dựng thuật toán → Cài đặt thuật toán → Gỡ lỗi và hiệu chỉnh chương trình.","items":{"a":"Xác định bài toán","b":"Xây dựng thuật toán","c":"Cài đặt thuật toán","d":"Gỡ lỗi và hiệu chỉnh chương trình"},"ans":["a","b","c","d"],"start":["c","a","d","b"]},{"id":"q4m","type":"match","q":"Mỗi việc dưới đây thuộc bước nào trong quy trình giải bài toán tính lương bằng máy tính?","k":"1 – Xác định bài toán; 2 – Xây dựng thuật toán; 3 – Cài đặt thuật toán; 4 – Gỡ lỗi và hiệu chỉnh.","items":[["Đầu vào là muc_luong, tgian_laodong; đầu ra là tien_luong.",1],["Chia thành: nhập dữ liệu, xử lí để tính tiền lương, xuất kết quả; mô tả bằng sơ đồ khối Hình 15.3.",2],["Viết chương trình thực hiện thuật toán, dùng thêm các biến luong_dmuc, luong_vuot.",3],["Chạy chương trình với nhiều dữ liệu khác nhau, sửa lỗi để chương trình chạy đúng.",4]],"opts":["Xác định bài toán","Xây dựng thuật toán","Cài đặt thuật toán","Gỡ lỗi và hiệu chỉnh chương trình"]},{"id":"luong","type":"mcq","q":"Chạy thuật toán tính lương với mức lương 50 (nghìn đồng/giờ) và số giờ làm việc 45. Tiền lương tuần của nhân viên là bao nhiêu?","k":"tgian_dmuc = 40, tgian_vuot = 5; luong_dmuc = 40 × 50 = 2 000; luong_vuot = 5 × 50 × 1,5 = 375; tien_luong = <b>2 375</b>.","o":["2 375 nghìn đồng","2 250 nghìn đồng","3 375 nghìn đồng","2 000 nghìn đồng"],"a":0},{"id":"mx","type":"mcq","q":"Với đầu vào 7, 3, 12, 5, 0, biến max lần lượt nhận những giá trị nào?","k":"max ← 0; nhập 7 > 0 → max = 7; 3 không lớn hơn 7; 12 > 7 → max = 12; 5 không lớn hơn; nhập 0 → dừng, xuất 12.","o":["0, 7, 12","0, 7, 3, 12, 5","7, 12, 0","0, 12"],"a":0},{"id":"mx0","type":"mcq","q":"Nếu ngay lần nhập đầu tiên đã nhập số 0 thì thuật toán Hình 15.4 cho đầu ra là gì?","k":"Vòng lặp không thực hiện lần nào, max = 0 nên xuất <b>“Không có dữ liệu”</b>.","o":["“Không có dữ liệu”","0","Thuật toán lặp mãi không dừng","Báo lỗi"],"a":0},{"id":"p82","type":"mcq","q":"Bài toán tin học được xem như một vấn đề cần giải quyết. Khi đó, bước nào trong quy trình giải bài toán tin học tương ứng với bước thực hiện giải pháp trong giải quyết vấn đề?","k":"<b>C. Cài đặt thuật toán</b>: triển khai giải pháp (thuật toán) thành chương trình máy tính.","o":["Xác định bài toán.","Xây dựng thuật toán.","Cài đặt thuật toán.","Gỡ lỗi và hiệu chỉnh chương trình."],"a":2},{"id":"lt1","type":"open","q":"Vẽ sơ đồ của thuật toán giải bài toán xác định một số có phải số nguyên tố hay không bằng cách chỉ sử dụng những cấu trúc điều khiển cơ bản.","k":"Bắt đầu → Nhập n → n < 2? đúng: xuất “không phải số nguyên tố”. Sai: i ← 2 → lặp khi i × i ≤ n: nếu n chia hết cho i thì xuất “không phải số nguyên tố”, kết thúc; i ← i + 1. Ra khỏi vòng lặp: xuất “là số nguyên tố” → Kết thúc.","label":"Luyện tập"},{"id":"vd1","type":"open","q":"Hãy mô tả đầu vào, đầu ra của bài toán sắp xếp một dãy số theo thứ tự tăng dần.","k":"Đầu vào: một dãy số (ví dụ 5, 2, 8, 1). Đầu ra: dãy số đó được sắp xếp theo thứ tự tăng dần (1, 2, 5, 8).","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Vẽ sơ đồ khối của giải thuật sắp xếp nổi bọt để sắp xếp một dãy số theo thứ tự tăng dần.","k":"Lặp: duyệt các cặp phần tử liền kề; nếu phần tử trước lớn hơn phần tử sau thì đổi chỗ; lặp lại cho đến khi một lượt duyệt không còn đổi chỗ nào.","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Bài toán tin học là một nhiệm vụ có thể giao cho máy tính thực hiện. Bài toán đó được xác định bởi dữ liệu đã biết (đầu vào), dữ liệu cần tìm (đầu ra).</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Quy trình giải một bài toán tin học gồm các bước: 1) Xác định bài toán; 2) Xây dựng thuật toán; 3) Cài đặt thuật toán; 4) Gỡ lỗi và hiệu chỉnh chương trình.</li></ul>"}]},"tin9-cong-cu-truc-quan":{"id":"tin9-bai8","ten":"Bài 8. Thực hành: Sử dụng công cụ trực quan trình bày thông tin trong trao đổi và hợp tác","cau":[{"id":"kd1","type":"open","q":"Ở Bài 7, em đã biết những cách nào để sử dụng sơ đồ tư duy và bài trình chiếu trong trao đổi, hợp tác? Hôm nay nhóm em sẽ tạo sản phẩm gì cho Triển lãm tin học?","k":"Bốn cách: <b>trình bày trực tiếp</b>; chia sẻ để <b>xem</b>; chia sẻ để <b>cập nhật</b>; chia sẻ để <b>cộng tác theo thời gian thực</b>. Hôm nay nhóm tạo <b>sơ đồ tư duy có đính kèm dữ liệu</b> (LuocSu.emm) và <b>bài trình chiếu</b> có hình ảnh, sơ đồ, video (LuocSuMayTinh) về Lược sử công cụ tính toán.","label":"Mở đầu"},{"id":"kp","type":"mcq","q":"Quan sát bảng tính KinhPhi.xlsx (Hình 8.1). Tổng chi phí cho phần nội dung “Lược sử công cụ tính toán” là bao nhiêu?","k":"In ảnh màu: 8 × 8 000 = 64 000; in nội dung chú thích: 8 × 1 000 = 8 000; văn phòng phẩm: 50 000. Tổng: 64 000 + 8 000 + 50 000 = <b>122 000 đồng</b>. Thành tiền nên tính bằng công thức (ví dụ =C3*D3, =SUM(E3:E5)).","o":["64 000 đồng.","72 000 đồng.","114 000 đồng.","122 000 đồng."],"a":3},{"id":"lenh","type":"sort","q":"Với mỗi dữ liệu dưới đây, em dùng lệnh nào của MindMaple Lite để đưa vào sơ đồ tư duy?","k":"Các <b>tệp</b> trên máy (bảng tính, hình ảnh, văn bản) dùng <b>Insert/Attachment/Attachment</b>. <b>Đường liên kết</b> đến video trên Internet dùng <b>Insert/Hyperlink</b>, dán địa chỉ vào ô <b>Link to</b>.","cats":["Insert/Attachment","Insert/Hyperlink"],"items":[["Tệp bảng tính KinhPhi.xlsx",0],["Tệp hình ảnh Pascaline.png",0],["Tệp văn bản CharlesBabbage.docx",0],["Đường liên kết đến video về Charles Babbage trên Internet",1]]},{"id":"dk","type":"order","q":"Sắp xếp các bước đính kèm một tệp vào nhánh của sơ đồ tư duy theo đúng thứ tự (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → c</b>. Chọn nhánh → Insert/Attachment/Attachment → chọn tệp, nháy Open → biểu tượng tệp đính kèm xuất hiện ở nhánh.","items":{"a":"Chọn tệp cần chèn trong hộp thoại Open, nháy chuột chọn Open.","b":"Chọn nhánh của sơ đồ tư duy cần đính kèm tệp.","c":"Biểu tượng tệp đính kèm xuất hiện ở nhánh của sơ đồ.","d":"Chọn Insert/Attachment/Attachment."},"ans":["b","d","a","c"],"start":["a","b","c","d"]},{"id":"nv1","type":"open","q":"Báo cáo kết quả Nhiệm vụ 1: em đã tạo sơ đồ tư duy (lưu với tên LuocSu.emm) với những nhánh nào và đã đính kèm những dữ liệu gì vào nhánh nào?","k":"Ví dụ: chủ đề chính Triển lãm tin học; các nhánh Sản phẩm công nghệ số, Lược sử công cụ tính toán (Máy tính cơ học, Máy tính điện tử), Dự kiến thu chi. Đính kèm: <b>Pascaline.png</b> vào nhánh Blaise Pascal; <b>CharlesBabbage.docx</b> và <b>liên kết video</b> vào nhánh Charles Babbage; <b>KinhPhi.xlsx</b> vào nhánh Dự kiến thu chi.","label":"NV1 – Kết quả"},{"id":"tb","type":"mcq","q":"Nhóm trưởng trình bày sơ đồ tư duy trước nhóm để các thành viên trao đổi, bổ sung nội dung ngay tại chỗ. Đó là cách sử dụng nào?","k":"Đó là <b>trình bày trực tiếp</b>: diễn giải được bức tranh toàn cảnh, làm rõ chi tiết và trả lời ngay câu hỏi của các thành viên.","o":["Trình bày trực tiếp.","Chia sẻ để các thành viên khác xem.","Chia sẻ để các thành viên chủ động cập nhật.","Chia sẻ để cộng tác theo thời gian thực."],"a":0},{"id":"pc","type":"open","q":"Sau khi trao đổi, thảo luận, nhóm em cần bổ sung thêm nội dung gì? Ghi lại bảng phân công công việc để các thành viên tiếp tục hoàn thành.","k":"Ví dụ:<ul><li><b>Bổ sung:</b> các thế hệ máy tính điện tử (ENIAC, IBM 7090, IBM System/360, Micral, iPhone); ảnh minh hoạ; video về ENIAC.</li><li><b>Phân công:</b> An – trang Blaise Pascal; Minh – trang Charles Babbage và video; Khoa – sơ đồ dòng thời gian, các thế hệ máy tính; nhóm trưởng – tổng hợp, kiểm tra.</li></ul>","label":"NV2 – Bổ sung và phân công"},{"id":"tg","type":"match","q":"Quan sát sơ đồ dòng thời gian (Hình 8.6). Ghép mỗi mốc năm với máy tính tương ứng.","k":"1642 – a, 1833 – b, 1945 – c, 1959 – d, 1964 – e, 1973 – f, 2007 – g. Sơ đồ dòng thời gian giúp trình bày <b>tiến trình lịch sử</b> rõ ràng, dễ nhớ.","items":[["1642",1],["1833",2],["1945",3],["1959",4],["1964",5],["1973",6],["2007",7]],"opts":["a) Máy tính cơ học đầu tiên (Blaise Pascal)","b) Máy tính đa năng (Charles Babbage)","c) ENIAC – thế hệ thứ nhất","d) IBM 7090 – thế hệ thứ hai","e) IBM System/360 – thế hệ thứ ba","f) Máy vi tính Micral – thế hệ thứ tư","g) iPhone – thế hệ thứ năm"]},{"id":"cc","type":"match","q":"Mỗi nội dung dưới đây nên trình bày bằng công cụ trực quan nào cho hợp lí?","k":"1 – a, 2 – b, 3 – c, 4 – d. Chọn loại minh hoạ <b>truyền tải tốt nhất thông điệp</b>, đơn giản và rõ ràng.","items":[["1) Các mốc lịch sử của công cụ tính toán",1],["2) Hình dáng máy tính cơ học Pascaline",2],["3) Cách máy tính của Charles Babbage hoạt động",3],["4) So sánh chi phí các khoản trong bảng kinh phí",4]],"opts":["a) Sơ đồ dòng thời gian","b) Hình ảnh","c) Video","d) Biểu đồ"]},{"id":"dv","type":"order","q":"Sắp xếp các bước tạo bài trình chiếu “Lược sử công cụ tính toán” theo thứ tự trong SGK (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → a → d → f → c → e</b>. Trang tiêu đề → dàn ý → sơ đồ dòng thời gian → Blaise Pascal (ảnh) → Charles Babbage (video) → lưu tệp.","items":{"a":"Tạo trang dàn ý (Hình 8.5).","b":"Khởi động phần mềm trình chiếu, tạo trang tiêu đề.","c":"Thêm trang về Charles Babbage, chèn video bằng Insert/Video/Insert Video from This Device.","d":"Dùng mẫu có sẵn tạo sơ đồ dòng thời gian (Hình 8.6).","e":"Lưu bài trình chiếu với tên LuocSuMayTinh.","f":"Thêm trang về Blaise Pascal, chèn hình ảnh máy tính Pascaline."},"ans":["b","a","d","f","c","e"],"start":["a","b","c","d","e","f"]},{"id":"nv3","type":"open","q":"Báo cáo kết quả Nhiệm vụ 3: bài trình chiếu LuocSuMayTinh của em gồm những trang nào? Em đã dùng hình ảnh, sơ đồ, video ở trang nào?","k":"Ví dụ: (1) Trang tiêu đề; (2) Dàn ý; (3) Sơ đồ dòng thời gian (dùng mẫu SmartArt hoặc mẫu trên Internet); (4) Blaise Pascal – ảnh Pascaline; (5) Charles Babbage – video; (6) Các thế hệ máy tính điện tử. Hình ảnh rõ nét, chữ đủ lớn, mỗi trang một ý chính.","label":"NV3 – Kết quả"},{"id":"lta","type":"open","q":"Lựa chọn một trong các cách sử dụng bài trình chiếu trình bày thông tin ở Bài 7 để một thành viên đóng vai trò trưởng nhóm trình bày bài trình chiếu LuocSuMayTinh trước tập thể. Nhóm em chọn cách nào? Vì sao?","k":"Thường chọn <b>trình bày trực tiếp</b> trước tập thể: người trình bày diễn giải toàn cảnh, làm rõ chi tiết, trả lời câu hỏi ngay. Có thể kết hợp chia sẻ tệp để mọi người xem lại sau.","label":"Luyện tập – a"},{"id":"ltb","type":"open","q":"Các thành viên trao đổi, thảo luận để rà soát nội dung bài trình chiếu theo các yêu cầu được nêu trong Nhiệm vụ 3. Ghi lại những điểm cần chỉnh sửa.","k":"Rà soát: đủ các trang theo dàn ý chưa; sơ đồ dòng thời gian đúng mốc chưa; hình ảnh có <b>sắc nét, đúng nội dung</b>; video chạy được; chữ có đọc được từ xa; màu sắc, bố cục hợp lí; có ghi nguồn tư liệu.","label":"Luyện tập – b"},{"id":"ltc","type":"open","q":"Chỉnh sửa bài trình chiếu theo kết quả thảo luận ở câu b. Em đã chỉnh sửa những gì?","k":"Ví dụ: tăng cỡ chữ; thay ảnh mờ bằng ảnh rõ nét; sửa mốc năm sai; rút gọn chữ trên trang chiếu; thêm trang nguồn tham khảo; thống nhất màu sắc, phông chữ.","label":"Luyện tập – c"},{"id":"th","type":"match","q":"Tìm hiểu đặc điểm của máy tính từng thế hệ. Ghép mỗi thế hệ với linh kiện điện tử chính được sử dụng.","k":"Thế hệ 1 – <b>đèn điện tử chân không</b> (to, nặng, tốn điện); thế hệ 2 – <b>transistor</b>; thế hệ 3 – <b>mạch tích hợp IC</b>; thế hệ 4 – <b>bộ vi xử lí</b>, máy vi tính cá nhân; thế hệ 5 – máy tính nhỏ gọn, thông minh, <b>trí tuệ nhân tạo</b>, kết nối Internet (điện thoại thông minh).","items":[["1) Thế hệ thứ nhất (1945 – 1955)",1],["2) Thế hệ thứ hai (1955 – 1965)",2],["3) Thế hệ thứ ba (1965 – 1974)",3],["4) Thế hệ thứ tư (1974 – 1990)",4],["5) Thế hệ thứ năm (1990 – nay)",5]],"opts":["a) Đèn điện tử chân không","b) Bóng bán dẫn (transistor)","c) Mạch tích hợp (IC)","d) Bộ vi xử lí, mạch tích hợp cỡ rất lớn","e) Thiết bị thông minh, trí tuệ nhân tạo, kết nối mạng"]},{"id":"vd1","type":"open","q":"Em hãy bổ sung vào bài trình chiếu LuocSuMayTinh nội dung về đặc điểm của máy tính từng thế hệ, sử dụng công cụ trực quan hợp lí. Nhóm em phân công ai chia sẻ bài trình chiếu, chia sẻ theo cách nào để cùng hoàn chỉnh sản phẩm?","k":"Ví dụ: thêm 5 trang (mỗi thế hệ một trang) hoặc một <b>bảng so sánh</b> các thế hệ, kèm ảnh linh kiện (đèn chân không, transistor, IC, bộ vi xử lí). Bạn Khoa đưa bài lên Google Trang trình bày và <b>chia sẻ quyền chỉnh sửa</b> để các bạn cùng cập nhật; dùng nhóm Zalo để trao đổi.","label":"Vận dụng – Bổ sung và chia sẻ"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Đính kèm <b>tệp</b> (văn bản, hình ảnh, bảng tính): chọn nhánh → <b>Insert/Attachment/Attachment</b> → chọn tệp → Open.</li><li>Đính kèm <b>đường liên kết</b> (video trên Internet): chọn nhánh → <b>Insert/Hyperlink</b> → dán địa chỉ vào ô Link to → OK.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Trình bày sơ đồ tư duy trước nhóm giúp các thành viên <b>trao đổi, bổ sung</b> nội dung và <b>phân công</b> công việc tiếp theo.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Bài trình chiếu nên có: trang tiêu đề, trang dàn ý, nội dung minh hoạ bằng <b>hình ảnh, sơ đồ, video</b> hợp lí.</li><li>Chèn video từ máy: <b>Insert/Video/Insert Video from This Device</b>.</li></ul>"}]},"tin9-danh-gia-chat-luong-thong-tin":{"id":"tin9-bai3","ten":"Bài 3. Thực hành: Đánh giá chất lượng thông tin","cau":[{"id":"kd1","type":"open","q":"Theo em, làm thế nào để tìm kiếm được thông tin giúp giải quyết vấn đề chọn trường THPT và đánh giá được chất lượng thông tin mà em đã tìm được?","k":"<ul><li><b>Xác định rõ mục đích</b> và những <b>yêu cầu cụ thể</b> của thông tin cần tìm (điểm chuẩn, chỉ tiêu, khoảng cách,…).</li><li>Tìm kiếm bằng <b>máy tìm kiếm với từ khoá phù hợp</b>, công cụ hội thoại thông minh; ưu tiên <b>nguồn tin cậy</b>; lưu lại thông tin tìm được.</li><li><b>Đánh giá</b> thông tin theo bốn tiêu chí: mới, chính xác, đầy đủ, sử dụng được; rồi mới ra quyết định.</li></ul>","label":"Mở đầu"},{"id":"md","type":"open","q":"Em hãy xác định mục đích tìm kiếm thông tin và nêu ít nhất ba yêu cầu cụ thể của thông tin cần tìm để chọn trường THPT.","k":"<b>Mục đích:</b> tìm thông tin về các trường THPT tại địa phương để quyết định lựa chọn nguyện vọng đăng kí.<br><b>Yêu cầu cụ thể</b> (ví dụ):<ul><li>Điểm chuẩn và chỉ tiêu tuyển sinh của trường trong ba năm gần nhất.</li><li>Tỉ lệ học sinh tốt nghiệp THPT và trúng tuyển vào các trường đại học có uy tín.</li><li>Những nhóm môn học mà trường có thế mạnh.</li><li>Các hoạt động ngoại khoá của trường.</li><li>Khoảng cách từ nhà đến trường.</li></ul>","label":"NV1 – Mục đích, yêu cầu"},{"id":"yc","type":"sort","q":"Để chọn trường THPT, thông tin nào dưới đây em cần tìm, thông tin nào không cần thiết?","k":"Cần tìm những thông tin <b>liên quan trực tiếp</b> đến việc chọn trường: điểm chuẩn, chỉ tiêu, tỉ lệ tốt nghiệp và đỗ đại học, môn thế mạnh, hoạt động ngoại khoá, khoảng cách. Số lượt theo dõi hay người nổi tiếng không giúp em chọn trường phù hợp.","cats":["Cần tìm","Không cần thiết"],"items":[["Điểm chuẩn và chỉ tiêu tuyển sinh ba năm gần nhất",0],["Tỉ lệ tốt nghiệp THPT, đỗ vào các trường đại học uy tín",0],["Các nhóm môn học trường có thế mạnh",0],["Khoảng cách từ nhà đến trường",0],["Số lượt theo dõi trang mạng xã hội của trường",1],["Ca sĩ nổi tiếng từng đến trường biểu diễn",1]]},{"id":"tk","type":"open","q":"Em hãy tìm kiếm thông tin về một trường THPT ở địa phương. Ghi lại: từ khoá (hoặc câu hỏi cho công cụ hội thoại thông minh) em đã dùng, tóm tắt thông tin tìm được và địa chỉ trang web.","k":"Ví dụ:<ul><li><b>Từ khoá:</b> “điểm chuẩn lớp 10 THPT Lê Xoay 2025”, “Olympic Tin học 2023 tỉnh Phú Thọ”.</li><li><b>Câu hỏi cho AI:</b> “Hãy cho biết tên các trường THPT gần Vĩnh Tường, Phú Thọ”.</li><li><b>Tóm tắt:</b> điểm chuẩn năm 2025 là …, chỉ tiêu … học sinh, có câu lạc bộ …</li><li><b>Địa chỉ:</b> phutho.edu.vn/…, trang web của trường, báo Giáo dục Việt Nam,…</li></ul>Lưu thông tin vào một tệp (văn bản, bảng tính) để dùng ở Nhiệm vụ 2.","label":"NV1 – Tìm kiếm và lưu trữ"},{"id":"ng","type":"match","q":"Mỗi loại thông tin dưới đây nên tìm ở nguồn nào để đảm bảo độ tin cậy?","k":"1 – a, 2 – b, 3 – c, 4 – d. Với mỗi yêu cầu cụ thể, cần xem xét <b>nguồn có thẩm quyền</b>. Thông tin từ AI hay từ Internet nói chung cần được <b>đối chiếu, kiểm chứng</b> trước khi sử dụng.","items":[["1) Thông tin tuyển sinh vào lớp 10",1],["2) Các hoạt động giáo dục, ngoại khoá của trường",2],["3) Danh sách các trường THPT gần nhà",3],["4) Thành tích học sinh giỏi, Olympic của trường",4]],"opts":["a) Website Sở Giáo dục và Đào tạo","b) Website của nhà trường","c) Công cụ hội thoại thông minh (AI), rồi kiểm chứng lại","d) Máy tìm kiếm, ưu tiên báo chính thống"]},{"id":"dm","type":"mcq","q":"Trang web của các Sở Giáo dục và Đào tạo thường có tên miền dạng nào?","k":"Trang web các Sở Giáo dục và Đào tạo thường có dạng <b>edu.vn</b>, ví dụ <b>phutho.edu.vn</b> (Hình 3.3).","o":[".com",".edu.vn",".net",".org"],"a":1},{"id":"ai","type":"mcq","q":"Em hỏi công cụ hội thoại thông minh (AI) “Hãy cho biết tên các trường THPT gần Vĩnh Tường, Phú Thọ” và nhận được một bảng kết quả (Hình 3.2). Em nên làm gì?","k":"Công cụ AI giúp <b>khoanh vùng phạm vi tìm kiếm</b> nhanh, nhưng câu trả lời có thể chưa chính xác hoặc đã cũ. Em cần <b>đối chiếu, kiểm chứng</b> với nguồn có thẩm quyền trước khi sử dụng.","o":["Dùng ngay vì AI luôn trả lời đúng.","Không dùng vì AI luôn trả lời sai.","Dùng để khoanh vùng tìm kiếm, rồi đối chiếu với website của Sở GD&ĐT và nhà trường.","Chỉ dùng nếu bảng có nhiều trường."],"a":2},{"id":"tc","type":"match","q":"Đọc phần Hướng dẫn a) của Nhiệm vụ 2. Mỗi cách kiểm tra dưới đây giúp em đánh giá tiêu chí nào?","k":"1 – a, 2 – b, 3 – c, 4 – d. Tránh những thông tin <b>chỉ nhằm thu hút sự chú ý</b> mà không liên quan đến mục đích tìm kiếm.","items":[["1) Xem ngày đăng bài hoặc ngày cuối cùng được đề cập trong bài viết",1],["2) Đối chiếu một lời đánh giá tiêu cực về trường với nhiều nguồn khác",2],["3) Xem đã có đủ điểm chuẩn, học phí, khoảng cách,… chưa",3],["4) Đọc tiêu đề và nội dung bài viết để xem có hợp với yêu cầu chọn trường không",4]],"opts":["a) Tính mới","b) Tính chính xác","c) Tính đầy đủ","d) Tính sử dụng được"]},{"id":"dg","type":"open","q":"Đánh giá chất lượng thông tin em đã tìm được ở Nhiệm vụ 1 theo bốn tiêu chí: tính mới, tính chính xác, tính đầy đủ, tính sử dụng được.","k":"Ví dụ:<ul><li><b>Mới:</b> điểm chuẩn năm 2025 trên phutho.edu.vn, đăng tháng 7/2025 → đạt.</li><li><b>Chính xác:</b> đối chiếu với website của trường và báo chính thống → trùng khớp.</li><li><b>Đầy đủ:</b> đã có điểm chuẩn, chỉ tiêu, khoảng cách; còn thiếu học phí → cần tìm thêm.</li><li><b>Sử dụng được:</b> thông tin đúng về trường em định chọn → đạt.</li></ul>","label":"NV2 – Đánh giá thông tin"},{"id":"nv","type":"open","q":"Dựa trên thông tin đã đánh giá, em hãy đưa ra danh sách ba trường theo thứ tự ưu tiên phù hợp với năng lực và sở thích của mình. Nêu tiêu chí em dùng để sắp xếp.","k":"Học sinh tự lựa chọn. Cần:<ul><li>Chọn trường <b>phù hợp năng lực và sở thích</b>, chú ý <b>tính khả thi</b> (điểm chuẩn so với sức học của mình).</li><li>Sắp xếp theo <b>thứ tự ưu tiên</b> giữa các tiêu chí, ví dụ: điểm chuẩn phù hợp → gần nhà → có môn thế mạnh em thích → hoạt động ngoại khoá.</li><li>Nguyện vọng 2, 3 nên là trường có điểm chuẩn thấp hơn để đảm bảo an toàn.</li></ul>","label":"NV2 – Ba nguyện vọng"},{"id":"qt","type":"order","q":"Sắp xếp các bước tìm kiếm và sử dụng thông tin để chọn trường theo thứ tự hợp lí (dùng nút ↑ ↓).","k":"Thứ tự: <b>b → d → a → c</b>. Xác định mục đích, yêu cầu → tìm kiếm và lưu trữ → đánh giá chất lượng → lựa chọn, sắp xếp thứ tự.","items":{"a":"Đánh giá chất lượng thông tin theo bốn tiêu chí.","b":"Xác định mục đích và các yêu cầu tìm kiếm cụ thể.","c":"Lựa chọn các trường phù hợp và sắp xếp thứ tự ưu tiên.","d":"Tìm kiếm thông tin từ nguồn tin cậy và lưu trữ lại."},"ans":["b","d","a","c"],"start":["a","b","c","d"]},{"id":"lt1","type":"open","q":"Em hãy tìm kiếm thông tin trên Internet để biết về các môn học được dạy ở cấp THPT. Ghi lại nguồn thông tin em đã dùng.","k":"Theo Chương trình GDPT 2018 (Thông tư 13/2022/TT-BGDĐT):<ul><li><b>Môn học bắt buộc:</b> Ngữ văn, Toán, Ngoại ngữ 1, Lịch sử, Giáo dục thể chất, Giáo dục quốc phòng và an ninh; cùng hoạt động trải nghiệm, hướng nghiệp và nội dung giáo dục của địa phương.</li><li><b>Môn lựa chọn</b> (chọn 4 môn): Địa lí, Giáo dục kinh tế và pháp luật, Vật lí, Hoá học, Sinh học, Công nghệ, Tin học, Âm nhạc, Mĩ thuật.</li><li>Ngoài ra có các chuyên đề học tập lựa chọn.</li></ul>Nguồn tin cậy: moet.gov.vn (Bộ GD&ĐT), website Sở GD&ĐT, website các trường THPT. Mỗi trường có thể chỉ tổ chức một số tổ hợp môn.","label":"Luyện tập – Môn học THPT"},{"id":"lt2","type":"sort","q":"Ở cấp THPT, mỗi môn dưới đây là môn bắt buộc hay môn lựa chọn?","k":"Bắt buộc: <b>Toán, Ngữ văn, Lịch sử</b> (cùng Ngoại ngữ 1, Giáo dục thể chất, Giáo dục quốc phòng và an ninh). Lựa chọn: <b>Tin học, Vật lí, Địa lí</b> (cùng Hoá học, Sinh học, Công nghệ, GD kinh tế và pháp luật, Âm nhạc, Mĩ thuật).","cats":["Bắt buộc","Lựa chọn"],"items":[["Toán",0],["Ngữ văn",0],["Lịch sử",0],["Tin học",1],["Vật lí",1],["Địa lí",1]]},{"id":"lt3","type":"open","q":"Dựa vào thông tin tìm được, em dự kiến chọn những môn học nào em thích ở cấp THPT? Vì sao?","k":"Học sinh tự trả lời. Ví dụ: chọn <b>Vật lí, Hoá học, Tin học, Công nghệ</b> vì em thích khoa học, kĩ thuật và muốn theo ngành công nghệ thông tin. Cần nêu lí do gắn với <b>sở thích, năng lực và định hướng nghề nghiệp</b>.","label":"Luyện tập – Dự kiến chọn môn"},{"id":"vd1","type":"open","q":"Em hãy lập dàn ý (các trang chiếu) cho bài trình chiếu chủ đề “Chọn môi trường học tập sau khi kết thúc cấp THCS”, kèm các nguồn thông tin em thu thập được.","k":"Gợi ý dàn ý:<ol><li>Trang tiêu đề: chủ đề, tên em, lớp.</li><li>Các lựa chọn sau THCS: THPT công lập, THPT ngoài công lập, giáo dục thường xuyên, trường nghề.</li><li>Tiêu chí lựa chọn: năng lực, sở thích, điểm chuẩn, khoảng cách, chi phí.</li><li>Thông tin về các trường em quan tâm (bảng so sánh).</li><li>Đánh giá chất lượng thông tin theo bốn tiêu chí.</li><li>Ba nguyện vọng của em và lí do.</li><li>Nguồn tham khảo: ghi rõ địa chỉ trang web.</li></ol>","label":"Vận dụng – Bài trình chiếu"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Cần <b>xác định rõ mục đích và yêu cầu cụ thể</b> trước khi tìm kiếm.</li><li>Độ tin cậy của thông tin trên Internet rất khác nhau: với mỗi yêu cầu cụ thể, cần xem xét <b>nguồn tin có thẩm quyền</b> (Sở GD&ĐT, nhà trường,…). Thông tin cần được <b>đối chiếu, kiểm chứng</b> trước khi sử dụng.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Đánh giá thông tin theo bốn tiêu chí: <b>tính mới, tính chính xác, tính đầy đủ, tính sử dụng được</b>.</li><li>Lựa chọn phù hợp năng lực, sở thích, chú ý <b>tính khả thi</b>; sắp xếp theo <b>thứ tự ưu tiên</b> giữa các tiêu chí.</li></ul>"}]},"tin9-giai-quyet-van-de":{"id":"tin9-bai14","ten":"Bài 14. Giải quyết vấn đề","cau":[{"id":"kd1","type":"open","q":"Minh từng vào mê cung trong một khu vui chơi và phải tìm đường thoát khỏi mê cung mà không được dùng sơ đồ. Theo em, có cách nào để tìm được đường thoát khỏi mê cung không?","k":"Ví dụ: luôn để một tay chạm vào bức tường (chẳng hạn tay phải) rồi đi theo bức tường đó cho đến khi gặp lối ra.","label":"Khởi động"},{"id":"hd1a","type":"mcq","q":"Quan sát Hình 14.1. Robot di chuyển trong mê cung theo cách nào?","k":"Robot di chuyển sao cho <b>bức tường luôn ở bên phải</b> nó.","o":["Robot di chuyển sao cho bức tường luôn ở bên phải nó.","Robot đi thẳng, gặp tường thì dừng lại.","Robot chọn hướng đi ngẫu nhiên ở mỗi ngã rẽ.","Robot đi theo sơ đồ mê cung đã được nạp sẵn."],"a":0},{"id":"hd1b","type":"open","q":"Tại sao cách di chuyển đó dẫn robot tới Lối ra?","k":"Vì đi bám theo bức tường bên phải, robot sẽ được bức tường dẫn qua mọi vị trí của mê cung nối với bức tường đó, cho đến khi tìm thấy Lối ra (lối ra nằm trên tường bao của mê cung).","label":"HĐ1 – Câu 2"},{"id":"b14","type":"match","q":"Trong Hoạt động 1, mỗi việc dưới đây thuộc bước nào của quá trình giải quyết vấn đề?","k":"1 – Tìm hiểu vấn đề; 2 – Phân tích vấn đề; 3 – Lựa chọn giải pháp; 4 – Thực hiện giải pháp; 5 – Đánh giá kết quả.","items":[["Xác định: cần tìm Lối ra, robot không có người để hỏi đường, không có sơ đồ.",1],["Chia việc chọn hướng đi thành ba trường hợp: rẽ phải, đi thẳng, rẽ trái.",2],["Chọn quy tắc ưu tiên từ phải sang trái để luôn giữ tường bên phải.",3],["Robot di chuyển theo cách đã chọn như thực hiện một thuật toán.",4],["Cho robot thử với nhiều mê cung có đặc điểm khác nhau để cải tiến.",5]],"opts":["Tìm hiểu vấn đề","Phân tích vấn đề","Lựa chọn giải pháp","Thực hiện giải pháp","Đánh giá kết quả"]},{"id":"tt","type":"match","q":"Ghép mỗi tình huống với cách lựa chọn của robot trong thuật toán bám tường phải.","k":"a) rẽ phải; b) đi thẳng; c) quay sang trái để chọn lại hướng.","items":[["a) Phía phải không có tường",1],["b) Phía phải có tường, phía trước không có tường",2],["c) Cả phía phải và phía trước đều có tường",3]],"opts":["Rẽ phải (quay phải rồi tiến một bước)","Đi thẳng (tiến một bước)","Quay sang trái để chọn lại hướng"]},{"id":"b5","type":"order","q":"Sắp xếp các bước của quá trình giải quyết vấn đề theo đúng thứ tự.","k":"Tìm hiểu vấn đề → Phân tích vấn đề → Lựa chọn giải pháp → Thực hiện giải pháp → Đánh giá kết quả.","items":{"a":"Tìm hiểu vấn đề","b":"Phân tích vấn đề","c":"Lựa chọn giải pháp","d":"Thực hiện giải pháp","e":"Đánh giá kết quả"},"ans":["a","b","c","d","e"],"start":["c","e","a","d","b"]},{"id":"p77","type":"open","q":"Em hãy mô tả các bước giải quyết vấn đề chọn trường để tiếp tục học tập sau khi tốt nghiệp THCS.","k":"1) Tìm hiểu: mục tiêu (học THPT, trung cấp nghề…), điểm số, sở thích, điều kiện gia đình. 2) Phân tích: các yếu tố khoảng cách, học phí, điểm chuẩn, ngành học… 3) Lựa chọn: so sánh, chọn trường phù hợp nhất (và nguyện vọng dự phòng). 4) Thực hiện: ôn thi, nộp hồ sơ. 5) Đánh giá: xem kết quả, điều chỉnh nguyện vọng nếu cần.","label":"Câu hỏi tr.77"},{"id":"hd2","type":"open","q":"Em hãy mô tả thuật toán xác định hướng di chuyển của robot, biết robot chỉ thực hiện được: 1. phát hiện xung quanh (trái, phải, phía trước) có tường hay không; 2. quay trái hoặc quay phải một góc 90°; 3. tiến (đi thẳng) một bước về phía trước.","k":"Lặp lại cho đến khi tìm thấy lối ra: nếu bên phải không có tường thì quay phải 90° và tiến một bước; nếu không thì: nếu phía trước không có tường thì tiến một bước, nếu không thì quay trái 90°.","label":"HĐ2 – Thuật toán bám tường"},{"id":"sd","type":"mcq","q":"Trong sơ đồ khối thuật toán bám tường, khi câu hỏi “Có tường bên phải?” có kết quả là “sai” thì robot làm gì?","k":"Bên phải không có tường → <b>quay phải 90°, tiến một bước</b>, rồi quay lại câu hỏi “Đến đích?”.","o":["Quay phải 90° rồi tiến một bước.","Tiến một bước.","Quay trái 90°.","Kết thúc."],"a":0},{"id":"p78","type":"open","q":"Em hãy mô tả giải pháp chọn trường sau khi tốt nghiệp THCS dưới dạng liệt kê các bước hoặc sơ đồ khối.","k":"Ví dụ: Bước 1: liệt kê các trường có thể học. Bước 2: với mỗi trường, nếu điểm dự kiến ≥ điểm chuẩn và phù hợp sở thích, điều kiện thì đưa vào danh sách chọn. Bước 3: xếp danh sách theo mức ưu tiên. Bước 4: đăng kí nguyện vọng theo thứ tự đó.","label":"Câu hỏi tr.78"},{"id":"lt1","type":"open","q":"Em hãy mô tả thuật toán bám tường bên trái để tìm đường thoát khỏi mê cung (liệt kê các bước hoặc sơ đồ khối).","k":"Lặp lại cho đến khi tìm thấy lối ra: nếu bên trái không có tường thì quay trái 90°, tiến một bước; nếu không thì: nếu phía trước không có tường thì tiến một bước, nếu không thì quay phải 90°.","label":"Luyện tập"},{"id":"lt2","type":"mcq","q":"Chạy thử hai thuật toán trên “Mê cung 3 (robot ở giữa)”. Em rút ra nhận xét gì?","k":"Khi robot xuất phát cạnh một khối tường đứng riêng, bám tường phải có thể đi vòng mãi. Đây là “tình huống đặc biệt” mà bước <b>Đánh giá kết quả</b> giúp phát hiện.","o":["Bám tường phải làm robot đi vòng mãi quanh khối tường giữa; bám tường trái thì thoát được – cần đánh giá với nhiều mê cung để cải tiến thuật toán.","Cả hai thuật toán đều luôn tìm được lối ra với mọi mê cung.","Robot đâm vào tường.","Bám tường trái luôn tốt hơn bám tường phải ở mọi mê cung."],"a":0},{"id":"vd1","type":"open","q":"Em hãy lập chương trình trong ngôn ngữ Scratch mô phỏng thuật toán bám tường. Mô tả các khối lệnh em đã dùng.","k":"Ví dụ: khi bấm vào lá cờ xanh → lặp lại cho đến khi chạm màu đỏ (lối ra): nếu không chạm tường bên phải thì xoay phải 90 độ, di chuyển 1 ô; nếu không: nếu không chạm tường phía trước thì di chuyển 1 ô, nếu không thì xoay trái 90 độ. Trong Scratch, có thể dùng các cảm biến là những khối màu nhỏ gắn quanh nhân vật và khối “màu … chạm màu …?”.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Giải quyết vấn đề là quá trình, thường được thực hiện qua các bước: 1) Tìm hiểu vấn đề; 2) Phân tích vấn đề; 3) Lựa chọn giải pháp; 4) Thực hiện giải pháp; 5) Đánh giá kết quả.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Phương pháp giải quyết vấn đề (hay giải pháp) có thể được mô tả dưới dạng thuật toán bằng phương pháp liệt kê các bước hoặc bằng sơ đồ khối.</li></ul>"}]},"tin9-ham-countif":{"id":"tin9-bai10a","ten":"Bài 10a. Sử dụng hàm COUNTIF","cau":[{"id":"kd1","type":"open","q":"Để việc chi tiêu của gia đình được kiểm soát thường xuyên, dữ liệu thu và chi cần được tổng hợp để trả lời các câu hỏi: Mỗi khoản chi đã được chi bao nhiêu lần? Mỗi khoản thu đã được thu bao nhiêu lần? Tổng số tiền đã chi tiêu của từng khoản chi là bao nhiêu? Tổng số tiền thu nhập của từng khoản thu là bao nhiêu? Thu nhập và chi tiêu của gia đình đã cân đối chưa? Theo em, có thể dùng những hàm nào em đã biết để trả lời các câu hỏi trên? Câu hỏi nào em chưa trả lời được?","k":"Hàm SUM, COUNT tính tổng, đếm cho <b>cả vùng</b>; nhưng để đếm, tính tổng <b>theo từng khoản</b> (theo điều kiện) cần các hàm mới: <b>COUNTIF</b> (bài này), SUMIF, IF (các bài sau).","label":"Khởi động"},{"id":"hd1","type":"open","q":"Giả sử dữ liệu chi tiêu đã được cập nhật trong vùng A3:D10 (Hình 10a.1). Theo em, công thức tại các ô G2, G3,…, G10 là gì để em có thể biết số lần chi tiêu của mỗi khoản?","k":"Cần đếm số ô trong vùng B3:B10 có giá trị bằng tên khoản chi ở cột F: dùng hàm đếm theo điều kiện <b>=COUNTIF($B$3:$B$10,F2)</b> tại G2 rồi sao chép xuống G10.","label":"HĐ1 – Các khoản chi được tổng hợp như thế nào?"},{"id":"vd","type":"match","q":"Ghép mỗi yêu cầu tính toán với công thức tương ứng (thử trên bảng tính mô phỏng).","k":"1 – a; 2 – b; 3 – c (dấu * thay cho dãy kí tự bất kì); 4 – d (điều kiện là giá trị của ô D2).","items":[["Đếm số ô trong vùng A1:A4 chứa giá trị số lớn hơn 100",1],["Đếm số ô trong vùng A1:A4 chứa từ Yes",2],["Đếm số ô trong vùng A1:A4 chứa xâu kí tự bắt đầu bằng chữ cái Y",3],["Đếm số ô trong vùng A1:A4 chứa giá trị giống như ô D2",4]],"opts":["a) =COUNTIF(A1:A4,\">100\")","b) =COUNTIF(A1:A4,\"Yes\")","c) =COUNTIF(A1:A4,\"Y*\")","d) =COUNTIF(A1:A4,D2)"]},{"id":"thamso","type":"match","q":"Trong công thức =COUNTIF(range, criteria), ghép mỗi tham số với ý nghĩa của nó.","k":"<b>range</b>: phạm vi chứa các ô tính cần kiểm tra để đếm; <b>criteria</b>: điều kiện kiểm tra các ô tính trong phạm vi range.","items":[["range",1],["criteria",2]],"opts":["a) Phạm vi chứa các ô tính cần kiểm tra để đếm","b) Điều kiện kiểm tra các ô tính trong phạm vi range"]},{"id":"g2","type":"mcq","q":"Vì sao công thức =COUNTIF($B$3:$B$10,\"Ở\") ở ô G2 được sửa lại thành =COUNTIF($B$3:$B$10,F2)?","k":"Dùng địa chỉ ô <b>F2</b> (địa chỉ tương đối) làm điều kiện để <b>sao chép</b> được công thức cho các khoản chi khác; vùng <b>$B$3:$B$10</b> (địa chỉ tuyệt đối) giữ nguyên.","o":["Vì tên khoản chi Ở đã được lưu ở ô F2; khi sao chép công thức xuống G3 đến G10, F2 tự đổi thành F3,…, F10 nên tính được số lần chi của các khoản còn lại.","Vì hàm COUNTIF không nhận điều kiện là chữ.","Vì công thức cũ cho kết quả sai.","Vì để công thức ngắn hơn."],"a":0},{"id":"p43a","type":"mcq","q":"Trong Hình 10a.2, công thức ở ô G2 là =COUNTIF($B$3:$B$10,F2). Khi sao chép công thức sang các ô G3,…, G10, công thức sẽ thay đổi như thế nào?","k":"Địa chỉ tuyệt đối <b>$B$3:$B$10</b> giữ nguyên; địa chỉ tương đối <b>F2</b> đổi thành F3, F4,…, F10.","o":["Vùng $B$3:$B$10 giữ nguyên, chỉ F2 đổi thành F3,…, F10. Ví dụ G3: =COUNTIF($B$3:$B$10,F3).","Cả hai tham số đều thay đổi.","Công thức không thay đổi.","Vùng thay đổi thành $B$4:$B$11."],"a":0},{"id":"p43b","type":"mcq","q":"Nếu bỏ các dấu $ thì công thức ở ô G2 sẽ là =COUNTIF(B3:B10,F2). Sau khi sao chép công thức này sang các ô từ G3 đến G10, kết quả trả về tại các ô đó có đúng không? Tại sao?","k":"Không đúng. Khi sao chép, <b>B3:B10</b> là địa chỉ tương đối nên đổi thành B4:B11, B5:B12,… → đếm thiếu các hàng phía trên. Cần giữ cố định vùng bằng dấu <b>$</b>.","o":["Không đúng: vùng đếm bị dịch xuống (G3: B4:B11, G4: B5:B12,…) nên bỏ sót dữ liệu ở các hàng đầu.","Đúng, vì vùng không thay đổi.","Đúng, vì COUNTIF tự sửa vùng.","Không đúng vì COUNTIF không sao chép được."],"a":0},{"id":"nv1","type":"mcq","q":"Với dữ liệu trang tính Thu nhập (Hình 10a.3), công thức tại G2 và kết quả của khoản Làm thêm (ô G4) là:","k":"G2: <b>=COUNTIF($B$3:$B$8,F2)</b>, sao chép xuống G6. Làm thêm có 2 lần thu (15/8 và 30/8).","o":["=COUNTIF($B$3:$B$8,F2); Làm thêm: 2","=COUNTIF(B3:B8,F2); Làm thêm: 1","=COUNT($B$3:$B$8); Làm thêm: 6","=COUNTIF($B$3:$B$8,\"Lương\"); Làm thêm: 2"],"a":0},{"id":"nv2","type":"open","q":"Báo cáo kết quả: số lần chi của từng khoản chi và số lần thu của từng khoản thu trong bảng tính TaiChinhGiaDinh.xlsx của em. Khoản nào được chi nhiều lần nhất?","k":"Ví dụ với dữ liệu Hình 10a.1: Ở 2 lần; Ăn, Di chuyển, Học tập, Sức khoẻ, Quà tặng/Từ thiện, Tiết kiệm 1 lần; Giải trí, Khác 0 lần.","label":"Thực hành – Kết quả"},{"id":"lt1","type":"open","q":"Bổ sung thêm một số dòng dữ liệu thu, chi vào cả hai trang tính Thu nhập và Chi tiêu. Em đã điều chỉnh công thức COUNTIF ở cột G như thế nào để kết quả tổng hợp số lần thu, chi của mỗi khoản được chính xác?","k":"Mở rộng vùng đếm cho đủ các dòng mới, ví dụ $B$3:$B$10 → <b>$B$3:$B$20</b> (ở G2), rồi sao chép lại xuống các ô còn lại của cột G.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"mcq","q":"Với dữ liệu khảo sát ở Hình 10a.6, công thức tại E5 và kết quả thống kê A, B, C, D lần lượt là:","k":"E5: <b>=COUNTIF($B$4:$B$13,D5)</b>, sao chép xuống E8. Kết quả: A 3, B 2, C 3, D 2 (tổng 10 học sinh).","o":["=COUNTIF($B$4:$B$13,D5); A: 3, B: 2, C: 3, D: 2","=COUNTIF(B4:B13,D5); A: 3, B: 3, C: 2, D: 2","=COUNT($B$4:$B$13); 10, 10, 10, 10","=COUNTIF($B$4:$B$13,\"A\"); 3, 3, 3, 3"],"a":0},{"id":"vd1","type":"open","q":"Mở bảng tính KinhPhiTrienLam.xlsx (Vận dụng Bài 9a), sử dụng hàm COUNTIF để tính số lần thu của mỗi khoản thu, số lần chi của mỗi khoản chi của dự án Triển lãm tin học. Ghi lại các công thức em đã dùng.","k":"Ví dụ trang tính Các khoản thu: G2 =COUNTIF($B$3:$B$20,F2), sao chép sang G3; trang tính Các khoản chi tương tự.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Hàm <b>COUNTIF</b> đếm số ô tính trong vùng dữ liệu (range) thoả mãn điều kiện (criteria).</li><li>Công thức: <b>=COUNTIF(range, criteria)</b> – range: phạm vi chứa các ô tính cần kiểm tra để đếm; criteria: điều kiện kiểm tra các ô tính trong phạm vi range.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Vùng đếm dùng <b>địa chỉ tuyệt đối</b> ($B$3:$B$10), điều kiện dùng <b>địa chỉ ô tương đối</b> (F2) để sao chép công thức cho các khoản khác.</li></ul>"}]},"tin9-ham-if":{"id":"tin9-bai12a","ten":"Bài 12a. Sử dụng hàm IF","cau":[{"id":"kd1","type":"open","q":"Quy tắc 50-30-20 khuyên chúng ta nên dành 50% số tiền của mình cho nhu cầu thiết yếu (ăn, ở, sức khoẻ,…), 30% cho mong muốn cá nhân (giải trí, thời trang,…) và 20% cho tiết kiệm. Theo em, chi tiêu của gia đình đã cân đối, hợp lí hay chưa được nhận xét dựa vào đâu?","k":"So sánh <b>tỉ lệ</b> tiền chi cho mỗi mục (thiết yếu, mong muốn cá nhân, tiết kiệm) với tổng chi, đối chiếu với quy tắc 50% – 30% – 20%; tuỳ tình hình thực tế mà điều chỉnh.","label":"Khởi động"},{"id":"muc","type":"sort","q":"Xếp mỗi khoản chi vào mục chi phù hợp theo quy tắc 50-30-20 (Hình 12a.2).","k":"A: ở, ăn, di chuyển, học tập, sức khoẻ. B: giải trí, quà tặng/từ thiện, khác. C: tiết kiệm.","cats":["A – Nhu cầu thiết yếu (50%)","B – Mong muốn cá nhân (30%)","C – Tiết kiệm (20%)"],"items":[["Ở",0],["Ăn",0],["Di chuyển",0],["Học tập",0],["Sức khoẻ",0],["Giải trí",1],["Quà tặng/Từ thiện",1],["Khác",1],["Tiết kiệm",2]]},{"id":"hd1a","type":"mcq","q":"Công thức ở ô M3 (tổng tiền mục A) và ô N3 (tỉ lệ mục A) trong Hình 12a.3 là:","k":"Tổng tiền mỗi mục: <b>SUMIF</b> kiểm tra cột Mục chi I, cộng cột Tổng tiền H. Tỉ lệ: tổng tiền mục chia tổng tất cả các khoản ở <b>$H$11</b>.","o":["M3: =SUMIF($I$2:$I$10,K3,$H$2:$H$10); N3: =M3/$H$11*100%","M3: =SUM(H2:H10); N3: =M3/H11","M3: =COUNTIF($I$2:$I$10,K3); N3: =M3*100","M3: =SUMIF(I2:I10,\"A\"); N3: =H11/M3"],"a":0},{"id":"hd1b","type":"open","q":"Viết quy tắc để đưa ra nhận xét tình trạng chi tiêu như minh hoạ ở cột O trong Hình 12a.3 dựa trên quy tắc quản lí tài chính 50-30-20.","k":"Nhu cầu thiết yếu: nếu tỉ lệ chi lớn hơn 50% thì “Nhiều hơn”, còn không thì “Ít hơn”. Tương tự với Mong muốn cá nhân (30%) và Tiết kiệm (20%).","label":"HĐ1 – Câu 2"},{"id":"ts","type":"match","q":"Trong công thức =IF(logical_test,[value_if_true],[value_if_false]), ghép mỗi tham số với ý nghĩa.","k":"logical_test – a; value_if_true – b; value_if_false – c.","items":[["logical_test",1],["value_if_true",2],["value_if_false",3]],"opts":["a) Điều kiện kiểm tra","b) Giá trị trả về nếu điều kiện là đúng","c) Giá trị trả về nếu điều kiện là sai"]},{"id":"o3","type":"mcq","q":"Ô N3 có giá trị 90.5%. Công thức =IF(N3>50%,\"Nhiều hơn\",\"Ít hơn\") ở ô O3 cho kết quả:","k":"90.5% &gt; 50% đúng → trả về value_if_true: <b>“Nhiều hơn”</b>.","o":["Nhiều hơn","Ít hơn","TRUE","90.5%"],"a":0},{"id":"long","type":"mcq","q":"Với công thức =IF(N3>80%,\"Nhiều quá\",IF(N3>50%,\"Nhiều hơn\",\"Ít hơn\")), nếu N3 = 60% thì kết quả là:","k":"60% &gt; 80% sai → xét IF thứ hai: 60% &gt; 50% đúng → <b>“Nhiều hơn”</b>. Nếu N3 = 90.5% thì “Nhiều quá”; N3 = 40% thì “Ít hơn”.","o":["Nhiều hơn","Nhiều quá","Ít hơn","Báo lỗi"],"a":0},{"id":"p49","type":"mcq","q":"Công thức trong các ô O4 và O5 ở Hình 12a.3 để nhận xét về tình trạng của mục Mong muốn cá nhân và Tiết kiệm dựa trên quy tắc 50-30-20 là:","k":"Mong muốn cá nhân so với <b>30%</b>, Tiết kiệm so với <b>20%</b>: O4 =IF(N4&gt;30%,…), O5 =IF(N5&gt;20%,…). Với dữ liệu mẫu đều “Ít hơn”.","o":["O4: =IF(N4>30%,\"Nhiều hơn\",\"Ít hơn\"); O5: =IF(N5>20%,\"Nhiều hơn\",\"Ít hơn\")","O4: =IF(N4>50%,\"Nhiều hơn\",\"Ít hơn\"); O5: =IF(N5>50%,\"Nhiều hơn\",\"Ít hơn\")","O4: =IF(N4<30%,\"Nhiều hơn\",\"Ít hơn\"); O5: =IF(N5<20%,\"Nhiều hơn\",\"Ít hơn\")","O4: =SUMIF(N4,30%); O5: =SUMIF(N5,20%)"],"a":0},{"id":"nv1","type":"open","q":"Báo cáo kết quả bảng Tổng hợp mục chi: tổng chi, tỉ lệ và trạng thái của mỗi mục. Gia đình chi tiêu đã cân đối theo quy tắc 50-30-20 chưa?","k":"Dữ liệu mẫu: A 12 340 (90.5%) – Nhiều hơn; B 300 (2.2%) – Ít hơn; C 1 000 (7.3%) – Ít hơn. Chưa cân đối: chi thiết yếu quá nhiều, tiết kiệm ít.","label":"Thực hành – Kết quả"},{"id":"lta","type":"mcq","q":"Hình 12a.7: nếu doanh thu đạt trên 10 triệu thì tỉ lệ thưởng là 5%, còn không thì 0%. Công thức ở ô C2 và các đại lí được thưởng là:","k":"Doanh thu tính theo nghìn đồng nên 10 triệu = 10 000: <b>=IF(B2&gt;10000,5%,0%)</b>; B đúng 10 000 không “trên 10 triệu” → chỉ C, D được 5%. Tiền thưởng D2 = <b>B2*C2</b>: C 600, D 900.","o":["=IF(B2>10000,5%,0%); đại lí C và D","=IF(B2>=10000,5%,0%); đại lí B, C, D","=IF(B2>10,5%,0%); cả bốn đại lí","=IF(B2<10000,5%,0%); đại lí A"],"a":0},{"id":"ltc","type":"mcq","q":"Cách tính mới: trên 20 triệu thưởng 6%; trên 15 triệu thưởng 4%; trên 10 triệu thưởng 2%; còn lại 0%. Công thức ở ô C2 là:","k":"Hàm IF lồng nhau, kiểm tra <b>từ mức cao xuống mức thấp</b>. Kết quả: A 0%, B 0%, C 2%, D 4%. (Nếu kiểm tra &gt;10000 trước thì D chỉ được 2% – sai.)","o":["=IF(B2>20000,6%,IF(B2>15000,4%,IF(B2>10000,2%,0%)))","=IF(B2>10000,2%,IF(B2>15000,4%,IF(B2>20000,6%,0%)))","=IF(B2>20000,6%,4%,2%,0%)","=IF(B2>20000,6%)+IF(B2>15000,4%)"],"a":0},{"id":"vd1","type":"mcq","q":"Công thức tại ô O3 nhận xét theo ba mức: tỉ lệ chi lớn hơn 80% thì “Nhiều quá”, lớn hơn 50% thì “Nhiều hơn”, còn không thì “Ít hơn” là:","k":"Kiểm tra mức 80% trước: <b>=IF(N3&gt;80%,\"Nhiều quá\",IF(N3&gt;50%,\"Nhiều hơn\",\"Ít hơn\"))</b> (Hình 12a.4).","o":["=IF(N3>80%,\"Nhiều quá\",IF(N3>50%,\"Nhiều hơn\",\"Ít hơn\"))","=IF(N3>50%,\"Nhiều hơn\",IF(N3>80%,\"Nhiều quá\",\"Ít hơn\"))","=IF(N3>80%,\"Nhiều quá\",\"Nhiều hơn\",\"Ít hơn\")","=IF(N3>50%,\"Nhiều quá\")"],"a":0},{"id":"vd2","type":"open","q":"Sử dụng hàm IF lồng nhau tại ô O4 và O5 để nhận xét chi tiết hơn tình trạng chi của mục Mong muốn cá nhân và Tiết kiệm. Dựa trên quy tắc 50-30-20, em hãy điều chỉnh sao cho các mục chi được cân đối và tài chính gia đình được kiểm soát hiệu quả. Mô tả công thức và cách em điều chỉnh.","k":"Ví dụ O4: =IF(N4&gt;40%,\"Nhiều quá\",IF(N4&gt;30%,\"Nhiều hơn\",\"Ít hơn\")); O5: =IF(N5&gt;20%,\"Tốt\",IF(N5&gt;10%,\"Cần tăng\",\"Quá ít\")). Điều chỉnh: giảm chi thiết yếu chưa cần thiết, tăng tiết kiệm.","label":"Vận dụng – câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Hàm <b>IF</b> kiểm tra điều kiện và trả về một giá trị khi điều kiện đó đúng và một giá trị khác nếu điều kiện đó sai.</li><li>Công thức: <b>=IF(logical_test,[value_if_true],[value_if_false])</b> – logical_test: điều kiện kiểm tra; value_if_true: giá trị trả về nếu điều kiện là đúng; value_if_false: giá trị trả về nếu điều kiện là sai.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Khi cần kiểm tra nhiều mức, dùng các hàm <b>IF lồng nhau</b>: IF thứ hai đặt ở vị trí value_if_false của IF thứ nhất; kiểm tra từ mức cao xuống mức thấp.</li></ul>"}]},"tin9-ham-sumif":{"id":"tin9-bai11a","ten":"Bài 11a. Sử dụng hàm SUMIF","cau":[{"id":"kd1","type":"open","q":"Trong bài học trước, em đã sử dụng hàm đếm theo điều kiện để biết được số lần thu, chi theo từng khoản mục. Theo em, để biết tổng số tiền đã chi cho từng khoản mục (ví dụ tổng tiền khoản Ở), em cần làm gì?","k":"Cần cộng các số tiền ở những dòng có khoản chi tương ứng – tính <b>tổng theo điều kiện</b>: dùng hàm <b>SUMIF</b>.","label":"Khởi động"},{"id":"hd1a","type":"mcq","q":"Hình 11a.1 là trang tính Chi tiêu đã được bổ sung thêm cột Tổng tiền. Con số 920 ở ô H2 mang ý nghĩa gì?","k":"920 là <b>tổng số tiền đã chi cho khoản Ở</b>: tiền điện tháng 8 (800) + tiền nước tháng 8 (120).","o":["Tổng số tiền đã chi cho khoản Ở (800 + 120).","Số lần chi của khoản Ở.","Tổng tất cả các khoản chi.","Số tiền chi lớn nhất."],"a":0},{"id":"hd1b","type":"mcq","q":"Công thức ở ô H2 liên quan đến những dữ liệu nào trong vùng dữ liệu A3:D10?","k":"Kiểm tra khoản chi ở <b>B3:B10</b>, cộng các số tiền tương ứng ở <b>D3:D10</b> (hàng 3 và hàng 8).","o":["Cột Khoản chi B3:B10 (để kiểm tra khoản Ở) và cột Số tiền D3:D10 (để cộng các số tiền tương ứng).","Chỉ cột Ngày A3:A10.","Chỉ cột Nội dung C3:C10.","Toàn bộ vùng A3:D10 đều được cộng."],"a":0},{"id":"b111","type":"match","q":"Ghép mỗi công thức với ý nghĩa của nó (thử trên bảng tính mô phỏng).","k":"Dạng 1 (không có sum_range): cộng chính các ô của range thoả mãn điều kiện. Dạng 2: kiểm tra range A2:A5, cộng các ô tương ứng ở sum_range B2:B5.","items":[["=SUMIF(A1:A5,\">5\")",1],["=SUMIF(A2:A5,\"Khoa\",B2:B5)",2]],"opts":["a) Tính tổng các giá trị lớn hơn 5 trong vùng A1:A5","b) Tính tổng các giá trị trong vùng B2:B5 với các ô tương ứng trong vùng A2:A5 có giá trị là “Khoa” (tổng tiền Khoa đã chi)"]},{"id":"thamso","type":"match","q":"Trong công thức =SUMIF(range, criteria, [sum_range]), ghép mỗi tham số với ý nghĩa.","k":"range – a; criteria – b; sum_range – c.","items":[["range",1],["criteria",2],["sum_range (tuỳ chọn)",3]],"opts":["a) Phạm vi chứa các giá trị cần kiểm tra hoặc tính tổng các giá trị nếu không có tham số sum_range","b) Điều kiện kiểm tra","c) Phạm vi chứa các giá trị cần tính tổng; nếu bị bỏ qua thì tính tổng các ô trong range thoả mãn điều kiện"]},{"id":"chon","type":"sort","q":"Mỗi câu hỏi dưới đây về trang tính Chi tiêu nên dùng hàm nào?","k":"Tổng cả vùng: <b>SUM</b>. Đếm theo điều kiện: <b>COUNTIF</b>. Tính tổng theo điều kiện: <b>SUMIF</b> (ví dụ =SUMIF(D3:D10,\">1000\")).","cats":["SUM","COUNTIF","SUMIF"],"items":[["Tổng số tiền của tất cả các khoản chi",0],["Khoản Ở đã được chi bao nhiêu lần?",1],["Tổng số tiền đã chi cho khoản Ở",2],["Có bao nhiêu lần chi trên 1 000 nghìn đồng?",1],["Tổng các lần chi lớn hơn 1 000 nghìn đồng",2]]},{"id":"h2","type":"mcq","q":"Công thức tại ô H2 (Hình 11a.2) để có thể sao chép đúng sang H3 đến H10 là:","k":"Tên khoản chi Ở đã lưu ở ô <b>F2</b> nên điều kiện là F2 (thay đổi khi sao chép); hai vùng phải là <b>địa chỉ tuyệt đối</b>: =SUMIF($B$3:$B$10,F2,$D$3:$D$10).","o":["=SUMIF($B$3:$B$10,F2,$D$3:$D$10)","=SUMIF(B3:B10,\"Ở\",D3:D10)","=SUMIF(B3:B10,F2,D3:D10)","=SUM($D$3:$D$10)"],"a":0},{"id":"p47","type":"mcq","q":"Hình 11a.3 minh hoạ dữ liệu của trang tính Thu nhập. Công thức cần nhập vào ô H2 là gì, giá trị của ô H2 có ý nghĩa gì?","k":"<b>=SUMIF($B$3:$B$8,F2,$D$3:$D$8)</b>; H2 = 10 000 (nghìn đồng) là <b>tổng tiền thu của khoản Lương</b>. (Thiếu sum_range thì SUMIF cộng chính các ô chữ ở cột B nên kết quả là 0.)","o":["=SUMIF($B$3:$B$8,F2,$D$3:$D$8); H2 = 10 000 là tổng tiền của khoản thu Lương.","=COUNTIF($B$3:$B$8,F2); H2 = 1 là số lần thu Lương.","=SUM($D$3:$D$8); H2 là tổng thu nhập.","=SUMIF($B$3:$B$8,F2); H2 là tổng tiền khoản Lương."],"a":0},{"id":"nv1","type":"mcq","q":"Sau khi sao chép công thức ở trang tính Thu nhập, tổng tiền của khoản Làm thêm (ô H4) là:","k":"Làm thêm có hai lần thu: 1 500 + 2 000 = <b>3 500</b> (nghìn đồng).","o":["3 500","1 500","2 000","2"],"a":0},{"id":"nv2","type":"open","q":"Ghi lại tổng tiền của từng khoản chi trong trang tính Chi tiêu. Khoản nào chi nhiều tiền nhất? Theo em, gia đình nên điều chỉnh chi tiêu thế nào?","k":"Với dữ liệu Hình 11a.1: Ăn 8 000, Học tập 2 200, Tiết kiệm 1 000, Ở 920, Sức khoẻ 620, Di chuyển 600, Quà tặng/Từ thiện 300. Khoản Ăn chi nhiều nhất; tránh chi quá nhiều cho những nhu cầu không thiết yếu.","label":"Thực hành – Báo cáo"},{"id":"lt1","type":"open","q":"Bổ sung thêm một số dòng dữ liệu thu, chi vào cuối phần dữ liệu của cả hai trang tính Thu nhập và Chi tiêu. Em đã điều chỉnh công thức SUMIF ở cột H như thế nào để kết quả tổng tiền của mỗi khoản được chính xác?","k":"Mở rộng cả hai vùng range và sum_range cho đủ các dòng mới, ví dụ <b>=SUMIF($B$3:$B$20,F2,$D$3:$D$20)</b>, rồi sao chép lại cho cột H (và sửa COUNTIF ở cột G tương tự).","label":"Luyện tập"},{"id":"vd1","type":"open","q":"Mở bảng tính KinhPhiTrienLam.xlsx (Vận dụng Bài 10a) và sử dụng hàm SUMIF để tính tổng các khoản thu, chi của dự án Triển lãm tin học. Ghi lại các công thức em đã dùng.","k":"Ví dụ trang tính Các khoản chi: H2 =SUMIF($B$3:$B$20,F2,$D$3:$D$20), sao chép sang H3; trang tính Các khoản thu tương tự.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Hàm <b>SUMIF</b> tính tổng giá trị của những ô thoả mãn một điều kiện nào đó.</li><li>Công thức: <b>=SUMIF(range, criteria, [sum_range])</b> – range: phạm vi chứa các giá trị cần kiểm tra hoặc tính tổng các giá trị nếu không có tham số sum_range; criteria: điều kiện kiểm tra; sum_range (tuỳ chọn): phạm vi chứa các giá trị cần tính tổng, nếu sum_range bị bỏ qua thì tính tổng các ô trong tham số range thoả mãn điều kiện.</li></ul>"}]},"tin9-khai-thac-phan-mem-mo-phong":{"id":"tin9-bai6","ten":"Bài 6. Thực hành: Khai thác phần mềm mô phỏng","cau":[{"id":"kd1","type":"open","q":"Em đã từng dùng phần mềm mô phỏng (thí nghiệm ảo) nào trong học tập? Phần mềm đó giúp em khám phá được điều gì?","k":"Ví dụ: <b>PhET</b> mô phỏng mạch điện, chuyển hoá năng lượng; <b>GeoGebra</b> vẽ và đo hình; phần mềm mô phỏng hệ Mặt Trời,… Phần mềm mô phỏng trình bày hiện tượng bằng hình ảnh động, cho em <b>tương tác, khám phá</b>, bổ sung kiến thức về khoa học, toán học và học cách giải quyết vấn đề.","label":"Mở đầu"},{"id":"nl1","type":"open","q":"Mở mô phỏng “Năng lượng: các dạng và sự chuyển hoá” trên PhET. Em quan sát được những dạng năng lượng nào?","k":"Các dạng năng lượng (biểu tượng trong phần mềm): <b>cơ năng</b>, <b>điện năng</b>, <b>nhiệt năng</b>, <b>quang năng</b> (năng lượng ánh sáng), <b>hoá năng</b>.","label":"NV1 – Dạng năng lượng"},{"id":"nl2","type":"match","q":"Tương tác với phần mềm (đổi nguồn năng lượng, thiết bị chuyển hoá, thiết bị tiêu thụ). Ghép mỗi tình huống với sự chuyển hoá năng lượng chính.","k":"1 – a, 2 – b, 3 – c, 4 – d, 5 – e, 6 – f. Năng lượng không tự mất đi mà <b>chuyển hoá</b> từ dạng này sang dạng khác.","items":[["1) Người đạp xe làm quay bánh xe",1],["2) Ánh sáng mặt trời chiếu vào pin mặt trời",2],["3) Vòi nước chảy làm quay máy phát điện",3],["4) Bóng đèn sợi đốt sáng",4],["5) Bếp điện đun nóng nước",5],["6) Quạt điện quay",6]],"opts":["a) Hoá năng → cơ năng","b) Quang năng → điện năng","c) Cơ năng → điện năng","d) Điện năng → quang năng và nhiệt năng","e) Điện năng → nhiệt năng","f) Điện năng → cơ năng"]},{"id":"nl3","type":"open","q":"Nêu một tình huống năng lượng được chuyển hoá từ dạng này sang dạng khác mà em đã tạo ra trong phần mềm.","k":"Ví dụ: người đạp xe (<b>hoá năng → cơ năng</b>) làm quay máy phát điện (<b>cơ năng → điện năng</b>), điện chạy tới bóng đèn sợi đốt (<b>điện năng → quang năng + nhiệt năng</b>).","label":"NV1 – Một tình huống"},{"id":"am1","type":"mcq","q":"Em cần dùng thiết bị nào để đo cường độ dòng điện trên mạch điện?","k":"Dùng <b>ampe kế</b> để đo cường độ dòng điện (đơn vị ampe, A). Vôn kế dùng để đo điện áp (hiệu điện thế).","o":["Vôn kế.","Ampe kế.","Công tắc.","Điện trở."],"a":1},{"id":"am2","type":"mcq","q":"Ampe kế được nối song song hay nối tiếp với đoạn mạch điện cần đo?","k":"Ampe kế mắc <b>nối tiếp</b> với đoạn mạch cần đo, để dòng điện chạy qua đoạn mạch cũng chạy qua ampe kế (Hình 6.5a).","o":["Nối song song.","Nối tiếp.","Nối thế nào cũng được.","Nối trực tiếp vào hai cực của nguồn điện."],"a":1},{"id":"am3","type":"mcq","q":"Ở Hình 6.5b, ampe kế được mắc trực tiếp vào hai cực của nguồn điện. Điều gì xảy ra?","k":"Ampe kế có điện trở rất nhỏ. Mắc trực tiếp vào hai cực nguồn là <b>đoản mạch</b>: dòng điện rất lớn (ampe kế chỉ hàng chục nghìn ampe), gây <b>cháy</b>. Trong phần mềm mô phỏng, em thấy được sự cố này mà <b>không nguy hiểm</b>.","o":["Đèn sáng hơn.","Không có gì xảy ra.","Dòng điện rất lớn (đoản mạch), gây cháy, hỏng thiết bị.","Ampe kế chỉ số 0."],"a":2},{"id":"am4","type":"open","q":"Trình bày giải pháp đo cường độ dòng điện đi qua một bóng đèn bằng phần mềm thí nghiệm ảo lắp ráp mạch điện một chiều.","k":"<ol><li>Mở PhET → Các mô phỏng → Vật lý → <b>Bộ lắp ráp mạch điện: DC – Phòng thí nghiệm ảo</b>.</li><li>Kéo pin, đèn tròn, ampe kế, công tắc, dây nối vào vùng hiển thị.</li><li>Nối pin, công tắc, bóng đèn và <b>ampe kế thành một mạch nối tiếp</b>; không nối ampe kế trực tiếp vào hai cực pin.</li><li>Đóng công tắc, đọc số chỉ trên ampe kế (ví dụ 0,90 A).</li></ol>","label":"NV2 – Trình bày giải pháp"},{"id":"tv1","type":"open","q":"Đo độ dài các đoạn thẳng AB, BC, AC, AD trên ngôi sao năm cánh (dùng Geometer's Sketchpad, GeoGebra hoặc ngôi sao mô phỏng ở trên). Ghi lại kết quả.","k":"Ví dụ (Hình 6.6): AB = 2,52 cm; BC = 1,56 cm; AC = 4,07 cm; AD = 6,59 cm. Kết quả của em có thể khác tuỳ kích thước ngôi sao.","label":"NV3 – Đo độ dài"},{"id":"tv2","type":"mcq","q":"Với số đo ở Hình 6.6, các tỉ lệ AB/BC, AC/AB, AD/AC xấp xỉ bằng bao nhiêu?","k":"AB/BC = 2,52 : 1,56 ≈ 1,62; AC/AB = 4,07 : 2,52 ≈ 1,62; AD/AC = 6,59 : 4,07 ≈ 1,62. Các tỉ lệ này <b>bằng nhau</b> và xấp xỉ <b>1,62</b>.","o":["1,41","1,62","2","3,14"],"a":1},{"id":"tv3","type":"mcq","q":"Khi thay đổi kích thước ngôi sao (kéo điểm P hoặc Q), điều gì xảy ra với các tỉ lệ AB/BC, AC/AB, AD/AC?","k":"Độ dài các đoạn thẳng thay đổi nhưng các tỉ lệ <b>không thay đổi</b>, luôn bằng nhau: (1 + √5)/2 ≈ <b>1,618034</b>. Tỉ lệ này gọi là <b>tỉ lệ vàng</b>.","o":["Các tỉ lệ tăng lên khi ngôi sao to ra.","Các tỉ lệ giảm đi khi ngôi sao to ra.","Độ dài thay đổi nhưng các tỉ lệ không đổi, luôn bằng (1 + √5)/2 ≈ 1,618034.","Các tỉ lệ thay đổi ngẫu nhiên."],"a":2},{"id":"tv4","type":"open","q":"Thế nào là hình chữ nhật tỉ lệ vàng? Kể một ví dụ em biết về tỉ lệ vàng trong thực tế.","k":"Hình chữ nhật có tỉ lệ hai cạnh là tỉ lệ vàng: cắt bỏ một hình vuông thì phần còn lại vẫn là hình chữ nhật có tỉ lệ hai cạnh là tỉ lệ vàng (Hình 6.8b). Ví dụ trong thực tế: kiến trúc (đền Parthenon), hội hoạ, thiết kế logo, cách sắp xếp hạt hoa hướng dương, vỏ ốc anh vũ,…","label":"NV3 – Hình chữ nhật vàng"},{"id":"lt1","type":"mcq","q":"Để đo điện áp giữa hai đầu một điện trở, em dùng vôn kế và mắc như thế nào?","k":"Vôn kế mắc <b>song song</b> với đoạn mạch cần đo: hai đầu vôn kế nối vào hai đầu điện trở.","o":["Mắc vôn kế nối tiếp với điện trở.","Mắc vôn kế song song với điện trở (hai đầu vôn kế nối vào hai đầu điện trở).","Mắc vôn kế vào hai cực của ampe kế.","Không cần mắc, chỉ cần đặt cạnh điện trở."],"a":1},{"id":"lt2","type":"open","q":"Em hãy nêu giải pháp đo điện áp giữa hai đầu một điện trở bằng cách sử dụng phần mềm mô phỏng.","k":"<ol><li>Mở PhET → Vật lý → Bộ lắp ráp mạch điện: DC – Phòng thí nghiệm ảo.</li><li>Lắp mạch: pin, công tắc, điện trở, dây nối.</li><li>Kéo <b>vôn kế</b> vào, đặt <b>hai đầu đo của vôn kế vào hai đầu điện trở</b> (mắc song song).</li><li>Đóng công tắc, đọc số chỉ của vôn kế (đơn vị vôn, V).</li></ol>","label":"Luyện tập – Giải pháp"},{"id":"vd1","type":"sort","q":"Lắp mạch gồm nguồn điện, công tắc, điện trở, ampe kế, vôn kế. Thay đổi trị số các linh kiện và quan sát: cường độ dòng điện I tăng hay giảm?","k":"Cường độ dòng điện <b>tăng khi điện áp tăng</b>, <b>giảm khi điện trở tăng</b>.","cats":["I tăng","I giảm"],"items":[["Giữ nguyên điện trở, tăng điện áp nguồn",0],["Giữ nguyên điện áp, tăng điện trở",1],["Giữ nguyên điện trở, giảm điện áp nguồn",1],["Giữ nguyên điện áp, giảm điện trở",0]]},{"id":"vd2","type":"open","q":"Từ các thử nghiệm, em hãy phát biểu quy luật phụ thuộc lẫn nhau giữa điện trở, cường độ dòng điện qua nó và điện áp giữa hai đầu điện trở đó.","k":"Cường độ dòng điện chạy qua điện trở <b>tỉ lệ thuận</b> với điện áp giữa hai đầu điện trở và <b>tỉ lệ nghịch</b> với điện trở: <b>I = U / R</b> (định luật Ohm). Ví dụ: U = 9 V, R = 10 Ω thì I = 0,9 A.","label":"Vận dụng – Quy luật"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Phần mềm mô phỏng cho em <b>quan sát</b> sự chuyển hoá giữa các dạng năng lượng và <b>tương tác</b>: thay đổi nguồn năng lượng, thiết bị chuyển hoá, thiết bị tiêu thụ.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Ampe kế đo cường độ dòng điện, mắc <b>nối tiếp</b> với đoạn mạch cần đo, không mắc trực tiếp vào hai cực của nguồn điện.</li><li>Thí nghiệm ảo giúp thấy được cả những sự cố nguy hiểm mà <b>không gây nguy hiểm</b> thật.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Trong ngôi sao năm cánh đều: AB/BC = AC/AB = AD/AC = (1 + √5)/2 ≈ 1,618034, gọi là <b>tỉ lệ vàng</b>.</li><li>Nhờ máy tính, phần mềm mô phỏng giúp con người <b>khám phá tri thức</b> và giải quyết vấn đề.</li></ul>"}]},"tin9-lap-chuong-trinh-may-tinh":{"id":"tin9-bai16","ten":"Bài 16. Thực hành: Lập chương trình máy tính","cau":[{"id":"kd1","type":"mcq","q":"Các ngôn ngữ lập trình đều được trang bị những cấu trúc điều khiển cơ bản nào?","k":"Ba cấu trúc điều khiển cơ bản: <b>tuần tự, rẽ nhánh và lặp</b>. Mô tả thuật toán chỉ bằng ba cấu trúc này giúp dễ dàng tạo ra chương trình máy tính.","o":["Tuần tự, rẽ nhánh và lặp.","Nhập, xuất và tính toán.","Biến, hằng và biểu thức.","Hỏi, trả lời và nói."],"a":0},{"id":"bien","type":"sort","q":"Xếp mỗi biến của chương trình tính lương vào nhóm phù hợp.","k":"Đầu vào: muc_luong, tgian_laodong. Đầu ra: tien_luong. Trung gian: tgian_dmuc, tgian_vuot, luong_dmuc, luong_vuot.","cats":["Biến đầu vào","Biến đầu ra","Biến trung gian"],"items":[["muc_luong",0],["tgian_laodong",0],["tien_luong",1],["tgian_dmuc",2],["tgian_vuot",2],["luong_dmuc",2],["luong_vuot",2]]},{"id":"lap","type":"mcq","q":"Vì sao bước nhập tgian_laodong dùng vòng lặp với điều kiện sau (Hình 16.1a) cần chuyển thành vòng lặp với điều kiện trước (Hình 16.1b)?","k":"Chương trình là bản mô tả thuật toán theo quy tắc của ngôn ngữ lập trình: phải hiệu chỉnh cách mô tả để cài đặt được bằng <b>công cụ có sẵn</b> của ngôn ngữ (Hình 16.1c).","o":["Để phù hợp với cấu trúc lặp có sẵn trong Scratch: “lặp lại cho đến khi ⟨⟩” kiểm tra điều kiện trước khi thực hiện thân lặp.","Vì vòng lặp với điều kiện sau luôn chạy sai.","Để chương trình chạy nhanh hơn.","Vì Scratch không có khối hỏi và đợi."],"a":0},{"id":"hs","type":"mcq","q":"Trong chương trình Scratch, hệ số 1,5 của thuật toán tính lương phải được viết thế nào?","k":"Viết <b>1.5</b>: dùng dấu chấm thay cho dấu phẩy để ngăn cách phần nguyên và phần thập phân.","o":["1.5","1,5","15/10,0","1 5"],"a":0},{"id":"ghep1","type":"order","q":"Sắp xếp các nhóm khối lệnh (Hình 16.2) theo đúng thứ tự để được chương trình tính lương.","k":"Nhập muc_luong → nhập tgian_laodong (có kiểm tra) → rẽ nhánh tính giờ định mức, giờ vượt → tính lương → xuất kết quả.","items":{"a":"Khi bấm vào lá cờ; hỏi “Mức lương của nhân viên (theo giờ)?” và đợi; đặt muc_luong thành trả lời","b":"Hỏi số giờ làm việc; lặp lại cho đến khi không phải ⟨trả lời < 1 hoặc trả lời > 60⟩: hỏi lại; đặt tgian_laodong thành trả lời","c":"Nếu tgian_laodong > 40 thì … nếu không thì … (tính tgian_dmuc, tgian_vuot)","d":"Đặt luong_dmuc, luong_vuot, tien_luong","e":"Nói kết hợp “Tiền lương theo tuần = ” và tien_luong trong 5 giây; dừng lại tất cả"},"ans":["a","b","c","d","e"],"start":["c","e","a","d","b"]},{"id":"gl1","type":"open","q":"Kiểm thử chương trình tính lương với 6 tình huống của Bảng 16.1. Tình huống nào chương trình chạy chưa đúng? Em đã sửa chương trình như thế nào?","k":"Tình huống 6 (muc_luong = −100) chưa đúng: chương trình vẫn tính lương. Sửa: sau khi hỏi mức lương, thêm vòng lặp “lặp lại cho đến khi trả lời > 0: hỏi lại mức lương” rồi mới đặt muc_luong thành trả lời.","label":"NV1 – Gỡ lỗi"},{"id":"ghep2","type":"order","q":"Sắp xếp các nhóm khối lệnh (Hình 16.3) theo đúng thứ tự để được chương trình tìm giá trị lớn nhất.","k":"Khởi tạo max → nhập x lần đầu → vòng lặp (so sánh, nhập tiếp) → xuất kết quả → dừng.","items":{"a":"Khi bấm vào lá cờ; đặt max thành 0","b":"Hỏi “Nhập một số nguyên dương” và đợi; đặt x thành trả lời","c":"Lặp lại cho đến khi x = 0: nếu x > max thì đặt max thành x; hỏi “Nhập số nguyên dương tiếp theo” và đợi; đặt x thành trả lời","d":"Nếu max = 0 thì nói “Không có dữ liệu!” nếu không thì nói kết hợp “Số lớn nhất là ” và max","e":"Dừng lại tất cả"},"ans":["a","b","c","d","e"],"start":["d","b","e","c","a"]},{"id":"t8","type":"mcq","q":"Chạy kiểm thử chương trình Hình 16.3 với tình huống 8 của Bảng 16.2 (7 data 12 0). Chương trình cho kết quả gì?","k":"Scratch không phân biệt số và chữ: khi so sánh “data” &gt; 7, Scratch so sánh như hai xâu kí tự nên “data” được coi là lớn hơn → kết quả <b>sai</b>.","o":["Số lớn nhất là data","Số lớn nhất là 12","Không có dữ liệu!","Số lớn nhất là 7"],"a":0},{"id":"lt1","type":"open","q":"Bộ giá trị ở tình huống 6 (Bảng 16.2) cho thấy có những giá trị đầu vào chưa hợp lí. Em hãy chỉnh sửa chương trình để có một chương trình hoạt động tốt. Mô tả cách sửa của em.","k":"Ví dụ: chỉ xử lí x khi x &gt; 0; nếu x &lt; 0 thì nói “Số không hợp lệ” rồi hỏi lại (hoặc bỏ qua số đó).","label":"Luyện tập"},{"id":"vd1","type":"open","q":"Chương trình lập trong Nhiệm vụ 2 cho kết quả sai với bộ dữ liệu ở tình huống 8 (Bảng 16.2). Em hãy sửa chương trình để có thể xác thực dữ liệu và bỏ qua dữ liệu dạng chữ trong bộ dữ liệu đầu vào. Mô tả cách sửa.","k":"Ví dụ: trong Scratch, một chữ khi cộng với 0 cho kết quả 0. Chỉ so sánh x với max khi ⟨(x + 0) = x⟩ (x là số); nếu không thì bỏ qua.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Chương trình là bản mô tả thuật toán bằng ngôn ngữ mà máy tính có thể “hiểu” và thực hiện.</li><li>Mô tả thuật toán chỉ bằng các cấu trúc tuần tự, rẽ nhánh, lặp giúp dễ dàng cài đặt thành chương trình.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Gỡ lỗi: lập các bộ dữ liệu kiểm thử, mỗi bộ đại diện cho một tình huống; chương trình chạy không đúng yêu cầu thì cần phải sửa.</li></ul>"}]},"tin9-phap-li-dich-vu-internet":{"id":"tin9-bai4","ten":"Bài 4. Một số vấn đề pháp lí về sử dụng dịch vụ Internet","cau":[{"id":"kd1","type":"open","q":"Bên cạnh những tác động tích cực, công nghệ kĩ thuật số cũng có những tác động tiêu cực đến con người. Em hãy thảo luận với bạn và kể ra một vài tác động tiêu cực đó.","k":"Ví dụ: nghiện trò chơi điện tử, nghiện mạng xã hội; ít giao tiếp, ít vận động, mất ngủ, cận thị; bị lộ thông tin cá nhân; bị lừa đảo trên mạng; bị bắt nạt qua mạng; tin giả lan truyền; rác thải điện tử gây ô nhiễm môi trường,…","label":"Mở đầu"},{"id":"hd1a","type":"sort","q":"Mỗi phương án dưới đây có nói về tác động tiêu cực của công nghệ kĩ thuật số tới đời sống con người và xã hội không?","k":"Tác động tiêu cực: <b>A, B, D</b>. Phương án C là tác động <b>tích cực</b> của ngân hàng số.","cats":["Tiêu cực","Không phải"],"items":[["A. Quyền riêng tư dễ bị ảnh hưởng.",0],["B. Dữ liệu tài khoản ngân hàng bị đánh cắp.",0],["C. Giao dịch trong thương mại tăng nhanh nhờ ứng dụng ngân hàng số.",1],["D. Ô nhiễm do rác thải từ những thiết bị công nghệ số lỗi thời.",0]]},{"id":"hd1b","type":"open","q":"Em hãy kể thêm một vài tác động tiêu cực của công nghệ kĩ thuật số đối với xã hội.","k":"Ví dụ: lừa đảo trên mạng (giả danh, lừa đầu tư, đánh bạc trực tuyến); tự động hoá làm <b>một số người mất việc</b>; người già, người khuyết tật, người ở vùng khó khăn <b>càng tụt hậu</b>; tin giả, tin sai sự thật lan nhanh; rác thải điện tử gây ô nhiễm môi trường.","label":"HĐ1 – Câu 2"},{"id":"dt","type":"sort","q":"Đọc mục 1 (SGK trang 15–16). Mỗi tác động tiêu cực dưới đây chủ yếu ảnh hưởng đến con người (cá nhân) hay đến xã hội?","k":"<ul><li><b>Đối với con người:</b> ảnh hưởng sức khoẻ thể chất và tinh thần (nghiện Internet, ít giao tiếp, mất ngủ,…); ảnh hưởng quyền riêng tư; quá lệ thuộc vào công nghệ (nhờ AI làm bài); nguy cơ mất an toàn khi trò chuyện với người lạ.</li><li><b>Đối với xã hội:</b> lừa đảo, đánh bạc, tuyên truyền tệ nạn; nguy cơ thất nghiệp; một bộ phận người dân càng tụt hậu; rác thải điện tử gây ô nhiễm môi trường.</li></ul>","cats":["Con người","Xã hội"],"items":[["Nghiện Internet, ít giao tiếp, mất ngủ",0],["Thông tin cá nhân bị rò rỉ, dữ liệu bị đánh cắp",0],["Lừa đảo, tổ chức đánh bạc, tuyên truyền tệ nạn trên mạng",1],["Tự động hoá khiến nguy cơ thất nghiệp tăng",1],["Người già, người khuyết tật, người ở vùng khó khăn càng tụt hậu",1],["Học sinh nhờ trí tuệ nhân tạo làm bài tập về nhà",0]]},{"id":"p16a","type":"mcq","q":"Phương án nào sau đây KHÔNG phải là tác động tiêu cực của công nghệ kĩ thuật số đến đời sống con người?","k":"Dùng phần mềm soạn thảo văn bản để làm báo cáo là <b>ứng dụng tích cực</b>, giúp làm việc nhanh, đẹp. Ba phương án còn lại là lệ thuộc công nghệ, nghiện mạng, thói quen hại sức khoẻ.","o":["Nhờ trí tuệ nhân tạo làm bài tập về nhà.","Truy cập mạng xã hội trong nhiều giờ.","Thường xuyên sử dụng phần mềm soạn thảo văn bản để làm báo cáo.","Vừa ăn vừa xem video trên trang YouTube."],"a":2},{"id":"p16b","type":"sort","q":"Những phương án nào sau đây là tác động tiêu cực của công nghệ kĩ thuật số đến xã hội?","k":"Đáp án: <b>B, C, D</b>. B ảnh hưởng đến cả một thế hệ (lớp trẻ); C, D ảnh hưởng đến môi trường và việc làm của xã hội. Việc thông tin cá nhân được số hoá (A) tự nó không phải tác động tiêu cực; chỉ khi thông tin bị rò rỉ, đánh cắp mới gây hại.","cats":["Tiêu cực đến xã hội","Không phải"],"items":[["A. Thông tin cá nhân của con người được số hoá.",1],["B. Sử dụng thiết bị số liên tục trong thời gian dài ảnh hưởng đến sức khoẻ thể chất và tinh thần của lớp trẻ.",0],["C. Gia tăng ô nhiễm môi trường.",0],["D. Làm gia tăng tỉ lệ thất nghiệp.",0]]},{"id":"hd2a","type":"sort","q":"Những hành vi nào sau đây vi phạm pháp luật, trái đạo đức, thiếu văn hoá?","k":"Hành vi vi phạm: <b>A</b> (vi phạm bản quyền), <b>B</b> (thiếu văn hoá), <b>D</b> (bôi nhọ, xúc phạm người khác). Chúc mừng sinh nhật bạn (C) là hành vi bình thường, có văn hoá.","cats":["Vi phạm","Không vi phạm"],"items":[["A. Tải về một hình ảnh trên Internet khi chưa có sự cho phép của chủ sở hữu và sử dụng như là của mình.",0],["B. Sử dụng ngôn ngữ phản cảm khi giao tiếp trên mạng xã hội.",0],["C. Chúc mừng sinh nhật bạn trên mạng xã hội.",1],["D. Đăng hình ảnh, video bôi nhọ, xúc phạm tập thể hoặc cá nhân lên mạng.",0]]},{"id":"hd2b","type":"open","q":"Em hãy kể thêm một số hành vi vi phạm pháp luật, trái đạo đức, thiếu văn hoá của người sử dụng dịch vụ Internet.","k":"Ví dụ: đăng tin sai sự thật; bắt nạt, đe doạ bạn qua mạng; lập tài khoản giả mạo người khác; lừa đảo trúng thưởng, chiếm đoạt tài khoản; dùng phần mềm bẻ khoá, không bản quyền; phát tán virus; đăng thông tin cá nhân của người khác khi chưa được đồng ý; bình luận khiếm nhã, tục tĩu.","label":"HĐ2 – Câu 2"},{"id":"hv","type":"match","q":"Đọc mục a) và Hình 4.2. Mỗi tình huống dưới đây là hành vi nào?","k":"1 – e, 2 – d, 3 – a, 4 – c, 5 – b, 6 – f.","items":[["1) Giả danh ngân hàng nhắn tin “trúng thưởng”, yêu cầu cung cấp mật khẩu",5],["2) Rủ cả lớp tẩy chay, chế ảnh chế giễu một bạn",4],["3) Chia sẻ tin “sắp động đất” chưa được kiểm chứng",1],["4) Cài phần mềm đã bị bẻ khoá",3],["5) Đăng số điện thoại, địa chỉ nhà của bạn khi bạn không đồng ý",2],["6) Tranh luận trên diễn đàn bằng từ ngữ tục tĩu",6]],"opts":["a) Viết, đăng, chia sẻ nội dung sai sự thật","b) Làm lộ thông tin cá nhân, tổ chức gây ảnh hưởng xấu","c) Sử dụng phần mềm không có bản quyền","d) Bắt nạt qua mạng","e) Lừa đảo qua mạng","f) Ứng xử thiếu văn hoá"]},{"id":"vb","type":"match","q":"Đọc mục b). Ghép mỗi văn bản pháp luật với nội dung chính của nó.","k":"1 – a, 2 – b, 3 – c. Cả ba văn bản đều ghi rõ <b>các hành vi bị nghiêm cấm</b>.","items":[["1) Luật Công nghệ thông tin số 67/2006/QH11 (năm 2006)",1],["2) Nghị định số 72/2013/NĐ-CP (năm 2013)",2],["3) Luật An ninh mạng (năm 2018)",3]],"opts":["a) Quyền, trách nhiệm của tổ chức, cá nhân tham gia ứng dụng và phát triển công nghệ thông tin","b) Quản lí, cung cấp, sử dụng dịch vụ Internet, thông tin trên mạng, trò chơi điện tử trên mạng","c) Bảo vệ an ninh quốc gia, trật tự, an toàn xã hội trên không gian mạng"]},{"id":"nhom","type":"match","q":"Mỗi hành vi dưới đây thuộc nhóm hành vi vi phạm pháp luật nào?","k":"1 – a, 2 – b, 3 – c, 4 – d, 5 – e. Ngoài ra còn nhóm hành vi <b>xuyên tạc lịch sử, phá hoại khối đại đoàn kết, xúc phạm, phân biệt đối xử</b>.","items":[["1) Bình luận sai trái, chi tiết bịa đặt về một vụ việc chưa được kiểm chứng",1],["2) Đăng ảnh, biển số xe của người khác mà không được đồng ý",2],["3) Chia sẻ đoạn mã chương trình của người khác khi không được phép",3],["4) Phát tán virus qua liên kết lừa nhận thưởng",4],["5) Quảng cáo vũ khí, buôn bán động vật quý hiếm",5]],"opts":["a) An ninh quốc gia, trật tự, an toàn xã hội","b) Quyền nhân thân, uy tín của cá nhân, tổ chức","c) Sở hữu trí tuệ, sở hữu tài sản, đánh bạc","d) Bảo đảm an toàn thông tin trên không gian mạng","e) Quảng cáo sản phẩm, dịch vụ trái quy định"]},{"id":"p19a","type":"mcq","q":"Hành vi nào sau đây khi hoạt động trong môi trường số KHÔNG vi phạm pháp luật, trái đạo đức, thiếu văn hoá?","k":"Chia sẻ thông tin về một lớp học lập trình trực tuyến là hành vi <b>có ích</b>. A gây chia rẽ vùng miền, B quảng cáo trái quy định, C xâm phạm tài khoản người khác đều vi phạm.","o":["Đăng bài hoặc bình luận gây mâu thuẫn vùng miền.","Quảng cáo bán hàng hoá, dịch vụ bị cấm.","Sử dụng trái phép tài khoản mạng của tổ chức, cá nhân khác.","Chia sẻ thông tin về lớp học ngôn ngữ lập trình trực tuyến."],"a":3},{"id":"p19b","type":"open","q":"Minh nhận được một liên kết lạ từ một bạn mới quen trên mạng yêu cầu chia sẻ liên kết này cho 5 bạn và truy cập liên kết để nhận được một phần quà là chiếc ba lô rất đẹp. Theo em, Minh có nên làm theo yêu cầu đó không? Tại sao?","k":"<b>Không nên.</b> Đây là dấu hiệu <b>lừa đảo</b>: người lạ, liên kết lạ, hứa tặng quà, yêu cầu chia sẻ tiếp. Liên kết có thể chứa <b>virus, mã độc</b>, trang giả mạo để <b>đánh cắp thông tin, tài khoản</b>; chia sẻ cho bạn bè là tiếp tay phát tán. Minh nên không bấm, không chia sẻ, báo cho bố mẹ, thầy cô.","label":"Câu hỏi tr.19 – câu 2"},{"id":"lt1","type":"sort","q":"Những cách nào sau đây giúp em tránh được các tác động tiêu cực khi sử dụng công nghệ kĩ thuật số? (Câu E, F do thầy cô thêm.)","k":"Cả bốn cách <b>A, B, C, D</b> trong SGK đều giúp tránh tác động tiêu cực. E, F là thói quen có hại.","cats":["Giúp tránh","Không giúp"],"items":[["A. Không sử dụng thiết bị số trong thời gian dài và liên tục.",0],["B. Không xem các video phản cảm.",0],["C. Giảm thời gian dùng điện thoại để nói chuyện với gia đình.",0],["D. Tham gia luyện tập thể dục thể thao.",0],["E. Thức khuya chơi trò chơi trực tuyến cho đỡ căng thẳng.",1],["F. Chia sẻ mật khẩu mạng xã hội cho bạn mới quen.",1]]},{"id":"lt2","type":"open","q":"Em hãy lấy ví dụ về một hành vi vi phạm pháp luật, một hành vi trái đạo đức khi hoạt động trong môi trường số.","k":"<ul><li><b>Vi phạm pháp luật:</b> phát tán virus; sử dụng trái phép tài khoản của người khác; đăng tin sai sự thật; lừa đảo chiếm đoạt tài sản; dùng phần mềm không bản quyền.</li><li><b>Trái đạo đức:</b> chế ảnh chế giễu bạn; bình luận khiếm nhã; tẩy chay, cô lập bạn trên nhóm lớp; nói dối, nói xấu người khác trên mạng.</li></ul>","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Em hãy tìm hiểu các hành vi bị cấm trong Luật Công nghệ thông tin số 67/2006/QH11 và Nghị định số 72/2013/NĐ-CP. Các hành vi bị cấm trong hai văn bản này giống và khác nhau như thế nào?","k":"Gợi ý (Điều 12 Luật CNTT 2006 và Điều 5 Nghị định 72/2013):<ul><li><b>Giống nhau:</b> đều cấm lợi dụng mạng để chống phá Nhà nước, gây rối an ninh, trật tự; kích động bạo lực, chia rẽ dân tộc, tôn giáo; xuyên tạc, xúc phạm danh dự, uy tín người khác; cản trở, phá hoại hệ thống thông tin; phát tán virus, đánh cắp, sử dụng trái phép mật khẩu, thông tin của người khác.</li><li><b>Khác nhau:</b> Luật CNTT có phạm vi rộng cho mọi hoạt động ứng dụng, phát triển CNTT (ví dụ cấm vi phạm quyền sở hữu trí tuệ, giả mạo trang thông tin điện tử). Nghị định 72 quy định cụ thể hơn cho việc cung cấp, sử dụng <b>dịch vụ Internet, thông tin trên mạng, trò chơi điện tử trên mạng</b>.</li></ul>Học sinh cần ghi rõ nguồn tìm hiểu (ví dụ thuvienphapluat.vn, chinhphu.vn).","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Ngoài các tác động tích cực, công nghệ kĩ thuật số còn có một số <b>tác động tiêu cực</b> lên đời sống con người và xã hội.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Khi hoạt động trong môi trường số, sử dụng các dịch vụ Internet, người sử dụng cần có <b>trách nhiệm</b>, ứng xử <b>lành mạnh, có văn hoá</b> và <b>không vi phạm pháp luật</b>.</li><li>Cần cẩn trọng, tránh vi phạm bản quyền khi sử dụng dữ liệu, phần mềm và cảnh giác với các giao tiếp trên mạng; khi giao tiếp luôn thể hiện là người có văn hoá, tôn trọng mọi người.</li></ul>"}]},"tin9-tai-chinh-gia-dinh":{"id":"tin9-bai13a","ten":"Bài 13a. Hoàn thiện bảng tính quản lí tài chính gia đình","cau":[{"id":"kd1","type":"open","q":"Dự án sử dụng bảng tính điện tử quản lí tài chính gia đình đã hoàn thành các trang tính Thu nhập và Chi tiêu. Theo em, để cân đối thu, chi, giúp kiểm soát chi tiêu gia đình hiệu quả, bảng tính cần bổ sung thông tin gì?","k":"Một trang tính <b>tổng hợp</b>: tổng thu nhập, tổng chi tiêu, phần chênh lệch (thu − chi) và biểu đồ so sánh trực quan.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Hãy chỉ ra mối liên hệ về dữ liệu của trang tính Tổng hợp ở Hình 13a.3 với hai trang tính Thu nhập và Chi tiêu ở Hình 13a.1 và Hình 13a.2.","k":"Tổng thu nhập (17 500) ở trang Tổng hợp chính là ô <b>H7</b> của trang Thu nhập; tổng chi tiêu (13 640) chính là ô <b>H11</b> của trang Chi tiêu; Giá trị NET = thu − chi.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"mcq","q":"Trong trang tính Tổng hợp, công thức để tính tổng thu nhập ở ô B14 và tổng số tiền chi tiêu ở ô B15 là:","k":"Lấy giá trị từ trang tính khác: <b>='Thu nhập'!H7</b> và <b>='Chi tiêu'!H11</b>. Dữ liệu được cập nhật tự động khi hai trang tính kia thay đổi.","o":["B14: ='Thu nhập'!H7; B15: ='Chi tiêu'!H11","B14: =H7; B15: =H11","B14: =SUM(H2:H6); B15: =SUM(H2:H10)","B14: ='Chi tiêu'!H7; B15: ='Thu nhập'!H11"],"a":0},{"id":"net","type":"mcq","q":"Giá trị NET ở ô B16 được tính bằng =B14-B15. Với dữ liệu mẫu, Giá trị NET và ý nghĩa của nó là:","k":"Giá trị NET là số tiền <b>chênh lệch giữa thu và chi</b>: 17 500 − 13 640 = 3 860. NET âm cho thấy chi tiêu nhiều hơn thu, cần báo động.","o":["3 860: thu nhiều hơn chi 3 860 nghìn đồng; nếu giá trị NET âm thì gia đình đang chi tiêu nhiều, cần báo động để mọi người tiết kiệm.","31 140: tổng thu và chi.","−3 860: gia đình đang thiếu tiền.","3 860: số lần chi tiêu."],"a":0},{"id":"p53a","type":"match","q":"Hình 13a.4 là công thức ='Thu nhập'!H7 lấy tổng tiền thu nhập từ trang tính Thu nhập đưa vào trang Tổng hợp. Ghép mỗi cụm từ với vị trí (1), (2), (3) cho phù hợp.","k":"(1) – Tên trang tính; (2) – Dấu chấm than; (3) – Địa chỉ ô.","items":[["(1) 'Thu nhập'",1],["(2) !",2],["(3) H7",3]],"opts":["Tên trang tính","Dấu chấm than","Địa chỉ ô"]},{"id":"p53b","type":"mcq","q":"Trong một bảng tính có chứa nhiều trang tính, nếu công thức tham chiếu đến địa chỉ ô ở một trang tính khác thì địa chỉ ô đó gồm những thành phần gì?","k":"<b>Tên trang tính</b> + <b>!</b> + <b>địa chỉ ô</b>, ví dụ ='Thu nhập'!H7. Tên trang tính có dấu cách được đặt trong cặp dấu nháy đơn.","o":["Tên trang tính, dấu chấm than (!) và địa chỉ ô.","Chỉ có địa chỉ ô.","Tên tệp và địa chỉ ô.","Tên trang tính và dấu hai chấm (:)."],"a":0},{"id":"nv1","type":"order","q":"Sắp xếp các bước thực hiện nhiệm vụ hoàn thiện bảng tính quản lí tài chính gia đình.","k":"Tính tổng ở hai trang tính → tạo trang Tổng hợp → bảng A13:B16 → biểu đồ cột.","items":{"a":"Trang Thu nhập: tại H7 nhập =SUM(H2:H6).","b":"Trang Chi tiêu: tại H11 nhập =SUM(H2:H10).","c":"Tạo trang tính mới, đặt tên Tổng hợp, A1: Cân đối thu chi.","d":"Tạo bảng A13:B16: B14 ='Thu nhập'!H7, B15 ='Chi tiêu'!H11, B16 =B14-B15.","e":"Chọn A13:B15, Insert → Charts → Clustered Column; đặt biểu đồ vào A2:B12."},"ans":["a","b","c","d","e"],"start":["d","a","e","c","b"]},{"id":"nv2","type":"mcq","q":"Để vẽ biểu đồ cột hiển thị trực quan giá trị thu và chi (Hình 13a.3), em chọn vùng dữ liệu nào và dạng biểu đồ nào?","k":"Chọn <b>A13:B15</b> (nội dung và số tiền của Thu nhập, Chi tiêu), dải lệnh <b>Insert</b> → nhóm <b>Charts</b> → <b>Clustered Column</b>.","o":["Vùng A13:B15; Insert → Charts → Clustered Column.","Vùng A13:B16; biểu đồ hình tròn.","Vùng B14:B16; biểu đồ đường.","Toàn bộ trang tính Chi tiêu; biểu đồ cột."],"a":0},{"id":"lt1","type":"open","q":"Bổ sung một số dòng dữ liệu thu, chi vào cả hai trang tính Thu nhập và Chi tiêu, sửa lại các công thức cho đúng vùng dữ liệu mới. Quan sát để thấy dữ liệu đã được cập nhật tự động vào trang tính Tổng hợp. Từ Giá trị NET, em hãy đánh giá tình hình tài chính hiện tại của gia đình và đề xuất những điều chỉnh chi tiêu sao cho phù hợp.","k":"Mở rộng vùng của COUNTIF, SUMIF, SUM. Trang Tổng hợp tự cập nhật. NET dương: thu đủ chi, có thể tăng tiết kiệm; NET âm hoặc nhỏ: cắt giảm khoản chi không thiết yếu (theo quy tắc 50-30-20).","label":"Luyện tập"},{"id":"vd1","type":"open","q":"Tạo trang tính Tổng hợp để cân đối kinh phí cho dự án Triển lãm tin học, trong đó tiền thu được lấy từ trang tính lưu các khoản thu, tiền chi được lấy từ trang tính lưu các khoản chi của triển lãm. Dựa trên dữ liệu của trang Tổng hợp, thảo luận với bạn để đánh giá tình hình kinh phí của dự án và điều chỉnh phù hợp.","k":"Ví dụ: B14 ='Các khoản thu'!H4; B15 ='Các khoản chi'!H4; B16 =B14-B15; vẽ biểu đồ cột A13:B15.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Khi sử dụng bảng tính điện tử quản lí tài chính gia đình, dữ liệu thu, chi được lưu trữ, cập nhật và hiển thị trực quan, sinh động, dễ so sánh,… giúp các gia đình kiểm soát chi tiêu hiệu quả.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Tham chiếu ô ở trang tính khác: <b>='Tên trang tính'!Địa chỉ ô</b>, ví dụ ='Thu nhập'!H7. Dữ liệu được cập nhật tự động.</li></ul>"}]},"tin9-the-gioi-ki-thuat-so":{"id":"tin9-bai1","ten":"Bài 1. Thế giới kĩ thuật số","cau":[{"id":"kd1","type":"open","q":"Bộ xử lí là “bộ não” của máy tính. Ngoài máy tính để bàn và máy tính xách tay, em còn biết những thiết bị nào khác cũng có gắn bộ xử lí?","k":"Bộ xử lí không chỉ có trong máy tính. Rất nhiều thiết bị điện tử khác cũng được gắn bộ xử lí để hoạt động như <b>máy tính</b>: điện thoại thông minh, ti vi kĩ thuật số, robot lau nhà, máy giặt, tủ lạnh, điều hoà, đồng hồ thông minh, máy ATM, máy chấm công nhận khuôn mặt,…","label":"Mở đầu"},{"id":"hd1a","type":"open","q":"Ti vi kĩ thuật số (Hình 1.1) tiếp nhận thông tin đầu vào nào từ bộ điều khiển?","k":"Khi em nhấn nút trên bộ điều khiển từ xa (chuyển kênh, tăng âm lượng,…), ti vi nhận được <b>tín hiệu từ nút bấm</b>, tức là <b>yêu cầu của người dùng</b> (ví dụ: chuyển sang kênh số 5).","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Ti vi thể hiện sự thay đổi ở đầu ra như thế nào?","k":"Ti vi <b>chuyển sang kênh mới</b>: màn hình hiển thị hình ảnh, loa phát âm thanh của kênh em yêu cầu (hoặc thay đổi âm lượng, hiện menu,…).","label":"HĐ1 – Câu 2"},{"id":"hd1c","type":"open","q":"Ti vi có thực hiện thao tác xử lí thông tin không? Vì sao?","k":"<b>Có.</b> Ti vi phải xử lí thông tin nhận được từ bộ điều khiển để chuyển sang kênh em yêu cầu. Để làm được việc đó, ti vi phải được <b>gắn một bộ xử lí</b> thông tin.","label":"HĐ1 – Câu 3"},{"id":"p6a","type":"match","q":"Em hãy ghép mỗi cụm từ với một thiết bị có gắn bộ xử lí trong Hình 1.2.","k":"a – bảng điện tử; b – máy chụp cắt lớp; c – robot lắp ráp; d – ô tô lái tự động.","items":[["a) Hình 1.2a",3],["b) Hình 1.2b",2],["c) Hình 1.2c",4],["d) Hình 1.2d",1]],"opts":["1) Ô tô lái tự động","2) Máy chụp cắt lớp","3) Bảng điện tử","4) Robot lắp ráp"]},{"id":"p6b","type":"match","q":"Những thiết bị trong Hình 1.2 thường xuất hiện ở nơi nào trong thực tế?","k":"Bảng điện tử – sân bay, nhà ga (thông tin chuyến bay, chuyến tàu); máy chụp cắt lớp – bệnh viện; robot lắp ráp – nhà máy sản xuất (lắp ráp ô tô); ô tô lái tự động – đường phố.","items":[["a) Bảng điện tử",3],["b) Máy chụp cắt lớp",1],["c) Robot lắp ráp",4],["d) Ô tô lái tự động",2]],"opts":["1) Bệnh viện","2) Đường phố, giao thông","3) Sân bay, nhà ga","4) Nhà máy, xí nghiệp sản xuất"]},{"id":"hd2","type":"open","q":"Em hãy nêu một số khả năng của máy tính mà nhờ đó máy tính có thể hỗ trợ con người một cách đắc lực trong cuộc sống.","k":"<ul><li><b>Tính toán nhanh, chính xác</b>: hàng tỉ phép tính mỗi giây.</li><li><b>Làm việc bền bỉ</b>, không mệt mỏi.</li><li><b>Lưu trữ dung lượng lớn</b> nhiều loại dữ liệu: văn bản, hình ảnh, âm thanh, video,… và truy xuất nhanh.</li><li><b>Kết nối toàn cầu với tốc độ cao</b> qua mạng Internet.</li></ul>","label":"HĐ2 – Máy tính thật là cần thiết"},{"id":"kn","type":"sort","q":"Đọc mục a) Khả năng của máy tính (SGK trang 6–7). Mỗi ý dưới đây có phải là khả năng của máy tính được nêu trong sách không?","k":"Bốn ý đầu là khả năng của máy tính: <b>tính toán nhanh, bền bỉ, chính xác; lưu trữ dữ liệu với dung lượng lớn; kết nối toàn cầu với tốc độ cao</b>. Máy tính chỉ làm việc theo chương trình do con người tạo ra và cần nguồn điện để hoạt động.","cats":["Đúng là khả năng","Không phải"],"items":[["Thực hiện hàng tỉ phép tính trong một giây, chính xác",0],["Làm việc bền bỉ, không biết mệt mỏi",0],["Lưu trữ và xử lí nhiều loại dữ liệu: văn bản, hình ảnh, âm thanh, video",0],["Kết nối với nhau thành mạng toàn cầu Internet",0],["Tự suy nghĩ và tự quyết định thay con người mà không cần chương trình",1],["Hoạt động được khi không có nguồn điện",1]]},{"id":"ud","type":"match","q":"Đọc mục b) Ứng dụng của máy tính trong khoa học kĩ thuật và đời sống (SGK trang 7). Ghép mỗi ví dụ với lĩnh vực phù hợp.","k":"1 – a, 2 – b, 3 – c, 4 – d, 5 – e. Máy tính được ứng dụng hiệu quả trong <b>hầu hết các lĩnh vực</b> của khoa học kĩ thuật và đời sống.","items":[["1) Mô phỏng dòng chảy chất lỏng, chất khí; dự báo thời tiết",1],["2) Hiểu cơ thể người, chẩn đoán bệnh; quản lí dữ liệu người bệnh",2],["3) Tham khảo tài liệu từ kho dữ liệu số hoá trên Internet",3],["4) Điều khiển xe tự động lái, điều khiển hệ thống đèn tín hiệu",4],["5) Gửi tin nhắn, mua sắm, đọc báo, giải trí chỉ bằng vài cú nhấp chuột",5]],"opts":["a) Khoa học kĩ thuật","b) Y tế","c) Nghiên cứu, học tập","d) Giao thông","e) Đời sống hằng ngày"]},{"id":"hd3","type":"open","q":"Em hãy kể một số ví dụ cho thấy tác động của công nghệ thông tin lên giáo dục và xã hội.","k":"<ul><li><b>Giáo dục:</b> học trực tuyến, thư viện điện tử, bài giảng video, phần mềm học tập, tra cứu tài liệu trên Internet mọi lúc, mọi nơi; nhiều dữ liệu học tập miễn phí.</li><li><b>Xã hội:</b> gọi điện, nhắn tin, mạng xã hội giúp liên lạc dễ dàng dù ở xa; dịch vụ công trực tuyến, mua bán, thanh toán qua mạng; chuyển giao và tiếp cận thông tin nhanh chóng.</li><li><b>Tác động tiêu cực</b> nếu dùng không đúng cách: nghiện game, mạng xã hội; ảnh hưởng sức khoẻ thể chất và tinh thần; tin giả,…</li></ul>","label":"HĐ3 – Tác động của CNTT"},{"id":"td","type":"sort","q":"Đọc mục 3 (SGK trang 8). Mỗi ví dụ dưới đây là tác động tích cực hay tiêu cực của công nghệ thông tin?","k":"Công nghệ thông tin tạo ra <b>nhiều tác động tích cực</b> đến con người và xã hội, nhưng nếu <b>sử dụng không đúng cách và thiếu trách nhiệm</b> thì có thể gây tác động tiêu cực. Cách chúng ta sử dụng sẽ quyết định tác động có lợi hay có hại.","cats":["Tích cực","Tiêu cực"],"items":[["Học sinh tự học thêm qua bài giảng video và thư viện điện tử",0],["Người thân ở xa vẫn trò chuyện, nhìn thấy nhau qua cuộc gọi video",0],["Thức khuya chơi trò chơi trực tuyến, ảnh hưởng sức khoẻ và việc học",1],["Mọi người chia sẻ kiến thức, kĩ năng trên Internet, nhiều tài liệu miễn phí",0],["Dành quá nhiều thời gian lướt mạng xã hội, ít giao tiếp với gia đình",1],["Tin đồn sai sự thật lan truyền nhanh trên mạng",1]]},{"id":"p8a","type":"open","q":"Kể về một ứng dụng của công nghệ thông tin mà em thường xuyên sử dụng.","k":"Học sinh tự kể. Ví dụ: <b>Zalo</b> (nhắn tin, gọi video với bạn bè, nhóm lớp), <b>YouTube</b> (xem bài giảng), <b>Google Maps</b> (tìm đường), phần mềm học tiếng Anh, <b>Google</b> (tra cứu thông tin),…","label":"Câu hỏi tr.8 – a"},{"id":"p8b","type":"open","q":"Nêu những tác động tích cực của ứng dụng đó và cách em sử dụng nó hằng ngày.","k":"Học sinh tự trả lời theo ứng dụng đã chọn. Ví dụ với Zalo: <b>tích cực</b> – liên lạc nhanh, miễn phí, trao đổi bài với bạn, nhận thông báo của lớp. <b>Cách dùng</b>: chỉ dùng khi cần trao đổi việc học, liên lạc gia đình; giới hạn thời gian; không chia sẻ thông tin cá nhân, không lan truyền tin chưa kiểm chứng.","label":"Câu hỏi tr.8 – b"},{"id":"lt1","type":"open","q":"Hãy tưởng tượng, các hoạt động xung quanh em sẽ thay đổi như thế nào khi một ngày các bộ xử lí biến mất, các thiết bị được gắn bộ xử lí không hoạt động nữa.","k":"Gợi ý: điện thoại, máy tính, ti vi không dùng được nên không liên lạc, học trực tuyến, xem tin tức được; đèn giao thông, bảng điện tử ở sân bay, nhà ga ngừng hoạt động gây ùn tắc; ATM, thanh toán điện tử dừng; máy móc trong bệnh viện, nhà máy dừng lại; máy giặt, điều hoà, tủ lạnh thông minh không chạy,… Cuộc sống sẽ <b>bị đảo lộn</b>, vì bộ xử lí đã có mặt ở hầu hết các lĩnh vực.","label":"Luyện tập – câu 1"},{"id":"lt2","type":"open","q":"Em hãy kể một ví dụ về kiến thức, kĩ năng hoặc nội dung thú vị, có nhiều ý nghĩa mà em học được từ nguồn thông tin trên Internet.","k":"Học sinh tự kể. Ví dụ: học cách sơ cứu khi bị bỏng qua video hướng dẫn; học lập trình Scratch, Python trên các trang học trực tuyến; tìm hiểu về Hệ Mặt Trời qua trang web khoa học; học nấu một món ăn,… Cần nêu rõ <b>nguồn</b> và <b>ý nghĩa</b> của điều đã học.","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Đồng hồ thông minh có những chức năng nào khác với đồng hồ thông thường?","k":"Ngoài xem giờ, đồng hồ thông minh có thể: <b>đo nhịp tim, đếm bước chân, theo dõi giấc ngủ</b>; nhận cuộc gọi, tin nhắn, thông báo từ điện thoại; <b>định vị GPS</b>; nghe nhạc; thanh toán; gọi khẩn cấp; cài thêm ứng dụng,…","label":"Vận dụng – a"},{"id":"vd2","type":"open","q":"Tại sao đồng hồ thông minh cần có bộ xử lí?","k":"Vì đồng hồ thông minh phải <b>tiếp nhận và xử lí thông tin</b>: dữ liệu từ cảm biến (nhịp tim, chuyển động, vị trí), tín hiệu từ điện thoại, thao tác chạm của người dùng, rồi tính toán và hiển thị kết quả. Mọi việc xử lí thông tin đó đều cần <b>bộ xử lí</b>.","label":"Vận dụng – b"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Thiết bị được gắn bộ xử lí hiện diện xung quanh ta. Chúng giúp con người <b>tự động hoá</b> một phần hoạt động xử lí thông tin và xuất hiện trong hầu hết các lĩnh vực kinh tế, xã hội và đời sống,…</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Máy tính có khả năng <b>tính toán nhanh, bền bỉ, chính xác; lưu trữ dữ liệu với dung lượng lớn; kết nối toàn cầu với tốc độ cao</b>.</li><li>Máy tính được ứng dụng hiệu quả trong nhiều lĩnh vực của khoa học kĩ thuật và đời sống.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Công nghệ thông tin có tác động mạnh mẽ, đem lại những thay đổi tích cực trong xã hội, trong đó có giáo dục.</li><li>Cần sử dụng công nghệ thông tin đúng cách để tránh những tác động tiêu cực đến cuộc sống.</li></ul>"}]},"tin9-the-gioi-nghe-nghiep":{"id":"tin9-bai17","ten":"Bài 17. Tin học và thế giới nghề nghiệp","cau":[{"id":"kd1","type":"open","q":"An, Minh và Khoa cùng làm một trò chơi trên máy tính: Khoa phác thảo kịch bản và chuyển thành phần mềm; An tạo hình ảnh nhân vật, trang phục, phong cảnh; Minh đưa trò chơi lên Internet, duy trì hoạt động và thu thập ý kiến phản hồi. Theo em, sở trường của mỗi bạn có thể phát triển để trở thành một nghề trong tương lai không?","k":"Có. Ví dụ: Khoa – lập trình, phát triển phần mềm; An – thiết kế đồ hoạ; Minh – quản trị hệ thống, mạng máy tính.","label":"Khởi động"},{"id":"hd1a","type":"match","q":"Ba người bạn, sau này có thể làm những nghề nghiệp gì trong lĩnh vực tin học? Ghép mỗi bạn với một nhóm nghề phù hợp.","k":"Khoa – phân tích và phát triển phần mềm; An – thiết kế đồ hoạ; Minh – quản trị hệ thống (cơ sở dữ liệu và mạng máy tính).","items":[["Khoa (viết kịch bản, chuyển thành phần mềm trò chơi)",1],["An (tạo hình ảnh nhân vật, phong cảnh bằng phần mềm đồ hoạ)",2],["Minh (đưa trò chơi lên Internet, theo dõi, quản trị)",3]],"opts":["Nhà chuyên môn về phân tích và phát triển phần mềm","Nhà thiết kế đồ hoạ và truyền thông đa phương tiện","Nhà chuyên môn về cơ sở dữ liệu và mạng máy tính (nhà quản trị hệ thống)"]},{"id":"hd1b","type":"match","q":"Đặc thù công việc và sản phẩm chính của những nghề nghiệp đó là gì? Ghép mỗi nhóm nghề với công việc đặc thù.","k":"Sản phẩm chính lần lượt: phần mềm; sản phẩm đồ hoạ, đa phương tiện; hệ thống cơ sở dữ liệu, mạng máy tính.","items":[["Nhà chuyên môn về phân tích và phát triển phần mềm",1],["Nhà thiết kế đồ hoạ và truyền thông đa phương tiện",2],["Nhà chuyên môn về cơ sở dữ liệu và mạng máy tính",3]],"opts":["Nghiên cứu, phân tích các thành phần của hệ thống thông tin; thiết kế, phát triển, thử nghiệm, bảo trì phần mềm","Thiết kế nội dung để truyền đạt thông tin dưới dạng hình ảnh, âm thanh, hoạt hình, video cho trò chơi, phim ảnh, quảng cáo","Thiết kế, xây dựng, tích hợp các hệ thống cơ sở dữ liệu; kế hoạch bảo mật; xây dựng, quản trị mạng máy tính"]},{"id":"hg","type":"sort","q":"Theo Hình 17.1, xếp mỗi nghề dưới đây vào hướng nghề phù hợp.","k":"<b>Khoa học máy tính</b>: phân tích và phát triển phần mềm; cơ sở dữ liệu và mạng máy tính. <b>Tin học ứng dụng</b>: thiết kế đồ hoạ và truyền thông đa phương tiện.","cats":["Khoa học máy tính","Tin học ứng dụng"],"items":[["Nhà lập trình các ứng dụng",0],["Nhà phân tích và thiết kế hệ thống",0],["Nhà khoa học dữ liệu",0],["Nhà bảo mật (máy tính)",0],["Nhà quản trị cơ sở dữ liệu",0],["Nhà thiết kế trò chơi máy tính",1],["Nghệ sĩ kĩ thuật số",1],["Nhà thiết kế trang web",1],["Nhà thiết kế đa phương tiện",1]]},{"id":"dt","type":"mcq","q":"Đặc trưng cơ bản của nhóm nghề thuộc hướng Tin học ứng dụng là gì?","k":"<b>Khoa học máy tính</b>: nghiên cứu lí thuyết về thông tin và thuật toán. <b>Tin học ứng dụng</b>: sử dụng phương tiện, công cụ CNTT để giải quyết vấn đề thực tế.","o":["Không đòi hỏi nghiên cứu chuyên sâu về lí thuyết khoa học máy tính mà chủ yếu sử dụng phương tiện và công cụ công nghệ thông tin để giải quyết các vấn đề thực tế trong các lĩnh vực khác.","Nghiên cứu lí thuyết về thông tin và thuật toán, tạo ra cách mới để biểu diễn, xử lí, trao đổi thông tin.","Chỉ làm việc trong các doanh nghiệp công nghệ thông tin.","Chỉ dành cho người giỏi toán."],"a":0},{"id":"p89","type":"open","q":"Sau khi tìm hiểu về nghề nghiệp trong lĩnh vực Tin học, em nhận thấy sở thích và khả năng của mình phù hợp với nhóm nghề nào? Tại sao?","k":"Học sinh nêu nhóm nghề và lí do dựa trên sở thích, khả năng của bản thân (có thể dùng phần “Em hợp với nhóm nghề nào?” để tham khảo).","label":"Câu hỏi tr.89"},{"id":"hd2a","type":"open","q":"Dùng máy tìm kiếm, hội thoại thông minh, website của tổ chức, doanh nghiệp,… Nêu tên một doanh nghiệp hoạt động trong lĩnh vực tin học. Những công việc tin học nào phù hợp nhất với doanh nghiệp đó?","k":"Ví dụ: một công ti phần mềm – phân tích, thiết kế hệ thống, lập trình, kiểm thử phần mềm, phát triển ứng dụng trí tuệ nhân tạo, an ninh mạng…","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Nêu tên một doanh nghiệp sử dụng lao động tin học nhưng hoạt động trong lĩnh vực khác. Những công việc tin học được sử dụng trong doanh nghiệp đó là gì?","k":"Ví dụ: ngân hàng, bệnh viện, siêu thị, đài truyền hình – quản lí thông tin và giao dịch khách hàng, thương mại điện tử, quản trị mạng, thiết kế đồ hoạ quảng cáo…","label":"HĐ2 – Câu 2"},{"id":"dn","type":"sort","q":"Mỗi công việc dưới đây tập trung nhiều hơn theo hướng nào?","k":"Hướng <b>Khoa học máy tính</b> tập trung ở các doanh nghiệp hoạt động trong lĩnh vực tin học; hướng <b>Tin học ứng dụng</b> có ở hầu hết các cơ quan, doanh nghiệp.","cats":["Khoa học máy tính","Tin học ứng dụng"],"items":[["Phân tích, thiết kế hệ thống thông tin",0],["Xây dựng giải pháp kĩ thuật và công nghệ xử lí thông tin",0],["Phát triển các ứng dụng trí tuệ nhân tạo",0],["Nghiên cứu an ninh mạng và bảo mật thông tin",0],["Quản lí thông tin và giao dịch khách hàng",1],["Thương mại điện tử",1],["Cung cấp dịch vụ phát thanh, truyền hình và báo điện tử",1],["Cung ứng dịch vụ đa phương tiện phục vụ quảng cáo, giải trí, truyền thông",1]]},{"id":"hd3","type":"open","q":"Bạn An đặt câu hỏi: “Những nghề liên quan đến tin học có phù hợp với nữ giới không?”. Em hãy giúp bạn An trả lời câu hỏi đó.","k":"Có. Nữ giới có nhiều ưu thế như ghi nhớ tốt, cẩn thận, chu đáo, giao tiếp tốt, chịu được áp lực; ở Việt Nam nữ giới làm tin học có cơ hội phát triển, thu nhập cao. Mọi người, không phân biệt giới tính, đều có cơ hội tiếp cận các nghề tin học theo sở thích, năng lực.","label":"HĐ3 – Nữ giới và tin học"},{"id":"p90","type":"mcq","q":"Em hãy chọn phát biểu đúng.","k":"<b>D</b>. Nghề nghiệp phù hợp phụ thuộc vào năng lực, sở thích, nhu cầu, không phụ thuộc giới tính.","o":["Nam giới làm những nghề như lập trình ứng dụng hay phân tích thiết kế hệ thống tốt hơn nữ giới do họ có tư duy lôgic tốt hơn.","Nữ giới làm những nghề như quản trị hệ thống hay quản trị cơ sở dữ liệu tốt hơn nam giới do họ cẩn thận hơn.","Lựa chọn nghề nghiệp trong lĩnh vực tin học phù hợp với giới tính sẽ đem lại hiệu quả lao động cao hơn.","Cả nam và nữ đều có thể chọn nghề trong lĩnh vực tin học phù hợp với năng lực và nhu cầu của mình."],"a":3},{"id":"lt1","type":"open","q":"Hãy kể tên hai công việc liên quan đến nghề nghiệp tin học trong lĩnh vực khác như y tế, giáo dục, nông nghiệp, xây dựng, giao thông,…","k":"Ví dụ: y tế – quản trị hệ thống hồ sơ bệnh án điện tử; giáo dục – thiết kế bài giảng đa phương tiện, quản trị hệ thống học trực tuyến; giao thông – lập trình hệ thống điều khiển đèn tín hiệu…","label":"Luyện tập – Câu 1"},{"id":"lt2","type":"open","q":"Em hãy nêu ví dụ về một nghề tin học mà theo em, lao động nữ có ưu thế. Giải thích cho câu trả lời của mình.","k":"Ví dụ: kiểm thử phần mềm (cần cẩn thận, chi tiết), thiết kế đồ hoạ, quản trị web, phân tích dữ liệu…","label":"Luyện tập – Câu 2"},{"id":"vd1","type":"open","q":"Hãy kể về một nghề tin học mà em quan tâm. Nghề nghiệp đó theo định hướng Khoa học máy tính hay Tin học ứng dụng?","k":"Học sinh nêu tên nghề, công việc, sản phẩm chính và xác định đúng định hướng.","label":"Vận dụng – Câu 1"},{"id":"vd2","type":"open","q":"Em cần bổ sung những kiến thức hay kĩ năng nào để có thể trở thành người lao động trong nghề nghiệp mà em quan tâm ở Câu 1?","k":"Ví dụ: học tốt Toán, Tin học, tiếng Anh; học lập trình, thiết kế đồ hoạ; kĩ năng làm việc nhóm, tự học, giải quyết vấn đề…","label":"Vận dụng – Câu 2"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Những nhóm nghề thuộc hướng <b>Khoa học máy tính</b> có đặc điểm chung là nghiên cứu lí thuyết về thông tin và thuật toán, tạo ra những cách mới để biểu diễn, xử lí và trao đổi thông tin trong môi trường số.</li><li>Những nhóm nghề thuộc hướng <b>Tin học ứng dụng</b> không đòi hỏi nghiên cứu chuyên sâu về lí thuyết khoa học máy tính mà chủ yếu là sử dụng phương tiện và công cụ công nghệ thông tin để giải quyết các vấn đề thực tế trong các lĩnh vực khác.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Không chỉ những doanh nghiệp tin học mà nhiều doanh nghiệp khác cũng cần lao động tin học, theo cả hai hướng Khoa học máy tính và Tin học ứng dụng.</li><li>Mọi người, không phân biệt giới tính đều có cơ hội tiếp cận các nghề nghiệp trong lĩnh vực tin học theo sở thích, năng lực và nhu cầu của mình.</li></ul>"}]},"tin9-thong-tin-giai-quyet-van-de":{"id":"tin9-bai2","ten":"Bài 2. Thông tin trong giải quyết vấn đề","cau":[{"id":"kd1","type":"open","q":"Thông tin trên Internet rất nhiều và dễ tìm. Theo em, vì sao An cần tìm thông tin có chất lượng để chọn trường THPT phù hợp?","k":"Thông tin trên Internet <b>rất nhiều nhưng không phải thông tin nào cũng hữu ích, đáng tin cậy</b>. Chỉ có thông tin <b>có chất lượng</b> mới giúp An so sánh đúng các trường và chọn được trường phù hợp với sở thích, khả năng của mình; nếu dùng thông tin sai, cũ hoặc thiếu, An có thể chọn nhầm trường.","label":"Mở đầu"},{"id":"hd1","type":"open","q":"Em hãy cho biết việc Minh chia sẻ thông tin với An và An đã tin tưởng, sử dụng thông tin để chọn trường mà chưa tìm hiểu kĩ sẽ có thể xảy ra vấn đề gì.","k":"<ul><li>Thông tin trên trang web có thể <b>đã cũ</b> (Hình 2.1 ghi “Năm học 2001–2002”), <b>chưa chính xác, chưa đầy đủ</b> hoặc chỉ là lời quảng cáo.</li><li>An chưa kiểm chứng nên quyết định có thể <b>không đúng</b>: trường thực tế khác lời giới thiệu, không phù hợp với An.</li><li>An chỉ đăng kí <b>một nguyện vọng</b> nên <b>giảm cơ hội lựa chọn</b>, nếu không đỗ sẽ gặp khó khăn.</li></ul>","label":"HĐ1 – Chọn trường"},{"id":"nguon","type":"sort","q":"Đọc mục 1 (SGK trang 10). Để chọn trường THPT, mỗi nguồn thông tin dưới đây là nguồn đáng tin cậy hay cần kiểm chứng thêm?","k":"SGK nêu các nguồn đáng tin cậy: <b>trang web của Sở Giáo dục và Đào tạo, ý kiến của giáo viên chủ nhiệm hay của người thân có kinh nghiệm</b>. Thông tin từ trang web lạ, quảng cáo, bình luận ẩn danh cần được <b>kiểm chứng</b> trước khi dùng để ra quyết định.","cats":["Đáng tin cậy","Cần kiểm chứng"],"items":[["Trang web của Sở Giáo dục và Đào tạo",0],["Ý kiến của giáo viên chủ nhiệm",0],["Người thân có kinh nghiệm",0],["Một trang web giới thiệu trường mà bạn gửi cho, chưa rõ cập nhật khi nào",1],["Bài quảng cáo về trường trên mạng xã hội",1],["Bình luận ẩn danh trên một diễn đàn",1]]},{"id":"kol","type":"mcq","q":"KOL (Key Opinion Leader) là người dẫn dắt dư luận chủ chốt hay người có ảnh hưởng. Khi em thấy một KOL quảng cáo sản phẩm trên mạng, em sẽ ứng xử thế nào?","k":"Lời quảng cáo của KOL <b>chưa chắc đã đúng</b> (KOL có thể được trả tiền để quảng cáo), nhưng cũng <b>chưa chắc đã sai</b>. Vì vậy em cần <b>cân nhắc, đánh giá chất lượng thông tin</b> trước khi sử dụng sản phẩm.","o":["Chia sẻ thông tin với người thân vì KOL là một nguồn tin đáng tin cậy.","Sử dụng sản phẩm vì KOL là một đảm bảo cho sản phẩm đã qua kiểm định.","Cân nhắc, đánh giá chất lượng thông tin trước khi sử dụng sản phẩm.","Không sử dụng và cảnh báo người thân về nguồn tin kém chất lượng."],"a":2},{"id":"hd2a","type":"open","q":"Hãy tìm kiếm và lựa chọn thông tin mà theo em là hữu ích giúp em chọn trường THPT.","k":"Ví dụ thông tin hữu ích: <b>điểm chuẩn</b> các năm gần đây, <b>chỉ tiêu tuyển sinh</b>, <b>thời gian và cách đăng kí</b> nguyện vọng, môn thi, khoảng cách từ nhà đến trường, học phí, chất lượng dạy học, các câu lạc bộ, hoạt động ngoại khoá,… lấy từ trang web của Sở GD&ĐT, của trường, ý kiến thầy cô.","label":"HĐ2 – Câu 1"},{"id":"hd2b","type":"open","q":"Tại sao thông tin đó là hữu ích đối với việc giải quyết vấn đề chọn trường của em?","k":"Vì thông tin đó <b>mới</b> (năm học này), <b>chính xác</b> (từ nguồn tin cậy), <b>đầy đủ</b> (nhiều khía cạnh) và <b>liên quan trực tiếp</b> đến việc chọn trường: giúp em so sánh điểm chuẩn với khả năng của mình, biết hạn đăng kí, chọn trường phù hợp sở thích và điều kiện gia đình.","label":"HĐ2 – Câu 2"},{"id":"tc","type":"match","q":"Đọc mục 2 (SGK trang 10–11). Mỗi thông tin kém chất lượng dưới đây vi phạm tiêu chí nào?","k":"1 – a (thông tin đã lỗi thời); 2 – b (nội dung sai); 3 – c (thiếu nhiều khía cạnh); 4 – d (không liên quan, không phù hợp với vấn đề cần giải quyết).","items":[["1) Trang web giới thiệu trường ghi thông tin của năm học 2001–2002",1],["2) Bài viết ghi sai điểm tuyển sinh, sai địa chỉ của trường",2],["3) Thông tin về trường thiếu chi tiết học phí, môi trường học tập, đội ngũ giáo viên",3],["4) Thông tin về du học nước ngoài khi em đang cần chọn một trường THPT công lập",4]],"opts":["a) Tính mới","b) Tính chính xác","c) Tính đầy đủ","d) Tính sử dụng được"]},{"id":"p11a","type":"mcq","q":"Khi tìm thông tin về các trường THPT, bạn An đã không để ý đến thời gian đăng kí nguyện vọng dự thi và xét tuyển vào lớp 10 các trường THPT công lập. Sơ suất này vi phạm tiêu chí nào về chất lượng thông tin?","k":"Vi phạm <b>tính đầy đủ</b>: thông tin An thu thập còn thiếu một khía cạnh quan trọng là <b>thời gian đăng kí</b> nguyện vọng, nên An không có cái nhìn toàn diện về việc chọn trường.","o":["Tính mới.","Tính chính xác.","Tính đầy đủ.","Tính sử dụng được."],"a":2},{"id":"p11b","type":"open","q":"Điều đó có thể dẫn đến khó khăn gì cho bạn An?","k":"An có thể <b>bỏ lỡ hạn đăng kí</b>, không kịp nộp hồ sơ dự thi, xét tuyển vào trường THPT công lập mình mong muốn; mất cơ hội vào trường công lập, phải chuyển sang học trường khác (dân lập, tư thục) với học phí cao hơn hoặc không phù hợp.","label":"Câu hỏi tr.11 – b"},{"id":"lt1","type":"sort","q":"Đọc tình huống Luyện tập (SGK trang 11). Thông tin số điện thoại mà mỗi bạn nhận được có đạt tiêu chí dưới đây không?","k":"Số điện thoại An lấy từ trang web của nông trại <b>chưa được cập nhật</b> nên không còn mới, không chính xác và không dùng để liên lạc được. Số Minh tìm trên website nhà cung cấp dịch vụ viễn thông là thông tin <b>mới, chính xác, dùng được</b> (Minh đã liên hệ thành công).","cats":["Đạt","Không đạt"],"items":[["Số của An (trang web nông trại): tính mới",1],["Số của An: tính chính xác",1],["Số của An: tính sử dụng được",1],["Số của Minh (website nhà cung cấp dịch vụ viễn thông): tính mới",0],["Số của Minh: tính chính xác",0],["Số của Minh: tính sử dụng được",0]]},{"id":"lt2","type":"open","q":"Em hãy nhận xét về chất lượng của thông tin (theo bốn tiêu chí ở Hình 2.2) mà mỗi bạn thu nhận được.","k":"<ul><li><b>Thông tin của An:</b> không có <b>tính mới</b> (số cũ, chưa cập nhật), không <b>chính xác</b> (số đã thay đổi), không <b>sử dụng được</b> (gọi không liên lạc được). Về <b>tính đầy đủ</b>: chỉ có số cũ, thiếu số mới.</li><li><b>Thông tin của Minh:</b> có <b>tính mới</b>, <b>chính xác</b>, <b>sử dụng được</b> (liên hệ thành công); đủ để giải quyết vấn đề liên lạc với nông trại.</li><li>Bài học: nên tìm và <b>đối chiếu thông tin từ nhiều nguồn</b>, ưu tiên nguồn được cập nhật, tin cậy.</li></ul>","label":"Luyện tập – Nhận xét"},{"id":"vd1","type":"open","q":"Em hãy tìm trên Internet thông tin về chiếc máy tính điện tử kĩ thuật số đầu tiên trên thế giới. Ghi lại thông tin em tìm được và nguồn (trang web) của thông tin đó.","k":"Nhiều nguồn cho biết đó là máy <b>ENIAC</b> (Electronic Numerical Integrator and Computer), hoàn thành năm <b>1945</b>, công bố năm <b>1946</b> tại Đại học Pennsylvania (Mỹ); nặng khoảng 27 tấn, dùng khoảng 17 468 bóng đèn điện tử chân không. Một số nguồn khác nêu máy <b>ABC</b> (Atanasoff–Berry Computer, 1937–1942) hoặc Colossus (Anh, 1943–1944) là máy tính điện tử đầu tiên.","label":"Vận dụng – Tìm thông tin"},{"id":"vd2","type":"open","q":"Đánh giá chất lượng thông tin em tìm được theo bốn tiêu chí: tính mới, tính chính xác, tính đầy đủ, tính sử dụng được.","k":"Gợi ý: <ul><li><b>Chính xác:</b> đối chiếu nhiều nguồn; nguồn uy tín (bách khoa toàn thư, bảo tàng, trang của trường đại học, báo chính thống) đáng tin hơn blog cá nhân. Các nguồn có thể khác nhau tuỳ cách hiểu “máy tính điện tử đầu tiên”.</li><li><b>Đầy đủ:</b> có tên máy, năm, nơi chế tạo, người chế tạo, đặc điểm chính chưa?</li><li><b>Mới:</b> sự kiện lịch sử không thay đổi, nhưng nên dùng bài viết được cập nhật.</li><li><b>Sử dụng được:</b> thông tin có trả lời đúng câu hỏi đặt ra không?</li></ul>","label":"Vận dụng – Đánh giá"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Thông tin là cơ sở để đưa ra các quyết định. Cần phải quan tâm đến <b>chất lượng thông tin</b> khi tìm kiếm, tiếp nhận, trao đổi và sử dụng thông tin để có thể đưa ra các quyết định đúng đắn.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Chất lượng thông tin là yếu tố quan trọng, quyết định hiệu quả của việc giải quyết vấn đề.</li><li>Chất lượng thông tin được đánh giá thông qua <b>tính mới, tính chính xác, tính đầy đủ, tính sử dụng được</b>.</li></ul>"}]},"tin9-tim-hieu-phan-mem-mo-phong":{"id":"tin9-bai5","ten":"Bài 5. Tìm hiểu phần mềm mô phỏng","cau":[{"id":"kd1","type":"open","q":"Theo em, phần mềm mô phỏng có thể giúp Minh tập pha màu như thế nào để tiết kiệm được thời gian và màu vẽ?","k":"Phần mềm mô phỏng cho Minh <b>thử pha màu trên máy tính</b>: chọn màu, thay đổi tỉ lệ, xem ngay màu kết quả; làm lại bao nhiêu lần cũng được mà <b>không tốn màu vẽ</b>, không làm hỏng hỗn hợp màu. Khi đã biết công thức pha, Minh mới pha màu thật.","label":"Mở đầu"},{"id":"hd1","type":"open","q":"Phần mềm mô phỏng pha màu (Hình 5.1) cho phép em chọn màu, tăng giảm tỉ lệ các màu và giúp em nhìn thấy màu kết quả trên màn hình. Em hãy cho biết việc sử dụng phần mềm mô phỏng pha màu để tập pha màu và tìm hiểu về màu sắc có những lợi ích gì?","k":"<ul><li><b>Tiết kiệm</b> màu vẽ, giấy, thời gian; không lo hỗn hợp màu bị xỉn đục, phải bỏ đi.</li><li>Thấy <b>ngay</b> màu kết quả, dễ dàng thay đổi tỉ lệ, làm lại nhiều lần.</li><li>Tìm hiểu được các <b>hệ màu</b> khác nhau; tạo ra nhiều màu mới; tăng hứng thú học tập.</li></ul>","label":"HĐ1 – Pha màu"},{"id":"pm","type":"match","q":"Đọc mục 1 (SGK trang 20–21). Ghép mỗi phần mềm (trang web) với đối tượng mà nó mô phỏng.","k":"1 – a, 2 – b, 3 – c, 4 – d, 5 – e, 6 – f. Phần mềm mô phỏng được dùng trong học tập và cả trong nghiên cứu, giao thông,…","items":[["1) Crocodile Physics, phet.colorado.edu",1],["2) Crocodile Chemistry, ChemLab",2],["3) GeoGebra, Cabri, Geometer's Sketchpad",3],["4) Flowgorithm",4],["5) physics.weber.edu/schroeder/md",5],["6) traffic-simulation.de",6]],"opts":["a) Thí nghiệm vật lí","b) Thí nghiệm hoá học","c) Vẽ hình hình học, giải toán","d) Chạy thử thuật toán dạng sơ đồ khối","e) Chuyển động, tương tác giữa các phân tử","f) Giao thông trong thành phố"]},{"id":"p21","type":"open","q":"Em hãy kể tên một phần mềm mô phỏng mà em biết. Phần mềm đó mô phỏng hoạt động của đối tượng nào?","k":"Ví dụ:<ul><li><b>PhET</b> (phet.colorado.edu): mô phỏng mạch điện, lực, chuyển động, ánh sáng,…</li><li><b>GeoGebra</b>: mô phỏng hình học, đồ thị hàm số.</li><li><b>Flowgorithm</b>: mô phỏng thuật toán dạng sơ đồ khối.</li><li>Phần mềm mô phỏng hệ Mặt Trời, mô phỏng lái xe, Google Earth,…</li></ul>","label":"Câu hỏi tr.21"},{"id":"hd2","type":"open","q":"Phần mềm mô phỏng pha màu có những lợi ích gì trong việc tìm hiểu và tập pha trộn màu theo cách thông thường?","k":"Giúp em học cách tạo ra màu mới từ những màu đã cho mà vẫn <b>tiết kiệm thời gian và vật liệu</b>. Bằng cách thay đổi các lựa chọn của phần mềm, em có thể tìm hiểu được những <b>hệ màu cơ bản</b> khác nhau như RGB (đỏ, lục, lam), CMYK (xanh lơ, hồng sẫm, vàng, đen) hay RYB (đỏ, vàng, lam).","label":"HĐ2 – Lợi ích"},{"id":"li","type":"sort","q":"Đọc mục 2 (SGK trang 21–22). Ý nào dưới đây là lợi ích của phần mềm mô phỏng?","k":"Bốn ý đầu là lợi ích của phần mềm mô phỏng. Phần mềm mô phỏng <b>hỗ trợ</b>, không thay thế hoàn toàn thực hành thật; các phần mềm có <b>chất lượng khác nhau</b>, cần chọn phần mềm có chất lượng cao.","cats":["Đúng là lợi ích","Không đúng"],"items":[["Làm quen, tìm hiểu, nghiên cứu một đối tượng với chi phí thấp",0],["Nghiên cứu lí thuyết một cách trực quan, sinh động bằng cách tương tác",0],["Tạo ra nhiều tình huống để luyện tập, nghiên cứu đầy đủ hơn",0],["Hạn chế những tình huống làm hỏng thiết bị hoặc gây nguy hiểm",0],["Thay thế hoàn toàn mọi giờ thực hành thật",1],["Mọi phần mềm mô phỏng đều chính xác như nhau",1]]},{"id":"bq","type":"mcq","q":"Khi sử dụng phần mềm mô phỏng, em cần lưu ý điều gì?","k":"Các phần mềm mô phỏng có chất lượng khác nhau. Em cần lưu ý sử dụng các phần mềm có <b>chất lượng cao</b> và <b>không vi phạm bản quyền</b>.","o":["Dùng phần mềm nào cũng được vì kết quả đều giống nhau.","Sử dụng các phần mềm có chất lượng cao và không vi phạm bản quyền.","Chỉ dùng phần mềm mô phỏng, không cần làm thí nghiệm thật.","Tải bản bẻ khoá cho đỡ tốn tiền."],"a":1},{"id":"p22","type":"open","q":"Em hãy cho biết lợi ích của phần mềm mô phỏng mà em đã kể tên ở phần Câu hỏi của Mục 1.","k":"Ví dụ với PhET mô phỏng mạch điện: lắp được nhiều mạch khác nhau mà <b>không tốn linh kiện</b>; <b>không nguy hiểm</b> (không bị điện giật, không cháy bóng đèn); thấy rõ dòng điện chạy trong mạch (<b>trực quan</b>); thay đổi điện trở, hiệu điện thế để thử <b>nhiều tình huống</b>.","label":"Câu hỏi tr.22"},{"id":"lta","type":"open","q":"Em hãy tìm một phần mềm mô phỏng hỗ trợ học tập. Phần mềm đó mô phỏng hoạt động nào?","k":"Học sinh tự tìm. Ví dụ: <b>PhET – Circuit Construction Kit</b> mô phỏng hoạt động của mạch điện; <b>GeoGebra</b> mô phỏng hình học; <b>Stellarium</b> mô phỏng bầu trời sao.","label":"Luyện tập – a"},{"id":"ltb","type":"open","q":"Phần mềm đó giúp em làm gì?","k":"Ví dụ với PhET mạch điện: giúp em <b>lắp ráp mạch điện ảo</b>, đo cường độ dòng điện, hiệu điện thế, quan sát bóng đèn sáng mạnh, yếu khi thay đổi linh kiện.","label":"Luyện tập – b"},{"id":"ltc","type":"open","q":"Phần mềm đó có những lợi ích gì?","k":"Ví dụ: tiết kiệm chi phí (không cần mua linh kiện); an toàn; trực quan, sinh động; thử được nhiều tình huống; học mọi lúc, mọi nơi.","label":"Luyện tập – c"},{"id":"cmy","type":"match","q":"Dùng phần mềm mô phỏng pha màu (hoặc bảng pha màu ở trên) để trả lời: mỗi cặp màu cơ bản trong hệ CMYK pha với nhau tạo ra màu nào?","k":"a) Xanh lơ + Vàng = <b>Lục</b> (Green); b) Xanh lơ + Hồng sẫm = <b>Lam</b> (Blue); c) Hồng sẫm + Vàng = <b>Đỏ</b> (Red).","items":[["a) Cyan + Yellow = ? (Hình 5.3)",2],["b) Cyan + Magenta = ?",3],["c) Magenta + Yellow = ?",1]],"opts":["1) Đỏ (Red)","2) Lục (Green)","3) Lam (Blue)"]},{"id":"vd2","type":"open","q":"Ghi lại tên (hoặc địa chỉ trang web) của phần mềm mô phỏng pha màu em đã tìm được và cách em dùng nó để kiểm tra kết quả.","k":"Ví dụ: trycolors.com hoặc tìm với từ khoá “mixing colors simulator”, “CMYK color mixer”. Chọn màu Cyan và Yellow với tỉ lệ bằng nhau, quan sát màu kết quả là màu lục; làm tương tự với các cặp màu còn lại.","label":"Vận dụng – Phần mềm em dùng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li><b>Phần mềm mô phỏng</b> thể hiện trực quan sự vận động của một đối tượng, cho phép người dùng tương tác và tìm hiểu cách thức hoạt động của đối tượng đó.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Lợi ích của phần mềm mô phỏng là hỗ trợ nghiên cứu đối tượng một cách <b>toàn diện, sinh động và an toàn</b> với <b>chi phí thấp hơn</b> nghiên cứu trực tiếp trong thực tế.</li></ul>"}]},"tin9-trao-doi-hop-tac":{"id":"tin9-bai7","ten":"Bài 7. Trình bày thông tin trong trao đổi và hợp tác","cau":[{"id":"kd1","type":"open","q":"Nhóm An, Minh, Khoa chuẩn bị bài trình bày về “Lược sử công cụ tính toán” cho Triển lãm tin học. Theo em, nhóm có thể dùng những công cụ nào để cùng nhau trao đổi, hợp tác chuẩn bị sản phẩm?","k":"Có thể dùng <b>sơ đồ tư duy</b> (MindMaple, XMind, Canva,…) để lên ý tưởng, phân công; <b>bài trình chiếu</b> (PowerPoint, Google Trang trình bày,…) để trình bày; các công cụ trực tuyến cho phép <b>chia sẻ, cùng chỉnh sửa</b>; kênh hội thoại (Zalo, Messenger, Google Meet) để trao đổi. Quan trọng là biết <b>cách làm việc hợp tác</b> để công cụ hỗ trợ hiệu quả.","label":"Mở đầu"},{"id":"hd1","type":"open","q":"Em hãy cho biết có thể sử dụng sơ đồ tư duy và bài trình chiếu như thế nào cho việc trình bày nội dung “Lược sử công cụ tính toán” trong Triển lãm tin học.","k":"<ul><li>Dùng <b>sơ đồ tư duy</b> để lên ý tưởng: các nhánh máy tính cơ học, máy tính điện tử,…; phân công mỗi bạn phụ trách một nhánh; đính kèm ảnh, video, tài liệu.</li><li>Dùng <b>bài trình chiếu</b> để trình bày tại triển lãm: mỗi trang chiếu một mốc lịch sử, có hình ảnh, sơ đồ dòng thời gian.</li><li>Chia sẻ trực tuyến để cả nhóm cùng xem, cùng chỉnh sửa; trình bày trực tiếp trước khách tham quan.</li></ul>","label":"HĐ1 – Sơ đồ tư duy, bài trình chiếu"},{"id":"cach","type":"match","q":"Đọc mục 1 (SGK trang 27–28). Mỗi tình huống dưới đây là cách sử dụng sơ đồ tư duy hoặc bài trình chiếu nào?","k":"1 – a, 2 – b, 3 – c, 4 – d. Trình bày trực tiếp giúp diễn giải toàn cảnh và trả lời câu hỏi ngay; chia sẻ giúp mọi người xem, cập nhật, cộng tác dù không gặp nhau.","items":[["1) Nhóm trưởng thuyết trình sơ đồ trước lớp và trả lời ngay câu hỏi của các bạn",1],["2) Gửi tệp sơ đồ (có đính kèm ảnh, video) để thầy cô xem khi có thời gian",2],["3) Mỗi bạn tự vào bài trình chiếu trực tuyến, cập nhật phần của mình vào lúc thuận tiện",3],["4) Cả nhóm cùng mở bài trình chiếu trực tuyến, vừa chỉnh sửa vừa trao đổi qua kênh hội thoại",4]],"opts":["a) Trình bày trực tiếp","b) Chia sẻ để các thành viên khác xem","c) Chia sẻ để các thành viên chủ động cập nhật","d) Chia sẻ để cộng tác theo thời gian thực"]},{"id":"tq","type":"sort","q":"Khi dùng hình ảnh, biểu đồ, video trong sơ đồ tư duy hay bài trình chiếu, việc nào dưới đây nên làm, việc nào không nên làm?","k":"Cần <b>sử dụng đúng công cụ trực quan</b> (đơn giản, rõ ràng, chọn loại minh hoạ truyền tải tốt nhất thông điệp) và <b>đảm bảo chất lượng dữ liệu</b> (xem được từ xa, sắc nét, bố cục hợp lí, màu sắc tăng sự chú ý).","cats":["Nên làm","Không nên"],"items":[["Trình bày tiến trình lịch sử bằng sơ đồ dòng thời gian",0],["Chọn hình ảnh sắc nét, bố cục hợp lí, nhìn từ xa vẫn rõ",0],["Dùng màu sắc để tăng sự chú ý của người xem",0],["Chèn thật nhiều hình ảnh, hiệu ứng dù không liên quan đến nội dung",1],["Dùng chữ rất nhỏ, ảnh mờ, vỡ nét",1],["Chọn loại minh hoạ phức tạp nhất có thể",1]]},{"id":"p28","type":"open","q":"Em hãy chỉ ra những kiến thức về tạo sơ đồ tư duy và bài trình chiếu mà em cần được bổ sung để việc trao đổi, hợp tác được hiệu quả.","k":"Ví dụ: cách <b>chèn hình ảnh, video, liên kết</b>; cách <b>đính kèm tệp</b> vào sơ đồ tư duy; cách <b>chia sẻ</b> tệp, cấp quyền xem hoặc chỉnh sửa; cách <b>cùng chỉnh sửa trực tuyến</b> (Google Trang trình bày, Canva); cách vẽ sơ đồ dòng thời gian, biểu đồ; cách chọn màu sắc, bố cục hợp lí.","label":"Câu hỏi tr.28"},{"id":"dk","type":"match","q":"Quan sát Hình 7.1. Em hãy chỉ ra loại dữ liệu được đính kèm vào mỗi nhánh của sơ đồ tư duy.","k":"Hình 7.1 có đính kèm: <b>ảnh</b> máy Pascaline; <b>liên kết đến video</b> giới thiệu dự án; <b>văn bản</b> tiểu sử của Babbage; <b>bảng tính</b> dự kiến thu chi.","items":[["1) Nhánh Pascal – máy tính cơ học Pascaline",1],["2) Nhánh Babbage – giới thiệu dự án Analytical Engine",2],["3) Nhánh Babbage – tiểu sử của Babbage",3],["4) Nhánh Dự kiến thu chi",4]],"opts":["a) Hình ảnh","b) Video (liên kết đến video)","c) Văn bản","d) Bảng tính"]},{"id":"dk2","type":"mcq","q":"Khi tạo sơ đồ tư duy bằng phần mềm, em có thể đính kèm những loại tệp nào vào sơ đồ?","k":"Phần mềm sơ đồ tư duy cho phép đính kèm <b>tệp văn bản, ảnh, video và trang tính</b> để minh hoạ chi tiết cho nội dung cần trình bày. Cách đính kèm được hướng dẫn cụ thể trong Bài 8.","o":["Chỉ văn bản.","Chỉ hình ảnh.","Văn bản, ảnh, video và trang tính.","Không đính kèm được tệp nào."],"a":2},{"id":"lt1","type":"open","q":"Em hãy nhận xét về tính hợp lí và lợi ích của những dữ liệu đính kèm trong sơ đồ tư duy ở Hình 7.1 khi trình bày thông tin trong trao đổi và hợp tác.","k":"<ul><li><b>Hợp lí:</b> mỗi tệp đính kèm đúng nhánh nội dung (ảnh Pascaline ở nhánh Pascal, tiểu sử ở nhánh Babbage, bảng tính ở nhánh thu chi); sơ đồ vẫn gọn trên một trang.</li><li><b>Lợi ích:</b> người xem có thông tin chi tiết khi cần mà không phải tìm thêm; các thành viên dễ bổ sung, cập nhật; dữ liệu đa dạng (ảnh, video, văn bản, bảng tính) giúp trình bày đầy đủ, hấp dẫn.</li></ul>","label":"Luyện tập – câu 1"},{"id":"lt2","type":"open","q":"Em hãy nêu những cách mà nhóm các bạn An, Minh và Khoa sử dụng sơ đồ tư duy ở Hình 7.1 trong trao đổi và hợp tác để hoàn thành công việc chuẩn bị nội dung “Lược sử công cụ tính toán” cho Triển lãm tin học.","k":"<ul><li><b>Chia sẻ để các thành viên chủ động cập nhật:</b> mỗi bạn phụ trách một nhánh (Pascal, Babbage, máy tính điện tử, dự kiến thu chi), tự đính kèm tài liệu.</li><li><b>Cộng tác theo thời gian thực</b> khi cần thống nhất nội dung, kèm kênh hội thoại.</li><li><b>Chia sẻ để thầy cô, các nhóm khác xem</b> và góp ý.</li><li><b>Trình bày trực tiếp</b> tại Triển lãm tin học.</li></ul>","label":"Luyện tập – câu 2"},{"id":"vd1","type":"open","q":"Em hãy tạo sơ đồ tư duy trình bày nội dung mà em muốn trưng bày trong Triển lãm tin học. Ghi lại: các nhánh chính, những tệp (văn bản, ảnh, video, trang tính) em đính kèm vào nhánh nào, và cách em chia sẻ sơ đồ với các bạn trong nhóm.","k":"Ví dụ chủ đề “Sổ lưu niệm lớp 9A”:<ul><li><b>Nhánh chính:</b> Kỉ niệm lớp 6, 7, 8, 9; Thầy cô; Hoạt động ngoại khoá; Dự kiến chi phí in.</li><li><b>Đính kèm:</b> ảnh tập thể (nhánh Kỉ niệm), video văn nghệ (nhánh Hoạt động), văn bản lời cảm ơn (nhánh Thầy cô), bảng tính chi phí (nhánh Dự kiến chi phí).</li><li><b>Chia sẻ:</b> gửi liên kết cho cả nhóm cùng cập nhật; trình bày trực tiếp tại triển lãm.</li></ul>","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Em có thể sử dụng bài trình chiếu và sơ đồ tư duy trong trao đổi thông tin và hợp tác theo các cách: <b>trình bày trực tiếp</b>; chia sẻ để các thành viên khác <b>xem độc lập</b>; chia sẻ để các thành viên <b>cập nhật độc lập</b>; chia sẻ để <b>cộng tác theo thời gian thực</b>.</li><li>Để sử dụng hình ảnh, biểu đồ và video hợp lí, em cần chú ý: <b>sử dụng đúng công cụ trực quan</b>; <b>đảm bảo chất lượng dữ liệu</b>.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li>Có thể <b>đính kèm tệp văn bản, hình ảnh, video, trang tính</b> vào sơ đồ tư duy giúp trình bày thông tin đầy đủ và hiệu quả.</li></ul>"}]},"tin9-xac-thuc-du-lieu":{"id":"tin9-bai9a","ten":"Bài 9a. Sử dụng công cụ xác thực dữ liệu","cau":[{"id":"kd1","type":"open","q":"Trong chủ đề này, em sẽ hoàn thành dự án nhỏ Quản lí tài chính gia đình bằng phần mềm bảng tính: xây dựng cấu trúc bảng tính và sử dụng một số công cụ cơ bản, nâng cao. Theo em, một bảng tính quản lí tài chính gia đình cần lưu những thông tin gì?","k":"Các khoản <b>thu</b> và khoản <b>chi</b>: ngày, khoản mục, nội dung, số tiền; từ đó tính tổng thu, tổng chi, số dư, theo dõi từng khoản mục.","label":"Khởi động"},{"id":"hd1a","type":"open","q":"Dựa trên hiểu biết về những khoản chi tiêu của gia đình, em hãy cho biết: chi tiêu gia đình gồm những khoản mục gì?","k":"Ví dụ: ở (điện, nước, nhà), ăn, di chuyển, học tập, sức khoẻ, giải trí, quà tặng/từ thiện, tiết kiệm, khác.","label":"HĐ1 – Câu 1"},{"id":"hd1b","type":"open","q":"Nêu cấu trúc một bảng tính điện tử quản lí tài chính mà em thấy phù hợp với gia đình em.","k":"Hai trang tính <b>Thu nhập</b> và <b>Chi tiêu</b>, mỗi trang có các cột: Ngày, Khoản thu/Khoản chi, Nội dung, Số tiền; một cột riêng (ví dụ cột F) liệt kê danh sách các khoản mục.","label":"HĐ1 – Câu 2"},{"id":"thuchi","type":"sort","q":"Xếp mỗi khoản mục vào nhóm Khoản thu hoặc Khoản chi của gia đình (Hình 9a.1).","k":"Khoản thu: lương, thưởng, làm thêm, được cho/tặng, khác. Khoản chi: ở, ăn, di chuyển, học tập, sức khoẻ, giải trí, quà tặng/từ thiện, tiết kiệm, khác.","cats":["Khoản thu","Khoản chi"],"items":[["Lương",0],["Thưởng",0],["Làm thêm",0],["Được cho/tặng",0],["Ở",1],["Ăn",1],["Di chuyển",1],["Học tập",1],["Sức khoẻ",1],["Giải trí",1],["Quà tặng/Từ thiện",1],["Tiết kiệm",1]]},{"id":"allow","type":"match","q":"Ghép mỗi lựa chọn ở ô Allow với ý nghĩa của nó.","k":"Any value – a; Whole number – b; Decimal – c; List – d; Date – e; Text length – f. (Time: thời gian; Custom: tuỳ chỉnh bằng công thức.)","items":[["Any value",1],["Whole number",2],["Decimal",3],["List",4],["Date",5],["Text length",6]],"opts":["a) Bất kì giá trị nào","b) Số nguyên – ô tính chỉ chấp nhận các số nguyên","c) Số thập phân – ô tính chỉ chấp nhận các số thập phân","d) Danh sách – chọn dữ liệu từ danh sách thả xuống","e) Ngày tháng – ô tính chỉ chấp nhận dữ liệu ngày tháng","f) Độ dài văn bản – hạn chế độ dài của văn bản nhập vào ô tính"]},{"id":"dv","type":"mcq","q":"Công cụ xác thực dữ liệu (Data Validation) dùng để:","k":"Công cụ xác thực dữ liệu <b>hạn chế kiểu dữ liệu hoặc giá trị dữ liệu</b> nhập vào ô tính, giúp việc nhập dữ liệu được chính xác và thoả mãn những yêu cầu bài toán đặt ra.","o":["Hạn chế kiểu dữ liệu hoặc giá trị dữ liệu nhập vào ô tính, giúp nhập dữ liệu chính xác và thoả mãn yêu cầu bài toán.","Tính tổng các khoản chi.","Sắp xếp dữ liệu theo thứ tự tăng dần.","Định dạng màu nền cho ô tính."],"a":0},{"id":"p36","type":"mcq","q":"Trang tính Thu nhập (Hình 9a.6) lưu các khoản thu của gia đình. Dữ liệu ở cột B cần được thiết lập để thoả mãn điều kiện xác thực nào?","k":"Mỗi ô ở cột B (Khoản thu) phải là một mục trong danh sách các khoản thu ở cột F: <b>List</b>, Source <b>=$F$2:$F$6</b>.","o":["Allow: List, Source: =$F$2:$F$6 (chọn khoản thu từ danh sách ở cột F).","Allow: Whole number, greater than 0.","Allow: Date.","Allow: Any value."],"a":0},{"id":"nv1","type":"order","q":"Sắp xếp các bước sử dụng công cụ xác thực dữ liệu thuộc danh sách cho trước cho cột Khoản chi.","k":"Chọn B3:B10 → Data/Data Tools/Data Validation → Settings: Allow = List → Source = $F$2:$F$10 → OK.","items":{"a":"Chọn các ô của cột B để nhập dữ liệu, ví dụ các ô từ B3 đến B10.","b":"Trong nhóm lệnh Data Tools của dải lệnh Data, chọn Data Validation.","c":"Trong thẻ Settings, ở ô Allow chọn List.","d":"Ở ô Source, chọn vùng chứa danh sách các khoản chi F2:F10.","e":"Chọn OK; nhập dữ liệu cột B bằng danh sách thả xuống."},"ans":["a","b","c","d","e"],"start":["c","e","a","d","b"]},{"id":"nv2","type":"mcq","q":"Để cột Số tiền (nghìn đồng) chỉ chấp nhận kiểu số lớn hơn 0, trong thẻ Settings em chọn:","k":"Allow: <b>Whole number</b>, Data: <b>greater than</b>, Minimum: <b>0</b> (Hình 9a.9). Thẻ Input Message: thông báo khi nhập; thẻ Error Alert: thông báo lỗi.","o":["Allow: Whole number; Data: greater than; Minimum: 0","Allow: List; Source: 0","Allow: Text length; Data: greater than; Minimum: 0","Allow: Any value"],"a":0},{"id":"nv3","type":"mcq","q":"Đã đặt Error Alert kiểu Stop cho cột Số tiền. Nếu nhập −500 vào ô D4 thì điều gì xảy ra?","k":"Kiểu <b>Stop</b> không cho nhập dữ liệu sai: xuất hiện hộp thông báo “Dữ liệu nhập sai”, chọn <b>Retry</b> nhập lại hoặc <b>Cancel</b> huỷ. (Warning, Information vẫn cho phép giữ giá trị nếu người dùng đồng ý.)","o":["Xuất hiện thông báo lỗi (Hình 9a.12); chọn Retry để nhập lại hoặc Cancel để huỷ, ô không nhận giá trị −500.","Ô nhận giá trị −500 bình thường.","Ô tự đổi thành 500.","Bảng tính bị đóng."],"a":0},{"id":"lt1","type":"open","q":"Mở tệp TaiChinhGiaDinh.xlsx: tạo thêm trang tính Thu nhập; nhập danh sách khoản thu (cột F), dùng công cụ xác thực dữ liệu để khoản thu ở cột B được lấy từ danh sách ở cột F; hạn chế kiểu dữ liệu và giá trị cho cột Số tiền như trang tính Chi tiêu; nhập ít nhất ba hàng dữ liệu. Em đã đặt những điều kiện xác thực nào?","k":"Cột B: List, Source =$F$2:$F$6. Cột D: Whole number, greater than 0, kèm Input Message và Error Alert. Nhập ít nhất ba khoản thu.","label":"Luyện tập – câu 1, 2"},{"id":"vd1","type":"open","q":"Tạo bảng tính quản lí tài chính cho dự án Triển lãm tin học: trang tính Các khoản thu (Quỹ, Tài trợ) và trang tính Các khoản chi (Văn phòng phẩm, In tài liệu). Sử dụng công cụ xác thực dữ liệu để việc nhập dữ liệu các khoản thu, chi được chính xác. Lưu tệp KinhPhiTrienLam.xlsx. Mô tả các điều kiện xác thực em đã đặt.","k":"Ở mỗi trang tính: cột khoản thu/chi dùng List lấy từ cột F; cột Số tiền dùng Whole number (hoặc Decimal) greater than 0; có thể thêm Date cho cột Ngày.","label":"Vận dụng"}],"the":[{"t":"Ghi nhớ","b":"<ul><li>Công cụ xác thực dữ liệu (<b>Data Validation</b>) hạn chế kiểu dữ liệu hoặc giá trị dữ liệu nhập vào ô tính, giúp cho việc nhập dữ liệu được chính xác và thoả mãn những yêu cầu bài toán đặt ra.</li></ul>"},{"t":"Ghi nhớ","b":"<ul><li><b>Data → Data Tools → Data Validation</b>: thẻ <b>Settings</b> (điều kiện), <b>Input Message</b> (thông báo khi chọn ô), <b>Error Alert</b> (thông báo khi nhập sai).</li><li>Danh sách thả xuống: Allow <b>List</b>, Source là vùng chứa danh sách (ví dụ <b>=$F$2:$F$10</b>).</li></ul>"}]}};
